import Twemoji from "react-twemoji";

import { ScopeType } from "sockapi/scope-types";
import { SockAPIScopeState } from "sockapi/scope-state";
import {
  LEADERBOARD_CONFIG,
  TeamNameDisplayData,
} from "sockapi/scope-specs/team-list-spec";
import { getTeamCollectibleIcons } from "sockapi/scope-specs/team-collectibles-spec";

import {
  useTeamId,
  useShouldDisplayAdmin,
} from "stores/ServerInteractionStore";
import {
  useGlobalScopeState,
  useGlobalScopeStatePosthuntable,
  useIsHuntOver,
  useScopeStateResolvable,
  useTeamScopeState,
} from "stores/ScopeStateStore";
import { ShipIcon } from "components/Icon";
import { Link } from "components/Link";
import { Spinner } from "components/Loading";
import Tooltip from "components/Tooltip";
import DownloadFailed from "components/DownloadFailed";
import { weakMapMemoize } from "util/memoize";
import settings from "settings";
import "./TeamDisplayName.css";

const teamScopeStateToTeamNameDisplayData = (
  teamId: string,
  { displayName }: SockAPIScopeState<ScopeType.TEAM>,
  teamCollectiblesScopeState: SockAPIScopeState<ScopeType.TEAM_COLLECTIBLES>,
  { ship }: SockAPIScopeState<ScopeType.TEAM_SHIP>,
  huntEndTime: number | null
): TeamNameDisplayData => {
  const collectibleIcons = getTeamCollectibleIcons(
    teamCollectiblesScopeState,
    huntEndTime
  );
  return {
    teamId,
    displayName,
    collectibleIcons: collectibleIcons === "" ? undefined : collectibleIcons,
    ship,
  };
};

type TeamDisplayNameRenderProps = {
  noLink?: boolean;
  hideAdminLinks?: boolean;
  hideCollectibles?: boolean;
  shipStyle?: "link" | "show";
};

type TeamDisplayNameProps = TeamDisplayNameRenderProps & {
  teamData: TeamNameDisplayData;
};

/** Memoized since every visible team name calls this on each TEAM_LIST update. */
const getNumFinishedTeams = weakMapMemoize(
  (teamList: SockAPIScopeState<ScopeType.TEAM_LIST>): number =>
    Object.values(teamList).filter(
      (team) => !(team.isHidden ?? false) && team.completionTime !== undefined
    ).length
);

export function useAreOtherTeamShipsRevealed(
  /** Disable to skip subscribing to the TEAM_LIST scope. */
  enable = true
): boolean {
  const shouldDisplayAdmin = useShouldDisplayAdmin();
  const isHuntOver = useIsHuntOver();
  const teamList = useGlobalScopeState(ScopeType.TEAM_LIST, enable);
  if (shouldDisplayAdmin || (isHuntOver ?? false)) return true;
  if (teamList === null) return false;
  return (
    getNumFinishedTeams(teamList) >=
    LEADERBOARD_CONFIG.shipRevealNumFinishedTeams
  );
}

export const makeTeamPagePath = (displayName: string) =>
  ({
    route: "team",
    params: { teamName: encodeURIComponent(displayName) },
  }) as const;

export function TeamAdminLinks({ teamId }: { teamId: string }) {
  const huntAdminScopeState = useGlobalScopeState(ScopeType.HUNT_ADMIN);
  const adminData = huntAdminScopeState?.teamAdminData[teamId] ?? null;

  if (adminData === null) return <Spinner inline />;

  const { userId, adminNotes } = adminData;
  const sigils = [
    adminNotes ? "ℹ️" : "",
    adminData.isHidden ? "👻" : "",
    adminData.isInactive ? "⛔" : "",
    adminData.isTempBlocked ? "🚧" : "",
  ].join("");

  return (
    <div className="button-squish-zone team-name-collectibles">
      {
        // If impersonating, we need to stop impersonating
        // first, otherwise the impersonate button doesn't work.
        userId !== null && !settings.isImpersonate ? (
          <Tooltip text="Impersonate">
            <Link route="impersonate" params={{ userId }} button>
              <Twemoji>🕵️</Twemoji>
            </Link>
          </Tooltip>
        ) : null
      }
      <Tooltip text="Sock Admin">
        <Link route="sock_admin_team" params={{ teamId }} button>
          <Twemoji>🧦️</Twemoji>
        </Link>
      </Tooltip>
      {sigils ? (
        <Tooltip text={adminNotes}>
          <button disabled>
            <Twemoji>{sigils}</Twemoji>
          </button>
        </Tooltip>
      ) : null}
    </div>
  );
}

export function TeamDisplayNamePreloaded(props: TeamDisplayNameProps) {
  const {
    teamData,
    noLink,
    hideAdminLinks: hideAdminLinksOpt = false,
    hideCollectibles = false,
    shipStyle: shipStyleOpt,
  } = props;
  const { teamId, displayName, collectibleIcons, ship } = teamData;
  const ownTeamId = useTeamId();
  const shouldDisplayAdmin = useShouldDisplayAdmin();
  const isOtherTeamShip =
    ship.length > 0 && shipStyleOpt !== undefined && teamId !== ownTeamId;
  const areShipsRevealed = useAreOtherTeamShipsRevealed(isOtherTeamShip);
  const shipStyle =
    isOtherTeamShip && !areShipsRevealed ? undefined : shipStyleOpt;
  const showAdminLinks = !hideAdminLinksOpt && shouldDisplayAdmin;

  const modifiedDisplayName = (
    <span className="team-display-name">
      {!hideCollectibles && (collectibleIcons ?? "").length > 0 ? (
        <span className="team-name-collectibles">
          <Twemoji tag="span">{collectibleIcons}</Twemoji>&nbsp;
        </span>
      ) : null}
      <Twemoji tag="span">{displayName}</Twemoji>
    </span>
  );

  return (
    <>
      {showAdminLinks ? (
        <>
          <TeamAdminLinks teamId={teamId} />
          &nbsp;
        </>
      ) : null}
      <span className="team-name-link">
        {ship.length === 0 || shipStyle === undefined ? null : shipStyle ===
          "link" ? (
          <>
            <Link route="victory">
              <ShipIcon ship={ship} />
            </Link>
            &nbsp;
          </>
        ) : (
          <>
            <ShipIcon ship={ship} />
            &nbsp;
          </>
        )}
        {noLink ? (
          modifiedDisplayName
        ) : (
          <Link {...makeTeamPagePath(displayName)}>{modifiedDisplayName}</Link>
        )}
      </span>
    </>
  );
}

/** Team display name display for a team we have full access to. */
function AccessibleTeamDisplayName(
  props: TeamDisplayNameRenderProps & { teamId: string }
) {
  const { teamId, ...renderProps } = props;
  const teamScopeState = useTeamScopeState(teamId);
  const teamCollectiblesScopeState = useScopeStateResolvable(
    ScopeType.TEAM_COLLECTIBLES,
    teamId === null ? null : { teamId }
  );
  const teamShipScopeState = useScopeStateResolvable(
    ScopeType.TEAM_SHIP,
    teamId === null ? null : { teamId }
  );

  if (
    teamScopeState === null ||
    teamCollectiblesScopeState === null ||
    teamShipScopeState === null
  )
    return <Spinner inline />;

  return (
    <TeamDisplayNamePreloaded
      teamData={teamScopeStateToTeamNameDisplayData(
        teamId,
        teamScopeState,
        teamCollectiblesScopeState,
        teamShipScopeState,
        // Show all collectibles for our own team even after hunt ends,
        // for posthunt progression.
        null
      )}
      {...renderProps}
    />
  );
}

/** Team display name display for a team we don't have full access to. */
function InaccessibleTeamDisplayName(
  props: TeamDisplayNameRenderProps & { teamId: string }
) {
  const { teamId, ...renderProps } = props;

  const posthuntTeamListResult = useGlobalScopeStatePosthuntable(
    ScopeType.TEAM_LIST,
    true,
    { hasPosthunt: true }
  );
  const teamList = useGlobalScopeState(ScopeType.TEAM_LIST);

  if (posthuntTeamListResult === null || teamList === null)
    return <Spinner inline />;
  const liveTeamData = teamList[teamId];
  // HACK: The posthunt team always takes priority, but if download
  // failed, fallback to the live team if it exists.
  if (!posthuntTeamListResult.success && liveTeamData === undefined)
    return <DownloadFailed {...posthuntTeamListResult} />;
  const posthuntTeamData = posthuntTeamListResult.success
    ? posthuntTeamListResult.state[teamId]
    : undefined;
  const teamData = posthuntTeamData ?? liveTeamData;

  // If a team is newly created, it may take a little while
  // before it gets reflected in the team list.
  if (teamData === undefined) return <Spinner inline />;

  return <TeamDisplayNamePreloaded teamData={teamData} {...renderProps} />;
}

function TeamDisplayName(
  props: TeamDisplayNameRenderProps & { teamId?: string }
) {
  const { teamId: teamIdOpt, ...renderProps } = props;
  const ownTeamId = useTeamId();
  const teamId = teamIdOpt ?? ownTeamId;

  if (ownTeamId === null || teamId === null) return <Spinner inline />;

  return teamId === ownTeamId ? (
    <AccessibleTeamDisplayName teamId={teamId} {...renderProps} />
  ) : (
    <InaccessibleTeamDisplayName teamId={teamId} {...renderProps} />
  );
}

export default TeamDisplayName;
