// Pacing tags in sheet-authored dialogue, shared by the client's typewriter
// (CutsceneUi/markup.ts) and the importers' lint. Tags render as nothing:
//   {pace=0.5}…{/pace}      reveal at 0.5× speed, i.e. slower (pauses too)
//   {pace=1..0.35}…{/pace}  speed eases linearly across the span (slowing down)
//   {pause=500}             hold for 500ms here
// Pace is a speed, so it must be positive; {pace=0} is invalid.
// Tags don't nest (a new {pace} replaces the current one), and an unclosed
// {pace} runs to the end of the line.

export type DialogueTag =
  | { kind: "pace"; from: number; to: number }
  | { kind: "endPace" }
  | { kind: "pause"; ms: number };

const NUM = String.raw`(\d*\.?\d+)`;
const TAG = new RegExp(
  String.raw`^\{(?:pace=${NUM}(?:\.\.${NUM})?|(\/pace)|pause=(\d+))\}`
);

/** The tag starting at `text[i]` and its length, if there is one. */
export function matchDialogueTag(
  text: string,
  i: number
): { tag: DialogueTag; length: number } | null {
  if (text[i] !== "{") return null;
  const m = TAG.exec(text.slice(i));
  if (m === null) return null;
  const [all, from, to, endPace, pauseMs] = m;
  if (from !== undefined && (Number(from) <= 0 || Number(to ?? from) <= 0))
    return null;
  const tag: DialogueTag =
    endPace !== undefined
      ? { kind: "endPace" }
      : pauseMs !== undefined
        ? { kind: "pause", ms: Number(pauseMs) }
        : { kind: "pace", from: Number(from), to: Number(to ?? from) };
  return { tag, length: all.length };
}

/** `{…}` spans that aren't valid tags (the client would show them literally). */
export function invalidDialogueTags(text: string): string[] {
  return [...text.matchAll(/\{[^{}]*\}?/g)]
    .filter((m) => matchDialogueTag(text, m.index) === null)
    .map((m) => m[0]);
}
