import { Fragment, ReactNode, useLayoutEffect, useRef, useState } from "react";
import { clsObj } from "client-util/util";
import { DialogueSegment } from "components/CutsceneUi/markup";
import "./DialogueBox.css";

// Name plate + the already-revealed dialogue. Pure presentation: the player owns
// the typewriter and passes `segments` sliced to what's visible. Emoji are
// pre-resolved Twemoji <img>s (not react-twemoji — see markup.ts for why).

// Each segment is one node: a styled text run or a single emoji image.
export function renderDialogueSegments(
  segments: DialogueSegment[]
): ReactNode[] {
  return segments.map((seg, i) => {
    if (seg.kind === "emoji")
      return (
        <img
          key={i}
          className="twemoji"
          src={seg.src}
          alt={seg.emoji}
          draggable={false}
        />
      );
    let node: ReactNode = seg.text;
    if (seg.italic) node = <em>{node}</em>;
    if (seg.bold) node = <strong>{node}</strong>;
    return <Fragment key={i}>{node}</Fragment>;
  });
}

export function DialogueBox(props: {
  speakerName?: string | null;
  speakerColor?: string;
  /** Narration: no name plate, italic text. */
  stageDirection?: boolean;
  segments: DialogueSegment[];
  showContinue: boolean;
  hidden?: boolean;
}) {
  const {
    speakerName,
    speakerColor,
    stageDirection,
    segments,
    showContinue,
    hidden,
  } = props;
  // The box animates to the text's height, so it visibly grows a line at a
  // time as the typewriter wraps onto new lines.
  const textRef = useRef<HTMLDivElement>(null);
  const [textHeight, setTextHeight] = useState<number | undefined>(undefined);
  useLayoutEffect(() => {
    const el = textRef.current;
    if (el === null) return;
    const observer = new ResizeObserver(([entry]) =>
      setTextHeight(entry?.borderBoxSize[0]?.blockSize)
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);
  return (
    <div
      className={clsObj({
        "cutscene-dialogue": true,
        "cutscene-dialogue-hidden": !!hidden,
        "cutscene-stage-direction": !!stageDirection,
      })}
      style={
        speakerColor
          ? ({ "--speaker-color": speakerColor } as React.CSSProperties)
          : undefined
      }
    >
      {speakerName ? (
        <div className="cutscene-name-plate">{speakerName}</div>
      ) : null}
      <div className="cutscene-dialogue-box">
        <div className="cutscene-dialogue-sizer" style={{ height: textHeight }}>
          <div className="cutscene-dialogue-text" ref={textRef}>
            {renderDialogueSegments(segments)}
            {/* Keeps the box from collapsing before any text is revealed. */}
            {segments.length === 0 ? " " : null}
            {showContinue ? <span className="cutscene-continue">▼</span> : null}
          </div>
        </div>
      </div>
    </div>
  );
}
