// Inline glyphs for puzzlehunt encodings that don't have Unicode characters.

const glyphStyle = (size: number) => ({
  width: `${size}em`,
  height: `${size}em`,
  verticalAlign: `${-size / 4}em`,
  overflow: "visible",
});

// Flag directions in degrees clockwise from straight up, as seen by the viewer.
const [N, NE, E, SE, S, SW, W, NW] = [0, 45, 90, 135, 180, 225, 270, 315];

const SEMAPHORE: Record<string, [number, number]> = {
  A: [S, SW],
  B: [S, W],
  C: [S, NW],
  D: [S, N],
  E: [S, NE],
  F: [S, E],
  G: [S, SE],
  H: [SW, W],
  I: [SW, NW],
  J: [N, E],
  K: [SW, N],
  L: [SW, NE],
  M: [SW, E],
  N: [SW, SE],
  O: [W, NW],
  P: [W, N],
  Q: [W, NE],
  R: [W, E],
  S: [W, SE],
  T: [NW, N],
  U: [NW, NE],
  V: [N, SE],
  W: [NE, E],
  X: [NE, SE],
  Y: [NW, E],
  Z: [SE, E],
};

export function Semaphore({ letter }: { letter: string }) {
  const flags = SEMAPHORE[letter.toUpperCase()];
  if (!flags) return letter;
  return (
    <>
      <span className="copy-only">[semaphore {letter}]</span>
      <SemaphoreArms angles={flags} label={`semaphore ${letter}`} />
    </>
  );
}

const DIRECTIONS = { N, NE, E, SE, S, SW, W, NW };

/** One semaphore arm on its own, pointing `dir` (N, NE, …, NW). */
export function SemaphoreArm({ dir }: { dir: keyof typeof DIRECTIONS }) {
  return (
    <>
      <span className="copy-only">[semaphore arm {dir}]</span>
      <SemaphoreArms
        angles={[DIRECTIONS[dir]]}
        label={`semaphore arm ${dir}`}
      />
    </>
  );
}

/* Flags at `angles` in a -10..10 box, filled and stroked by the enclosing
   element; GeneticCode draws these into its chart too. */
const flagsSVG = (angles: number[]) =>
  angles
    .map(
      (a) =>
        `<g transform="rotate(${a})"><line x1="0" y1="0" x2="0" y2="-7" ` +
        `stroke-width="0.9" stroke-linecap="round"/>` +
        `<rect x="-1.6" y="-9.8" width="3.2" height="3.2" stroke="none"/></g>`
    )
    .join("");

/** A letter's semaphore flags, as SVG markup. */
export const semaphoreFlagsSVG = (letter: string) =>
  flagsSVG(SEMAPHORE[letter]);

function SemaphoreArms({ angles, label }: { angles: number[]; label: string }) {
  return (
    <svg
      className="no-copy"
      viewBox="-10 -10 20 20"
      style={glyphStyle(1.4)}
      role="img"
      aria-label={label}
      fill="currentColor"
      stroke="currentColor"
      // eslint-disable-next-line @eslint-react/dom-no-dangerously-set-innerhtml -- SVG we generate
      dangerouslySetInnerHTML={{ __html: flagsSVG(angles) }}
    />
  );
}

// Segments of a pigpen glyph as [x1, y1, x2, y2] in a 20×20 box.
type Segment = [number, number, number, number];
const TOP: Segment = [3, 3, 17, 3];
const BOTTOM: Segment = [3, 17, 17, 17];
const LEFT: Segment = [3, 3, 3, 17];
const RIGHT: Segment = [17, 3, 17, 17];

const gridCell = (row: number, col: number): Segment[] => [
  ...(row > 0 ? [TOP] : []),
  ...(row < 2 ? [BOTTOM] : []),
  ...(col > 0 ? [LEFT] : []),
  ...(col < 2 ? [RIGHT] : []),
];

// The X-shaped grids, named by which side the right-angled wedge opens toward.
const OPEN_UP: Segment[] = [
  [3, 6.5, 10, 13.5],
  [10, 13.5, 17, 6.5],
];
const OPEN_LEFT: Segment[] = [
  [6.5, 3, 13.5, 10],
  [13.5, 10, 6.5, 17],
];
const OPEN_RIGHT: Segment[] = [
  [13.5, 3, 6.5, 10],
  [6.5, 10, 13.5, 17],
];
const OPEN_DOWN: Segment[] = [
  [3, 13.5, 10, 6.5],
  [10, 6.5, 17, 13.5],
];

const PIGPEN: Record<string, { segments: Segment[]; dot?: [number, number] }> =
  {};
"ABCDEFGHI".split("").forEach((c, i) => {
  PIGPEN[c] = { segments: gridCell(Math.floor(i / 3), i % 3) };
});
"JKLMNOPQR".split("").forEach((c, i) => {
  PIGPEN[c] = { segments: gridCell(Math.floor(i / 3), i % 3), dot: [10, 10] };
});
// Each X shape with where its dot goes, inside the opening.
const X_SHAPES: [Segment[], [number, number]][] = [
  [OPEN_UP, [10, 9.5]],
  [OPEN_LEFT, [9.5, 10]],
  [OPEN_RIGHT, [10.5, 10]],
  [OPEN_DOWN, [10, 10.5]],
];
"STUV".split("").forEach((c, i) => {
  PIGPEN[c] = { segments: X_SHAPES[i][0] };
});
"WXYZ".split("").forEach((c, i) => {
  PIGPEN[c] = { segments: X_SHAPES[i][0], dot: X_SHAPES[i][1] };
});

export function Pigpen({ letter }: { letter: string }) {
  const glyph = PIGPEN[letter.toUpperCase()];
  if (!glyph) return letter;
  return (
    <>
      <span className="copy-only">[pigpen {letter}]</span>
      <svg
        className="no-copy"
        viewBox="0 0 20 20"
        style={glyphStyle(1.1)}
        role="img"
        aria-label={`pigpen ${letter}`}
      >
        {glyph.segments.map(([x1, y1, x2, y2], i) => (
          <line
            key={i}
            x1={x1}
            y1={y1}
            x2={x2}
            y2={y2}
            stroke="currentColor"
            strokeWidth={1.1}
            strokeLinecap="round"
          />
        ))}
        {glyph.dot && (
          <circle
            cx={glyph.dot[0]}
            cy={glyph.dot[1]}
            r={1.4}
            fill="currentColor"
          />
        )}
      </svg>
    </>
  );
}
