/** Wordle colors lightened, indexed by fill char: "." none, 1 gray, 2 green, 3 yellow. */
const COLORS = ["", "#bbbdbe", "#b4d4b1", "#e4d9ab"];
const color = (ch: string) => COLORS[ch === "." ? 0 : +ch];

/**
 * One table: each piece's cells, then its clue in the next column. Same
 * layout on the page and when copied, so clues paste to the right of pieces.
 */
export function WordtrisPieces(props: {
  /** [fills, clue]; fills is rows separated by "|" as in `PuzzleGrid`. */
  pieces: [string, string][];
  /** Piece i's letters are `letters[4 * i ...]`; editable when given. */
  letters?: string[];
  onEdit?: (index: number, value: string) => void;
}) {
  const { letters, onEdit } = props;
  /** Moves focus `by` inputs along the table, in reading order. */
  const focusNext = (input: HTMLInputElement, by: number) => {
    const inputs = [
      ...input.closest("table")!.querySelectorAll<HTMLInputElement>("input"),
    ];
    inputs[inputs.indexOf(input) + by]?.focus();
  };
  return (
    <table className="puzzle-grid wordtris-pieces">
      <tbody>
        {props.pieces.map(([fills, clue], i) => {
          const rows = fills.split("|");
          let k = 4 * i;
          return (
            <Fragment key={i}>
              {i > 0 ? (
                <tr className="wordtris-spacer">
                  <td className="hidden-cell" colSpan={5} />
                </tr>
              ) : null}
              {rows.map((row, r) => (
                <tr key={r}>
                  {[...row.padEnd(4, ".")].map((ch, c) => {
                    if (ch === ".")
                      return <td key={c} className="hidden-cell" />;
                    const j = k++;
                    const letter = letters?.[j] ?? "";
                    return (
                      <td key={c} style={{ backgroundColor: color(ch) }}>
                        {onEdit ? (
                          <>
                            <span className="copy-only">{letter}</span>
                            <input
                              className="wordtris-input no-copy"
                              value={letter}
                              aria-label={`${clue}, letter ${j - 4 * i + 1}`}
                              onFocus={(e) => e.target.select()}
                              onChange={(e) => {
                                const value = [...e.target.value.trim()]
                                  .slice(-1)
                                  .join("")
                                  .toUpperCase();
                                onEdit(j, value);
                                if (value) focusNext(e.target, 1);
                              }}
                              onKeyDown={(e) => {
                                if (e.key === "Backspace" && !letter) {
                                  if (j > 0) onEdit(j - 1, "");
                                  focusNext(e.currentTarget, -1);
                                  e.preventDefault();
                                }
                              }}
                            />
                          </>
                        ) : null}
                      </td>
                    );
                  })}
                  {r === 0 ? (
                    <>
                      <td className="hidden-cell" />
                      <td className="wordtris-clue">{clue}</td>
                    </>
                  ) : null}
                </tr>
              ))}
            </Fragment>
          );
        })}
      </tbody>
    </table>
  );
}

type WordtrisGridData = {
  text: string;
  fills: string;
  /** Same shape as `text`; cells sharing a char are one piece, "." is a lone cell. */
  pieces?: string;
  /** Column (0-indexed) to bold. */
  column?: number;
};

function barsFor(pieces: string) {
  const rows = pieces.split("|");
  const same = (r: number, c: number, ch: string) =>
    ch !== "." && rows[r]?.[c] === ch;
  return rows
    .map((row, r) =>
      [...row]
        .map((ch, c) =>
          (
            (same(r - 1, c, ch) ? 0 : 1) |
            (same(r, c + 1, ch) ? 0 : 2) |
            (same(r + 1, c, ch) ? 0 : 4) |
            (same(r, c - 1, ch) ? 0 : 8)
          ).toString(16)
        )
        .join("")
    )
    .join("|");
}

type PieceRef = [grid: number, piece: string];

export function WordtrisGrids(props: {
  grids: WordtrisGridData[];
  /** Darken every cell outside these pieces. */
  highlight?: PieceRef[];
  onHover?: (piece?: PieceRef) => void;
}) {
  const { grids, highlight, onHover } = props;
  return (
    <div
      className="wordtris-grids"
      onMouseLeave={onHover && (() => onHover(undefined))}
    >
      {grids.map(({ text, fills, pieces, column }, i) => {
        const pieceRows = pieces?.split("|");
        const textRows = text.split("|");
        return (
          <PuzzleGrid
            key={i}
            // bolded letters are drawn by renderCell instead
            text={textRows
              .map((row) =>
                column === undefined
                  ? row
                  : row.slice(0, column) + "." + row.slice(column + 1)
              )
              .join("|")}
            fills={fills}
            fillColors={COLORS}
            bars={pieces && barsFor(pieces)}
            renderCell={(r, c) => {
              const ch = pieceRows?.[r][c];
              return (
                <>
                  {c === column ? <b>{textRows[r][c]}</b> : null}
                  {ch !== undefined && onHover ? (
                    <span
                      className="wordtris-hit"
                      onMouseEnter={() =>
                        onHover(ch === "." ? undefined : [i, ch])
                      }
                    />
                  ) : null}
                </>
              );
            }}
            overlay={
              pieceRows
                ? pieceRows.flatMap((row, r) =>
                    [...row].map((ch, c) => (
                      <rect
                        key={`${r},${c}`}
                        className={clsObj({
                          "wordtris-overlay": true,
                          "wordtris-dim":
                            !!highlight &&
                            !highlight.some(([g, p]) => g === i && p === ch),
                        })}
                        x={c}
                        y={r}
                        width={1}
                        height={1}
                      />
                    ))
                  )
                : null
            }
          />
        );
      })}
    </div>
  );
}

export function WordtrisSolution(props: {
  grids: WordtrisGridData[];
  /** [clue, answer, grid index, piece char]. */
  clues: [string, string, number, string][];
}) {
  const { grids, clues } = props;
  const [hovered, setHovered] = useState<PieceRef>();
  return (
    <div className="wordtris-solution">
      <table className="wordtris-clues">
        <thead>
          <tr>
            <th>Clue</th>
            <th>Answer</th>
          </tr>
        </thead>
        <tbody onMouseLeave={() => setHovered(undefined)}>
          {clues.map(([clue, answer, grid, piece]) => (
            <tr
              key={`${grid}${piece}`}
              className={
                hovered?.[0] === grid && hovered[1] === piece
                  ? "wordtris-active"
                  : undefined
              }
              onMouseEnter={() => setHovered([grid, piece])}
            >
              <td>{clue}</td>
              <td className="wordtris-answer">{answer}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <WordtrisGrids
        grids={grids}
        highlight={hovered && [hovered]}
        onHover={setHovered}
      />
    </div>
  );
}

type Rot = WordtrisPlacement["rot"];
/** [r, c] of each of a piece's cells, in MDX reading order. */
type Shape = [number, number][];

function shapeOf(fills: string): Shape {
  return fills
    .split("|")
    .flatMap((row, r) =>
      [...row].flatMap((ch, c): Shape => (ch === "." ? [] : [[r, c]]))
    );
}

/** SVG path, in cell units, of the edges around the cells of `shape`. */
function outlinePath(shape: Shape) {
  const has = new Set(shape.map(([r, c]) => `${r},${c}`));
  return shape
    .map(([r, c]) =>
      [
        has.has(`${r - 1},${c}`) ? "" : `M${c} ${r}h1`,
        has.has(`${r},${c + 1}`) ? "" : `M${c + 1} ${r}v1`,
        has.has(`${r + 1},${c}`) ? "" : `M${c} ${r + 1}h1`,
        has.has(`${r},${c - 1}`) ? "" : `M${c} ${r}v1`,
      ].join("")
    )
    .join("");
}

/** `shape` turned `rot` quarter turns clockwise, still with its corner at 0, 0. */
function rotate(shape: Shape, rot: number): Shape {
  let cells = shape;
  for (let i = 0; i < rot; i++) {
    const h = Math.max(...cells.map(([r]) => r)) + 1;
    cells = cells.map(([r, c]) => [c, h - 1 - r]);
  }
  return cells;
}

/** SRS kicks [x, y] (y up) turning clockwise out of states 0, R, 2, L. */
const JLSTZ_KICKS = [
  [
    [0, 0],
    [-1, 0],
    [-1, 1],
    [0, -2],
    [-1, -2],
  ],
  [
    [0, 0],
    [1, 0],
    [1, -1],
    [0, 2],
    [1, 2],
  ],
  [
    [0, 0],
    [1, 0],
    [1, 1],
    [0, -2],
    [1, -2],
  ],
  [
    [0, 0],
    [-1, 0],
    [-1, -1],
    [0, 2],
    [-1, 2],
  ],
];
const I_KICKS = [
  [
    [0, 0],
    [-2, 0],
    [1, 0],
    [-2, -1],
    [1, 2],
  ],
  [
    [0, 0],
    [-1, 0],
    [2, 0],
    [-1, 2],
    [2, -1],
  ],
  [
    [0, 0],
    [2, 0],
    [-1, 0],
    [2, 1],
    [-1, -2],
  ],
  [
    [0, 0],
    [1, 0],
    [-2, 0],
    [1, -2],
    [-2, 1],
  ],
];

/**
 * `shape` turned `rot` as an SRS piece: its state, where its corner sits in
 * the SRS box it turns inside, that box's size (4 for I, 2 for O, else 3), and
 * kicks.
 */
function srs(shape: Shape, rot: number) {
  // State 0 lies flat, fuller row down; S and Z don't care which way.
  const count = (cells: Shape, row: number) =>
    cells.filter(([r]) => r === row).length;
  const base = [0, 1, 2, 3].find((k) => {
    const cells = rotate(shape, k);
    const h = Math.max(...cells.map(([r]) => r)) + 1;
    const w = Math.max(...cells.map(([, c]) => c)) + 1;
    return h <= w && count(cells, h - 1) >= count(cells, 0);
  })!;
  const state = (rot - base + 4) % 4;
  const s = Math.max(...rotate(shape, base).flat()) + 1;
  let cells = rotate(shape, base).map(([r, c]): [number, number] => [
    s === 4 ? r + 1 : r,
    c,
  ]);
  for (let i = 0; i < state; i++) cells = cells.map(([r, c]) => [c, s - 1 - r]);
  return {
    state,
    offset: [
      Math.min(...cells.map(([r]) => r)),
      Math.min(...cells.map(([, c]) => c)),
    ],
    size: s,
    kicks: s === 4 ? I_KICKS : s === 3 ? JLSTZ_KICKS : null,
  };
}

/** Board cells [grid, r, c] each of a placed piece's cells lands on. */
const cellsOf = (shape: Shape, { grid, row, col, rot }: WordtrisPlacement) =>
  rotate(shape, rot).map(
    ([r, c]) => [grid, row + r, col + c] as [number, number, number]
  );

const { rows: ROWS, cols: COLS } = WORDTRIS_CONFIG;

/** Board cells [grid, r, c] of a placed piece, given its fills as in `pieces`. */
export const wordtrisPieceCells = (
  fills: string,
  placement: WordtrisPlacement
) => cellsOf(shapeOf(fills), placement);

const inBounds = (shape: Shape, placement: WordtrisPlacement) =>
  cellsOf(shape, placement).every(
    ([, r, c]) => r >= 0 && r < ROWS && c >= 0 && c < COLS
  );

/** The placement putting `shape`'s cell `anchor` on (r, c) of `grid`. */
function anchoredAt(
  shape: Shape,
  anchor: number,
  rot: Rot,
  grid: number,
  r: number,
  c: number
): WordtrisPlacement {
  const [ar, ac] = rotate(shape, rot)[anchor];
  return { grid, row: r - ar, col: c - ac, rot };
}

type SendUpdate = (update: WordtrisUpdate) => Promise<unknown>;

/** Pending local edits over the server's, as in `GridAdventure`. */
function usePending<V>(
  send: ((edits: [number, V][]) => Promise<unknown>) | null
) {
  const [pending, setPending] = useState<Map<number, V>>(() => new Map());
  const edit = (edits: [number, V][]) => {
    setPending((prev) => new Map([...prev, ...edits]));
    void send?.(edits).then(() =>
      setPending((prev) => {
        const next = new Map(prev);
        for (const [i, value] of edits)
          if (next.get(i) === value) next.delete(i);
        return next;
      })
    );
  };
  return [pending, edit] as const;
}

type WordtrisProps = {
  pieces: [string, string][];
  grids: WordtrisGridData[];
};

export function Wordtris(props: WordtrisProps) {
  const { teamId, send } = usePuzzleTeam();
  if (teamId === null)
    return <WordtrisBoard {...props} serverState={null} send={null} />;
  return <SyncedWordtris {...props} teamId={teamId} canSend={send} />;
}

function SyncedWordtris(
  props: WordtrisProps & { teamId: string; canSend: boolean }
) {
  const { teamId, canSend } = props;
  const sockClient = useSockClient();
  const identifier = useMemo(() => ({ teamId }), [teamId]);
  const state = useScopeStateResolvable(ScopeType.TEAM_WORDTRIS, identifier);
  const send = useCallback<SendUpdate>(
    (update) =>
      sockClient.sendScopeStepAndWaitAsync(
        { type: ScopeType.TEAM_WORDTRIS, teamId },
        update
      ),
    [sockClient, teamId]
  );
  return (
    <WordtrisBoard
      {...props}
      serverState={state ?? null}
      send={canSend ? send : null}
    />
  );
}

/** A piece picked from the tray or the boards, by the cell that was clicked. */
type Selection = { piece: number; anchor: number; rot: Rot };

function WordtrisBoard(
  props: WordtrisProps & {
    /** Null when not synced; the board is then local only. */
    serverState: {
      letters: string[];
      placements: (WordtrisPlacement | null)[];
    } | null;
    send: SendUpdate | null;
  }
) {
  const { pieces, grids, serverState, send } = props;
  const shapes = pieces.map(([fills]) => shapeOf(fills));
  const colorsOf = pieces.map(([fills]) => [...fills.replace(/[.|]/g, "")]);

  const [pendingLetters, editLetters] = usePending<string>(
    send && ((letters) => send({ letters }))
  );
  const [pendingPlaces, editPlaces] = usePending<WordtrisPlacement | null>(
    send && ((place) => send({ place }))
  );
  const letterAt = (i: number) =>
    pendingLetters.get(i) ?? serverState?.letters[i] ?? "";
  const placementOf = (p: number) =>
    pendingPlaces.has(p)
      ? pendingPlaces.get(p)!
      : (serverState?.placements[p] ?? null);
  const place = (p: number, placement: WordtrisPlacement | null) =>
    editPlaces([[p, placement]]);

  const [sel, setSel] = useState<Selection | null>(null);
  const [hover, setHover] = useState<[number, number, number] | null>(null);
  const selPlacement = sel && placementOf(sel.piece);
  const selRot = selPlacement?.rot ?? sel?.rot ?? 0;

  /** covers[grid][r][c]: [piece, cell] on that board cell. */
  const covers = grids.map(() =>
    Array.from({ length: ROWS }, () =>
      Array.from({ length: COLS }, () => [] as [number, number][])
    )
  );
  shapes.forEach((shape, p) => {
    const placement = placementOf(p);
    if (placement)
      cellsOf(shape, placement).forEach(([g, r, c], k) =>
        covers[g]?.[r]?.[c]?.push([p, k])
      );
  });

  /** Pieces on a board cell besides the selection, which moves over itself. */
  const othersAt = (g: number, r: number, c: number) =>
    covers[g][r][c].filter(([p]) => p !== sel?.piece);

  const ghost =
    sel && hover && othersAt(...hover).length === 0
      ? anchoredAt(shapes[sel.piece], sel.anchor, selRot, ...hover)
      : null;
  const ghostOk = ghost && inBounds(shapes[sel!.piece], ghost);
  /** ghostAt[grid][r][c]: the ghost's cell there. */
  const ghostCells = new Map(
    ghost
      ? cellsOf(shapes[sel!.piece], ghost).map(([g, r, c], k) => [
          `${g},${r},${c}`,
          k,
        ])
      : []
  );

  const rotateSel = (by: number) => {
    if (!sel) return;
    const rot = ((selRot + by + 4) % 4) as Rot;
    setSel({ ...sel, rot });
    if (!selPlacement) return;
    // Turn in the SRS box, then try the SRS kicks, then anything within 2
    // cells of the spot shifted back onto the board, nearest first. Take the
    // first spot that overlaps the fewest other pieces.
    const shape = shapes[sel.piece];
    const from = srs(shape, selPlacement.rot);
    const to = srs(shape, rot);
    const turned = {
      ...selPlacement,
      row: selPlacement.row - from.offset[0] + to.offset[0],
      col: selPlacement.col - from.offset[1] + to.offset[1],
      rot,
    };
    const kicks = !to.kicks
      ? [[0, 0]]
      : by > 0
        ? to.kicks[from.state]
        : to.kicks[to.state].map(([x, y]) => [-x, -y]);
    const cells = rotate(shape, rot);
    const h = Math.max(...cells.map(([r]) => r)) + 1;
    const w = Math.max(...cells.map(([, c]) => c)) + 1;
    const row = Math.min(Math.max(turned.row, 0), ROWS - h);
    const col = Math.min(Math.max(turned.col, 0), COLS - w);
    const nearby: WordtrisPlacement[] = [];
    for (let dr = -2; dr <= 2; dr++)
      for (let dc = -2; dc <= 2; dc++)
        if (Math.abs(dr) + Math.abs(dc) <= 2)
          nearby.push({ ...turned, row: row + dr, col: col + dc });
    const dist = (pl: WordtrisPlacement) =>
      Math.abs(pl.row - turned.row) + Math.abs(pl.col - turned.col);
    nearby.sort((a, b) => dist(a) - dist(b));
    const candidates = [
      ...kicks.map(([x, y]) => ({
        ...turned,
        row: turned.row - y,
        col: turned.col + x,
      })),
      ...nearby,
    ].filter((pl) => inBounds(shape, pl));
    const overlap = (pl: WordtrisPlacement) =>
      cellsOf(shape, pl).filter(([g, r, c]) =>
        covers[g][r][c].some(([p]) => p !== sel.piece)
      ).length;
    // Nonempty: the shifted-back spot itself is always on the board.
    let best = candidates[0];
    for (const pl of candidates) if (overlap(pl) < overlap(best)) best = pl;
    place(sel.piece, best);
  };
  const removeSel = () => {
    if (sel && selPlacement) place(sel.piece, null);
    setSel(null);
  };

  const onCellClick = (g: number, r: number, c: number) => {
    const [top] = othersAt(g, r, c);
    if (top) {
      const [piece, anchor] = top;
      setSel({ piece, anchor, rot: placementOf(piece)!.rot });
    } else if (sel) {
      // From the clicked cell, not `hover`: taps may not hover first.
      const shape = shapes[sel.piece];
      const placement = anchoredAt(shape, sel.anchor, selRot, g, r, c);
      if (inBounds(shape, placement)) place(sel.piece, placement);
    }
  };

  // Shortcuts, except while typing letters.
  const keysRef = useRef<(e: KeyboardEvent) => void>(null);
  keysRef.current = (e: KeyboardEvent) => {
    if (!sel || e.ctrlKey || e.metaKey || e.altKey) return;
    if ((e.target as Element).closest("input, textarea")) return;
    if (e.key === "r" || e.key === "R") rotateSel(e.shiftKey ? -1 : 1);
    else if (e.key === "Delete" || e.key === "Backspace") removeSel();
    else if (e.key === "Escape") setSel(null);
    else return;
    e.preventDefault();
  };
  // Clicking anywhere but a piece or the buttons deselects.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => keysRef.current?.(e);
    const onClick = (e: MouseEvent) => {
      if (!(e.target as Element).closest(".wordtris-keep")) setSel(null);
    };
    document.addEventListener("keydown", onKey);
    document.addEventListener("click", onClick);
    return () => {
      document.removeEventListener("keydown", onKey);
      document.removeEventListener("click", onClick);
    };
  }, []);

  const button = (
    symbol: React.ReactNode,
    title: string,
    onClick: () => void
  ) => (
    <Tooltip
      text={title}
      directRef={(refProps) => (
        <button
          {...refProps}
          type="button"
          aria-label={title}
          onClick={onClick}
        >
          {symbol}
        </button>
      )}
    />
  );

  /**
   * The rotate / remove buttons, floating centered above the top of the
   * selection's SRS box, which plain rotations don't move. Placed as a
   * fraction of the board, so it lines up with cells whatever their borders.
   */
  const toolbar = (() => {
    if (!sel || !selPlacement) return null;
    const { offset, size } = srs(shapes[sel.piece], selPlacement.rot);
    const x = selPlacement.col - offset[1] + size / 2;
    // on the row line one above the box, to cover less of any one cell
    const y = selPlacement.row - offset[0] - 1;
    return {
      grid: selPlacement.grid,
      node: (
        <div
          className="wordtris-toolbar wordtris-keep no-copy"
          style={{ left: `${(x / COLS) * 100}%`, top: `${(y / ROWS) * 100}%` }}
          onMouseEnter={() => setHover(null)}
        >
          {button(
            <Twemoji>↪️</Twemoji>,
            "Rotate counterclockwise (Shift+R)",
            () => rotateSel(-1)
          )}
          {button(<Twemoji>📤</Twemoji>, "Remove (Delete)", removeSel)}
          {button(<Twemoji>↩️</Twemoji>, "Rotate clockwise (R)", () =>
            rotateSel(1)
          )}
        </div>
      ),
    };
  })();

  return (
    <>
      <WordtrisPieces
        pieces={pieces}
        letters={pieces.flatMap((_, p) =>
          [0, 1, 2, 3].map((k) => letterAt(4 * p + k))
        )}
        onEdit={(i, value) => {
          if (isValidWordtrisLetter(value)) editLetters([[i, value]]);
        }}
      />
      <div className="wordtris-grids" onMouseLeave={() => setHover(null)}>
        {grids.map(({ text, fills }, g) => {
          const fillRows = fills.split("|");
          const textRows = text.split("|");
          const coverAt = (r: number, c: number) => covers[g][r][c][0];
          /** Each piece placed here, outlined whole as if see-through. */
          const outlineOf = (p: number) => {
            const placement = placementOf(p);
            return placement?.grid === g
              ? outlinePath(
                  cellsOf(shapes[p], placement).map(([, r, c]) => [r, c])
                )
              : "";
          };
          return (
            // The board's size exactly, for the toolbar to position against.
            <div key={g} className="wordtris-board">
              <PuzzleGrid
                text={text}
                fills={fillRows
                  .map((row, r) =>
                    [...row]
                      .map((ch, c) => {
                        const top = coverAt(r, c);
                        return top ? colorsOf[top[0]][top[1]] : ch;
                      })
                      .join("")
                  )
                  .join("|")}
                fillColors={COLORS}
                // Each placed piece outlined whole, overlaps and all, then
                // the selection's outline on top.
                overlay={
                  <>
                    <path
                      className="wordtris-bars"
                      vectorEffect="non-scaling-stroke"
                      d={shapes.map((_, p) => outlineOf(p)).join("")}
                    />
                    {sel ? (
                      <path
                        className="wordtris-bars wordtris-bars-selected"
                        vectorEffect="non-scaling-stroke"
                        d={outlineOf(sel.piece)}
                      />
                    ) : null}
                  </>
                }
                renderCell={(r, c) => {
                  const cover = covers[g][r][c];
                  const ghostK = ghostCells.get(`${g},${r},${c}`);
                  const given = textRows[r][c] !== ".";
                  const top = cover[0];
                  // The ghost stands in for the piece it would move here.
                  const ghostHere = ghostK !== undefined;
                  const layers =
                    (ghostHere
                      ? cover.filter(([p]) => p !== sel!.piece).length + 1
                      : cover.length) + (given ? 1 : 0);
                  const overlapped = layers > 1;
                  return (
                    <>
                      {top && !given ? letterAt(4 * top[0] + top[1]) : null}
                      {ghostHere ? (
                        <>
                          <span
                            className={clsObj({
                              "wordtris-ghost no-copy": true,
                              "wordtris-ghost-bad": !ghostOk,
                            })}
                            style={
                              {
                                "--wordtris-ghost-color": color(
                                  colorsOf[sel!.piece][ghostK]
                                ),
                              } as CSSProperties
                            }
                          >
                            {letterAt(4 * sel!.piece + ghostK)}
                          </span>
                          <CageCell
                            r={r}
                            c={c}
                            inCage={(r2, c2) =>
                              ghostCells.has(`${g},${r2},${c2}`)
                            }
                            className={
                              ghostOk ? undefined : "wordtris-ghost-bad"
                            }
                          />
                        </>
                      ) : null}
                      {overlapped ? (
                        <span className="wordtris-overlap no-copy" />
                      ) : null}
                      <span
                        className={clsObj({
                          "wordtris-hit no-copy": true,
                          "wordtris-keep": !!top || !!sel,
                        })}
                        onMouseEnter={() => setHover([g, r, c])}
                        onClick={() => onCellClick(g, r, c)}
                      />
                    </>
                  );
                }}
              />
              {toolbar?.grid === g ? toolbar.node : null}
            </div>
          );
        })}
      </div>
      <div className="wordtris-controls wordtris-keep no-copy">
        {sel ? (
          <span className="wordtris-controls-clue">{pieces[sel.piece][1]}</span>
        ) : (
          "Letters typed in the pieces above are synced below and with your team."
        )}
      </div>
      <div className="wordtris-tray no-copy">
        {pieces.map(([fills, clue], p) => {
          const rows = fills.split("|");
          let k = 0;
          return (
            <Tooltip key={p} text={clue} className="wordtris-tray-slot">
              <div
                className={clsObj({
                  "wordtris-tray-piece": true,
                  "wordtris-placed": !!placementOf(p),
                  "wordtris-tray-selected": sel?.piece === p,
                })}
              >
                <table className="puzzle-grid">
                  <tbody>
                    {rows.map((row, r) => (
                      <tr key={r}>
                        {[...row].map((ch, c) => {
                          if (ch === ".")
                            return <td key={c} className="hidden-cell" />;
                          const anchor = k++;
                          return (
                            <td
                              key={c}
                              className="wordtris-keep"
                              style={{ backgroundColor: color(ch) }}
                              onClick={() => {
                                const placement = placementOf(p);
                                setSel({
                                  piece: p,
                                  anchor,
                                  rot: placement?.rot ?? 0,
                                });
                              }}
                            >
                              {letterAt(4 * p + anchor)}
                            </td>
                          );
                        })}
                      </tr>
                    ))}
                  </tbody>
                </table>
                {sel?.piece === p ? (
                  <svg
                    className="wordtris-tray-outline"
                    viewBox={`0 0 ${Math.max(...rows.map((row) => row.length))} ${rows.length}`}
                    preserveAspectRatio="none"
                  >
                    <path
                      className="wordtris-bars wordtris-bars-selected"
                      vectorEffect="non-scaling-stroke"
                      d={outlinePath(shapes[p])}
                    />
                  </svg>
                ) : null}
              </div>
            </Tooltip>
          );
        })}
      </div>
    </>
  );
}
