import { FC, HTMLProps, SVGProps, CSSProperties } from "react";
import Twemoji from "react-twemoji";
import { AnimatePresence, motion } from "framer-motion";

import { PuzzleMetadata, PuzzleType } from "sockapi/puzzle-data";
import CHARACTER_COLORS from "sockapi/character-colors";
import Tooltip from "components/Tooltip";
import { useAccessibleRounds } from "stores/ScopeStateStore";

import OpenCannedHint from "images/icons/can-open.svg?react";
import CannedHint from "images/icons/can-closed.svg?react";

export enum IconType {
  CANNED_HINT = "canned_hint",
  OPEN_CANNED_HINT = "open_canned_hint",
}

// TS believes it's a string, but it's actually a react component
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const iconToSvg: { [key in IconType]: any } = {
  [IconType.CANNED_HINT]: CannedHint,
  [IconType.OPEN_CANNED_HINT]: OpenCannedHint,
} as const;

export function Icon(props: { icon: IconType } & SVGProps<SVGSVGElement>) {
  const { icon, className = "", ...otherProps } = props;
  const svg = iconToSvg[icon] as FC<SVGProps<SVGSVGElement>>;
  return svg({ className: `emoji ${className}`, ...otherProps });
}

export const Emoji = {
  STORY: "💬",
  PUZZLE: "🧩",
  PUZZLE_SOLVED: "✅",
  PUZZLE_UNSEEN: "🆕",
  META: "👥",
  META_SOLVED: "🫂",
  BIG_META: "💟",
  HINT: "💡",
  FREE_ANSWER: "🎁",
  SOLUTION: "📚",
  STATS: "🧮",
};

export function typeIcon(type: PuzzleType): string {
  switch (type) {
    case PuzzleType.STORY:
      return Emoji.STORY;
    case PuzzleType.PUZZLE:
      return Emoji.PUZZLE;
  }
}

export function PuzzleIcon(props: { puzData: PuzzleMetadata }) {
  const { puzData } = props;
  const { isBigMeta = false, isMeta = false, type } = puzData;
  return (
    <Twemoji tag="span" options={{ folder: "svg", ext: ".svg" }}>
      {isBigMeta ? Emoji.BIG_META : isMeta ? Emoji.META : typeIcon(type)}
    </Twemoji>
  );
}

const CharacterIconType = {
  default: ".webp",
  icon: "-icon.svg",
};

export type CharacterIconSpec = {
  characterId: string;
  imageOverride?: string;
  nameOverride?: string;
};

export function CharacterIcon(
  props: {
    type?: keyof typeof CharacterIconType;
    className?: string;
    tooltip?: true;
  } & CharacterIconSpec
) {
  const { type = "default", className = "", tooltip = false } = props;
  const { characterId, imageOverride, nameOverride } = props;
  const rounds = useAccessibleRounds() ?? {};
  const unknown = characterId in CHARACTER_COLORS && !(characterId in rounds);
  const image = imageOverride ?? characterId + CharacterIconType[type];
  const name =
    (unknown ? null : (nameOverride ?? rounds[characterId]?.displayName)) ??
    "???";

  const img = (
    <img
      className={`character-portrait ${unknown ? "unknown" : ""} ${className}`}
      src={`/static/images/${image}`}
      alt={name}
      draggable={false}
    />
  );
  return tooltip ? <Tooltip text={name}>{img}</Tooltip> : img;
}

export function ShipIcon(
  props: { ship: string[] } & HTMLProps<HTMLDivElement>
) {
  const { ship, style = {}, ...otherProps } = props;
  const rounds = useAccessibleRounds() ?? {};
  const names = ship.map((char) => rounds[char]?.displayName ?? "???");
  const colors = ship.map(
    (char) => (CHARACTER_COLORS as Record<string, string>)[char]
  );

  return (
    <Tooltip
      className="character-ship"
      text={names.join(" + ") || "(none selected)"}
      style={
        {
          ...style,
          "--ship-left": colors[0],
          "--ship-right": colors[1],
        } as CSSProperties
      }
      {...otherProps}
    >
      <AnimatePresence mode="popLayout">
        {(ship.length === 0 ? [""] : ship).map((char, i) => (
          <motion.span
            key={char}
            layout
            initial={{ opacity: 0, scale: 0 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0 }}
            transition={{ duration: 1, type: "spring" }}
          >
            {char ? (
              <CharacterIcon
                type="icon"
                characterId={char}
                className={i ? "flip" : ""}
              />
            ) : (
              "—"
            )}
          </motion.span>
        ))}
      </AnimatePresence>
    </Tooltip>
  );
}
