import { useEffect, useState, ReactNode } from "react";
import Twemoji from "react-twemoji";
import { CharacterIcon } from "components/Icon";
import Modal from "components/Modal";
import Tooltip from "components/Tooltip";
import { CafePage } from "pages/WorldBase";
import GALLERY_IMAGES from "pages/gallery-images.json";
import "./GalleryPage.css";

/**
 * Image names under /static/images/cutscenes/, without the extension. The
 * lists are generated by admin-util/process-art.py from the Krita export.
 */
const SECTIONS: {
  title: string;
  icon: ReactNode;
  kind: "scene" | "sprite";
  images: string[];
}[] = [
  {
    title: "CGs",
    icon: <Twemoji>🖼️</Twemoji>,
    kind: "scene",
    images: GALLERY_IMAGES.cgs,
  },
  {
    title: "Backgrounds",
    icon: <Twemoji>🏞️</Twemoji>,
    kind: "scene",
    images: GALLERY_IMAGES.backgrounds,
  },
  ...(
    [
      ["Camille", "camille"],
      ["DJ", "dj"],
      ["Lam", "lam"],
      ["Taylor", "taylor"],
    ] as const
  ).map(([title, characterId]) => ({
    title,
    icon: (
      <CharacterIcon type="icon" className="emoji" characterId={characterId} />
    ),
    kind: "sprite" as const,
    images: GALLERY_IMAGES.characters[characterId],
  })),
];

const ALL_IMAGES = SECTIONS.flatMap(({ images }) => images);

const imageUrl = (name: string) => `/static/images/cutscenes/${name}.webp`;

function GalleryPage() {
  // Index into ALL_IMAGES of the image shown full size.
  const [viewing, setViewing] = useState<number | null>(null);
  const step = (delta: number) =>
    setViewing((index) =>
      index === null
        ? null
        : (index + delta + ALL_IMAGES.length) % ALL_IMAGES.length
    );

  useEffect(() => {
    const worldBg = document.querySelector(".world-bg") as HTMLElement | null;
    if (
      worldBg !== null &&
      viewing !== null &&
      viewing < GALLERY_IMAGES.cgs.length + GALLERY_IMAGES.backgrounds.length
    )
      worldBg.style.backgroundImage = `url(${imageUrl(ALL_IMAGES[viewing])})`;
  }, [viewing]);

  return (
    <CafePage
      heading="Gallery"
      toolbar={
        <div className="button-squish-zone">
          {SECTIONS.map(({ title, icon }) => (
            <Tooltip text={title} placement="left" key={title}>
              <button
                onClick={() => {
                  document
                    .querySelector(`h2[data-section="${title}"]`)
                    ?.scrollIntoView({
                      behavior: "smooth",
                    });
                }}
              >
                {icon}
              </button>
            </Tooltip>
          ))}
        </div>
      }
    >
      {SECTIONS.map(({ title, kind, images }) => (
        <section key={title} className="gallery-section">
          <h2 className="cafe-heading" data-section={title}>
            {title}
          </h2>
          <ul className="gallery-grid" data-kind={kind}>
            {images.map((name) => (
              <li key={name}>
                <Tooltip text={name}>
                  <button
                    type="button"
                    aria-label={`View ${name}`}
                    onClick={() => setViewing(ALL_IMAGES.indexOf(name))}
                  >
                    <img src={imageUrl(name)} alt="" loading="lazy" />
                  </button>
                </Tooltip>
              </li>
            ))}
          </ul>
        </section>
      ))}
      {viewing === null ? null : (
        <Modal
          aria-label={ALL_IMAGES[viewing]}
          className="gallery-viewer"
          onClose={() => setViewing(null)}
          onKeyDown={(e) => {
            if (e.ctrlKey || e.metaKey || e.altKey) return;
            if (e.key === "ArrowLeft") step(-1);
            else if (e.key === "ArrowRight") step(1);
            else return;
            e.preventDefault();
          }}
          footerChildren={
            <>
              <button onClick={() => step(-1)} aria-label="Previous image">
                ◀︎
              </button>
              <button onClick={() => step(1)} aria-label="Next image">
                ▶︎
              </button>
            </>
          }
        >
          <button
            className="genetic-zoom-close"
            aria-label="Close"
            onClick={() => setViewing(null)}
          >
            ×
          </button>
          <img src={imageUrl(ALL_IMAGES[viewing])} alt="" />
        </Modal>
      )}
    </CafePage>
  );
}

export default GalleryPage;
