import AnswerListChecker from "components/PuzzlePage/checkers/AnswerListChecker";

const AXES: [string, string][] = [
  ["CHECKS", "BALANCES"],
  ["FAIR", "SQUARE"],
  ["FISH", "CHIPS"],
  ["HELL", "HIGH WATER"],
  ["KICKING", "SCREAMING"],
  ["PRIDE", "JOY"],
  ["SMOKE", "MIRRORS"],
  ["SNAKES", "LADDERS"],
];

export default function WavelengthsChecker() {
  return (
    <AnswerListChecker
      label="Paste the two axes of each grid, one grid per line."
      answers={AXES.map(([x, y]) => [`${x} ${y}`, `${x} AND ${y}`])}
    />
  );
}
