import { useEffect } from "react";
import { ScopeType } from "sockapi/scope-types";
import { useTeamId, useSockClient } from "stores/ServerInteractionStore";
import {
  useTeamScopeState,
  usePuzzleData,
  useScopeStateResolvable,
} from "stores/ScopeStateStore";
import { useNavStore } from "stores/NavStore";
import { useUpdateBrowserWidePersistentState } from "stores/BrowserWidePersistentState";
import { ShipIcon } from "components/Icon";
import { Spinner, LargeSpinner } from "components/Loading";
import "./VictoryPage.css";

function VictoryPage() {
  const sockClient = useSockClient();
  const teamId = useTeamId();
  const teamScopeState = useTeamScopeState();
  const finalCutscenePuzName =
    Object.values(teamScopeState?.puzzles ?? {}).find(
      ({ isFinalCutscene = false }) => isFinalCutscene
    )?.puzName ?? null;
  const setRedirectRoute = useNavStore((state) => state.setRedirectRoute);
  const puzData = usePuzzleData(finalCutscenePuzName);
  const updateBrowserWidePersistentState =
    useUpdateBrowserWidePersistentState();
  const shipState = useScopeStateResolvable(
    ScopeType.TEAM_SHIP,
    teamId !== null ? { teamId } : null
  );

  useEffect(() => {
    if (teamScopeState === null) return;
    // If the final cutscene is not unlocked, then the user should
    // not have access to this page.
    if (finalCutscenePuzName === null) setRedirectRoute({ route: "puzzles" });
  }, [teamScopeState, finalCutscenePuzName, setRedirectRoute]);

  useEffect(() => {
    if (finalCutscenePuzName === null) return;
    if (teamId === null) return;
    if (puzData === null) return;
    const puzName = finalCutscenePuzName;
    updateBrowserWidePersistentState({
      completedStoryBeats: { [puzName]: true },
    });
    if (puzData.solveTime === undefined)
      sockClient
        .sendScopeStepAndWaitAsync(
          {
            type: ScopeType.TEAM_CUTSCENES,
            teamId,
          },
          {
            setCutsceneComplete: puzName,
          }
        )
        .catch(console.error);
  }, [
    finalCutscenePuzName,
    sockClient,
    teamId,
    updateBrowserWidePersistentState,
    puzData,
  ]);

  if (
    teamId === null ||
    finalCutscenePuzName === null ||
    puzData?.solveTime === undefined
  )
    return <LargeSpinner />;
  return (
    <div className="victory-page">
      <div className="victory-box">
        <h1 className="cafe-heading">Congratulations!</h1>
        <p className="note-box">
          Thank you for attending our reunion at Galactic Puzzle Hunt 2026!
          You’ll receive more information via email soon. Please fill out our{" "}
          <a href="https://docs.google.com/forms/d/e/1FAIpQLSfJmaE3uplQSIxh0LR-45cWza_2fQvsjLvS8OvxQDrPMBSRcw/viewform">
            feedback form
          </a>{" "}
          as well!
        </p>
        <p className="note-box">
          Solutions for puzzles you’ve solved are now available (with the
          exception of some that might spoil you on puzzles you haven’t yet
          solved).
        </p>
      </div>
      <div className="victory-ship">
        <div className="victory-box">
          <h3 className="cafe-heading">Pick your ship!</h3>
          <p className="note-box">
            Which pair of characters does your team most want to see get
            together? Or, choose your favorite single character. Come back here
            to update or clear your choice anytime.
          </p>
        </div>
        {shipState === null ? <Spinner inline /> : <ShipIcon {...shipState} />}
      </div>
    </div>
  );
}

export default VictoryPage;
