import { ReactNode, useId, useState } from "react";
import Twemoji from "react-twemoji";

import "./AnswerListChecker.css";

export type CheckerAnswer = string | string[];

export const normalizeCheckerInput = (s: string): string =>
  s
    .normalize("NFD")
    .replace(/\p{M}/gu, "")
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, "");

const alternates = (answer: string | string[]): string[] =>
  (typeof answer === "string" ? [answer] : answer).map(normalizeCheckerInput);

const cellsOf = (line: string): string[] => {
  const cells = line.split("\t").map(normalizeCheckerInput).filter(Boolean);
  if (cells.length > 1) cells.push(cells.join(""));
  return cells;
};

function checkLines(
  lines: string[][],
  answers: CheckerAnswer[],
  ordered: boolean
): boolean[] {
  const expected = answers.map(alternates);
  const matches = (cells: string[], j: number) =>
    expected[j].some((alt) => cells.includes(alt));

  if (!ordered) {
    const used = expected.map(() => false);
    return lines.map((cells) => {
      const j = expected.findIndex((_, j) => !used[j] && matches(cells, j));
      if (j === -1) return false;
      used[j] = true;
      return true;
    });
  }

  const n = lines.length;
  const m = expected.length;
  if (n === m) return lines.map((cells, j) => matches(cells, j));

  // Some lines are missing, so line up as many as we can, in order: lcs lmao.
  // Unknown lines always take the next answer's place.
  const isUnknown = (i: number) => lines[i].length === 0;
  const best = Array.from({ length: n + 1 }, () =>
    Array<number>(m + 1).fill(0)
  );
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      best[i][j] = isUnknown(i)
        ? best[i + 1][j + 1]
        : matches(lines[i], j)
          ? 1 + best[i + 1][j + 1]
          : Math.max(best[i + 1][j], best[i][j + 1]);
    }
  }
  const results: boolean[] = [];
  let [i, j] = [0, 0];
  while (i < n) {
    if (isUnknown(i)) {
      results.push(false);
      i++;
      if (j < m) j++;
    } else if (j < m && matches(lines[i], j)) {
      results.push(true);
      i++;
      j++;
    } else if (j === m || best[i][j] === best[i + 1][j]) {
      results.push(false);
      i++;
    } else {
      j++;
    }
  }

  return results;
}

export type CheckResult = { summary: ReactNode; details?: ReactNode };

/**
 * A textarea with a Check button. `check` runs on the text as of the last
 * click, and returns null if there's nothing to say. Pass `text` and `setText`
 * to fill the textarea from elsewhere.
 */
export function CheckerForm(props: {
  label: ReactNode;
  check: (text: string) => CheckResult | null;
  text?: string;
  setText?: (text: string) => void;
}) {
  const { label, check } = props;
  const id = useId();
  const [ownText, setOwnText] = useState("");
  const [text, setText] =
    props.text !== undefined && props.setText !== undefined
      ? [props.text, props.setText]
      : [ownText, setOwnText];
  const [checkedText, setCheckedText] = useState<string | null>(null);
  const result =
    checkedText === null
      ? null
      : (check(checkedText) ?? { summary: "Nothing to check." });

  return (
    <form
      className="answer-list-checker"
      onSubmit={(e) => {
        e.preventDefault();
        setCheckedText(text);
      }}
    >
      <label htmlFor={id}>{label}</label>
      <textarea
        id={id}
        rows={6}
        value={text}
        onChange={(e) => setText(e.target.value)}
        spellCheck={false}
      />
      <div className="answer-list-checker-controls">
        <span aria-live="polite">{result?.summary}</span>
        <button type="submit" disabled={text.trim() === ""}>
          Check
        </button>
      </div>
      {result?.details}
    </form>
  );
}

export type CheckStatus = "correct" | "partial" | "wrong";

/** The same marks as previous guesses: right, a message, or wrong. */
const STATUS_MARKS: Record<CheckStatus, string> = {
  correct: "✅",
  partial: "💬",
  wrong: "❌",
};

export function CheckerResultList(props: {
  results: { status: CheckStatus; content: ReactNode }[];
}) {
  return (
    <ul className="answer-list-checker-results">
      {props.results.map(({ status, content }, i) => (
        <li key={i}>
          <Twemoji tag="span" className="answer-list-checker-mark">
            {STATUS_MARKS[status]}
          </Twemoji>
          <span>{content}</span>
        </li>
      ))}
    </ul>
  );
}

export type CellStatus = "right" | "wrong" | "unknown";

/** A grid of entries, each colored by whether it's right. */
export function CheckerGrid(props: {
  cells: { text: string; status: CellStatus }[][];
  title?: ReactNode;
  note?: ReactNode;
}) {
  return (
    <figure className="checker-grid">
      {props.title !== undefined && <figcaption>{props.title}</figcaption>}
      <table>
        <tbody>
          {props.cells.map((row, r) => (
            <tr key={r}>
              {row.map(({ text, status }, c) => (
                <td key={c} className={`checker-cell-${status}`}>
                  {text}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
      {props.note && <div className="checker-grid-note">{props.note}</div>}
    </figure>
  );
}

/**
 * Answers one per line. Blank lines and lines of only ?s are unknowns: they
 * never match, but in ordered mode they hold their answer's place.
 */
export default function AnswerListChecker(props: {
  label: ReactNode;
  answers: CheckerAnswer[];
  ordered?: boolean;
  text?: string;
  setText?: (text: string) => void;
}) {
  const { label, answers, ordered = false, text, setText } = props;
  return (
    <CheckerForm
      label={label}
      text={text}
      setText={setText}
      check={(text) => {
        // Leading blank lines are unknowns, but trailing ones are just slack.
        const allLines = text
          .trimEnd()
          .split("\n")
          .map((line) => ({ line: line.trim(), cells: cellsOf(line) }));
        if (allLines.every(({ cells }) => cells.length === 0)) return null;
        const isMatched = checkLines(
          allLines.map(({ cells }) => cells),
          answers,
          ordered
        );
        const lines = allLines
          .map((line, i) => ({ ...line, isCorrect: isMatched[i] }))
          .filter(({ cells }) => cells.length > 0);
        return {
          summary: (
            <>
              <b>
                {lines.filter(({ isCorrect }) => isCorrect).length} of{" "}
                {answers.length}
              </b>{" "}
              correct.
            </>
          ),
          details: (
            <CheckerResultList
              results={lines.map(({ line, isCorrect }) => ({
                status: isCorrect ? "correct" : "wrong",
                content: line,
              }))}
            />
          ),
        };
      }}
    />
  );
}
