import { useCallback, useEffect, useRef, useState } from "react";

// Counts revealed characters over time, following a per-character schedule
// (see parseDialogue); the caller slices its text at `revealed`.

export type TypewriterOptions = {
  /** When false, the whole thing is revealed instantly (e.g. reduced motion). */
  enabled?: boolean;
  /** When set, nothing is output for this many ms. */
  initialPause?: number;
};

export type Typewriter = {
  /** Number of characters currently revealed. */
  revealed: number;
  /** True once every character is shown. */
  isDone: boolean;
  /** True once the line has been fully shown for ADVANCE_DELAY_MS. */
  canAdvance: boolean;
  /** Reveal everything immediately (used when the reader clicks to hurry). */
  finish: () => void;
  /** True if we are in the initial pause stage. */
  paused: boolean;
};

const ADVANCE_DELAY_MS = 300;

/** How many schedule entries are at or before `ms`. */
const countRevealed = (schedule: readonly number[], ms: number): number => {
  let lo = 0;
  let hi = schedule.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (schedule[mid] <= ms) lo = mid + 1;
    else hi = mid;
  }
  return lo;
};

/**
 * @param schedule  the ms at which each character appears, ascending (its
 *                  length is the total to reveal); keep it referentially stable
 * @param resetKey  changing this restarts the animation from zero (pass the
 *                  line's text or index so each new line re-types)
 */
export function useTypewriter(
  schedule: readonly number[],
  resetKey: string | number,
  options: TypewriterOptions = {}
): Typewriter {
  const { enabled = true, initialPause = 0 } = options;
  const length = schedule.length;

  // The revealed count, tagged with the resetKey it belongs to — one atomic
  // piece of state, so a count left over from the previous line can be detected
  // before the effect re-syncs.
  const [state, setState] = useState<{
    key: string | number;
    revealed: number;
    paused: boolean;
  }>({
    key: resetKey,
    revealed: enabled ? 0 : length,
    paused: enabled ? initialPause > 0 : false,
  });

  // Timestamp of when the animation started
  const startRef = useRef<number | null>(null);
  // Handle to our outstanding `requestAnimationFrame` call (so we can cancel it)
  const rafRef = useRef<number | null>(null);

  useEffect(() => {
    // Reset the typewriter when an input changes
    startRef.current = null;
    if (!enabled) {
      // Just show the whole text
      setState({ key: resetKey, revealed: length, paused: false });
      return;
    }
    setState({ key: resetKey, revealed: 0, paused: initialPause > 0 });

    // Every frame, compute whether we should reveal another letter
    const tick = (now: number) => {
      if (startRef.current === null) startRef.current = now;
      const elapsed = now - startRef.current - initialPause;
      const next = countRevealed(schedule, Math.max(0, elapsed));
      setState({ key: resetKey, revealed: next, paused: elapsed < 0 });
      if (next < length) rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);

    // Cleanup; cancel the outstanding `requestAnimationFrame`
    return () => {
      if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
    };
  }, [schedule, length, resetKey, enabled, initialPause]);

  // "finish" just reveals the whole text
  const finish = useCallback(() => {
    if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
    setState((s) => ({ key: s.key, revealed: length, paused: false }));
  }, [length]);

  // On the first frame after `resetKey` changes, the effect hasn't run yet, so
  // the stored count still belongs to the previous line. Show the reset value
  // for that one frame — otherwise the new (shorter) line flashes fully-typed
  // before the typewriter starts.
  const revealed =
    state.key === resetKey ? state.revealed : enabled ? 0 : length;

  const isDone = revealed >= length;

  const [advanceableKey, setAdvanceableKey] = useState<string | number | null>(
    null
  );
  useEffect(() => {
    if (!isDone) return;
    const timeout = setTimeout(
      () => setAdvanceableKey(resetKey),
      ADVANCE_DELAY_MS
    );
    return () => clearTimeout(timeout);
  }, [isDone, resetKey]);

  return {
    revealed,
    isDone,
    canAdvance: isDone && advanceableKey === resetKey,
    finish,
    paused: state.paused,
  };
}
