// Boring pages are centered and look like Django pages.
// The page extends vertically and uses browser scroll.
export function BoringPage({
  heading,
  children,
  className = "",
  ...otherProps
}: PropsWithChildren<{ heading: ReactNode } & HTMLProps<HTMLDivElement>>) {
  return (
    <div className={`boring-page ${className}`} {...otherProps}>
      <h1>{heading}</h1>
      <main>{children}</main>
    </div>
  );
}

// Wide pages expand to 100% width and limit to 100% height.
// The contents handle their own scrolling.
export function WidePage({
  children,
  className = "",
  ...otherProps
}: PropsWithChildren<HTMLProps<HTMLDivElement>>) {
  return (
    <main className={`wide-page ${className}`} {...otherProps}>
      {children}
    </main>
  );
}

// consumers provide these so we can animate smoothly between them while
// retaining shared elements
const CafeSlotsContext = createContext({
  title: null,
  toolbar: null,
  form: null,
} as {
  title: HTMLElement | null;
  toolbar: HTMLElement | null;
  form: HTMLElement | null;
});

type Sized = { el: HTMLElement; box: HTMLElement };

/**
 * Height keyframes for the title and the page body (each `box`) to follow
 * their content (`el`). They're measured together, and against where the
 * frame will be once it has scrolled to the top (`toTop`, while CafeFrame's
 * scroll tween runs): the part of a change below the viewport is cut, since a
 * 5000px puzzle shrinking to a 300px hints page would otherwise spend nearly
 * the whole tween off screen, then snap. So we tween only the visible part,
 * then set the real height at the end. The body's top moves by however much
 * the title will grow or shrink.
 */
function useFrameHeights(
  title: Sized | null,
  body: Sized | null,
  getViewport: () => HTMLElement | undefined,
  toTop: RefObject<boolean>,
  pathname: string
): { title: number[] | null; body: number[] | null } {
  const [keyframes, setKeyframes] = useState<{
    title: number[] | null;
    body: number[] | null;
  }>({ title: null, body: null });

  useEffect(() => {
    if (title === null || body === null) return;
    let fallback: ReturnType<typeof setTimeout> | undefined;
    const measure = (force: boolean) => {
      clearTimeout(fallback);
      // A page still loading measures as a spinner; tweening to that and back
      // is worse than starting a moment late, unless it's still loading then.
      if (
        !force &&
        toTop.current &&
        body.el.querySelector(".spinnything") !== null
      ) {
        fallback = setTimeout(() => {
          measure(true);
        }, 300);
        return;
      }
      const scroll = toTop.current ? (getViewport()?.scrollTop ?? 0) : 0;
      // Unrounded, unlike offsetHeight: a rounded title leaves a hairline
      // between the cap and the page when the page top is fractional.
      const rect = (el: HTMLElement) => el.getBoundingClientRect();
      // Visible within the scroller, which moves with the frame: measured
      // against the window, a frame still rising in would come up short.
      const viewport = getViewport();
      const viewTop = viewport === undefined ? 0 : rect(viewport).top;
      const viewHeight = viewport?.clientHeight ?? window.innerHeight;
      const frames = ({ el, box }: Sized, shift: number) => {
        const now = rect(box);
        const to = rect(el).height;
        const visible = (top: number) =>
          Math.max(0, viewHeight - (top - viewTop));
        return [
          Math.min(now.height, visible(now.top)),
          Math.min(to, visible(now.top + shift)),
          to,
        ];
      };
      const titleGrowth = rect(title.el).height - rect(title.box).height;
      setKeyframes({
        title: frames(title, scroll),
        body: frames(body, scroll + titleGrowth),
      });
    };
    const observer = new ResizeObserver(() => {
      measure(false);
    });
    observer.observe(title.el);
    observer.observe(body.el);
    return () => {
      observer.disconnect();
      clearTimeout(fallback);
    };
    // pathname: observing afresh measures at once, so every page change gets
    // keyframes, and with them the scroll tween, even at the same size.
  }, [title, body, getViewport, toTop, pathname]);

  return keyframes;
}

/**
 * Holds the router still for a scene on its way out. These UNSAFE_ contexts
 * are the ones <Routes location={...}> sets, which a data router has no public
 * equivalent for.
 */
function FrozenRoute({ children }: PropsWithChildren) {
  const isPresent = useIsPresent();
  const location = use(UNSAFE_LocationContext);
  const route = use(UNSAFE_RouteContext);
  const [frozen, setFrozen] = useState({ location, route });
  if (isPresent && (frozen.location !== location || frozen.route !== route))
    setFrozen({ location, route });

  return (
    <UNSAFE_LocationContext value={frozen.location}>
      <UNSAFE_RouteContext value={frozen.route}>{children}</UNSAFE_RouteContext>
    </UNSAFE_LocationContext>
  );
}

/** Cafe content that fades through: the old fades out, then the new rises in. */
function CafeScene({
  ref,
  children,
}: PropsWithChildren<{ ref?: Ref<HTMLDivElement> }>) {
  const isPresent = useIsPresent();
  const { fadeThrough } = useMotion();

  return (
    <motion.div
      className="cafe-scene"
      data-exiting={isPresent ? undefined : ""}
      ref={ref}
      {...fadeThrough("medium")}
    >
      <FrozenRoute>{children}</FrozenRoute>
    </motion.div>
  );
}

/** Cafe content outside the scene, fading through in step with it. */
function CafeSlot({
  className,
  children,
}: PropsWithChildren<{ className: string }>) {
  const isPresent = useIsPresent();
  // Labels come from the enclosing CafeScene; only the variants are needed.
  const { variants } = useMotion().fadeThrough("medium", {
    rise: "0em",
  });

  return (
    <motion.div
      className={className}
      data-exiting={isPresent ? undefined : ""}
      variants={variants}
    >
      {children}
    </motion.div>
  );
}

/** Subpages of one cafe page, swapping without disturbing the page around them. */
export function CafeSubpages({ children }: PropsWithChildren) {
  const { pathname } = useLocation();

  return (
    <div className="cafe-substack">
      <AnimatePresence initial={false}>
        <CafeScene key={pathname}>{children}</CafeScene>
      </AnimatePresence>
    </div>
  );
}

const PUZZLE_SUBPAGES = new Set<string>([
  "puzzle",
  "solution",
  "hints",
  "stats",
] satisfies RouteName[]);

function useSceneKey(): string {
  const { pathname } = useLocation();
  const match = useMatches().findLast(({ id }) => PUZZLE_SUBPAGES.has(id));
  return match === undefined ? pathname : `puzzle-${match.params.slug ?? ""}`;
}

/**
 * The frame cafe pages live in: it outlives the page inside it, so the box can
 * animate between content sizes instead of jump-cutting. Pages still declare
 * their own title, toolbar and answer form through <CafePage>, which fills in
 * the slots here; two pages can fill a slot at once, while one fades through.
 */
export function CafeFrame({ children }: PropsWithChildren) {
  // Heights and scroll move in step; one transition, kept stable for effects.
  const heightDuration = useMotion().duration("medium");
  const heightTween = useMemo(
    () => ({ duration: heightDuration, ease: EASE.standard }),
    [heightDuration]
  );
  // please don't ask me how this slop works
  const isPresent = useIsPresent();
  const liveSceneKey = useSceneKey();
  const [sceneKey, setSceneKey] = useState(liveSceneKey);
  if (isPresent && sceneKey !== liveSceneKey) setSceneKey(liveSceneKey);
  const inRound = useRouteMatch("round") !== null;
  const [pinned, setPinned] = useState(inRound);
  if (isPresent && pinned !== inRound) setPinned(inRound);
  const [title, setTitle] = useState<HTMLElement | null>(null);
  const [toolbar, setToolbar] = useState<HTMLElement | null>(null);
  const [form, setForm] = useState<HTMLElement | null>(null);
  const slots = useMemo(
    () => ({ title, toolbar, form }),
    [title, toolbar, form]
  );
  const [scene, setScene] = useState<HTMLElement | null>(null);
  // The exiting scene unmounts later than the entering one mounts, and its ref
  // fires with null on the way out; the latest live scene is the one to size to.
  const keepScene = useCallback((el: HTMLDivElement | null) => {
    if (el !== null) setScene(el);
  }, []);
  const [stack, setStack] = useState<HTMLElement | null>(null);
  // Set directly by the jump below; motion would re-render a style write away.
  const stackHeight = useMotionValue<number | string>("auto");
  const [titleBox, setTitleBox] = useState<HTMLElement | null>(null);
  const sizedTitle = useMemo(
    () =>
      title === null || titleBox === null ? null : { el: title, box: titleBox },
    [title, titleBox]
  );
  const sizedBody = useMemo(
    () => (scene === null || stack === null ? null : { el: scene, box: stack }),
    [scene, stack]
  );

  // The frame scrolls inside .cafe-outer, which <ScrollRestoration>
  // doesn't know about. Without this, a page change mid-scroll keeps the offset
  // until the exiting page unmounts and the offset gets clamped. Native smooth
  // scrolling is too slow to beat that, so this runs on the pages' own tween.
  const scrollerRef = useRef<HTMLDivElement>(null);
  const getViewport = useCallback(() => scrollerRef.current ?? undefined, []);
  const toTopRef = useRef(false);
  const { pathname: livePathname } = useLocation();
  const [pathname, setPathname] = useState(livePathname);
  if (isPresent && pathname !== livePathname) setPathname(livePathname);
  // The page itself doesn't scroll (its gutter would sit outside .cafe-bg), so
  // hand keyboard scrolling to the frame: on load, and when a page change
  // drops focus with the exiting page. Leave anyone typing alone.
  useEffect(() => {
    if (
      document.activeElement?.closest(
        "input, textarea, select, [contenteditable]"
      )
    )
      return;
    scrollerRef.current?.focus({ preventScroll: true });
  }, [pathname]);
  const heights = useFrameHeights(
    sizedTitle,
    sizedBody,
    getViewport,
    toTopRef,
    pathname
  );
  // Before the new page is measured, so its heights land at the top.
  useLayoutEffect(() => {
    toTopRef.current = true;
    // From deep in a long page, jump most of the way up at once rather than
    // tweening thousands of pixels: the old page is held where it was and the
    // body's bottom edge stays put, so the jump is hidden by the crossfade.
    // What's left keeps the head just off screen, or half a screen at least.
    const viewport = getViewport();
    if (viewport === undefined || stack === null) return;
    const bodyTop = stack.getBoundingClientRect().top + viewport.scrollTop;
    const excess =
      viewport.scrollTop - Math.max(bodyTop, viewport.clientHeight / 2);
    if (excess <= 0) return;
    viewport.scrollTop -= excess;
    stackHeight.set(stack.getBoundingClientRect().height - excess);
    for (const scene of stack.querySelectorAll<HTMLElement>(
      ".cafe-scene[data-exiting]"
    )) {
      if (scene.parentElement?.closest(".cafe-scene[data-exiting]") != null)
        continue;
      const top = parseFloat(scene.style.top) || 0;
      scene.style.setProperty("top", `${top - excess}px`);
    }
  }, [pathname, getViewport, stack, stackHeight]);
  // Started (and restarted) with the height tweens rather than on the page
  // change, which comes a render or more earlier, and eased like them: the
  // page's edges are sums of the three, and only move one way when in step.
  // A layout effect, to start in the same task as the height tweens.
  useLayoutEffect(() => {
    const viewport = getViewport();
    if (!toTopRef.current || viewport === undefined) return;
    const controls = animate(viewport.scrollTop, 0, {
      ...heightTween,
      onUpdate: (top) => {
        viewport.scrollTop = top;
      },
      onComplete: () => {
        toTopRef.current = false;
      },
    });
    return () => {
      controls.stop();
    };
  }, [heights, heightTween, getViewport]);

  return (
    <CafeSlotsContext value={slots}>
      <div className="cafe-frame" data-pinned={pinned ? "" : undefined}>
        <div className="cafe-outer" ref={scrollerRef} tabIndex={-1}>
          <div className="cafe-page">
            <div className="cafe-head">
              <Arrow side="left" />
              <div className="cafe-head-content">
                <motion.h1
                  ref={setTitleBox}
                  animate={{ height: heights.title ?? "auto" }}
                  transition={{ ...heightTween, times: [0, 1, 1] }}
                >
                  <div className="cafe-title" ref={setTitle} />
                </motion.h1>
                <div className="cafe-cap" />
              </div>
            </div>
            <div className="cafe-body">
              <main className="cafe-inner">
                <motion.div
                  className="cafe-stack"
                  ref={setStack}
                  style={{ height: stackHeight }}
                  animate={{ height: heights.body ?? "auto" }}
                  transition={{ ...heightTween, times: [0, 1, 1] }}
                >
                  <AnimatePresence initial={false}>
                    <CafeScene key={sceneKey} ref={keepScene}>
                      {children}
                    </CafeScene>
                  </AnimatePresence>
                </motion.div>
              </main>
              <div ref={setToolbar} />
            </div>
            <div className="cafe-form-slot" ref={setForm} />
          </div>
        </div>
      </div>
    </CafeSlotsContext>
  );
}

// Cafe pages are contained in a box in the world base.
// They use overlay scrollbars, for no particular reason.
export function CafePage({
  heading,
  toolbar,
  children,
  className = "",
  showSubmitAnswerForm = false,
}: PropsWithChildren<{
  heading: ReactNode;
  toolbar?: ReactNode;
  className?: string;
  showSubmitAnswerForm?: boolean;
}>) {
  const slots = use(CafeSlotsContext);
  const isPresent = useIsPresent();

  return (
    <>
      {slots.title === null
        ? null
        : createPortal(
            <CafeSlot className={`cafe-heading ${className}`}>
              {heading}
            </CafeSlot>,
            slots.title
          )}
      {slots.toolbar === null || toolbar === undefined
        ? null
        : createPortal(
            <CafeSlot className="cafe-toolbar">{toolbar}</CafeSlot>,
            slots.toolbar
          )}
      {slots.form === null
        ? null
        : createPortal(
            <AnimatePresence>
              {showSubmitAnswerForm && isPresent ? <SubmitAnswerForm /> : null}
            </AnimatePresence>,
            slots.form
          )}
      <div
        className={`cafe-content ${toolbar ? "has-toolbar" : ""} ${className}`}
      >
        {children}
      </div>
    </>
  );
}

// This used to be more arrow-like in appearance.
// It rides the frame in and out; only its buttons swap on their own.
function Arrow({ side }: { side: "left" | "right" }) {
  const { puzData, puzRounds } = useParsedSlug();
  const swap = useMotion().fadeThrough("small", { rise: "0em" });
  // The finale links to these.
  const inGallery = useRouteMatch("gallery") !== null;
  const inJukebox = useRouteMatch("jukebox") !== null;

  return (
    <div className={`world-arrow world-arrow-${side}`}>
      <AnimatePresence initial={false} mode="popLayout">
        {inGallery ||
        inJukebox ||
        (puzData !== null && puzRounds.length === 0) ? (
          <motion.div key="finale" {...swap}>
            <Tooltip text="Back to the finale">
              <Link route="finale" button aria-label="Back to the finale">
                <Twemoji>🏁</Twemoji>
              </Link>
            </Tooltip>
          </motion.div>
        ) : puzRounds.length === 0 ? (
          <motion.div key="cafe" {...swap}>
            <Tooltip text="Back to the café">
              <Link route="puzzles" button aria-label="Back to the café">
                <Twemoji>☕</Twemoji>
              </Link>
            </Tooltip>
          </motion.div>
        ) : (
          puzRounds.map((round) => (
            <motion.div key={round.roundId} {...swap}>
              <CharacterButton
                round={round}
                label={`Back to ${round.displayName}`}
              />
            </motion.div>
          ))
        )}
      </AnimatePresence>
    </div>
  );
}

export function CharacterButton({
  round,
  label,
  children,
}: {
  round: RoundData;
  label: string;
  children?: ReactNode;
}) {
  const completedStoryBeats = useCompletedStoryBeats();
  return (
    <Tooltip text={label}>
      <Link
        route="round"
        params={{ slug: roundUrlSlug(round, completedStoryBeats) }}
        button
        aria-label={label}
        className="character-icon"
        style={
          {
            "--character-color":
              CHARACTER_COLORS[round.slug as keyof typeof CHARACTER_COLORS],
          } as CSSProperties
        }
      >
        <CharacterIcon
          type="icon"
          characterId={round.roundId}
          className="emoji"
        />
        {children}
      </Link>
    </Tooltip>
  );
}

function WorldToggle() {
  const { fade, fadeThrough } = useMotion();
  const inCafe = useRouteMatch("puzzles") !== null;
  const inFinale = useRouteMatch("finale") !== null;
  const inVictory = useRouteMatch("victory") !== null;
  const hasFinale = (useRoundlessPuzzles()?.length ?? 0) > 0;
  const target: {
    route: "puzzles" | "finale";
    label: string;
    emoji: string;
  } | null =
    inFinale || inVictory
      ? { route: "puzzles", label: "Back to the café", emoji: "☕" }
      : inCafe && hasFinale
        ? { route: "finale", label: "To the finale", emoji: "🏁" }
        : null;

  return (
    <AnimatePresence initial={false}>
      {target === null ? null : (
        <motion.div className="world-toggle" {...fade("small")}>
          <Tooltip text={target.label}>
            <Link route={target.route} button aria-label={target.label}>
              <AnimatePresence initial={false}>
                <motion.span
                  key={target.emoji}
                  {...fadeThrough("small", { rise: "0em" })}
                >
                  <Twemoji tag="span">{target.emoji}</Twemoji>
                </motion.span>
              </AnimatePresence>
            </Link>
          </Tooltip>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

const CAFE_BG = "/static/images/cutscenes/cafe.webp";
const CAFE_NIGHT_BG = "/static/images/cutscenes/cafe-night.webp";

/** World routes that sit on the page background rather than in the cafe. */
const PLAIN_BACKGROUND_ROUTES = new Set<string>([
  "errata",
  "teams",
  "team",
  "hunt_stats",
  "wrapup",
  "wrapup_shoutouts",
  "wrapup_ama",
] satisfies RouteName[]);

export function WorldBase() {
  const { pathname } = useLocation();
  useRecordPreviousPathname();
  const cutscenePuzName = useCutscenePuzName();
  const isCutscene = cutscenePuzName !== null;
  const cutscene = useCutscene(cutscenePuzName);
  const prologue = usePrologue();
  const pageSolveDialogue = useSolveDialogue();
  const solveDialogue =
    prologue.playback.status === "none" ? pageSolveDialogue : prologue.playback;
  const outletElem = useOutlet();
  // Every world route but the cafe itself is a cafe page. Keying .world-fg on
  // that instead of the pathname is what keeps one frame across those pages.
  const inPuzzles = useRouteMatch("puzzles") !== null;
  const inVictory = useRouteMatch("victory") !== null;
  const inFinale = useRouteMatch("finale") !== null;
  const inCountdown = useRouteMatch("countdown") !== null;
  const inFrame =
    !inPuzzles && !inVictory && !inFinale && !inCountdown && !isCutscene;
  const { surface, fadeThrough, tween, leaveDuration } = useMotion();
  // Backgrounds crossfade: there's nothing behind them to fade through to.
  const bgTween = tween("large");
  // The cafe frame is a surface; whole-screen pages fade through in place.
  // Either waits for the layer it replaces to finish leaving.
  const fgKey = inFrame ? "cafe-frame" : pathname;
  const [shownFgKey, setShownFgKey] = useState(fgKey);
  const [fromFrame, setFromFrame] = useState(false);
  const pageLeave = leaveDuration("large", "fadeThrough");
  const frameLeave = leaveDuration("large", "exit");
  // The cast walks when the foreground moves, and arrives as it goes.
  const [castCue, setCastCue] = useState<CastCue>({ walk: 0, enter: 0 });
  if (shownFgKey !== fgKey) {
    const wasFrame = shownFgKey === "cafe-frame";
    setShownFgKey(fgKey);
    setFromFrame(wasFrame);
    setCastCue({
      walk: wasFrame ? 0 : pageLeave,
      enter: CAST_ARRIVES_AT * (wasFrame ? frameLeave : pageLeave),
    });
  }
  const fgPreset = inFrame
    ? surface("large", { after: pageLeave })
    : fadeThrough("large", {
        rise: "0em",
        ...(fromFrame ? { after: frameLeave } : {}),
      });
  const fgMotion = {
    ...fgPreset,
    variants: {
      ...fgPreset.variants,
      leave: { ...fgPreset.variants.leave, pointerEvents: "none" },
    },
  };
  const cutsceneBackground =
    cutscene.status === "playing" && cutscene.keyframe.background !== undefined
      ? cutsceneImageNameToUrl(cutscene.keyframe.background)
      : null;

  const hasCafeBackground = !useMatches().some(({ id }) =>
    PLAIN_BACKGROUND_ROUTES.has(id)
  );
  // Backgrounds only ever crossfade; anything that moves is foreground.
  const background = cutsceneBackground ?? (hasCafeBackground ? CAFE_BG : null);

  return (
    <PrologueContext value={prologue}>
      <SolveDialogueContext value={solveDialogue}>
        {/* custom: an exiting background keeps its last props. */}
        <AnimatePresence initial={false} custom={background !== null}>
          {background === null ? null : (
            <motion.div
              key={background}
              className="world-bg"
              style={{ backgroundImage: `url(${background})` }}
              variants={{
                // Held under a replacement as it fades in; else faded out.
                leave: (replaced: boolean) => ({
                  opacity: replaced ? 0.99 : 0,
                }),
              }}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit="leave"
              transition={bgTween}
            />
          )}
        </AnimatePresence>
        <AnimatePresence initial={false}>
          {inCountdown ? (
            <motion.div
              className="world-bg"
              exit={{ opacity: 0 }}
              transition={bgTween}
            >
              <Sunrise className="world-bg" image={CAFE_NIGHT_BG} />
            </motion.div>
          ) : null}
        </AnimatePresence>
        {/* Don't flash the page the prologue is about to send us from. */}
        {prologue.redirecting ? null : (
          <>
            <AnimatePresence>
              <motion.div className="world-fg" key={fgKey} {...fgMotion}>
                <FrozenRoute>
                  {inFrame ? <CafeFrame>{outletElem}</CafeFrame> : outletElem}
                </FrozenRoute>
              </motion.div>
            </AnimatePresence>
            <SolveDialogueStage playback={solveDialogue} />
            <WorldCharacters
              cutscene={cutscene}
              isCutscene={isCutscene}
              solveDialogue={solveDialogue}
              cue={castCue}
            />
          </>
        )}
        {isCutscene ? null : <WorldToggle />}
        <CutsceneLayer playback={cutscene} cue={castCue} />
      </SolveDialogueContext>
    </PrologueContext>
  );
}
