import { createContext, use, useId, useState } from "react";
import type { CSSProperties, ReactNode } from "react";

export type PuzzleGridProps = {
  /** Rows separated by "|". "@" is a block, "." is an empty cell. */
  text: string;
  /** Crossword-style numbering. Bars end words like blocks do. */
  numbered?: boolean;
  /** Same shape as `text`; each char is an index into `fillColors`, "." is 0. */
  fills?: string;
  /** CSS colors. "transparent" hides the cell, except for `renderCell`. */
  fillColors?: string[];
  /** Text colors, indexed like `fillColors`. */
  textColors?: string[];
  /**
   * Same shape as `text`; each char is a hex digit of bars on that cell's
   * sides: 1 top, 2 right, 4 bottom, 8 left. "." is none. A bar may be given
   * on either cell sharing the edge.
   */
  bars?: string;
  /** Extra content inside cell (r, c); the cell is `position: relative`. */
  renderCell?: (r: number, c: number) => ReactNode;
  /**
   * SVG content drawn over the grid in cell units: cell (r, c) spans
   * x ∈ [c, c + 1], y ∈ [r, r + 1].
   */
  overlay?: ReactNode;
};

export const TOP = 1;
export const RIGHT = 2;
export const BOTTOM = 4;
export const LEFT = 8;

/**
 * Bars on each side of cell (r, c), whichever of the two cells sharing an
 * edge it was given on.
 */
export function barGrid(bars?: string) {
  const rows = bars?.split("|");
  const own = (r: number, c: number) =>
    parseInt(rows?.[r]?.[c] ?? ".", 16) || 0;
  return (r: number, c: number) =>
    own(r, c) |
    (own(r - 1, c) & BOTTOM ? TOP : 0) |
    (own(r, c + 1) & LEFT ? RIGHT : 0) |
    (own(r + 1, c) & TOP ? BOTTOM : 0) |
    (own(r, c - 1) & RIGHT ? LEFT : 0);
}

/** Crossword numbers for each cell, or null for unnumbered cells. */
export function numberGrid(text: string, bars?: string): (number | null)[][] {
  const rows = text.split("|");
  const bar = barGrid(bars);
  const isOpen = (r: number, c: number) => (rows[r]?.[c] ?? "@") !== "@";
  const joinedRight = (r: number, c: number) =>
    isOpen(r, c) && isOpen(r, c + 1) && !(bar(r, c) & RIGHT);
  const joinedDown = (r: number, c: number) =>
    isOpen(r, c) && isOpen(r + 1, c) && !(bar(r, c) & BOTTOM);

  let clueNum = 0;
  return rows.map((row, r) =>
    [...row].map((_, c) =>
      (joinedRight(r, c) && !joinedRight(r, c - 1)) ||
      (joinedDown(r, c) && !joinedDown(r - 1, c))
        ? ++clueNum
        : null
    )
  );
}

/**
 * Cell (r, c)'s part of a killer sudoku style cage: dashed, inset where the
 * cage ends. Render it from `renderCell` for each cell in the cage.
 */
export function CageCell(props: {
  r: number;
  c: number;
  inCage: (r: number, c: number) => boolean;
  /** Added to `puzzle-cage`. */
  className?: string;
  solid?: boolean;
}) {
  const { r, c, inCage, solid } = props;
  const className = `puzzle-cage ${props.className ?? ""} no-copy`;
  const style = solid ? "solid" : "dashed";
  const ends = [
    [r - 1, c],
    [r, c + 1],
    [r + 1, c],
    [r, c - 1],
  ].map(([r2, c2]) => !inCage(r2, c2));
  return (
    <>
      <span
        className={className}
        style={{
          inset: ends.map((e) => (e ? "3px" : 0)).join(" "),
          borderStyle: ends.map((e) => (e ? style : "none")).join(" "),
        }}
      />
      {/*
       * Inner corners: where both neighbors toward a corner are in the cage
       * but the diagonal isn't, the two neighbors' lines end at this cell's
       * edges. Join them.
       */}
      {(
        [
          [-1, -1],
          [-1, 1],
          [1, 1],
          [1, -1],
        ] as const
      )
        .filter(
          ([dr, dc]) =>
            inCage(r + dr, c) && inCage(r, c + dc) && !inCage(r + dr, c + dc)
        )
        .map(([dr, dc]) => (
          <span
            key={`${dr},${dc}`}
            className={`${className} puzzle-cage-joint`}
            style={{
              inset: "auto",
              [dr < 0 ? "top" : "bottom"]: 0,
              [dc < 0 ? "left" : "right"]: 0,
              // Sides facing the cell's middle, as top right bottom left.
              borderStyle: [dr > 0, dc < 0, dr < 0, dc > 0]
                .map((b) => (b ? style : "none"))
                .join(" "),
            }}
          />
        ))}
    </>
  );
}

export function PuzzleGrid(props: PuzzleGridProps) {
  const {
    text,
    numbered,
    fills,
    fillColors,
    textColors,
    bars,
    renderCell,
    overlay,
  } = props;
  const rows = text.split("|");
  const fillRows = fills?.split("|");
  const barAt = barGrid(bars);
  const numbers = numbered ? numberGrid(text, bars) : null;
  const numCols = Math.max(...rows.map((row) => row.length));
  const fillIndexAt = (r: number, c: number) => {
    const fillChar = fillRows?.[r][c] ?? ".";
    return fillChar === "." ? 0 : parseInt(fillChar, 36);
  };
  const isHidden = (r: number, c: number) =>
    fillColors?.[fillIndexAt(r, c)] === "transparent";
  // With collapsed borders, the table box includes the outer half of the
  // outermost borders; inset the overlay by that much so its viewBox lands on
  // the cell grid lines.
  const edgeInset = (cells: [number, number][], side: number) => {
    const widest = Math.max(
      0,
      ...cells
        .filter(([r, c]) => !isHidden(r, c))
        .map(([r, c]) => (barAt(r, c) & side ? 2 : 1))
    );
    return ["0px", "0.5px", "calc(var(--puzzle-bar-width, 3px) / 2)"][widest];
  };
  const last = rows.length - 1;
  const insetTop = edgeInset(
    [...rows[0]].map((_, c) => [0, c]),
    TOP
  );
  const insetBottom = edgeInset(
    [...rows[last]].map((_, c) => [last, c]),
    BOTTOM
  );
  const insetLeft = edgeInset(
    rows.map((_, r) => [r, 0]),
    LEFT
  );
  const insetRight = edgeInset(
    rows.map((row, r) => [r, row.length - 1]),
    RIGHT
  );

  return (
    <div className="puzzle-grid-wrapper">
      {/* "barred grid" opts into copyjack's workaround for mixed-width borders. */}
      <table className={bars ? "puzzle-grid barred grid" : "puzzle-grid"}>
        <tbody>
          {rows.map((row, r) => (
            <tr key={r}>
              {[...row].map((ch, c) => {
                const fillIndex = fillIndexAt(r, c);
                const fill = fillColors?.[fillIndex];
                if (fill === "transparent") {
                  return (
                    <td key={c} className="hidden-cell">
                      {renderCell?.(r, c)}
                    </td>
                  );
                }
                const bar = barAt(r, c);
                const style: CSSProperties = {
                  backgroundColor: fill,
                  color: textColors?.[fillIndex],
                };
                const number = numbers?.[r][c];
                return (
                  <td
                    key={c}
                    // Bars are classes, not inline styles: copyjack clones
                    // inline styles verbatim, and its barred-grid workaround
                    // needs cells to have no top border of their own.
                    className={
                      [
                        ch === "@" && "block",
                        bar & TOP && "bar-top",
                        bar & RIGHT && "bar-right",
                        bar & BOTTOM && "bar-bottom",
                        bar & LEFT && "bar-left",
                      ]
                        .filter(Boolean)
                        .join(" ") || undefined
                    }
                    style={style}
                  >
                    {number ? (
                      <span className="clue-number no-copy">{number}</span>
                    ) : null}
                    {ch === "@" || ch === "." ? null : ch}
                    {renderCell?.(r, c)}
                  </td>
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
      {overlay ? (
        <svg
          className="puzzle-grid-overlay no-copy"
          viewBox={`0 0 ${numCols} ${rows.length}`}
          preserveAspectRatio="none"
          style={{
            top: insetTop,
            left: insetLeft,
            width: `calc(100% - ${insetLeft} - ${insetRight})`,
            height: `calc(100% - ${insetTop} - ${insetBottom})`,
          }}
        >
          {overlay}
        </svg>
      ) : null}
    </div>
  );
}

const PIECE_SRCS = import.meta.glob<string>("/src/images/cburnett/*.svg", {
  eager: true,
  query: "?url",
  import: "default",
});
const pieceSrc = (piece: string) =>
  PIECE_SRCS[
    `/src/images/cburnett/${piece === piece.toUpperCase() ? "w" : "b"}${piece.toUpperCase()}.svg`
  ];
const CHECKERBOARD = [..."01234567"]
  .map((r) => (+r % 2 ? "10101010" : "01010101"))
  .join("|");
const CHECKERBOARD_COLORS = ["#f0d9b5", "#b58863"];
// Darker so white and black copied text both read on either square (contrast ≥ 3).
const COPY_CHECKERBOARD_COLORS = ["#b58863", "#8b5e3c"];
// Board plus a rank-label column on the left and a file-label row on the bottom.
const COPY_CHECKERBOARD = [
  ...CHECKERBOARD.split("|").map((row) => `2${row}`),
  "222222222",
].join("|");
const FILES = "abcdefgh";

type ChessAnnotation = {
  arrows?: string;
  squares?: string;
};

const squareCell = (sq: string) => [8 - +sq[1], FILES.indexOf(sq[0])];
const words = (s?: string) => (s ? s.split(/\s+/).filter(Boolean) : []);

function ChessOverlay(props: ChessAnnotation) {
  const id = useId();
  const color = "var(--green-40)";
  return (
    <>
      <defs>
        <marker id={id} markerWidth={4} markerHeight={4} refY={2} orient="auto">
          <path d="M0,0 L4,2 L0,4 z" fill={color} />
        </marker>
      </defs>
      {words(props.squares).map((sq) => {
        const [r, c] = squareCell(sq);
        return (
          <rect
            key={sq}
            x={c}
            y={r}
            width={1}
            height={1}
            fill={color}
            opacity={0.5}
          />
        );
      })}
      {words(props.arrows).map((move) => {
        const [[r1, c1], [r2, c2]] = move.split("-").map(squareCell);
        const len = Math.hypot(r2 - r1, c2 - c1);
        const k = (len - 0.6) / len;
        return (
          <line
            key={move}
            x1={c1 + 0.5}
            y1={r1 + 0.5}
            x2={c1 + 0.5 + (c2 - c1) * k}
            y2={r1 + 0.5 + (r2 - r1) * k}
            stroke={color}
            strokeWidth={0.15}
            opacity={0.8}
            markerEnd={`url(#${id})`}
          />
        );
      })}
    </>
  );
}

/**
 * Board part of a FEN, e.g. "4k3/8/8/8/8/8/8/4K3"; rank 8 on top. Copies as
 * FEN letters colored by side, e.g. white "K" and black "k", with rank and
 * file labels outside the board.
 */
export function ChessPuzzle(
  props: { fen?: string; text?: string } & ChessAnnotation
) {
  const board = (props.fen ?? "8/8/8/8/8/8/8/8")
    .split("/")
    .map((row) => row.replace(/\d/g, (n) => ".".repeat(+n)));
  const empty = (rows: number, cols: number) =>
    Array(rows).fill(".".repeat(cols)).join("|");
  return (
    <div className="chess-board">
      <div className="no-copy">
        <PuzzleGrid
          text={props.text ?? empty(8, 8)}
          fills={CHECKERBOARD}
          fillColors={CHECKERBOARD_COLORS}
          renderCell={(r, c) => {
            const piece = board[r][c];
            // Labels take the other square's color, like lichess.
            const color = CHECKERBOARD_COLORS[(r + c + 1) % 2];
            return (
              <>
                {piece === "." ? null : (
                  <img
                    src={pieceSrc(piece)}
                    alt={piece}
                    style={{ display: "block", width: "100%", height: "100%" }}
                  />
                )}
                {r === 7 ? (
                  <span className="chess-coord file" style={{ color }}>
                    {FILES[c]}
                  </span>
                ) : null}
                {c === 7 ? (
                  <span className="chess-coord rank" style={{ color }}>
                    {8 - r}
                  </span>
                ) : null}
              </>
            );
          }}
          overlay={
            props.arrows || props.squares ? (
              <ChessOverlay arrows={props.arrows} squares={props.squares} />
            ) : undefined
          }
        />
      </div>
      <div className="copy-only">
        <PuzzleGrid
          text={empty(9, 9)}
          fills={COPY_CHECKERBOARD}
          fillColors={[...COPY_CHECKERBOARD_COLORS, "transparent"]}
          renderCell={(r, c) => {
            if (r === 8) return c ? FILES[c - 1] : null;
            if (c === 0) return 8 - r;
            const piece = board[r][c - 1];
            if (piece === ".") return null;
            const color = piece === piece.toUpperCase() ? "white" : "black";
            return <span style={{ color }}>{piece}</span>;
          }}
        />
      </div>
    </div>
  );
}

const ChessRetroContext = createContext<{
  active: ChessAnnotation | null;
  setActive: (a: ChessAnnotation | null) => void;
} | null>(null);

export function ChessRetro(props: { fen: string; children: ReactNode }) {
  const [active, setActive] = useState<ChessAnnotation | null>(null);
  return (
    <ChessRetroContext value={{ active, setActive }}>
      <div className="chess-retro">
        <ChessPuzzle fen={props.fen} {...active} />
        <div className="chess-retro-text">{props.children}</div>
      </div>
    </ChessRetroContext>
  );
}

export function ChessMark(props: ChessAnnotation & { children: ReactNode }) {
  const { children, ...annotation } = props;
  const ctx = use(ChessRetroContext);
  if (!ctx) return children;
  const { active, setActive } = ctx;
  const on = () => setActive(annotation);
  const off = () => setActive(null);
  return (
    <span
      className={`chess-mark${active?.arrows === annotation.arrows && active?.squares === annotation.squares ? " active" : ""}`}
      tabIndex={0}
      onMouseEnter={on}
      onMouseLeave={off}
      onFocus={on}
      onBlur={off}
    >
      {children}
    </span>
  );
}
