import { useEffect } from "react";
import Twemoji from "react-twemoji";
import { Link } from "components/Link";
import { LargeSpinner } from "components/Loading";
import { RoundPuzzles } from "pages/RoundPage";
import { useCompletedStoryBeats } from "stores/BrowserWidePersistentState";
import { useNavStore } from "stores/NavStore";
import settings from "settings";
import { useIsAdmin } from "stores/ServerInteractionStore";
import { isPuzzleSolved, useRoundlessPuzzles } from "stores/ScopeStateStore";
import "./FinalePage.css";

function FinalePage() {
  const puzzles = useRoundlessPuzzles();
  const completedStoryBeats = useCompletedStoryBeats();
  const setRedirectRoute = useNavStore((state) => state.setRedirectRoute);
  const isAdmin = useIsAdmin() === true;

  useEffect(() => {
    if (puzzles?.length === 0) setRedirectRoute({ route: "puzzles" });
  }, [puzzles, setRedirectRoute]);

  if (puzzles === null) return <LargeSpinner />;
  const showVictory = puzzles.some(
    (puzData) =>
      (puzData.isFinalCutscene ?? false) &&
      isPuzzleSolved(puzData, completedStoryBeats)
  );

  const showExtras = isAdmin || showVictory;
  const showCountdown = isAdmin || settings.isPosthunt;

  return (
    <div className="finale-page">
      <RoundPuzzles puzzles={puzzles}>
        {showVictory ? (
          <div className="round-puzzle">
            <Twemoji tag="span" options={{ folder: "svg", ext: ".svg" }}>
              🏆
            </Twemoji>
            <div className="round-puzzle-body">
              <Link route="victory">Victory</Link>
            </div>
          </div>
        ) : null}
        {showExtras ? (
          <div className="round-puzzle">
            <Twemoji tag="span" options={{ folder: "svg", ext: ".svg" }}>
              🎵
            </Twemoji>
            <div className="round-puzzle-body">
              <Link route="jukebox">Jukebox</Link>
            </div>
          </div>
        ) : null}
        {showExtras ? (
          <div className="round-puzzle">
            <Twemoji tag="span" options={{ folder: "svg", ext: ".svg" }}>
              🖼️
            </Twemoji>
            <div className="round-puzzle-body">
              <Link route="gallery">Gallery</Link>
            </div>
          </div>
        ) : null}
        {showCountdown ? (
          <div className="round-puzzle">
            <Twemoji tag="span" options={{ folder: "svg", ext: ".svg" }}>
              ⌛
            </Twemoji>
            <div className="round-puzzle-body">
              <Link route="countdown">Countdown</Link>
            </div>
          </div>
        ) : null}
      </RoundPuzzles>
    </div>
  );
}

export default FinalePage;
