/**
 * Cells to highlight on the puzzle's grid, set by the editor when the posthunt
 * step-through is on. The grid and editor are separate MDX components.
 */
const useMYOCBAlive = create<{ alive: ReadonlySet<string> | null }>(() => ({
  alive: null,
}));

export function MYOCBGrid(props: {
  /** Letters of the shaded cells in reading order; solution pages only. */
  letters?: string;
  /** Cells to highlight, as "r,c" keys. */
  alive?: ReadonlySet<string>;
}) {
  const sharedAlive = useMYOCBAlive((state) => state.alive);
  const { letters, alive = sharedAlive ?? undefined } = props;
  let i = -1;
  return (
    <table className={`myocb-grid${letters ? " myocb-grid-letters" : ""}`}>
      <tbody>
        {MYOCB_CONFIG.mask.map((row, r) => (
          <tr key={r}>
            {[...row].map((ch, c) => {
              if (ch === "x") i++;
              return (
                <td
                  key={c}
                  className={
                    ch === "x"
                      ? alive?.has(key(r, c))
                        ? "myocb-shaded myocb-alive"
                        : "myocb-shaded"
                      : undefined
                  }
                >
                  {ch === "x" ? (letters?.[i] ?? "?") : "."}
                </td>
              );
            })}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function IconButton(
  props: {
    tip: string;
    emoji: string;
  } & ButtonHTMLAttributes<HTMLButtonElement>
) {
  const { tip, emoji, ...buttonProps } = props;
  return (
    <Tooltip
      text={tip}
      directRef={(refProps) => (
        <button aria-label={tip} {...buttonProps} {...refProps}>
          <Twemoji>{emoji}</Twemoji>
        </button>
      )}
    />
  );
}

function MYOCBEditor(props: {
  lines: MYOCBLine[];
  setLines: (lines: MYOCBLine[]) => void;
  children?: ReactNode;
}) {
  const { lines, setLines, children } = props;
  const replace = (i: number, line: MYOCBLine) =>
    setLines(lines.map((l, j) => (j === i ? line : l)));
  const swap = (i: number, j: number) =>
    setLines(
      lines.map((l, k) => (k === i ? lines[j] : k === j ? lines[i] : l))
    );
  return (
    <>
      <ul className="myocb-transcript">
        {lines.length === 0 && <li>(No lines yet.)</li>}
        {lines.map((line, i) => (
          <li key={i}>
            <select
              value={line.speaker}
              onChange={(e) =>
                replace(i, {
                  ...line,
                  speaker: e.target.value === "0" ? 0 : 1,
                })
              }
            >
              <option value="0">Albert</option>
              <option value="1">Bernard</option>
            </select>
            <select
              value={line.kind}
              onChange={(e) =>
                replace(i, { ...line, kind: e.target.value as MYOCBLineKind })
              }
            >
              {MYOCB_CONFIG.kinds.map(({ kind }) => (
                <option key={kind} value={kind}>
                  {describeMYOCBLine({ kind, speaker: line.speaker }, true)}
                </option>
              ))}
            </select>
            <IconButton
              disabled={i === 0}
              tip="Move up"
              emoji="⬆️"
              onClick={() => swap(i, i - 1)}
            />
            <IconButton
              disabled={i === lines.length - 1}
              tip="Move down"
              emoji="⬇️"
              onClick={() => swap(i, i + 1)}
            />
            <IconButton
              tip="Remove"
              emoji="❌"
              onClick={() => setLines(lines.filter((_, j) => j !== i))}
            />
          </li>
        ))}
      </ul>
      <div className="myocb-actions">
        <button
          disabled={lines.length >= MYOCB_CONFIG.maxLines}
          onClick={() =>
            setLines([
              ...lines,
              {
                kind: "dont_know",
                // Lines usually alternate, so start the new one that way.
                speaker:
                  lines.length === 0
                    ? 0
                    : lines[lines.length - 1].speaker === 0
                      ? 1
                      : 0,
              },
            ])
          }
        >
          Add line
        </button>
        <button disabled={lines.length === 0} onClick={() => setLines([])}>
          Clear
        </button>
        {children}
      </div>
    </>
  );
}

export function MYOCB() {
  const teamId = useTeamId();
  const sockClient = useSockClient();
  const submitLock = useUILock();
  const [lines, setLines] = useState<MYOCBLine[]>([]);
  const [message, setMessage] = useState<{
    status: "ok" | "warn" | "error";
    message: string;
    transcript: MYOCBLine[];
  } | null>(null);
  const messageRef = useRef<HTMLDivElement>(null);
  const showSteps = useIsCheckPuzzleToggleOn(MYOCB_CONFIG.puzName);
  const [step, setStep] = useState(0);
  const { states } = useMemo(() => run(MYOCB_GRID, lines), [lines]);
  const alive = showSteps ? states[Math.min(step, states.length - 1)] : null;
  useEffect(() => {
    useMYOCBAlive.setState({ alive });
  }, [alive]);
  useEffect(() => () => useMYOCBAlive.setState({ alive: null }), []);

  if (teamId === null) return null;

  return (
    <>
      <MYOCBEditor
        lines={lines}
        setLines={(next) => {
          setLines(next);
          setStep(next.length);
          setMessage(null);
        }}
      >
        <button
          disabled={submitLock.isHeld}
          onClick={() => {
            submitLock.acquireAndRun(async () => {
              const resp = await sockClient.sendScopeStepAndWaitAsync(
                { type: ScopeType.TEAM_MYOCB, teamId },
                { transcript: lines }
              );
              setMessage({
                ...(resp ?? {
                  status: "error",
                  message: "Something went wrong. Please try again.",
                }),
                transcript: lines,
              });
            });
          }}
        >
          Submit
        </button>
      </MYOCBEditor>
      {showSteps && (
        <MYOCBSteps
          lines={lines}
          states={states}
          step={step}
          setStep={setStep}
        />
      )}
      {message && (
        <div
          ref={messageRef}
          className={`myocb-message myocb-message-${message.status}`}
        >
          {message.status === "ok" && (
            <>
              <Tooltip text="Copy to clipboard" className="myocb-copy no-copy">
                <button
                  aria-label="Copy to clipboard"
                  onClick={(e) =>
                    Globals.handleClipboardButton(
                      messageRef.current,
                      e.currentTarget
                    )
                  }
                >
                  <Twemoji className="clipboard-original">📋️</Twemoji>
                  <Twemoji className="clipboard-copied">✔️</Twemoji>
                  <Twemoji className="clipboard-failed">❌</Twemoji>
                </button>
              </Tooltip>
              <blockquote>
                {message.transcript.map((line, i) => (
                  <Fragment key={i}>
                    {describeMYOCBLine(line)}
                    <br />
                  </Fragment>
                ))}
              </blockquote>
            </>
          )}
          <p>{message.message}</p>
        </div>
      )}
    </>
  );
}

const MYOCB_CELLS = MYOCB_CONFIG.mask.flatMap((row, r) =>
  [...row].flatMap((ch, c) => (ch === "x" ? [key(r, c)] : []))
);
const MYOCB_GRID = new Set(MYOCB_CELLS);

const parseMYOCBTranscript = (transcript: string): MYOCBLine[] =>
  transcript.split(" ").map((token) => ({
    speaker: token[0] === "0" ? 0 : 1,
    kind: token.slice(1) as MYOCBLineKind,
  }));

function MYOCBSteps(props: {
  lines: MYOCBLine[];
  states: ReadonlySet<string>[];
  step: number;
  setStep: (step: number) => void;
}) {
  const { lines, states, step, setStep } = props;
  return (
    <div className="myocb-steps">
      {states.map((state, i) => (
        <Fragment key={i}>
          <button
            className={clsObj({ "myocb-step-current": i === step })}
            onClick={() => setStep(i)}
          >
            {i === 0 ? "\u2014" : i}
          </button>
          <span>
            {i === 0
              ? "Before anyone says anything."
              : describeMYOCBLine(lines[i - 1])}{" "}
            <i>
              ({state.size} {state.size === 1 ? "cell" : "cells"} left)
            </i>
          </span>
        </Fragment>
      ))}
    </div>
  );
}

export function MYOCBSolution(props: {
  /** Letters of the shaded cells in reading order. */
  letters: string;
  /** One transcript per shaded cell, as `<speaker><kind>` tokens. */
  examples: string[];
}) {
  const { letters, examples } = props;
  const [isBuilding, setIsBuilding] = useState(false);
  const [example, setExample] = useState(0);
  const [built, setBuilt] = useState<MYOCBLine[]>([]);
  const [step, setStep] = useState(1);
  // Any edit jumps to the end of the transcript, as adding a line used to.
  const editBuilt = (next: MYOCBLine[]) => {
    setBuilt(next);
    setStep(next.length);
  };

  // Each example is labelled by the cell it actually resolves to, so a
  // mislabelled or stale transcript shows up as a wrong letter, not a lie.
  const runs = examples.map((transcript) => {
    const lines = parseMYOCBTranscript(transcript);
    const { answer, states } = run(MYOCB_GRID, lines);
    const [cell] = [...answer];
    return { lines, states, cell: answer.size === 1 ? cell : null };
  });
  const { lines, states } = isBuilding
    ? { lines: built, ...run(MYOCB_GRID, built) }
    : runs[example];
  const problem = built.length > 0 ? validate(built) : null;

  return (
    <div className="myocb-solution">
      <div className="button-squish-zone">
        <div className={clsObj({ active: !isBuilding })}>
          <button
            onClick={() => {
              setIsBuilding(false);
              setStep(1);
            }}
          >
            Example puzzles
          </button>
        </div>
        <div className={clsObj({ active: isBuilding })}>
          <button
            onClick={() => {
              setIsBuilding(true);
              setStep(built.length);
            }}
          >
            Build your own
          </button>
        </div>
      </div>
      <MYOCBGrid
        letters={letters}
        alive={states[Math.min(step, states.length - 1)]}
      />
      {isBuilding ? (
        <MYOCBEditor lines={built} setLines={editBuilt} />
      ) : (
        <label className="myocb-examples">
          <span>Puzzle extracting</span>
          <select
            value={example}
            onChange={(e) => {
              setExample(parseInt(e.target.value));
              setStep(1);
            }}
          >
            {runs.map(({ cell }, i) => {
              if (cell === null)
                return (
                  <option key={i} value={i}>
                    ???
                  </option>
                );
              const { r, c } = parse(cell);
              return (
                <option key={i} value={i}>
                  {letters[MYOCB_CELLS.indexOf(cell)]} (row {r + 1}, column{" "}
                  {c + 1})
                </option>
              );
            })}
          </select>
        </label>
      )}
      <MYOCBSteps lines={lines} states={states} step={step} setStep={setStep} />
      {isBuilding && problem !== null && (
        <p className="myocb-message myocb-message-error">{problem}</p>
      )}
    </div>
  );
}
