import { CSSProperties, PropsWithChildren, useMemo } from "react";
import Twemoji from "react-twemoji";
import { SolveDialogueLine } from "sockapi/scope-specs/solve-dialogue-spec";
import { renderDialogueSegments } from "components/CutsceneUi/DialogueBox";
import { parseDialogue, sliceDialogue } from "components/CutsceneUi/markup";
import Tooltip from "components/Tooltip";

import "./SolveDialogueBubble.css";

/**
 * A speech bubble over a corner character's head.
 */

/** Which way the bubble opens: away from its own side of the screen. */
export type BubbleSide = "left" | "right";

function Bubble({
  side,
  className = "",
  accent,
  label,
  onPress,
  children,
}: PropsWithChildren<{
  side: BubbleSide;
  className?: string;
  accent?: string;
  label?: string;
  onPress: () => void;
}>) {
  const button = (
    <button
      type="button"
      className={`solve-dialogue-bubble ${className}`}
      style={
        accent === undefined
          ? undefined
          : ({ "--bubble-accent": accent } as CSSProperties)
      }
      aria-label={label}
      onClick={(evt) => {
        evt.preventDefault();
        evt.stopPropagation();
        onPress();
      }}
    >
      {children}
    </button>
  );

  return (
    <div className={`solve-dialogue-anchor solve-dialogue-anchor-${side}`}>
      {label === undefined ? button : <Tooltip text={label}>{button}</Tooltip>}
    </div>
  );
}

export function SolveDialogueBubble({
  line,
  side,
  reveal,
  showContinue,
  advance,
}: {
  line: SolveDialogueLine;
  side: BubbleSide;
  /** How much of the line to show; "all" for a line that is already finished. */
  reveal: number | "all";
  showContinue: boolean;
  advance: () => void;
}) {
  const segments = useMemo(
    () => parseDialogue(line.dialogue).segments,
    [line.dialogue]
  );

  return (
    <Bubble side={side} accent={line.color} onPress={advance}>
      <div className="cutscene-name-plate">{line.name}</div>
      {/*
       * The whole line, laid out but invisible, so the bubble is its final size
       * from the first letter instead of growing as the line types.
       */}
      <span className="solve-dialogue-sizer" aria-hidden="true">
        {renderDialogueSegments(segments)}
        <span className="solve-dialogue-continue">▼</span>
      </span>
      <span className="solve-dialogue-text">
        {renderDialogueSegments(
          reveal === "all" ? segments : sliceDialogue(segments, reveal)
        )}
        {showContinue ? (
          <span className="solve-dialogue-continue">▼</span>
        ) : null}
      </span>
    </Bubble>
  );
}

/** The collapsed bubble left behind once the dialogue has played. */
export function SolveDialogueReplayBubble({
  side,
  replay,
  unseen,
  cutscene,
}: {
  side: BubbleSide;
  replay: () => void;
  unseen: boolean;
  cutscene: boolean;
}) {
  return (
    <Bubble
      side={side}
      className={`solve-dialogue-replay ${unseen ? "solve-dialogue-unseen" : ""}`}
      label={`${unseen ? "Play" : "Replay"} ${cutscene ? "scene" : "solve dialogue"}`}
      onPress={replay}
    >
      <Twemoji tag="span">{unseen ? "‼️" : "🔁"}</Twemoji>
    </Bubble>
  );
}
