/** Which side of the screen a character stands on, and how far out. */
type CharacterPosition = "far-left" | "left" | "right" | "far-right";

/** Where one character stands. */
type CharacterSpot = {
  /** Horizontal position, as a CSS length. */
  x: string;
  /** The same position in vw, used for animation. */
  xVw: number;
  /** Which edge of the sprite's body sits at `x`. */
  anchor: "left" | "center" | "right";
  scale: number;
  /** How far above the floor the sprite stands, as a CSS length. */
  y?: string;
  /** Face left instead of right. */
  flip: boolean;
  /** Sprite height before scaling, as a CSS length. */
  height?: string;
  /** Where on screen the sprite is cut off, if anywhere. */
  cutAt?: string;
};

/** See admin-util/process-art.py. */
type SpriteBox = { height: number; left: number; right: number };
const spriteBox = (imageUrl: string): SpriteBox | undefined =>
  (SPRITE_BOXES as { [url: string]: SpriteBox })[imageUrl];

/**
 * Where the body sits across the sprite, as fractions of its width, facing the
 * way it's drawn. Sprite boxes are padded out to fit every pose.
 */
const bodySpan = (imageUrl: string, flip: boolean): [number, number] => {
  const { left, right } = spriteBox(imageUrl) ?? { left: 0, right: 1 };
  return flip ? [1 - right, 1 - left] : [left, right];
};

const STAGE_SCALE = 1.6;

const toScale = (
  imageUrl: string,
  spot: Omit<CharacterSpot, "scale" | "height" | "y">
): CharacterSpot => ({
  ...spot,
  scale: 1,
  height: `calc(${spriteBox(imageUrl)?.height ?? 0.95} * var(--bg-h))`,
  y: "0px",
});

const WALK_SPEED = 80; // vw per second

const CAFE_VW: { [side in CharacterPosition]: number } = {
  "far-left": 12,
  left: 36,
  right: 64,
  "far-right": 86,
};

/**
 * CAFE_VW from the middle, but on screens wider than 16:9, where sprites stop
 * growing with the width, no further than it is at 16:9 (56.25vw tall).
 */
const cafeX = (side: CharacterPosition) => {
  const offset = CAFE_VW[side] - 50;
  return `calc(50vw ${offset < 0 ? "-" : "+"} min(${Math.abs(offset)}vw, ${Math.abs(offset) / 56.25} * var(--bg-h)))`;
};

const bodyWidthVw = () => Math.min(90, 96000 / window.innerWidth);

// in a portait layout, do a two-row thing
const ROW_DIVIDER = "59vh";
const FRONT_HEIGHT = "min(80vw, 44vh)";
const BACK_HEIGHT = FRONT_HEIGHT; //"min(50vw, 36vh)";
const FRONT_SPREAD = `0.5 * ${FRONT_HEIGHT}`;
// About half Camille's width, arm included, so she fits on the narrowest screens.
const FRONT_INSET = `0.31 * ${FRONT_HEIGHT}`;
const BACK_GAP = `0.08 * ${BACK_HEIGHT}`;

const portraitCafeSpot = (onLeft: boolean, back: boolean): CharacterSpot => ({
  // The front pair stands centred the same distance in from each screen edge,
  // or on wider screens, half a sprite height from the middle; centred, since
  // anchoring their outer edges would put the wide Camille's middle much
  // further in than Taylor's. The back pair stands either side of the middle,
  // a little apart.
  x: back
    ? `calc(50vw ${onLeft ? "-" : "+"} ${BACK_GAP})`
    : onLeft
      ? `max(${FRONT_INSET}, 50vw - ${FRONT_SPREAD})`
      : `min(100vw - ${FRONT_INSET}, 50vw + ${FRONT_SPREAD})`,
  xVw: back ? 50 : onLeft ? 0 : 100,
  anchor: back ? (onLeft ? "right" : "left") : "center",
  scale: 1,
  flip: !onLeft,
  height: back ? BACK_HEIGHT : FRONT_HEIGHT,
  ...(back
    ? {
        y: `calc(100dvh - ${ROW_DIVIDER})`,
        cutAt: ROW_DIVIDER,
      }
    : {}),
});

// Below about 6:5, one row leaves the top half empty. Also narrow screens, where
// the nameplates, a fixed 2rem against a 24vw spacing, start to crowd.
const PORTRAIT_QUERY = "(max-aspect-ratio: 6/5), (max-width: 36rem)";

// Too narrow for a cutscene's whole stage at once: phones and tablets upright.
const NARROW_STAGE_QUERY = "(max-aspect-ratio: 3/4)";

const mediaQueryStore = (query: string) => ({
  subscribe: (onChange: () => void) => {
    const list = window.matchMedia(query);
    list.addEventListener("change", onChange);
    return () => {
      list.removeEventListener("change", onChange);
    };
  },
  matches: () => window.matchMedia(query).matches,
});

const PORTRAIT = mediaQueryStore(PORTRAIT_QUERY);
const usePortrait = () =>
  useSyncExternalStore(PORTRAIT.subscribe, PORTRAIT.matches);

const NARROW_STAGE = mediaQueryStore(NARROW_STAGE_QUERY);
const useNarrowStage = () =>
  useSyncExternalStore(NARROW_STAGE.subscribe, NARROW_STAGE.matches);

/**
 * On a narrow stage, sprites are big enough to read faces by, with the dialogue
 * box over their lower half, and stand this many sprite heights apart.
 */
const NARROW_STAGE_HEIGHT = "min(70vh, 120vw)";
const NARROW_STAGE_SPACING = 0.55;
/**
 * How far from a body's middle the camera keeps in view, in sprite heights: a
 * little over the widest body's half (Camille's).
 * One figure for everyone; per sprite needs box aspects in sprite-boxes.json.
 */
const NARROW_STAGE_BODY_HALF = 0.25;

/**
 * Pans a narrow stage of `count` characters, from `from` (in sprite heights
 * from the stage's middle), only as far as it must to keep the speaker in full;
 * with no speaker, it stays. Returns where it ends up, and each one's spot.
 */
const panNarrowStage = (count: number, speakerIndex: number, from: number) => {
  const at = (i: number) => (i - (count - 1) / 2) * NARROW_STAGE_SPACING;
  const heightVw =
    (100 * Math.min(0.7 * window.innerHeight, 1.2 * window.innerWidth)) /
    window.innerWidth;
  const reach = Math.max(0, 50 / heightVw - NARROW_STAGE_BODY_HALF);
  let camera = from;
  if (speakerIndex !== -1) {
    const speakerAt = at(speakerIndex);
    camera = Math.min(Math.max(camera, speakerAt - reach), speakerAt + reach);
  }
  const spot = (i: number, flip: boolean): CharacterSpot => {
    const offset = at(i) - camera;
    return {
      x: `calc(50vw + ${offset} * ${NARROW_STAGE_HEIGHT})`,
      xVw: 50 + offset * heightVw,
      anchor: "center",
      scale: 1,
      y: "0px",
      flip,
      height: NARROW_STAGE_HEIGHT,
    };
  };
  return { camera, spot };
};

/** Pans a narrow stage, remembering where the camera was for `key`'s scene. */
type NarrowStagePan = (
  key: string,
  count: number,
  speakerIndex: number
) => (i: number, flip: boolean) => CharacterSpot;

/** The round page's character's position. */
const ROUND_SPOT: CharacterSpot = {
  x: "50vw",
  xVw: 50,
  anchor: "center",
  scale: STAGE_SCALE,
  // See --round-sprite in WorldBase.css.
  y: "calc(100dvh - 1.28 * var(--round-sprite))",
  flip: false,
  height: "min(0.8 * var(--round-sprite), 60vw)",
};

/** What a character is saying, if anything. */
type CharacterBubble =
  | { kind: "replay"; replay: () => void; unseen: boolean; cutscene: boolean }
  | {
      kind: "line";
      line: SolveDialogueLine;
      /** How much to show; "all" for a line this character already finished. */
      reveal: number | "all";
      showContinue: boolean;
      advance: () => void;
    };

/**
 * Where one character stands. Corner and stage placements render the same node,
 * keyed by character, so a character in both keeps it across the swap.
 */
type CharacterPlacement = {
  id: string;
  /** A speech bubble over this character's head. */
  bubble?: CharacterBubble;
  /** Lifted over the dimmed page, for solve dialogue on a narrow screen. */
  staged?: boolean;
} & (
  | {
      kind: "corner";
      side: CharacterPosition;
      onRoundPage: boolean;
      hasMainContent: boolean;
      spot?: CharacterSpot;
    }
  /** A character who is only here to say something, not to be visited. */
  | {
      kind: "guest";
      side: CharacterPosition;
      spot?: CharacterSpot;
      /** Fades in over this span of server time. */
      fadeIn?: Fade;
      /**
       * Covers the sprite with its silhouette, made by process-art.py. The
       * silhouette crossfades off once this is unset.
       */
      silhouette?: boolean;
    }
  | {
      kind: "stage";
      spot: CharacterSpot;
      speaking: boolean;
      dimmed: boolean;
      /** Placed by the body rather than the box, off the composed stage. */
      byBody?: boolean;
    }
) &
  CharacterIconSpec;

/**
 * Where a character stands on the countdown: Camille on the left, Lam on the
 * right, and Taylor, facing left, in the middle (behind, if portrait).
 */
const countdownGuest = (
  characterId: string,
  imageName: string | undefined,
  portrait: boolean
) => {
  const onLeft = characterId === "camille";
  const side: CharacterPosition = onLeft ? "far-left" : "far-right";
  const imageUrl = `/static/images/${imageName ?? `${characterId}.webp`}`;
  const spot =
    characterId === "taylor"
      ? portrait
        ? {
            ...portraitCafeSpot(false, true),
            x: "50vw",
            xVw: 50,
            anchor: "center" as const,
            // Uncut, which would clip the bubble; painted first, so the front
            // pair stand over their feet anyway.
            cutAt: undefined,
          }
        : toScale(imageUrl, {
            x: "50vw",
            xVw: 50,
            anchor: "center",
            flip: true,
          })
      : portrait
        ? portraitCafeSpot(onLeft, false)
        : toScale(imageUrl, cornerSpot(side, false));
  return {
    id: characterId,
    kind: "guest" as const,
    side,
    spot,
    characterId,
    imageOverride: imageName,
  };
};

/** Which half of the screen a character stands in. */
const sideGroup = (side: CharacterPosition): BubbleSide =>
  side === "far-left" || side === "left" ? "left" : "right";

/**
 * Between the content column and a character's body: clears the cafe toolbar,
 * which overhangs the column's right edge by min(5vw, 2rem) (--toolbar-right),
 * and is the same on the left so the pair stays symmetric.
 */
const COLUMN_GAP = "min(5vw, 2rem) + 1.5rem";

/**
 * A corner spot. Beside a content column, the body's inner edge stands a gap
 * out from it, so characters flank the column whatever their aspect ratio.
 */
const cornerSpot = (
  side: CharacterPosition,
  hasMainContent: boolean
): CharacterSpot => {
  const onLeft = sideGroup(side) === "left";
  return {
    x: hasMainContent
      ? `calc(50vw ${onLeft ? "-" : "+"} (var(--body-width) / 2 + ${COLUMN_GAP}))`
      : cafeX(side),
    xVw: hasMainContent
      ? 50 + (onLeft ? -1 : 1) * (bodyWidthVw() / 2)
      : CAFE_VW[side],
    anchor: hasMainContent ? (onLeft ? "right" : "left") : "center",
    scale: 1,
    flip: !onLeft,
  };
};

const placementSpot = (placement: CharacterPlacement): CharacterSpot =>
  placement.kind === "stage"
    ? placement.spot
    : placement.kind === "guest"
      ? (placement.spot ?? cornerSpot(placement.side, true))
      : (placement.spot ??
        (placement.hasMainContent
          ? cornerSpot(placement.side, true)
          : toScale(
              `/static/images/${placement.characterId}.webp`,
              cornerSpot(placement.side, false)
            )));

const cornerPlacement = (
  side: CharacterPosition,
  characterId?: string,
  opts?: {
    onRoundPage?: boolean;
    hasMainContent?: boolean;
    spot?: CharacterSpot;
  }
): CharacterPlacement[] =>
  characterId === undefined
    ? []
    : [
        {
          id: characterId,
          kind: "corner",
          side,
          characterId,
          onRoundPage: opts?.onRoundPage ?? false,
          hasMainContent: opts?.hasMainContent ?? false,
          spot: opts?.spot,
        },
      ];

/** The last thing `characterId` said, if they have spoken yet. */
const lastLineOf = (
  spoken: SolveDialogueLine[],
  characterId: string
): SolveDialogueLine | undefined =>
  spoken.findLast((line) => line.characterId === characterId);

/**
 * Hands the solve dialogue to the characters on screen.
 */
function withSolveDialogue(
  placements: CharacterPlacement[],
  solveDialogue: SolveDialoguePlayback,
  /** Set on a narrow stage, to pan the speakers there as in cutscenes. */
  narrowPan:
    | ((
        count: number,
        speakerIndex: number
      ) => (i: number, flip: boolean) => CharacterSpot)
    | null
): CharacterPlacement[] {
  // No solve dialogue -> return as-is
  if (solveDialogue.status === "none") return placements;
  const [leftPlacement, rightPlacement] = placements;
  // "..." box -> assign it to the left character, or everyone for a cutscene
  if (solveDialogue.status === "idle") {
    const { replay, unseen, cutscene } = solveDialogue;
    return placements.map((placement) =>
      cutscene || placement === leftPlacement
        ? { ...placement, bubble: { kind: "replay", replay, unseen, cutscene } }
        : placement
    );
  }

  // In-progress dialogue: assign it to the main character, and the guest character, if they exist
  const { spoken, revealed, canAdvance, advance } = solveDialogue;
  const leftId = leftPlacement?.id ?? null;
  const speakerId = spoken[spoken.length - 1].characterId;
  // If there is a second character, find them
  const rightId =
    spoken.findLast((line) => line.characterId !== leftId)?.characterId ??
    rightPlacement?.id ??
    null;

  // Assign the dialogue to the left and right characters
  const withBubble = (placement: CharacterPlacement): CharacterPlacement => {
    const line = lastLineOf(spoken, placement.id);
    if (line === undefined) return placement;
    const isSpeaking = placement.id === speakerId;
    return {
      ...placement,
      // The line's sprite, if the sheet gave one
      imageOverride: line.imageName ?? placement.imageOverride,
      bubble: {
        kind: "line",
        line,
        reveal: isSpeaking ? revealed : "all",
        showContinue: isSpeaking && canAdvance,
        advance,
      },
    };
  };

  // Add the dialogue to the left character.
  // If there's a second character, put them on the right.
  const cast: CharacterPlacement[] = [
    ...(leftPlacement === undefined ? [] : [withBubble(leftPlacement)]),
    ...(rightId === null || rightId === leftId
      ? []
      : [
          withBubble(
            rightPlacement?.id === rightId
              ? rightPlacement
              : {
                  id: rightId,
                  kind: "guest",
                  side: "far-right",
                  characterId: rightId,
                  nameOverride: lastLineOf(spoken, rightId)?.name,
                }
          ),
        ]),
  ];
  if (!solveDialogue.staged) return cast;

  // No room for bubbles: the speakers take the stage as in a cutscene, and
  // SolveDialogueStage plays the lines in a box.
  const narrowSpot =
    narrowPan === null
      ? null
      : narrowPan(
          cast.length,
          cast.findIndex((placement) => placement.id === speakerId)
        );
  const layout = stageLayout(cast.length);
  return cast.map((placement, i) => {
    // Never: the cast is corners and guests.
    if (placement.kind === "stage") return placement;
    const line =
      placement.bubble?.kind === "line" ? placement.bubble.line : undefined;
    if (narrowSpot !== null)
      return {
        ...placement,
        kind: "stage",
        staged: true,
        spot: narrowSpot(i, line?.flip ?? i !== 0),
        speaking: placement.id === speakerId,
        dimmed: placement.id !== speakerId,
        byBody: true,
      };
    // Elsewhere, where a cutscene's would stand, at a cutscene's size.
    const { left } = layout[i];
    return {
      ...placement,
      kind: "stage",
      staged: true,
      spot: toScale(
        `/static/images/${placement.imageOverride ?? `${placement.characterId}.webp`}`,
        {
          x: `${left}vw`,
          xVw: left,
          anchor: "center",
          flip: line?.flip ?? i !== 0,
        }
      ),
      speaking: placement.id === speakerId,
      dimmed: placement.id !== speakerId,
    };
  });
}

const castNodeId = (characterId: string) =>
  characterId === "dawn" ? "dj" : characterId;

function useCharacters(
  cutscene: CutscenePlayback,
  isCutscene: boolean,
  solveDialogue: SolveDialoguePlayback
): CharacterPlacement[] {
  const inCafe = useRouteMatch("puzzles") !== null;
  const inVictory = useRouteMatch("victory") !== null;
  const inFinale = useRouteMatch("finale") !== null;
  const inRound = useRouteMatch("round") !== null;
  const inTeam = useRouteMatch("team") !== null;
  const inCountdown = useRouteMatch("countdown") !== null;
  const prologue = use(PrologueContext);
  const { slug, puzData } = useParsedSlug();
  const rounds = useAccessibleRounds();
  const portrait = usePortrait();
  const narrowStage = useNarrowStage();
  // Where a narrow stage's camera points, for the scene it was pointed in.
  const [camera, setCamera] = useState({ key: "", x: 0 });
  const pan: NarrowStagePan = (key, count, speakerIndex) => {
    const panned = panNarrowStage(
      count,
      speakerIndex,
      camera.key === key ? camera.x : 0
    );
    if (camera.key !== key || camera.x !== panned.camera)
      setCamera({ key, x: panned.camera });
    return panned.spot;
  };
  const teamShip = useNavStore((state) => state.teamShip);

  if (isCutscene) {
    if (cutscene.status !== "playing")
      // Taylor waits where the countdown left them, to walk onto the stage.
      return prologue?.entering === true
        ? [
            {
              ...countdownGuest("taylor", undefined, portrait),
              silhouette: true,
            },
          ]
        : [];
    const stage = cutscene.keyframe.stage ?? [];
    const speakerId = cutscene.keyframe.speaker ?? null;
    if (narrowStage) {
      const spotAt = pan(
        cutscene.keyframe.puzName,
        stage.length,
        stage.findIndex((character) => character.characterId === speakerId)
      );
      return stage.flatMap((character, i) => {
        if (cutsceneImageNameToUrl(character.imageName) === null) return [];
        return [
          {
            id: castNodeId(character.characterId),
            kind: "stage" as const,
            spot: spotAt(i, character.flip ?? false),
            characterId: character.characterId,
            imageOverride: character.imageName,
            nameOverride: character.name,
            speaking: character.characterId === speakerId,
            dimmed: speakerId !== null && character.characterId !== speakerId,
            byBody: true,
          },
        ];
      });
    }
    const layout = stageLayout(stage.length);
    return stage.flatMap((character, i) => {
      const imageUrl = cutsceneImageNameToUrl(character.imageName);
      if (imageUrl === null) return [];
      return [
        {
          id: castNodeId(character.characterId),
          kind: "stage" as const,
          spot: toScale(imageUrl, {
            x: `${layout[i].left}vw`,
            xVw: layout[i].left,
            anchor: "center",
            flip: character.flip ?? false,
          }),
          characterId: character.characterId,
          imageOverride: character.imageName,
          nameOverride: character.name,
          speaking: character.characterId === speakerId,
          dimmed: speakerId !== null && character.characterId !== speakerId,
        },
      ];
    });
  }

  if (inCountdown) {
    // Each fades in as a silhouette shortly before their scene opens, and
    // stands in the cafe corner, in colour once their scene has played.
    // Taylor fades in as time runs out, and takes the team into the cafe.
    if (prologue === null) return [];
    const roles: string[] = ["camille", "lam"] satisfies PreviewRole[];
    const guest = (characterId: string, imageName?: string) =>
      countdownGuest(characterId, imageName, portrait);
    const line =
      solveDialogue.status === "playing"
        ? solveDialogue.spoken[solveDialogue.spoken.length - 1]
        : null;
    const speaking =
      line === null
        ? []
        : withSolveDialogue(
            [
              {
                ...guest(line.characterId, line.imageName),
                nameOverride: line.name,
              },
            ],
            solveDialogue,
            null
          );
    // In a fixed order: moving a sprite's node restarts its fade.
    const cast = (["camille", "lam"] satisfies PreviewRole[]).flatMap(
      (role): CharacterPlacement[] => {
        const speaker = speaking.filter(({ id }) => id === role);
        if (speaker.length > 0) return speaker;
        const fadeIn = prologue.appear[role];
        if (fadeIn === null || prologue.playing === role) return [];
        return [
          {
            // The scene's first sprite, so it plays from the same pose.
            ...guest(role, prologue.sprite[role]),
            silhouette: !prologue.seen[role],
            fadeIn,
            ...(prologue.canPlay[role]
              ? {
                  bubble: {
                    kind: "replay",
                    replay: () => prologue.play(role),
                    unseen: !prologue.seen[role],
                    cutscene: true,
                  },
                }
              : {}),
          },
        ];
      }
    );
    const { leave } = prologue;
    const taylor: CharacterPlacement[] =
      prologue.appear.taylor === null
        ? []
        : [
            {
              ...guest("taylor"),
              silhouette: true,
              fadeIn: prologue.appear.taylor,
              ...(leave === null
                ? {}
                : {
                    bubble: {
                      kind: "replay",
                      replay: leave,
                      unseen: true,
                      cutscene: true,
                    },
                  }),
            },
          ];
    return [
      ...taylor,
      ...cast,
      ...speaking.filter(({ id }) => !roles.includes(id)),
    ];
  }

  if (inCafe || inVictory || inFinale) {
    if (rounds === null) return [];
    const chars = Object.keys(rounds).sort();
    // Lam stands in the inner pair either side of DJ's arrival: left of Taylor
    // before it, right of DJ after. Their sprites overlap, so paint Lam last.
    const lamOnTop = (inner: CharacterPlacement[]) => [
      ...inner.filter(({ id }) => id !== "lam"),
      ...inner.filter(({ id }) => id === "lam"),
    ];
    // The inner pair stands behind, the outer pair in front.
    if (portrait)
      return [
        ...lamOnTop([
          ...cornerPlacement("left", chars[1], {
            spot: portraitCafeSpot(true, true),
          }),
          ...cornerPlacement("right", chars[2], {
            spot: portraitCafeSpot(false, true),
          }),
        ]),
        ...cornerPlacement("far-left", chars[0], {
          spot: portraitCafeSpot(true, false),
        }),
        ...cornerPlacement("far-right", chars[3], {
          spot: portraitCafeSpot(false, false),
        }),
      ];
    return [
      ...cornerPlacement("far-left", chars[0]),
      ...cornerPlacement("far-right", chars[3]),
      // Paint outside in, so the inner pair sits over the outer pair's edges.
      ...lamOnTop([
        ...cornerPlacement("left", chars[1]),
        ...cornerPlacement("right", chars[2]),
      ]),
    ];
  }

  if (inRound) {
    if (rounds === null || slug === null) return [];
    return cornerPlacement(
      "far-left",
      Object.keys(rounds).find((roundId) =>
        roundMatchesSlug(rounds[roundId], slug)
      ),
      {
        onRoundPage: true,
        hasMainContent: true,
        spot: { ...ROUND_SPOT, flip: slug === "lam" || slug === "taylor" },
      }
    );
  }

  if (inTeam) {
    return [
      ...cornerPlacement("far-left", teamShip[0], { hasMainContent: true }),
      ...cornerPlacement("far-right", teamShip[1], { hasMainContent: true }),
    ];
  }

  if (puzData === null) return [];
  return withSolveDialogue(
    [
      ...cornerPlacement("far-left", puzData.roundIds?.[0], {
        hasMainContent: true,
      }),
      ...cornerPlacement("far-right", puzData.roundIds?.[1], {
        hasMainContent: true,
      }),
    ],
    solveDialogue,
    narrowStage
      ? (count, speakerIndex) =>
          pan(`solve:${puzData.puzName}`, count, speakerIndex)
      : null
  );
}

function useRoundCounts(roundId: string): string[] {
  const teamScopeState = useTeamScopeState();
  const completedStoryBeats = useCompletedStoryBeats();
  if (teamScopeState === null) return [];
  const counts = [Emoji.META, Emoji.STORY, Emoji.PUZZLE].map((emoji) => ({
    solved: 0,
    unsolved: 0,
    emoji,
  }));
  for (const puzData of Object.values(teamScopeState.puzzles))
    if (puzData.roundIds?.includes(roundId) ?? false)
      counts[puzData.type === PuzzleType.STORY ? 1 : puzData.isMeta ? 0 : 2][
        isPuzzleSolved(puzData, completedStoryBeats) ? "solved" : "unsolved"
      ]++;
  return counts
    .filter(({ solved, unsolved }) => solved + unsolved > 0)
    .map(
      ({ solved, unsolved, emoji }) => `${solved}/${solved + unsolved} ${emoji}`
    );
}

/**
 * Over the sprite, but outside its link, so it can fade out after the link is
 * gone; it passes clicks through to the sprite. Fades in by CSS, which waits.
 */
function CafeNamePlate({
  round,
  inCafe,
  cutAt,
}: {
  round: RoundData;
  /** Stood in the cafe proper, where the plate sits higher up the sprite. */
  inCafe: boolean;
  cutAt: string | undefined;
}) {
  const counts = useRoundCounts(round.roundId);
  const { exit } = useMotion();
  // Placed by its own props, not the character's: on the way out, it keeps
  // its place while the character takes on the next page's.
  return (
    <motion.span
      className={clsObj({
        "character-name-plate": true,
        "character-name-plate-cafe": inCafe,
        "character-name-plate-cut": cutAt !== undefined,
      })}
      aria-hidden
      exit={{ opacity: 0, transition: exit("small") }}
      style={
        {
          "--character-color":
            CHARACTER_COLORS[round.slug as keyof typeof CHARACTER_COLORS],
          ...(cutAt === undefined ? {} : { "--plate-cut": cutAt }),
        } as CSSProperties
      }
    >
      {round.displayName}
      {counts.map((count) => (
        // Keyed by the text: twemoji swaps out the text node React would update.
        <Twemoji key={count} className="character-name-plate-counts">
          {count}
        </Twemoji>
      ))}
    </motion.span>
  );
}

/**
 * Issued when the world's foreground changes: how long (in seconds) the cast
 * waits before moving with it.
 */
export interface CastCue {
  /** Walks start with the foreground's own motion. */
  walk: number;
  /**
   * Arrivals wait for most of the layer leaving: not all of it, or there's a
   * beat of empty screen between the two.
   */
  enter: number;
}

/**
 * How far through the layer leaving the cast arrives. Exits accelerate, so at
 * this point the layer has barely started to move (about a quarter of the
 * way), and the cast fades in under the rest of it.
 */
export const CAST_ARRIVES_AT = 0.9;

// Rendering can't read the clock, so each cue's starts when first consulted:
// by a character mounting in the render that issues it, or else at its commit.
const cueStart = new WeakMap<CastCue, number>();
export function castWait(cue: CastCue, kind: keyof CastCue): number {
  let at = cueStart.get(cue);
  if (at === undefined) {
    at = performance.now();
    cueStart.set(cue, at);
  }
  return Math.max(0, cue[kind] - (performance.now() - at) / 1000);
}

/**
 * `spot`, but with each change held until the frame after it has painted. A
 * route change's first render can block the main thread for a couple hundred
 * milliseconds; a walk started before that would already be most of the way
 * there by the next frame, and the sprite would jump.
 */
function usePaintedSpot(
  spot: CharacterSpot,
  cue: CastCue
): { spot: CharacterSpot; walkWait: number; enterWait: number } {
  const key = JSON.stringify(spot);
  const [shown, setShown] = useState({ spot, walkWait: 0, enterWait: 0 });
  useEffect(() => {
    let frame = requestAnimationFrame(() => {
      frame = requestAnimationFrame(() => {
        setShown({
          spot: JSON.parse(key) as CharacterSpot,
          walkWait: castWait(cue, "walk"),
          enterWait: castWait(cue, "enter"),
        });
      });
    });
    return () => {
      cancelAnimationFrame(frame);
    };
  }, [key, cue]);
  return shown;
}

/**
 * Walks take time by distance, not a motion token: at any one duration, a walk
 * across the screen would dart and a step would drag. But no shorter than a
 * medium tween, since a walk also carries any change of size, and a short step
 * from a page's spot onto a stage would otherwise resize at a snap.
 */
function useWalkDuration(xVw: number): number {
  const [from, setFrom] = useState(xVw);
  const [duration, setDuration] = useState(0.3);
  if (from !== xVw) {
    setFrom(xVw);
    setDuration(
      Math.min(0.8, Math.max(0.35, Math.abs(xVw - from) / WALK_SPEED))
    );
  }
  return useMotion().scaled(duration);
}

// Drifts in from the screen edge on its side.
const FADE_IN: { [side in BubbleSide | "center"]: Keyframe[] } = {
  left: [
    { opacity: 0, translate: "-5vw 0" },
    { opacity: 1, translate: "0 0" },
  ],
  right: [
    { opacity: 0, translate: "5vw 0" },
    { opacity: 1, translate: "0 0" },
  ],
  center: [{ opacity: 0 }, { opacity: 1 }],
};

function FadeIn({
  fade,
  side,
  onClick,
  className,
  children,
}: {
  fade: Fade | undefined;
  side: BubbleSide | "center";
  onClick?: () => void;
  className?: string;
  children: ReactNode;
}) {
  const ref = useRef<HTMLDivElement>(null);
  useServerTimedAnimation(ref, FADE_IN[side], fade ?? null);
  return (
    <div
      ref={ref}
      className={className}
      onClick={onClick}
      style={{
        // for the silhouette laid over the sprite
        position: "relative",
        // userSelect: so double-clicking through lines doesn't select it
        ...(onClick === undefined
          ? {}
          : { cursor: "pointer", userSelect: "none" }),
      }}
    >
      {children}
    </div>
  );
}

/**
 * A hard cut between sitting and standing is jarring, so the sprite sinks out
 * and rises back in its new posture. Stepping through a cutscene cuts instead.
 */
const isSitting = (placement: CharacterPlacement) =>
  /-sitting\b/.test(placement.imageOverride ?? "");

function Character({
  placement,
  cue,
  stepped,
}: {
  placement: CharacterPlacement;
  cue: CastCue;
  /** Reached the line by stepping, not advancing. */
  stepped: boolean;
}) {
  const stage = placement.kind === "stage" ? placement : null;
  const corner = placement.kind === "stage" ? null : placement;
  const guest = placement.kind === "guest" ? placement : null;
  const shownSilhouette =
    guest?.silhouette === true
      ? `/static/images/${(guest.imageOverride ?? `${guest.characterId}.webp`).replace(/\.webp$/, "-silhouette.webp")}`
      : null;
  // The last silhouette shown, kept after it's hidden so it fades off as the
  // sprite changes, even as the character walks onto a cutscene's stage.
  const [silhouette, setSilhouette] = useState<string | null>(null);
  if (shownSilhouette !== null && shownSilhouette !== silhouette)
    setSilhouette(shownSilhouette);
  const {
    spot,
    walkWait,
    enterWait: plateWait,
  } = usePaintedSpot(placementSpot(placement), cue);
  const motionTokens = useMotion();
  // Only the entrance waits, and arrives; later changes are on screen already.
  const [enterWait] = useState(() => castWait(cue, "enter"));
  const [entered, setEntered] = useState(false);
  const walk = useWalkDuration(spot.xVw);
  const { bubble } = placement;
  // Cutscenes are composed with the whole sprite box in each slot.
  const [bodyLeft, bodyRight] =
    placement.kind === "stage" && placement.byBody !== true
      ? [0, 1]
      : bodySpan(
          `/static/images/${placement.imageOverride ?? `${placement.characterId}.webp`}`,
          spot.flip
        );
  const bodyCenter = (bodyLeft + bodyRight) / 2;
  const anchor = { left: bodyLeft, center: bodyCenter, right: bodyRight }[
    spot.anchor
  ];
  // Stage characters come and go from their own side of the screen.
  const translate =
    corner === null
      ? spot.xVw < 49
        ? "-20% 0%"
        : spot.xVw > 51
          ? "20% 0%"
          : "0% 0%"
      : spot.anchor === "center"
        ? "0% 10%"
        : sideGroup(corner.side) === "left"
          ? "-100% 0%"
          : "100% 0%";

  const teamId = useTeamId();
  const sockClient = useSockClient();
  const inVictory = useRouteMatch("victory") !== null;
  const shipState = useScopeStateResolvable(
    ScopeType.TEAM_SHIP,
    inVictory && teamId !== null ? { teamId } : null
  );
  const round = useAccessibleRounds()?.[placement.characterId] ?? null;
  const completedStoryBeats = useCompletedStoryBeats();
  const inTeam = useRouteMatch("team") !== null;
  const inFinale = useRouteMatch("finale") !== null;
  const inCountdown = useRouteMatch("countdown") !== null;
  const inCafe =
    corner?.kind === "corner" &&
    !corner.hasMainContent &&
    corner.spot === undefined;
  const onCafeRoute = useRouteMatch("puzzles") !== null;
  // As the link below, for a cafe character without a page of its own. By the
  // route, not the placement: a character leaving the finale for a cutscene
  // re-renders under the scene's route on its way out.
  const platedRound =
    corner?.kind === "corner" &&
    !corner.hasMainContent &&
    onCafeRoute &&
    bubble?.kind !== "line"
      ? round
      : null;

  return (
    <motion.div
      className={clsObj({
        "world-character": true,
        speaking: stage?.speaking ?? false,
        dimmed:
          (stage?.dimmed ?? false) ||
          inFinale ||
          (inVictory &&
            !(shipState?.ship ?? []).includes(placement.characterId)),
        "world-character-talking": bubble !== undefined,
        "world-character-in-dialogue": bubble?.kind === "line",
        "world-character-staged": placement.staged ?? false,
        "world-character-sunk": spot.y !== undefined,
        "world-character-cut": spot.cutAt !== undefined,
        "world-character-round":
          corner?.kind === "corner" && corner.onRoundPage,
        "world-character-cafe": inCafe,
        "world-character-countdown-camille":
          inCountdown && placement.characterId === "camille",
      })}
      style={
        {
          "--char-x": spot.x,
          "--char-anchor": `${-100 * anchor}%`,
          "--char-body-center": `${100 * bodyCenter}%`,
          "--char-scale": spot.scale,
          "--char-y": spot.y ?? "0px",
          "--char-flip": spot.flip ? -1 : 1,
          "--char-walk": `${walk}s`,
          "--walk-wait": `${walkWait}s`,
          "--plate-wait": `${plateWait}s`,
          ...(spot.height === undefined
            ? {}
            : { "--char-height": spot.height }),
          ...(spot.cutAt === undefined ? {} : { "--char-cut": spot.cutAt }),
        } as CSSProperties
      }
      initial={{ opacity: 0, translate }}
      animate={{ opacity: 1, translate: stage?.speaking ? "0% 0%" : "0% 3%" }}
      exit={{ opacity: 0, translate, transition: motionTokens.exit("medium") }}
      transition={
        entered
          ? motionTokens.tween("small")
          : motionTokens.enter("medium", enterWait)
      }
      onAnimationComplete={() => {
        if (!entered) setEntered(true);
      }}
    >
      {/* One wrapper for both, so a guest's sprite carries onto the stage. */}
      {placement.kind === "stage" || placement.kind === "guest" ? (
        // custom, not transition: an exiting node keeps its last props.
        <AnimatePresence mode="wait" initial={false} custom={stepped}>
          <motion.div
            key={isSitting(placement) ? "sitting" : "standing"}
            custom={stepped}
            variants={{
              out: (cut: boolean) => ({
                opacity: 0,
                translate: "0% 10%",
                transition: cut ? { duration: 0 } : motionTokens.exit("small"),
              }),
            }}
            initial="out"
            animate={{ opacity: 1, translate: "0% 0%" }}
            exit="out"
            transition={stepped ? { duration: 0 } : motionTokens.enter("small")}
          >
            <FadeIn
              fade={guest?.fadeIn}
              side={spot.xVw < 49 ? "left" : spot.xVw > 51 ? "right" : "center"}
              className={clsObj({
                "character-silhouetted": shownSilhouette !== null,
              })}
              onClick={
                // Only here: everywhere else, only the bubble takes clicks.
                !(inCountdown || bubble?.kind === "line") ||
                bubble === undefined
                  ? undefined
                  : bubble.kind === "line"
                    ? bubble.advance
                    : bubble.replay
              }
            >
              <CharacterIcon
                characterId={placement.characterId}
                imageOverride={placement.imageOverride}
                nameOverride={placement.nameOverride}
                {...(guest === null || inCountdown || bubble?.kind === "line"
                  ? {}
                  : { tooltip: true })}
              />
              {silhouette === null ? null : (
                <img
                  className="character-portrait character-silhouette"
                  src={shownSilhouette ?? silhouette}
                  alt=""
                  draggable={false}
                />
              )}
            </FadeIn>
          </motion.div>
        </AnimatePresence>
      ) : placement.onRoundPage ? (
        <CharacterIcon
          characterId={placement.characterId}
          imageOverride={placement.imageOverride}
        />
      ) : inVictory &&
        shipState !== null &&
        teamId !== null &&
        shipState.ship.includes(placement.characterId) ? (
        <a
          href="#"
          onClick={(evt) => {
            evt.preventDefault();
            sockClient.sendScopeStep(
              {
                type: ScopeType.TEAM_SHIP,
                teamId,
              },
              {
                ship: shipState.ship.filter(
                  (char) => char !== placement.characterId
                ),
              }
            );
          }}
        >
          <CharacterIcon
            characterId={placement.characterId}
            imageOverride={placement.imageOverride}
            tooltip
          />
        </a>
      ) : inVictory &&
        shipState !== null &&
        teamId !== null &&
        shipState.ship.length < 2 ? (
        <a
          href="#"
          onClick={(evt) => {
            evt.preventDefault();
            sockClient.sendScopeStep(
              {
                type: ScopeType.TEAM_SHIP,
                teamId,
              },
              {
                ship: [...shipState.ship, placement.characterId],
              }
            );
          }}
        >
          <CharacterIcon
            characterId={placement.characterId}
            imageOverride={placement.imageOverride}
            tooltip
          />
        </a>
      ) : inVictory ? (
        <CharacterIcon
          characterId={placement.characterId}
          imageOverride={placement.imageOverride}
          tooltip
        />
      ) : inFinale ? (
        <CharacterIcon
          characterId={placement.characterId}
          imageOverride={placement.imageOverride}
        />
      ) : inTeam || round === null ? (
        <CharacterIcon
          characterId={placement.characterId}
          imageOverride={placement.imageOverride}
          tooltip
        />
      ) : bubble?.kind === "line" ? (
        <div
          style={{ cursor: "pointer" }}
          onClick={(evt) => {
            evt.preventDefault();
            bubble.advance();
          }}
        >
          <CharacterIcon
            characterId={placement.characterId}
            imageOverride={placement.imageOverride}
          />
        </div>
      ) : (
        <Link
          route="round"
          params={{ slug: roundUrlSlug(round, completedStoryBeats) }}
        >
          {placement.hasMainContent ? (
            <CharacterIcon
              characterId={placement.characterId}
              imageOverride={placement.imageOverride}
              tooltip
            />
          ) : (
            <CharacterIcon
              characterId={placement.characterId}
              imageOverride={placement.imageOverride}
            />
          )}
        </Link>
      )}
      <AnimatePresence>
        {platedRound === null ? null : (
          <CafeNamePlate
            key="plate"
            round={platedRound}
            inCafe={inCafe}
            cutAt={spot.cutAt}
          />
        )}
      </AnimatePresence>
      {bubble === undefined || corner === null ? null : bubble.kind ===
        "replay" ? (
        <SolveDialogueReplayBubble
          side={sideGroup(corner.side)}
          replay={bubble.replay}
          unseen={bubble.unseen}
          cutscene={bubble.cutscene}
        />
      ) : (
        <SolveDialogueBubble
          line={bubble.line}
          side={sideGroup(corner.side)}
          reveal={bubble.reveal}
          showContinue={bubble.showContinue}
          advance={bubble.advance}
        />
      )}
    </motion.div>
  );
}

/**
 * The sprite's clip-path to look to stand behind a cafe page: everything but
 * the page's column, from the cap's zigzag down. In percentages of the
 * sprite's box, whose screen rect already has its transforms in it.
 */
function pageCut(sprite: DOMRect, cap: DOMRect, unit: number): string {
  if (sprite.width === 0 || sprite.height === 0) return "";
  const x = (px: number) =>
    `${(((px - sprite.left) / sprite.width) * 100).toFixed(2)}%`;
  const y = (px: number) =>
    `${(((px - sprite.top) / sprite.height) * 100).toFixed(2)}%`;
  // The cap's mask (WorldBase.css): a tile every 2 × --body-padding, and the
  // cap is 1.1 of that padding tall; mask-repeat: round fits whole tiles. Each
  // tile peaks at its edges on the cap's top and dips to 1/1.1 down between.
  const teeth = Math.max(1, Math.round(cap.width / unit));
  const tooth = cap.width / teeth;
  const zigzag: string[] = [];
  for (let i = teeth; i >= 0; i--) {
    zigzag.push(`${x(cap.left + i * tooth)} ${y(cap.top)}`);
    if (i > 0)
      zigzag.push(
        `${x(cap.left + (i - 0.5) * tooth)} ${y(cap.top + unit / 2)}`
      );
  }
  // Far out, so bubbles and name plates past the box aren't cut.
  const far = "1000%";
  const near = "-1000%";
  return `polygon(${[
    `${near} ${near}`,
    `${far} ${near}`,
    `${far} ${far}`,
    `${x(cap.right)} ${far}`,
    ...zigzag,
    `${x(cap.left)} ${far}`,
    `${near} ${far}`,
  ].join(", ")})`;
}

/**
 * Cafe pages look to stand in front of the cast, but the cast is drawn over
 * them, so each character takes its own clicks and the page everything else,
 * wheel included. So each sprite is cut away where the page is. Characters
 * mid-dialogue step in front uncut, unless sunk behind the page top, and staged
 * ones always, over the dimmed page.
 *
 * Not while the page fades in or out, though: a hard cut against a page that
 * is half there looks wrong. Then the page is simply drawn over the cast
 * (data-fading, WorldBase.css), which fades with it; clicks can wait.
 * Polled every frame, since scrolling, walks and every height tween
 * move things; per-event updates if it ever shows in a profile.
 */
function useCutByPage() {
  useEffect(() => {
    const last = new WeakMap<HTMLElement, string>();
    let frame = requestAnimationFrame(function track() {
      const capEl = document.querySelector(".cafe-frame .cafe-inner");
      const fg = capEl?.closest<HTMLElement>(".world-fg");
      const fading = fg != null && Number(getComputedStyle(fg).opacity) < 1;
      if (fg != null) fg.toggleAttribute("data-fading", fading);
      const cap = fading ? undefined : capEl?.getBoundingClientRect();
      const unit =
        capEl === null
          ? null
          : getComputedStyle(capEl).maskSize.match(/,\s*([0-9.]+)px/)?.[1]; // dwai
      for (const el of document.querySelectorAll<HTMLElement>(
        ".world-character"
      )) {
        const inFront =
          el.classList.contains("world-character-staged") ||
          (el.classList.contains("world-character-in-dialogue") &&
            !el.classList.contains("world-character-sunk"));
        const clip =
          cap === undefined || inFront || !unit
            ? ""
            : pageCut(el.getBoundingClientRect(), cap, +unit);
        if (last.get(el) !== clip) {
          last.set(el, clip);
          el.style.clipPath = clip;
        }
      }
      frame = requestAnimationFrame(track);
    });
    return () => {
      cancelAnimationFrame(frame);
    };
  }, []);
}

/** The world's cast: the corner characters, or the cutscene stage. */
export function WorldCharacters({
  cutscene,
  isCutscene,
  solveDialogue,
  cue,
}: {
  cutscene: CutscenePlayback;
  isCutscene: boolean;
  solveDialogue: SolveDialoguePlayback;
  cue: CastCue;
}) {
  const shown = useCharacters(cutscene, isCutscene, solveDialogue);
  // React reorders by moving nodes, and a moved node drops its CSS transitions,
  // so its walk snaps. A cutscene's stage keeps the order the cast is already
  // in, and so hands it back unmoved: its speaker is raised anyway, and the
  // overlaps elsewhere are slight. Pages keep theirs, which paint by it.
  const [order, setOrder] = useState<string[]>([]);
  const characters = isCutscene
    ? shown.toSorted((a, b) => {
        // Arrivals after, in their own order (the sort is stable).
        const rank = (id: string) => {
          const i = order.indexOf(id);
          return i === -1 ? order.length : i;
        };
        return rank(a.id) - rank(b.id);
      })
    : shown;
  const ids = characters.map(({ id }) => id);
  // Not while the cutscene loads, with no one on stage for a render or so.
  if (ids.length > 0 && ids.join() !== order.join()) setOrder(ids);
  useLayoutEffect(() => {
    castWait(cue, "walk");
  }, [cue]);
  useCutByPage();
  const stepped =
    isCutscene && cutscene.status === "playing" && cutscene.stepped;
  return (
    <AnimatePresence>
      {characters.map((placement) => (
        <Character
          key={placement.id}
          placement={placement}
          cue={cue}
          stepped={stepped}
        />
      ))}
    </AnimatePresence>
  );
}
