import {
  createContext,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";
import { ScopeType } from "sockapi/scope-types";
import { SolveDialogueLine } from "sockapi/scope-specs/solve-dialogue-spec";
import { ParsedDialogue, parseDialogue } from "components/CutsceneUi/markup";
import { cutsceneImageNameToUrl } from "components/CutsceneUi/useCutscene";
import { useTypewriter } from "components/CutsceneUi/useTypewriter";
import { useRouteMatch } from "components/urls";
import { useNavStore, useParsedSlug } from "stores/NavStore";
import {
  useHasSeenSolveDialogue,
  useUpdateBrowserWidePersistentState,
} from "stores/BrowserWidePersistentState";
import {
  useIsPuzzleSolved,
  useScopeStateResolvable,
} from "stores/ScopeStateStore";

const NO_LINES: SolveDialogueLine[] = [];
const NO_DIALOGUE: ParsedDialogue = { segments: [], schedule: [] };

export type SolveDialoguePlayback =
  | { status: "none" }
  /** The collapsed bubble. Clicking it plays the dialogue. */
  | {
      status: "idle";
      replay: () => void;
      // Never played to the end (for a cutscene: the team never finished it)
      unseen: boolean;
      // Replays the post-solve cutscene rather than dialogue, from every character
      cutscene: boolean;
    }
  | {
      status: "playing";
      // Play it centre stage with a dialogue box, rather than in corner bubbles
      staged: boolean;
      // Every line so far, ending with the one being typed
      spoken: SolveDialogueLine[];
      // How many characters of the last line are revealed
      revealed: number;
      // Whether a click would move on to the next line
      canAdvance: boolean;
      // Finish the line being typed, or move on to the next one
      advance: () => void;
      exit: () => void;
    };

/** WorldBase's playback, for the puzzle page toolbar's replay button. */
export const SolveDialogueContext = createContext<SolveDialoguePlayback>({
  status: "none",
});

// Narrow screens have no room for corner bubbles beside the page.
const STAGED_QUERY = "(max-width: 1200px)";

const subscribeStaged = (onChange: () => void) => {
  const query = window.matchMedia(STAGED_QUERY);
  query.addEventListener("change", onChange);
  return () => {
    query.removeEventListener("change", onChange);
  };
};

const useStaged = () =>
  useSyncExternalStore(
    subscribeStaged,
    () => window.matchMedia(STAGED_QUERY).matches
  );

/** Plays `lines` one at a time with the typewriter. */
export function useDialoguePlayback(
  /** What's playing; null plays nothing. */
  key: string | null,
  lines: SolveDialogueLine[]
): { playback: SolveDialoguePlayback; play: () => void; stop: () => void } {
  const hasSeen = useHasSeenSolveDialogue(key);
  const updateBrowserWidePersistentState =
    useUpdateBrowserWidePersistentState();
  const staged = useStaged();

  // Preload and decode every sprite and portrait, so a line doesn't wait on the
  // network. Matches what WorldCharacters shows for each line.
  const preloadRef = useRef<HTMLImageElement[]>([]);
  useEffect(() => {
    const imageNames = new Set(
      lines.map((line) => line.imageName ?? `${line.characterId}.webp`)
    );
    preloadRef.current = Array.from(imageNames).flatMap((imageName) => {
      const imgUrl = cutsceneImageNameToUrl(imageName);
      if (imgUrl === null) return [];
      const img = new Image();
      img.src = imgUrl;
      img.decode().catch(() => {});
      return [img];
    });
  }, [lines]);

  // Which line is showing, tagged with the key it belongs to so a position
  // left over from the last dialogue can't leak into this one.
  const [position, setPosition] = useState<{
    key: string;
    index: number;
  } | null>(null);

  // Get the exact dialogue to show
  const index =
    key !== null && position !== null && position.key === key
      ? position.index
      : null;
  const line = index === null ? undefined : lines[index];
  const dialogueText = line?.dialogue;
  const { schedule } = useMemo(
    () =>
      dialogueText === undefined ? NO_DIALOGUE : parseDialogue(dialogueText),
    [dialogueText]
  );
  // Typewriter types out the dialogue one character at a time
  const typewriter = useTypewriter(schedule, `${key ?? ""}_${index ?? -1}`);

  const play = useCallback(() => {
    if (key !== null) setPosition({ key, index: 0 });
  }, [key]);
  const stop = useCallback(() => setPosition(null), []);

  if (key === null || lines.length === 0)
    return { playback: { status: "none" }, play, stop };
  if (index === null || line === undefined)
    return {
      playback: {
        status: "idle",
        replay: play,
        unseen: !hasSeen,
        cutscene: false,
      },
      play,
      stop,
    };

  return {
    playback: {
      status: "playing",
      staged,
      spoken: lines.slice(0, index + 1),
      revealed: typewriter.revealed,
      canAdvance: typewriter.canAdvance,
      advance: () => {
        // Clicking mid-line finishes it, as in a cutscene.
        if (!typewriter.isDone) {
          typewriter.finish();
          return;
        }
        if (!typewriter.canAdvance) return;
        if (index + 1 < lines.length) {
          setPosition({ key, index: index + 1 });
          return;
        }
        setPosition(null);
        updateBrowserWidePersistentState({
          seenSolveDialogues: { [key]: true },
        });
      },
      exit: stop,
    },
    play,
    stop,
  };
}

/**
 * Drives the dialogue a puzzle's characters play once the team has solved it.
 */
export function useSolveDialogue(): SolveDialoguePlayback {
  const inPuzzleRoute = useRouteMatch("puzzle") !== null;
  const { puzName } = useParsedSlug();
  const viewedPuzName = inPuzzleRoute ? puzName : null;
  const isPuzzleSolved = useIsPuzzleSolved(viewedPuzName);
  const activePuzName = (isPuzzleSolved ?? false) ? viewedPuzName : null;
  // Get the lines from the server. Only ask once solved; the server refuses before then
  const dialogue = useScopeStateResolvable(
    ScopeType.SOLVE_DIALOGUE,
    activePuzName === null ? null : { puzName: activePuzName }
  );
  const lines = dialogue?.lines ?? NO_LINES;
  const cutscene = dialogue?.cutscene ?? null;
  const isCutsceneSeen = useIsPuzzleSolved(cutscene?.puzName ?? null);
  const setRedirectRoute = useNavStore((state) => state.setRedirectRoute);
  const { playback, play, stop } = useDialoguePlayback(activePuzName, lines);

  // Whether the puzzle on screen was solved last time we looked, so we can tell
  // the moment of solving from arriving at a puzzle that was already solved.
  const wasSolvedRef = useRef<{ puzName: string; isSolved: boolean } | null>(
    null
  );

  // Listen for a solve on this puzzle and show the solve dialogue
  useEffect(() => {
    const wasSolved = wasSolvedRef.current;
    if (viewedPuzName === null || isPuzzleSolved === null) {
      // Not looking at a puzzle (or not told yet whether it's solved)
      wasSolvedRef.current = null;
      stop();
      return;
    }
    wasSolvedRef.current = { puzName: viewedPuzName, isSolved: isPuzzleSolved };
    if (wasSolved?.puzName !== viewedPuzName) return;
    if (wasSolved.isSolved || !isPuzzleSolved) return;
    // It was just solved with this page open; show the dialogue
    play();
  }, [viewedPuzName, isPuzzleSolved, play, stop]);

  if (activePuzName === null) return { status: "none" };
  if (lines.length === 0 && cutscene !== null) {
    const { slug } = cutscene;
    return {
      status: "idle",
      replay: () => setRedirectRoute({ route: "scene", params: { slug } }),
      unseen: !(isCutsceneSeen ?? true),
      cutscene: true,
    };
  }
  return playback;
}
