import Twemoji from "react-twemoji";
import {
  ARROWS_DISPLAY_NAME,
  ARROWS_TITLE,
  Arrows,
} from "components/PuzzleContent/Arrows";

/** A puzzle's display name, drawing the arrows puzzle's title as arrows. */
function PuzzleTitle({ displayName }: { displayName: string }) {
  // Keyed on the display name text so string call sites need no puzzle lookup;
  // admin names keep their "[slug] " prefix.
  if (!displayName.endsWith(ARROWS_DISPLAY_NAME)) {
    return <Twemoji tag="span">{displayName}</Twemoji>;
  }
  return (
    <>
      {displayName.slice(0, -ARROWS_DISPLAY_NAME.length)}
      <Arrows seq={ARROWS_TITLE} />
    </>
  );
}

export default PuzzleTitle;
