import { clsObj } from "client-util/util";
import { type QuestionT } from "components/PuzzleContent/NormalQuiz/NormalQuiz";
import {
  PuzzleAudio,
  PuzzleImage,
} from "components/PuzzleContent/puzzle-components";

type QuestionProps = {
  question: QuestionT;
  answer: number | null;
  setAnswer: (index: number) => void;
  submitted: boolean;
  staticPuzDir: string;
};

const Question = ({
  question,
  answer: currentAnswer,
  setAnswer,
  submitted,
  staticPuzDir,
}: QuestionProps) => {
  const { name, text, answers, image, correct, audio } = question;
  return (
    <li>
      <div className="question">
        <span>{text}</span>
        {image && (
          <PuzzleImage staticPuzDir={staticPuzDir} nameWithExt={image} />
        )}
        {audio && (
          <PuzzleAudio
            staticPuzDir={staticPuzDir}
            isPreview={false}
            name={audio}
          />
        )}
        {answers.map((answer, index) => (
          <label
            key={answer}
            className={clsObj({
              "question-label": true,
              correct:
                submitted &&
                currentAnswer === index &&
                currentAnswer === correct,
              incorrect:
                submitted &&
                currentAnswer === index &&
                currentAnswer !== correct,
            })}
          >
            <input
              type="radio"
              name={name}
              disabled={submitted}
              checked={currentAnswer === index}
              onChange={() => setAnswer(index)}
            />
            <span>
              ({String.fromCharCode(index + 97)}) {answer}
            </span>
          </label>
        ))}
      </div>
    </li>
  );
};

export default Question;
