import { useRef } from "react";
import "./SingBeans.css";

function requestFullscreen(el: HTMLElement) {
  if (el.requestFullscreen) {
    void el.requestFullscreen();
    return;
  }
  const webkitEl = el as HTMLElement & {
    webkitRequestFullscreen?: () => Promise<void> | void;
  };
  void webkitEl.webkitRequestFullscreen?.();
}

export function SingBeans({ staticPuzDir }: { staticPuzDir: string }) {
  const iframeRef = useRef<HTMLIFrameElement>(null);

  return (
    <div className="opus-frame">
      <button
        type="button"
        title="Enter fullscreen"
        className="fullscreen-btn"
        onClick={() => {
          const iframe = iframeRef.current;
          if (iframe) requestFullscreen(iframe);
        }}
      >
        <img src={`${staticPuzDir}/default/enlarge.svg`} />
      </button>
      <iframe
        ref={iframeRef}
        id="opus-game"
        src={`${staticPuzDir}/default/index-v0.9.html`}
        allow="fullscreen"
        allowFullScreen
        title="Sing, Beans!"
      />
    </div>
  );
}
