/** Credit link to a sound on Freesound, shown as the uploader's username. */
function freesound(user: string, soundId: number): ReactNode {
  return (
    <a
      href={`https://freesound.org/people/${user}/sounds/${soundId}/`}
      target="_blank"
      rel="noopener noreferrer"
    >
      {user}
    </a>
  );
}

