/** What happens when a track ends. */
const LOOP_MODES = [
  { mode: "off", label: "Play through", emoji: "➡️" },
  { mode: "all", label: "Loop all", emoji: "🔁" },
  { mode: "one", label: "Loop one", emoji: "🔂" },
] as const;

const SMOBSTER_TRACK = TRACKS.length - 1;
const SMOBSTER_START = 125;
const SMOBSTER_END = 132;

function formatTime(seconds: number): string {
  if (!Number.isFinite(seconds)) return "-:--";
  const s = Math.floor(seconds);
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}

function JukeboxPage() {
  const isAdmin = useIsAdmin();

  const audioRef = useRef<HTMLAudioElement>(null);
  const [current, setCurrent] = useState<number | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [time, setTime] = useState(0);
  const [duration, setDuration] = useState(NaN);
  const [loopMode, setLoopMode] = useState(0);
  const loop = LOOP_MODES[loopMode].mode;

  const volume = useSeparatelyPersistedState((state) => state.bgmVolume);
  const isMuted = useSeparatelyPersistedState((state) => state.bgmIsMuted);
  useEffect(() => {
    const audio = audioRef.current;
    if (audio === null) return;
    audio.volume = volume / 100;
    audio.muted = isMuted;
  }, [volume, isMuted, current]);

  // Stop whatever's still ringing when leaving the page.
  useEffect(
    () => () => {
      SFXPlayer.howl.stop();
    },
    []
  );

  const play = (index: number) => {
    const audio = audioRef.current;
    if (audio === null) return;
    if (index === current) {
      if (audio.paused) void audio.play();
      else audio.pause();
      return;
    }
    setCurrent(index);
    setTime(0);
    setDuration(NaN);
    audio.src = `/static/bgm/${TRACKS[index].file}.ogg`;
    void audio.play();
  };

  return (
    <CafePage
      heading="Jukebox"
      className="jukebox-page"
      toolbar={
        <div className="button-squish-zone">
          <Tooltip text={LOOP_MODES[loopMode].label} placement="left">
            <button
              onClick={() => setLoopMode((loopMode + 1) % LOOP_MODES.length)}
              aria-label={`${LOOP_MODES[loopMode].label} (click to change)`}
            >
              <Twemoji>{LOOP_MODES[loopMode].emoji}</Twemoji>
            </button>
          </Tooltip>
          <Tooltip text="Stop sound effects" placement="left">
            <button
              onClick={() => SFXPlayer.howl.stop()}
              aria-label="Stop sound effects"
            >
              <Twemoji>🔇</Twemoji>
            </button>
          </Tooltip>
        </div>
      }
    >
      {/* Out of the cafe frame, which would carry a fixed child with it. */}
      {current === SMOBSTER_TRACK &&
      time >= SMOBSTER_START &&
      time < SMOBSTER_END
        ? createPortal(
            <img
              className="jukebox-smobster"
              src="/static/images/smobster.gif"
              alt=""
              data-paused={!isPlaying || undefined}
            />,
            document.body
          )
        : null}
      <audio
        ref={audioRef}
        loop={loop === "one"}
        onPlay={() => setIsPlaying(true)}
        onPause={() => setIsPlaying(false)}
        onTimeUpdate={(e) => setTime(e.currentTarget.currentTime)}
        onDurationChange={(e) => setDuration(e.currentTarget.duration)}
        onEnded={() => {
          if (current === null) return;
          if (current + 1 < TRACKS.length) play(current + 1);
          else if (loop === "all") play(0);
        }}
      />
      <section className="jukebox-section">
        <h2 className="cafe-heading">Music</h2>
        <ol className="jukebox-tracks">
          {TRACKS.map(({ title, credit }, index) => {
            const isCurrent = index === current;
            return (
              <li key={title}>
                <button
                  type="button"
                  className="jukebox-track"
                  data-current={isCurrent || undefined}
                  onClick={() => play(index)}
                  aria-label={`${isCurrent && isPlaying ? "Pause" : "Play"} ${title}`}
                >
                  <span className="jukebox-track-icon" aria-hidden>
                    {isCurrent && isPlaying ? "⏸" : "▶"}
                  </span>
                  <span className="jukebox-track-title">{title}</span>
                  <span className="jukebox-track-credit">
                    {credit ?? TRACK_CREDIT}
                  </span>
                  <span className="jukebox-track-time">
                    {isCurrent
                      ? `${formatTime(time)} / ${formatTime(duration)}`
                      : null}
                  </span>
                </button>
                {isCurrent ? (
                  <input
                    type="range"
                    className="jukebox-seek"
                    aria-label={`Seek ${title}`}
                    min={0}
                    max={Number.isFinite(duration) ? duration : 0}
                    step="any"
                    value={time}
                    onChange={(e) => {
                      const audio = audioRef.current;
                      if (audio !== null)
                        audio.currentTime = Number(e.currentTarget.value);
                    }}
                  />
                ) : null}
              </li>
            );
          })}
        </ol>
      </section>
      <section className="jukebox-section">
        <h2 className="cafe-heading">Sound effects</h2>
        <ul className="jukebox-tracks">
          {SFX.map(([name, [, ms]]) => (
            <li key={name}>
              <button
                type="button"
                className="jukebox-track"
                onClick={() => SFXPlayer.play(name, { stopOtherSfx: false })}
                aria-label={`Play ${name}`}
              >
                <span className="jukebox-track-icon" aria-hidden>
                  ▶
                </span>
                <span className="jukebox-track-title">{name}</span>
                <span className="jukebox-track-credit">
                  {SFX_CREDITS[name]}
                </span>
                <span className="jukebox-track-time">
                  {(ms / 1000).toFixed(1)}s
                </span>
              </button>
            </li>
          ))}
        </ul>
      </section>
      {isAdmin === true ? <Jackbax /> : null}
    </CafePage>
  );
}

function Jackbax() {
  const adminQueueScopeState = useGlobalScopeState(ScopeType.ADMIN_QUEUE);
  const vowelsScopes =
    adminQueueScopeState === null
      ? null
      : Object.values(adminQueueScopeState.tasks)
          .filter(
            (task) =>
              task.type === AdminQueueTaskType.PUZZLE_SUBMISSION &&
              task.submissionType === PuzzleSubmissionType.VOWELS
          )
          .map(({ teamId }) => ({ teamId }));
  const vowelsScopeStates = useScopeStateArrayResolvable(
    ScopeType.TEAM_VOWELS,
    vowelsScopes
  );
  const audioRef = useRef<HTMLAudioElement>(null);
  if (vowelsScopes === null || vowelsScopeStates === null) return null;
  const getText = (status?: VowelsStatus): string | null => {
    if (status === undefined) return null;
    switch (status.type) {
      case VowelsStatusType.PENDING:
        return null;
      case VowelsStatusType.ACCEPTED:
        return `✅ ${status.comment ?? ""}`;
      case VowelsStatusType.REJECTED:
        return `❌ ${status.reason}`;
    }
  };
  return (
    <section className="jukebox-section">
      <h2 className="cafe-heading">Vowels</h2>
      <audio ref={audioRef} />
      <ul className="jukebox-tracks">
        {vowelsScopeStates.map(({ audioUrl = null, status }, i) => {
          if (audioUrl === null) return null;
          const text = getText(status);
          const { teamId } = vowelsScopes[i];
          return (
            <li key={audioUrl}>
              <button
                type="button"
                className="jukebox-track"
                onClick={() => {
                  const audio = audioRef.current;
                  if (audio === null) return;
                  audio.src = makeSubmittedFileUrl(audioUrl);
                  void audio.play();
                }}
                aria-label="Play"
              >
                <span className="jukebox-track-icon" aria-hidden>
                  ▶
                </span>
                <span className="jukebox-track-title">
                  <TeamDisplayName teamId={teamId} hideAdminLinks />
                </span>
                {text && (
                  <Twemoji className="jukebox-track-time">{text}</Twemoji>
                )}
              </button>
            </li>
          );
        })}
      </ul>
    </section>
  );
}

export default JukeboxPage;
