import "./CountdownPage.css";

const MINUTE = 60 * 1000;
const PREVIEW_LEAD = { lam: 20 * MINUTE, camille: 10 * MINUTE };
const SILHOUETTE_DURATION = 3 * MINUTE;

export type PreviewRole = keyof typeof PREVIEW_LEAD;
type PrologueRole = NonNullable<PuzzleMetadata["prologue"]>;

/** A span of server time. */
export type Fade = { start: number; duration: number };

export type Prologue = {
  /** Scene converted to playback. */
  playback: SolveDialoguePlayback;
  canPlay: { [role in PreviewRole]: boolean };
  /** Each scene's first sprite. */
  sprite: { [role in PreviewRole]: string | undefined };
  /** Each character's silhouette fade-in, once it has begun. */
  appear: { [role in PreviewRole | "taylor"]: Fade | null };
  seen: { [role in PreviewRole]: boolean };
  /** On taylor-0, fresh from the countdown, before it has been seen. */
  entering: boolean;
  /** Current scene on screen. */
  playing: PreviewRole | null;
  play: (role: PreviewRole) => void;
  leave: (() => void) | null;
  /** About to be sent from this page into the prologue. */
  redirecting: boolean;
};

export const PrologueContext = createContext<Prologue | null>(null);

const NO_PLAYBACK: SolveDialoguePlayback = { status: "none" };

const linesOf = (content: FullPuzzleContent | null) =>
  content?.type === PuzzleContentType.STORY
    ? keyframesToDialogueLines(content.keyframes, content.firstKeyframeId)
    : [];

const usePreviewStart = create<{ start: number | null }>(() => ({
  start: null,
}));

function useHuntStartTime(): number | null {
  const preview = usePreviewStart((state) => state.start);
  const real = useTeamScopeState()?.huntStartTime ?? null;
  return preview ?? real;
}

/**
 * Runs the prologue for WorldBase: plays lam-0 and camille-0 on the
 * countdown without completing them, and keeps the team on the countdown,
 * then on taylor-0, until they've been through each.
 */
export function usePrologue(): Prologue {
  const inCountdown = useRouteMatch("countdown") !== null;
  const inScene = useRouteMatch("scene") !== null;
  const inTeams = useRouteMatch("teams") !== null;
  const inTeam = useRouteMatch("team") !== null;
  const inTeamPage = inTeams || inTeam;
  const { puzName: slugPuzName } = useParsedSlug();
  const isAdmin = useIsAdmin();
  const teamId = useTeamId();
  const sockClient = useSockClient();
  const teamScopeState = useTeamScopeState();
  const puzzles = teamScopeState?.puzzles ?? null;

  const puzName = useMemo(() => {
    if (puzzles === null) return null;
    const puzNames: Partial<{ [role in PrologueRole]: string }> = {};
    for (const { puzName, prologue } of Object.values(puzzles))
      if (prologue !== undefined) puzNames[prologue] = puzName;
    const { lam, camille, taylor } = puzNames;
    if (lam === undefined || camille === undefined || taylor === undefined)
      return null;
    return { lam, camille, taylor };
  }, [puzzles]);

  const setRedirectRoute = useNavStore((state) => state.setRedirectRoute);
  const updateBrowserWidePersistentState =
    useUpdateBrowserWidePersistentState();
  const leaveLock = useUILock();

  const huntStartTime = useHuntStartTime();
  const lead = (role: PreviewRole, extra = 0) =>
    huntStartTime === null ? null : huntStartTime - PREVIEW_LEAD[role] - extra;
  const canPlay = {
    lam: useServerTimeReached(lead("lam")) ?? false,
    camille: useServerTimeReached(lead("camille")) ?? false,
  };
  const hasAppeared = {
    lam: useServerTimeReached(lead("lam", SILHOUETTE_DURATION)) ?? false,
    camille:
      useServerTimeReached(lead("camille", SILHOUETTE_DURATION)) ?? false,
  };
  const appear = (role: PreviewRole): Fade | null => {
    const start = lead(role, SILHOUETTE_DURATION);
    return hasAppeared[role] && start !== null
      ? { start, duration: SILHOUETTE_DURATION }
      : null;
  };
  const hasHuntStarted = useServerTimeReached(huntStartTime) ?? false;
  // Taylor arrives as the countdown ends, to take the team into the cafe.
  const taylorStart =
    huntStartTime === null ? null : huntStartTime - SILHOUETTE_DURATION;
  const hasTaylorAppeared = useServerTimeReached(taylorStart) ?? false;

  // prefetch
  const contents = {
    lam: useScopeStateResolvable(
      ScopeType.PUZZLE_CONTENT,
      inCountdown && puzName !== null ? { puzName: puzName.lam } : null
    ),
    camille: useScopeStateResolvable(
      ScopeType.PUZZLE_CONTENT,
      inCountdown && puzName !== null ? { puzName: puzName.camille } : null
    ),
  };

  const [requested, setRequested] = useState<{
    role: PreviewRole;
    pending: boolean;
  } | null>(null);
  const lamLines = useMemo(() => linesOf(contents.lam), [contents.lam]);
  const camilleLines = useMemo(
    () => linesOf(contents.camille),
    [contents.camille]
  );
  const allLines = { lam: lamLines, camille: camilleLines };
  const lines = requested === null ? [] : allLines[requested.role];
  const requestedPuzName =
    requested === null || puzName === null ? null : puzName[requested.role];
  const { playback, play } = useDialoguePlayback(
    inCountdown ? requestedPuzName : null,
    lines
  );
  useEffect(() => {
    if (requested?.pending !== true) return;
    play();
    setRequested({ ...requested, pending: false });
  }, [requested, play]);

  const hasSeenLam = useHasSeenSolveDialogue(puzName?.lam ?? null);
  const hasSeenCamille = useHasSeenSolveDialogue(puzName?.camille ?? null);
  const leave =
    puzName !== null &&
    teamId !== null &&
    hasSeenLam &&
    hasSeenCamille &&
    hasHuntStarted
      ? () =>
          leaveLock.acquireAndRun(async () => {
            const { lam, camille } = puzName;
            const resps = await Promise.all(
              [lam, camille].map((puzName) =>
                sockClient.sendScopeStepAndWaitAsync(
                  { type: ScopeType.TEAM_CUTSCENES, teamId },
                  { setCutsceneComplete: puzName }
                )
              )
            );
            if (resps.includes(null)) return;
            updateBrowserWidePersistentState({
              completedStoryBeats: { [lam]: true, [camille]: true },
            });
            const taylor = teamScopeState?.puzzles[puzName.taylor];
            setRedirectRoute(
              taylor === undefined ||
                (taylor.solveTime !== undefined && !settings.isPosthunt)
                ? { route: "puzzles", replace: true }
                : {
                    route: "scene",
                    params: { slug: taylor.slug },
                    replace: true,
                  }
            );
          })
      : null;

  const isPlaying = playback.status === "playing";
  // Worked out during render, so WorldBase can hold the page it's leaving.
  const redirect = useMemo((): RedirectRoute<RouteName> | null => {
    if (
      isAdmin === true ||
      settings.isPosthunt ||
      inTeamPage ||
      puzName === null ||
      teamScopeState === null
    )
      return null;
    const isSolved = (puzName: string) =>
      teamScopeState.puzzles[puzName]?.solveTime !== undefined;
    if (!isSolved(puzName.lam) || !isSolved(puzName.camille))
      return inCountdown ? null : { route: "countdown", replace: true };
    // let a teammate finish the line they're on before moving them
    if (inCountdown && isPlaying) return null;
    const taylor = teamScopeState.puzzles[puzName.taylor];
    if (taylor !== undefined && taylor.solveTime === undefined)
      return inScene && slugPuzName === puzName.taylor
        ? null
        : { route: "scene", params: { slug: taylor.slug }, replace: true };
    return inCountdown ? { route: "puzzles", replace: true } : null;
  }, [
    isAdmin,
    inTeamPage,
    puzName,
    teamScopeState,
    inCountdown,
    inScene,
    slugPuzName,
    isPlaying,
  ]);
  useEffect(() => {
    // isAdmin is null until auth; hold the page but don't move yet.
    if (isAdmin === false && redirect !== null) setRedirectRoute(redirect);
  }, [isAdmin, redirect, setRedirectRoute]);

  return {
    playback: inCountdown ? playback : NO_PLAYBACK,
    canPlay,
    sprite: {
      lam: lamLines[0]?.imageName,
      camille: camilleLines[0]?.imageName,
    },
    appear: {
      lam: appear("lam"),
      camille: appear("camille"),
      taylor:
        hasTaylorAppeared && taylorStart !== null
          ? { start: taylorStart, duration: SILHOUETTE_DURATION }
          : null,
    },
    seen: { lam: hasSeenLam, camille: hasSeenCamille },
    entering:
      inScene &&
      puzName !== null &&
      slugPuzName === puzName.taylor &&
      teamScopeState?.puzzles[puzName.taylor]?.solveTime === undefined,
    playing: isPlaying ? (requested?.role ?? null) : null,
    play: (role) => setRequested({ role, pending: true }),
    leave,
    redirecting: redirect !== null && !inCountdown,
  };
}

const SUNRISE = 10 * MINUTE;
const NIGHT_FADE: Keyframe[] = [
  { opacity: 1, easing: "ease-in" },
  { opacity: 0 },
];

/** Plays `keyframes` on `ref` over `fade`, in server time. */
export function useServerTimedAnimation(
  ref: RefObject<HTMLElement | null>,
  keyframes: Keyframe[],
  fade: Fade | null
) {
  const offset = useServerInteractionStore((state) => state.serverTimeOffset);
  const start = fade?.start ?? null;
  const duration = fade?.duration ?? null;
  useEffect(() => {
    const elt = ref.current;
    if (elt === null || offset === null || start === null || duration === null)
      return;
    const animation = elt.animate(keyframes, { duration, fill: "both" });
    animation.currentTime = offset + performance.now() - start;
    return () => animation.cancel();
  }, [ref, keyframes, offset, start, duration]);
}

/** Night fades to day over the last ten minutes. */
export function Sunrise({
  className,
  image,
}: {
  className: string;
  image: string;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const huntStartTime = useHuntStartTime();
  useServerTimedAnimation(
    ref,
    NIGHT_FADE,
    huntStartTime === null
      ? null
      : { start: huntStartTime - SUNRISE, duration: SUNRISE }
  );
  return (
    <div
      ref={ref}
      className={className}
      style={{ backgroundImage: `url(${image})` }}
    />
  );
}

const PREVIEW_MAX_MINUTES = 30;
const clampPreviewMinutes = (minutes: number) =>
  Math.min(PREVIEW_MAX_MINUTES, Math.max(0, minutes));

function CountdownPreview(props: { now: number; secondsLeft: number }) {
  const { now, secondsLeft } = props;
  const [minutes, setMinutes] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);

  const setPreview = (value: string) => {
    const parsed = parseFloat(value);
    if (!Number.isFinite(parsed)) {
      setMinutes(value);
      usePreviewStart.setState({ start: null });
      return;
    }
    const clamped = clampPreviewMinutes(parsed);
    setMinutes(clamped === parsed ? value : String(clamped));
    usePreviewStart.setState({ start: now + clamped * MINUTE });
  };

  const handleWheel = useEvent((e: WheelEvent) => {
    if (e.deltaY === 0) return;
    e.preventDefault();
    const parsed = parseFloat(minutes);
    const current = Number.isFinite(parsed)
      ? parsed
      : Math.round(secondsLeft / 60);
    const next = clampPreviewMinutes(
      Math.round(current) + (e.deltaY < 0 ? 1 : -1)
    );
    setPreview(String(next));
  });
  useEffect(() => {
    const input = inputRef.current;
    if (input === null) return;
    input.addEventListener("wheel", handleWheel, { passive: false });
    return () => input.removeEventListener("wheel", handleWheel);
  }, [handleWheel]);

  return (
    <div className="countdown-preview">
      <Tooltip
        text="This countdown page was shown to solvers shortly before the hunt started. Enter a time or scroll in the box to adjust the countdown time."
        placement="bottom"
      >
        <Twemoji tag="span">ℹ️</Twemoji>
      </Tooltip>
      <label>
        Preview minutes left{" "}
        <input
          ref={inputRef}
          type="number"
          step="any"
          min={0}
          max={PREVIEW_MAX_MINUTES}
          placeholder="real"
          value={minutes}
          onChange={(evt) => setPreview(evt.target.value)}
        />
      </label>
    </div>
  );
}

function CountdownPage() {
  const isAdmin = useIsAdmin() === true;
  const canPreview = isAdmin || settings.isPosthunt;
  const huntStartTime = useHuntStartTime();
  const now = useServerNow(100);
  const secondsLeft =
    now === null || huntStartTime === null
      ? 0
      : Math.max(0, Math.ceil((huntStartTime - now) / 1000));
  if (secondsLeft === 0 && !canPreview) return null;
  return (
    <div className="countdown-hud">
      <div className="countdown-timer">
        {`${Math.floor(secondsLeft / 60)}:${String(secondsLeft % 60).padStart(2, "0")}`}
      </div>
      {canPreview && now !== null ? (
        <CountdownPreview now={now} secondsLeft={secondsLeft} />
      ) : null}
    </div>
  );
}

export default CountdownPage;
