/** Placement for one sprite, as percentages of the stage width. */
export type SpritePlacement = {
  left: number;
  width: number;
};

const MAX_GAP = 32;
const MAX_SPAN = 68;
const BASE_WIDTH = 40;

/** Lays out `count` sprites left to right, evenly spaced about center. */
export function stageLayout(count: number): SpritePlacement[] {
  if (count <= 0) return [];
  const width = count <= 3 ? BASE_WIDTH : Math.max(24, 120 / count);
  if (count === 1) return [{ left: 50, width }];
  const span = Math.min(MAX_GAP * (count - 1), MAX_SPAN);
  const gap = span / (count - 1);
  return Array.from({ length: count }, (_, i) => ({
    left: 50 - span / 2 + i * gap,
    width,
  }));
}
