import { useEffect, useState } from "react";
import Twemoji from "react-twemoji";
import { TimedTokenType } from "sockapi/scope-specs/team-hints-spec";
import { PuzzleType } from "sockapi/puzzle-data";
import settings from "settings";
import { Emoji } from "components/Icon";
import TeamDisplayName from "components/TeamDisplayName";
import Tooltip from "components/Tooltip";
import {
  useTeamScopeState,
  useNumTotalTokens,
  useNumUsedFreeAnswers,
  useNumUsedHintTokens,
} from "stores/ScopeStateStore";
import {
  useServerInteractionStore,
  useTeamId,
} from "stores/ServerInteractionStore";

function NavTeamName() {
  const sockClient = useServerInteractionStore(
    (state) => state.getSockClient
  )();
  const teamId = useTeamId();
  const teamScopeState = useTeamScopeState();
  const numTotalHintTokens = useNumTotalTokens(teamId, TimedTokenType.HINT);
  const numUsedHintTokens = useNumUsedHintTokens(teamId);
  const numTotalFreeAnswers = useNumTotalTokens(
    teamId,
    TimedTokenType.FREE_ANSWER
  );
  const numUsedFreeAnswers = useNumUsedFreeAnswers(teamId);
  const [connected, setConnected] = useState(false);

  useEffect(() => {
    return sockClient?.addAuthEffect(() => {
      setConnected(true);
      return () => {
        setConnected(false);
      };
    });
  }, [sockClient]);

  if (
    teamId === null ||
    numTotalHintTokens === null ||
    numUsedHintTokens === null ||
    numTotalFreeAnswers === null ||
    numUsedFreeAnswers === null ||
    teamScopeState === null
  )
    return null;

  let numSolves = 0;
  let metaSolves = 0;
  for (const puzData of Object.values(teamScopeState.puzzles))
    if (puzData.type === PuzzleType.PUZZLE && puzData.solveTime !== undefined) {
      if (puzData.isMeta) metaSolves++;
      else numSolves++;
    }

  return (
    <>
      {!settings.localMode ? (
        <Tooltip
          text={
            connected ? "Connected" : "Disconnected; attempting to reconnect..."
          }
        >
          <div className="nav-stat">
            <Twemoji tag="span">{connected ? "🟢️" : "🟡️"}</Twemoji>
            &nbsp;{connected ? "Connected" : "Disconnected"}
          </div>
        </Tooltip>
      ) : null}
      <TeamDisplayName hideAdminLinks shipStyle="link" />
      {numTotalHintTokens === 0 &&
      numTotalFreeAnswers === 0 &&
      numSolves === 0 ? null : (
        <div className="nav-stats">
          {numSolves === 0 ? null : (
            <Tooltip text="Puzzles solved">
              {numSolves}
              <Twemoji tag="small">{Emoji.PUZZLE_SOLVED}</Twemoji>
            </Tooltip>
          )}
          {metaSolves === 0 ? null : (
            <Tooltip text="Metas solved">
              {metaSolves}
              <Twemoji tag="small">{Emoji.META_SOLVED}</Twemoji>
            </Tooltip>
          )}
          {numTotalHintTokens === 0 ? null : (
            <Tooltip text="Hints available">
              {numTotalHintTokens - numUsedHintTokens}
              <Twemoji tag="small">{Emoji.HINT}</Twemoji>
            </Tooltip>
          )}
          {numTotalFreeAnswers === 0 ? null : (
            <Tooltip text="Free answers available">
              {numTotalFreeAnswers - numUsedFreeAnswers}
              <Twemoji tag="small">{Emoji.FREE_ANSWER}</Twemoji>
            </Tooltip>
          )}
        </div>
      )}
    </>
  );
}

export default NavTeamName;
