import { Fragment, useState } from "react";
import "components/PuzzleContent/Arrows.css";
import {
  ARROW_DOT,
  ARROW_GLYPHS,
  ARROW_STROKE,
  ARROW_Y,
} from "components/PuzzleContent/arrow-glyphs";
import { numberGrid, PuzzleGrid } from "components/PuzzleContent/puzzle-grid";

export const ARROWS_TITLE =
  ". ese nn sw wnw nnw * ss nw w nne n ee ssw ssw wsw sse";
export const ARROWS_DISPLAY_NAME = "(arrows)";

// 😵‍💫️
export const escapeArrows = (s: string) =>
  s.endsWith(ARROWS_DISPLAY_NAME) ? s + "\u200b" : s;

function Glyph({ tok }: { tok: string }) {
  if (tok === "*") return <span className="arrow-gap" />;
  if (tok === "'") return <span className="arrow-apostrophe no-copy">’</span>;
  const { x, w, d, dot } = ARROW_GLYPHS[tok];
  return (
    <svg
      className="arrow-glyph"
      viewBox={`${x} ${-ARROW_Y} ${w} ${2 * ARROW_Y}`}
      style={{
        width: `calc(${w} * var(--arrow-unit))`,
        height: `calc(${2 * ARROW_Y} * var(--arrow-unit))`,
      }}
      aria-hidden
    >
      <path d={d} strokeWidth={ARROW_STROKE} />
      {dot ? <circle r={ARROW_DOT} /> : null}
    </svg>
  );
}

export function Arrows({ seq }: { seq: string }) {
  const text = seq.replaceAll("*", "/");
  return (
    <span className="arrows" role="img" aria-label={text}>
      <span className="copy-only">{text}</span>
      {seq.split(" ").map((tok, i) => (
        <Glyph key={i} tok={tok} />
      ))}
    </span>
  );
}

export function ArrowClues(props: {
  heading: string;
  clues: Record<number, string>;
}) {
  const { heading, clues } = props;
  return (
    <>
      <h3>
        <Arrows seq={heading} />
      </h3>
      <table className="arrow-clues">
        <tbody>
          {Object.entries(clues).map(([n, seq]) => (
            <tr key={n}>
              <td>{n}.</td>
              <td>
                <Arrows seq={seq} />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </>
  );
}

const MOVES: Record<string, [number, number]> = {
  n: [-1, 0],
  ne: [-1, 1],
  e: [0, 1],
  se: [1, 1],
  s: [1, 0],
  sw: [1, -1],
  w: [0, -1],
  nw: [-1, -1],
};

/** One per word of a clue, for its path and its text; most words is 4. */
const WORD_HUES = ["green", "blue", "red", "yellow"];

type Cell = [number, number];

/**
 * Follows `seq` from `start`: each token is a run of moves ending on a letter,
 * e.g. "ese" is e then se, and "*" starts the next word in place. Returns each
 * word's visited cells and the number of steps before it.
 */
function trace(start: Cell, seq: string) {
  let [r, c] = start;
  let steps = 0;
  const words = [{ cells: [start], start: 0 }];
  for (const tok of seq.split(" ")) {
    if (tok === "*") words.push({ cells: [[r, c]], start: steps });
    else {
      // "." and "'" have no moves
      for (const m of tok.match(/[ns][ew]?|[ew]/g) ?? []) {
        r += MOVES[m][0];
        c += MOVES[m][1];
        words[words.length - 1].cells.push([r, c]);
        steps++;
      }
    }
  }
  return words;
}

const center = ([r, c]: Cell) => ({ x: c + 0.5, y: r + 0.5 });

/** Each word in its hue, shading light to dark from start to end. */
function PathOverlay({ words }: { words: ReturnType<typeof trace> }) {
  const total = words.reduce((n, w) => n + w.cells.length - 1, 0);
  const shade = (i: number, t: number) =>
    `color-mix(in oklab, var(--${WORD_HUES[i]}-30) ${Math.round(100 * t)}%, var(--${WORD_HUES[i]}-70))`;
  // t of the cell `k` steps into word `i`
  const t = (i: number, k: number) =>
    total ? (words[i].start + k) / total : 1;
  return (
    <g className="arrow-path">
      {words.flatMap(({ cells }, i) =>
        cells.slice(1).map((cell, k) => {
          const a = center(cells[k]);
          const b = center(cell);
          return (
            <line
              key={`${i},${k}`}
              x1={a.x}
              y1={a.y}
              x2={b.x}
              y2={b.y}
              style={{ stroke: shade(i, t(i, k + 0.5)) }}
            />
          );
        })
      )}
    </g>
  );
}

/**
 * A 3x3 classroom; "." is an empty seat. Each run of friends gets a path.
 * `cells` is a verbose alternative to `text` with space-separated seats, where
 * a seat may list its options, e.g. "A/C L A/C|. . .|. N O". In either, a
 * seat followed by "!" is highlighted.
 */
export function FuzzyLogic(props: { text: string } | { cells: string }) {
  const marked =
    "cells" in props
      ? props.cells.split("|").map((row) => row.trim().split(/\s+/))
      : props.text.split("|").map((row) => row.match(/.!?/g) ?? []);
  const highlighted = marked.map((row) => row.map((s) => s.endsWith("!")));
  const seats = marked.map((row) => row.map((s) => s.replace(/!$/, "")));
  // Seats with options are empty here, so only placed students get paths.
  const text = seats
    .map((row) => row.map((s) => (s.length === 1 ? s : ".")).join(""))
    .join("|");
  const runs: Cell[][] = [[]];
  for (const c of "ABCDEFGHIJKLMNO") {
    const i = text.indexOf(c);
    if (i < 0) runs.push([]);
    else runs[runs.length - 1].push([Math.floor(i / 4), i % 4]);
  }
  // "?" seats are unknown friends, e.g. a back pair: a run of their own.
  runs.push(
    seats.flatMap((row, r) =>
      row.flatMap((s, c): Cell[] => (s === "?" ? [[r, c]] : []))
    )
  );
  let steps = 0;
  const words = runs
    .filter((cells) => cells.length > 1)
    .map((cells) => {
      const word = { cells, start: steps };
      steps += cells.length - 1;
      return word;
    });
  return (
    <PuzzleGrid
      text={text}
      fills={highlighted
        .map((row) => row.map((h) => (h ? "1" : ".")).join(""))
        .join("|")}
      fillColors={["", "var(--red-70)"]}
      overlay={<PathOverlay words={words} />}
      renderCell={(r, c) =>
        seats[r][c].length > 1 ? (
          <span className="fuzzy-logic-options">{seats[r][c]}</span>
        ) : null
      }
    />
  );
}

/**
 * Placed / attended counts for A to O, in that order, e.g. "2/4 0/5-6 ...",
 * or just attended counts, e.g. "4 6 ...", laid out in columns of 3. Fully
 * placed students are muted.
 */
export function FuzzyLogicCounts({ counts }: { counts: string }) {
  const entries = counts.trim().split(/\s+/);
  const rows = [0, 1, 2].map((r) =>
    entries.flatMap((_, i) => (i % 3 === r ? [i] : []))
  );
  return (
    <table className="fuzzy-logic-counts">
      <tbody>
        {rows.map((row, r) => (
          <tr key={r}>
            {row.map((i) => {
              const [placed, total] = entries[i].split("/");
              const className = placed === total ? "done" : undefined;
              // Letter and count in separate cells so the counts line up.
              return (
                <Fragment key={i}>
                  <th
                    className={className}
                    // Inline to beat the solution page's table padding.
                    style={{ paddingLeft: i < 3 ? undefined : "1.2em" }}
                  >
                    {"ABCDEFGHIJKLMNO"[i]}
                  </th>
                  <td className={className}>
                    {entries[i].replaceAll("-", "–")}
                  </td>
                </Fragment>
              );
            })}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

/** Crossword number to its cell. */
function clueStarts(text: string) {
  const starts = new Map<number, Cell>();
  numberGrid(text).forEach((row, r) =>
    row.forEach((n, c) => n && starts.set(n, [r, c]))
  );
  return starts;
}

/** The grid with the path of `seq` from clue number `start`. */
export function ArrowsPath(props: {
  text: string;
  start: number;
  seq: string;
}) {
  const { text, start, seq } = props;
  return (
    <PuzzleGrid
      text={text}
      numbered
      overlay={<PathOverlay words={trace(clueStarts(text).get(start)!, seq)} />}
    />
  );
}

/** [clue number, arrows, clue, answer]. */
type ArrowAnswer = [number, string, string, string];

export function ArrowsSolution(props: {
  text: string;
  across: ArrowAnswer[];
  down: ArrowAnswer[];
}) {
  const { text, across, down } = props;
  const [hovered, setHovered] = useState<string>();
  const starts = clueStarts(text);
  const path = hovered
    ? trace(
        starts.get(
          [...across, ...down].find(([, seq]) => seq === hovered)![0]
        )!,
        hovered
      )
    : undefined;

  const table = (heading: string, clues: ArrowAnswer[]) => (
    <div>
      <h3>{heading}</h3>
      <table className="arrow-solution-clues">
        <tbody onMouseLeave={() => setHovered(undefined)}>
          {clues.map(([n, seq, clue, answer]) => (
            <tr
              key={n}
              className={hovered === seq ? "arrow-active" : undefined}
              onMouseEnter={() => setHovered(seq)}
            >
              <td>{n}.</td>
              <td>
                <Arrows seq={seq} />
              </td>
              <td>
                {clue.split(" ").map((word, i) => (
                  <Fragment key={i}>
                    {i > 0 ? " " : null}
                    <span style={{ color: `var(--${WORD_HUES[i]}-20)` }}>
                      {word}
                    </span>
                  </Fragment>
                ))}
              </td>
              <td className="arrow-answer">{answer}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );

  return (
    <div className="arrow-solution-wrapper">
      <div className="arrow-solution">
        <PuzzleGrid
          text={text}
          numbered
          overlay={<PathOverlay words={path ?? []} />}
        />
        <div>
          {table("Across", across)}
          {table("Down", down)}
        </div>
      </div>
    </div>
  );
}
