import { useState } from "react";

import { ScopeType } from "sockapi/scope-types";
import { WORDTRIS_CONFIG } from "sockapi/scope-specs/team-wordtris-spec";
import { useScopeStateResolvable } from "stores/ScopeStateStore";
import { useTeamId } from "stores/ServerInteractionStore";
import {
  WordtrisGrids,
  wordtrisPieceCells,
} from "components/PuzzleContent/Wordtris";
import AnswerListChecker from "components/PuzzlePage/checkers/AnswerListChecker";

/** Each piece's fills, as in the puzzle's `pieces` prop. */
const PIECE_FILLS = [
  ".3|.1|13",
  "2.|13|.1",
  ".1|11|1.",
  "11.|.22",
  "21|13",
  "2222",
  "1113",
  "2.|2.|21",
  "21|23",
  "33|1.|1.",
  "111|.3.",
  ".1.|131",
  ".1|.3|11",
  "13.|.11",
  "1.|33|2.",
  "11.|.11",
  "1..|311",
  "2222",
  "1.|21|.1",
  "1112",
  "..1|111",
  ".31|33.",
  "1.|11|1.",
  "133|..2",
  "23.|.11",
  "2.|11|.1",
  "2.|2.|23",
  "22|31",
  "1.|11|1.",
  "22|31",
  ".11|31.",
  "11|31",
  "1113",
  "..1|313",
  "121|2..",
];
/** The puzzle's given letters, as in its `grids` prop. */
const GIVENS = [
  "....E|.....|.....|.....|..E..|.....",
  ".....|....N|.....|.....|.P...|.....",
  ".B...|.....|.....|.....|.....|..R..",
  ".....|.....|.....|....T|.B...|.....",
  "O....|.....|.....|.I...|.....|.....",
];
/** Each solved grid, with which piece covers each cell, as in the solution. */
const SOLUTION = [
  {
    text: "SPITE|FINAL|TEETH|SCALE|NEEDS|ESSAY",
    pieces: "aaaa.|bbbcc|dbcce|dddee|ff.eg|ffggg",
  },
  {
    text: "NAVAL|ALIGN|MAJOR|EMAIL|OPERA|FACTS",
    pieces: "abbbb|aacc.|daecc|ddeee|d.fgg|fffgg",
  },
  {
    text: "ABUSE|THREE|EARLY|KNIFE|AREAS|FIRST",
    pieces: "a.bbb|aabcd|aeecd|eeccd|ffggd|ff.gg",
  },
  {
    text: "STEEL|HOUSE|WORST|SLEPT|ABOVE|NEVER",
    pieces: "abbcc|aabcc|adbee|ddee.|d.fff|ggggf",
  },
  {
    text: "OTHER|ARENA|PILLS|HIDES|ELITE|PENAL",
    pieces: ".abbb|aaccb|accdd|e.ffd|eeffd|egggg",
  },
];
/** Each piece's answer, and the grid and solution piece it belongs to. */
const CLUES: [answer: string, grid: number, piece: string][] = [
  ["ACTS", 0, "d"],
  ["ALAN", 1, "a"],
  ["ALSO", 3, "d"],
  ["EAST", 2, "g"],
  ["ELSE", 3, "c"],
  ["EVEN", 3, "g"],
  ["EYES", 2, "d"],
  ["FACE", 1, "f"],
  ["FAIR", 2, "f"],
  ["FILE", 2, "c"],
  ["FINE", 0, "b"],
  ["HATE", 2, "a"],
  ["HEAR", 4, "b"],
  ["HELD", 0, "e"],
  ["HELP", 4, "e"],
  ["IGOR", 1, "c"],
  ["JAIL", 1, "e"],
  ["LANE", 4, "g"],
  ["LATE", 0, "c"],
  ["LAVA", 1, "b"],
  ["LESS", 4, "d"],
  ["LINE", 4, "c"],
  ["MEMO", 1, "d"],
  ["OVER", 3, "f"],
  ["PART", 4, "a"],
  ["RANK", 2, "e"],
  ["SAYS", 0, "g"],
  ["SEEN", 0, "f"],
  ["SHOW", 3, "a"],
  ["STAR", 1, "g"],
  ["STEP", 3, "e"],
  ["TIED", 4, "f"],
  ["TIPS", 0, "a"],
  ["TRUE", 3, "b"],
  ["USER", 2, "b"],
];

type WordtrisState = {
  letters: string[];
  placements: (Parameters<typeof wordtrisPieceCells>[1] | null)[];
};

const { cellsPerPiece, numGrids, rows, cols } = WORDTRIS_CONFIG;

/** Fill chars, as in `WordtrisGrids`: 1 gray, 2 green, 3 yellow. */
const pieceStatus = (p: number, cells: [number, number, number][]) => {
  const [answer, grid, piece] = CLUES[p];
  if (cells[0][0] !== grid) return "1";
  const { text, pieces } = SOLUTION[grid];
  const [textRows, pieceRows] = [text.split("|"), pieces.split("|")];
  const isRight =
    cells.every(([, r, c], k) => textRows[r][c] === answer[k]) &&
    cells.every(([, r, c]) => pieceRows[r][c] === piece);
  return isRight ? "2" : "3";
};

/** Each grid as the team has it, with each piece colored by its status. */
function checkedGrids({ letters, placements }: WordtrisState) {
  // Givens are left unfilled, so their colors aren't mistaken for statuses.
  const grids = GIVENS.map((text) => ({
    text: text.split("|").map((row) => [...row]),
    fills: Array.from({ length: rows }, () => Array<string>(cols).fill(".")),
    // Empty cells share one region, so they get no bars between them; givens
    // are lone cells, as in the solution.
    pieces: text
      .split("|")
      .map((row) => [...row].map((ch): string => (ch === "." ? "_" : "."))),
  }));
  placements.forEach((placement, p) => {
    if (placement === null) return;
    const cells = wordtrisPieceCells(PIECE_FILLS[p], placement);
    const status = pieceStatus(p, cells);
    // Any char but ".", "_" and "|" names a piece for drawing its bars.
    const id = String.fromCharCode(0x100 + p);
    cells.forEach(([g, r, c], k) => {
      const letter = letters[p * cellsPerPiece + k]?.toUpperCase() ?? "";
      grids[g].text[r][c] = /^[A-Z]$/.test(letter) ? letter : ".";
      grids[g].fills[r][c] = status;
      grids[g].pieces[r][c] = id;
    });
  });
  const join = (cells: string[][]) =>
    cells.map((row) => row.join("")).join("|");
  return grids.slice(0, numGrids).map(({ text, fills, pieces }) => ({
    text: join(text),
    fills: join(fills),
    pieces: join(pieces),
  }));
}

/** Each piece's word, or ? if it isn't filled in. */
const wordsOf = ({ letters }: WordtrisState) =>
  PIECE_FILLS.map((_, p) => {
    const word = letters.slice(p * cellsPerPiece, (p + 1) * cellsPerPiece);
    return word.every((letter) => /^[A-Za-z]$/.test(letter))
      ? word.join("").toUpperCase()
      : "?";
  }).join("\n");

export default function WordtrisChecker() {
  const teamId = useTeamId();
  const state = useScopeStateResolvable(
    ScopeType.TEAM_WORDTRIS,
    teamId === null ? null : { teamId }
  );
  const [text, setText] = useState("");
  const [checked, setChecked] = useState<WordtrisState | null>(null);
  return (
    <>
      <AnswerListChecker
        label="Paste the answers, one per line."
        ordered
        answers={CLUES.map(([answer]) => answer)}
        text={text}
        setText={setText}
      />
      {state !== null && (
        <>
          <p>
            <button onClick={() => setText(wordsOf(state))}>Copy pieces</button>{" "}
            <button onClick={() => setChecked(state)}>Check grids</button>
          </p>
          {checked && (
            <div className="puzzle-content">
              <WordtrisGrids grids={checkedGrids(checked)} />
            </div>
          )}
        </>
      )}
    </>
  );
}
