import { KeyboardEvent, useCallback, useMemo, useState } from "react";
import { motion } from "framer-motion";
import { ScopeType } from "sockapi/scope-types";
import {
  applyMetametaMove,
  MetametaMove,
} from "sockapi/scope-specs/team-metameta-spec";
import { CUSTOM_TITLE_MAX_LENGTH } from "sockapi/scope-specs/team-titles-spec";
import {
  useAccessiblePuzzles,
  useCustomTitle,
  usePuzzleDisplayNames,
  useScopeStateResolvable,
} from "stores/ScopeStateStore";
import { useSockClient, useTeamId } from "stores/ServerInteractionStore";
import { CharacterIcon } from "components/Icon";
import { PuzzleLink } from "components/Link";
import { escapeArrows } from "components/PuzzleContent/Arrows";
import { useMotion } from "client-util/motion";
import "components/PuzzleContent/Goodbye.css";

export function Goodbye() {
  const teamId = useTeamId();
  if (teamId === null) return null;
  return <GoodbyeSort teamId={teamId} />;
}

function GoodbyeSort({ teamId }: { teamId: string }) {
  const { spring } = useMotion();
  const sockClient = useSockClient();
  const scope = useMemo(
    () => ({ type: ScopeType.TEAM_METAMETA as const, teamId }),
    [teamId]
  );
  const serverDays =
    useScopeStateResolvable(ScopeType.TEAM_METAMETA, { teamId })?.days ?? null;
  const puzzles = useAccessiblePuzzles();
  const displayNames = usePuzzleDisplayNames();

  const [pending, setPending] = useState<MetametaMove[]>([]);
  const days = useMemo(() => {
    if (serverDays === null) return null;
    const next = serverDays.map((ids) => [...ids]);
    for (const move of pending) applyMetametaMove(next, move);
    return next;
  }, [serverDays, pending]);

  const move = useCallback(
    (m: MetametaMove) => {
      setPending((prev) => [...prev, m]);
      void sockClient
        .sendScopeStepAndWaitAsync(scope, { move: m })
        .catch(() => {})
        .then(() => setPending((prev) => prev.filter((p) => p !== m)));
    },
    [sockClient, scope]
  );

  /** picked lands in days[day] at index at, once removed from its own day */
  const [placing, setPlacing] = useState<{
    picked: string;
    day: number;
    at: number;
  } | null>(null);
  const [result, setResult] = useState<
    "correct" | "incorrect" | "rateLimited" | null
  >(null);
  const submit = async () => {
    setResult(null);
    const resp = await sockClient.sendScopeStepAndWaitAsync(scope, {
      submit: true,
    });
    if (resp === null) return;
    if (resp.isRateLimited === true) setResult("rateLimited");
    else setResult(resp.correct ? "correct" : "incorrect");
  };

  if (days === null) return null;

  const rest =
    placing === null
      ? days
      : days.map((ids) => ids.filter((id) => id !== placing.picked));
  const shown = rest.map((ids, d) =>
    placing !== null && d === placing.day
      ? ids.toSpliced(placing.at, 0, placing.picked)
      : ids
  );
  const offsets = shown.map((_, d) =>
    shown.slice(0, d).reduce((n, ids) => n + ids.length, 0)
  );
  const pickUp = (picked: string, day: number, at: number) =>
    setPlacing({ picked, day, at });
  const hover = (day: number, at: number) => {
    if (placing !== null) setPlacing({ ...placing, day, at });
  };
  const commit = (day: number, at: number) => {
    if (placing === null) return;
    move([placing.picked, day, rest[day][at] ?? null]);
    setPlacing(null);
  };
  const onKeyDown = (e: KeyboardEvent) => {
    if (placing === null) return;
    const { day, at } = placing;
    const clamp = (d: number) => Math.min(at, rest[d].length);
    if (e.key === "Escape") setPlacing(null);
    else if (e.key === "ArrowLeft" && at > 0) hover(day, at - 1);
    else if (e.key === "ArrowRight" && at < rest[day].length)
      hover(day, at + 1);
    else if (e.key === "ArrowUp" && day > 0) hover(day - 1, clamp(day - 1));
    else if (e.key === "ArrowDown" && day < days.length - 1)
      hover(day + 1, clamp(day + 1));
    else return;
    e.preventDefault();
  };

  return (
    <div className="goodbye no-copy" onKeyDown={onKeyDown}>
      {shown.map((ids, d) => (
        <section key={d} className="goodbye-day">
          <h3 className="goodbye-day-label">
            {["Friday", "Saturday", "Sunday", "Monday", "Tuesday"][d]}
          </h3>
          <ol className="goodbye-cards">
            {ids.map((puzName, i) => (
              <motion.li key={puzName} layout transition={spring("small")}>
                <GoodbyeCard
                  puzName={puzName}
                  num={offsets[d] + i + 1}
                  chars={puzzles?.[puzName]?.roundIds ?? []}
                  title={displayNames?.[puzName] ?? "???"}
                  isPicked={placing?.picked === puzName}
                  onHover={() => {
                    if (placing?.picked !== puzName) hover(d, i);
                  }}
                  onClick={() =>
                    placing === null ? pickUp(puzName, d, i) : commit(d, i)
                  }
                />
              </motion.li>
            ))}
            {placing !== null && (
              <li>
                <button
                  type="button"
                  className="goodbye-slot"
                  aria-label={`Place at end of day ${d + 1}`}
                  onMouseEnter={() => hover(d, rest[d].length)}
                  onClick={() => commit(d, rest[d].length)}
                />
              </li>
            )}
          </ol>
        </section>
      ))}
      <p>
        <button type="button" onClick={() => void submit()}>
          Check order
        </button>{" "}
        {result === "correct" && "Correct!"}
        {result === "incorrect" && "Incorrect."}
        {result === "rateLimited" &&
          "Too many checks. Try again in a few seconds."}
      </p>
    </div>
  );
}

function GoodbyeCard({
  puzName,
  num,
  chars,
  title,
  isPicked,
  onHover,
  onClick,
}: {
  puzName: string;
  num: number;
  chars: string[];
  title: string;
  isPicked: boolean;
  onHover: () => void;
  onClick: () => void;
}) {
  const [isRenaming, setIsRenaming] = useState(false);
  const customTitle = useCustomTitle(puzName, () => setIsRenaming(false));

  const contents = (
    <>
      <span className="goodbye-num">{num}</span>
      <span className="goodbye-chars">
        {chars.map((char) => (
          <CharacterIcon key={char} type="icon" characterId={char} />
        ))}
      </span>
    </>
  );

  return (
    <>
      {isRenaming ? (
        <div className="goodbye-card">
          {contents}
          <textarea
            className="goodbye-title"
            autoFocus
            maxLength={CUSTOM_TITLE_MAX_LENGTH}
            defaultValue={customTitle.value}
            disabled={customTitle.disableInput}
            onBlur={(e) => customTitle.set(escapeArrows(e.currentTarget.value))}
            onKeyDown={(e) => {
              e.stopPropagation();
              if (e.key === "Enter") {
                e.preventDefault();
                customTitle.set(escapeArrows(e.currentTarget.value));
              }
              if (e.key === "Escape") setIsRenaming(false);
            }}
          />
        </div>
      ) : (
        <button
          type="button"
          className="goodbye-card"
          aria-pressed={isPicked}
          onMouseEnter={onHover}
          onClick={onClick}
        >
          {contents}
          <span className="goodbye-title">{title}</span>
        </button>
      )}
      <span className="goodbye-actions">
        <button
          type="button"
          aria-label="Rename"
          title="Rename"
          onClick={() => setIsRenaming(true)}
        >
          ✎
        </button>
        <PuzzleLink puzName={puzName} aria-label="Replay" title="Replay">
          ▶
        </PuzzleLink>
      </span>
    </>
  );
}
