import { createContext, use } from "react";
import { useTeamId } from "stores/ServerInteractionStore";

/**
 * Shows another team's synced puzzle state (e.g. the requester's, on a hint
 * request) instead of the active team's. Edits there stay local.
 */
export const PuzzleTeamOverrideContext = createContext<string | null>(null);

/** The team whose synced state to show; `send` is false for an override. */
export function usePuzzleTeam(): { teamId: string | null; send: boolean } {
  const override = use(PuzzleTeamOverrideContext);
  const activeTeamId = useTeamId();
  return override !== null
    ? { teamId: override, send: false }
    : { teamId: activeTeamId, send: true };
}
