import AnswerListChecker, {
  CheckerForm,
  CheckerGrid,
} from "components/PuzzlePage/checkers/AnswerListChecker";

const SKYSCRAPERS = [
  "1235467",
  "3416725",
  "5672143",
  "2741356",
  "7564231",
  "4357612",
  "6123574",
];
const SIZE = SKYSCRAPERS.length;

function checkSkyscrapers(text: string) {
  const digits = text.replace(/[^1-9?]/g, "");
  if (!new RegExp(`^[1-${SIZE}?]{${SIZE * SIZE}}$`).test(digits)) {
    return {
      summary: `Expected ${SIZE} rows of ${SIZE} digits from 1 to ${SIZE}, with ? for unknowns.`,
    };
  }
  const cells = SKYSCRAPERS.map((row, r) =>
    [...row].map((answer, c) => {
      const text = digits[r * SIZE + c];
      return {
        text,
        status:
          text === "?"
            ? ("unknown" as const)
            : text === answer
              ? ("right" as const)
              : ("wrong" as const),
      };
    })
  );
  const statuses = cells.flat().map(({ status }) => status);
  const numCorrect = statuses.filter((status) => status === "right").length;
  const numFilled = statuses.filter((status) => status !== "unknown").length;
  return {
    summary:
      numCorrect === SIZE * SIZE ? (
        <b>Correct!</b>
      ) : (
        <>
          <b>
            {numCorrect} of {numFilled}
          </b>{" "}
          filled cells correct.
        </>
      ),
    details: <CheckerGrid cells={cells} />,
  };
}

export default function RealismChecker() {
  return (
    <>
      <AnswerListChecker
        label="Paste the values of A, C, H, K, M, and P, one per line. Use ? for unknowns."
        ordered
        answers={["15", "8", "9", "16", "12", "7"]}
      />
      <CheckerForm
        label="Paste the Skyscrapers grid, one row per line, without the outside clues. Use ? for unknowns."
        check={checkSkyscrapers}
      />
    </>
  );
}
