import { useRef, useState } from "react";

import { ScopeType } from "sockapi/scope-types";
import {
  VOWELS_CONFIG,
  VowelsStatusType,
} from "sockapi/scope-specs/team-vowels-spec";
import { useSockClient } from "stores/ServerInteractionStore";
import {
  useScopeStateResolvable,
  useTeamAnswerableScopeState,
} from "stores/ScopeStateStore";
import { useNavStore } from "stores/NavStore";
import { Spinner } from "components/Loading";
import { PuzzleLink } from "components/Link";
import { SolveAttemptMessage } from "components/PuzzlePage/PreviousGuessesDisplay";
import { ButtonTabs } from "components/AdminQueue/ButtonTabs";
import TeamDisplayName from "components/TeamDisplayName";
import {
  VowelsStatusDisplay,
  makeSubmittedFileUrl,
} from "components/PuzzleContent/Vowels";
import { toastr } from "Globals";

function VowelsRecording(props: { teamId: string }) {
  const { teamId } = props;
  const vowelsState = useScopeStateResolvable(ScopeType.TEAM_VOWELS, {
    teamId,
  });
  if (vowelsState === null) return <Spinner inline />;
  const { audioUrl } = vowelsState;
  return audioUrl === undefined ? (
    <div>No recording found.</div>
  ) : (
    <audio controls src={makeSubmittedFileUrl(audioUrl)} />
  );
}

export function VowelsAdminQueueTaskSummaryDisplay(props: { teamId: string }) {
  const { teamId } = props;
  return (
    <div>
      <h4>Vowels Submission</h4>
      <div>
        Team: <TeamDisplayName teamId={teamId} />
      </div>
      <VowelsRecording teamId={teamId} />
    </div>
  );
}

export function VowelsAdminQueueTaskDisplay(props: {
  teamId: string;
  isClaimedBySelf: boolean;
}) {
  const { teamId, isClaimedBySelf } = props;
  const vowelsState = useScopeStateResolvable(ScopeType.TEAM_VOWELS, {
    teamId,
  });
  const teamAnswerableScopeState = useTeamAnswerableScopeState(
    teamId,
    VOWELS_CONFIG.puzName
  );
  const sockClient = useSockClient();
  const setRedirectRoute = useNavStore((state) => state.setRedirectRoute);
  const [reviewType, setReviewType] = useState<
    VowelsStatusType.ACCEPTED | VowelsStatusType.REJECTED | null
  >(null);
  const textInputRef = useRef<HTMLTextAreaElement>(null);

  if (vowelsState === null || teamAnswerableScopeState === null)
    return <Spinner inline />;
  const { status } = vowelsState;
  if (status === undefined) return <div>No submission found.</div>;
  const isReviewable = status.type !== VowelsStatusType.ACCEPTED;
  const promptAttempt = Object.values(teamAnswerableScopeState.submissions)
    .filter(({ message }) => message !== undefined)
    .sort((a, b) => b.timestamp - a.timestamp)[0];

  return (
    <div className="admin-queue-task-columns">
      <div>
        <h2>Vowels Submission</h2>
        <div>
          Team: <TeamDisplayName teamId={teamId} />
        </div>
        <div>
          <PuzzleLink
            puzName={VOWELS_CONFIG.puzName}
            subpage="puzzle"
            button
            target="_blank"
          >
            Open puzzle
          </PuzzleLink>
        </div>
        <h4>Prompt</h4>
        {promptAttempt === undefined ? (
          <div>Team has not guessed the prompt answer.</div>
        ) : (
          <SolveAttemptMessage info={promptAttempt} />
        )}
        <h4>Submission</h4>
        <VowelsRecording teamId={teamId} />
        <hr className="show-only-when-small" />
      </div>
      <div>
        <h4>Current status</h4>
        <VowelsStatusDisplay status={status} />
        <hr />
        {!isClaimedBySelf ? (
          <div className="admin-queue-claim-this-task-notice">
            Claim this task to respond to it.
          </div>
        ) : null}
        {isReviewable ? (
          <>
            <div className="admin-queue-task-status-tabs">
              <ButtonTabs
                tabs={[
                  { content: "Pending", value: null, disabled: true },
                  { content: "Accept", value: VowelsStatusType.ACCEPTED },
                  { content: "Reject", value: VowelsStatusType.REJECTED },
                ]}
                selected={reviewType}
                setSelected={setReviewType}
                disabled={!isClaimedBySelf}
              />
            </div>
            {reviewType !== null ? (
              <>
                <div>
                  {reviewType === VowelsStatusType.ACCEPTED
                    ? "Comment (optional, shown to the team, no need to mention answer):"
                    : "Reason (shown to the team):"}
                </div>
                <textarea
                  key={reviewType}
                  disabled={!isClaimedBySelf}
                  ref={textInputRef}
                />
              </>
            ) : null}
            {reviewType !== null ? (
              <button
                disabled={!isClaimedBySelf}
                onClick={async () => {
                  try {
                    const text = textInputRef.current?.value.trim() ?? "";
                    if (
                      reviewType === VowelsStatusType.REJECTED &&
                      text === ""
                    ) {
                      toastr.warning("Reason required.");
                      return;
                    }
                    const review =
                      reviewType === VowelsStatusType.ACCEPTED
                        ? {
                            type: reviewType,
                            ...(text === "" ? {} : { comment: text }),
                          }
                        : { type: reviewType, reason: text };
                    await sockClient.sendScopeStepAndWaitAsync(
                      { type: ScopeType.TEAM_VOWELS, teamId },
                      { review }
                    );
                    toastr.success("Response submitted.");
                    setRedirectRoute({ route: "admin_queue" });
                  } catch (err) {
                    console.error(err);
                  }
                }}
              >
                {reviewType === VowelsStatusType.ACCEPTED
                  ? "Accept and solve puzzle"
                  : "Reject"}
              </button>
            ) : null}
          </>
        ) : null}
      </div>
    </div>
  );
}
