import Question from "components/PuzzleContent/NormalQuiz/Question";
import "./NormalQuiz.css";
import { useState } from "react";
import { FourthWall } from "components/PuzzleContent/puzzle-components";
import { useSockClient } from "stores/ServerInteractionStore";
import { DirectBackendReqType } from "sockapi/direct-backend";
import { useIsCheckPuzzleToggleOn } from "stores/BrowserWidePersistentState";

const NormalQuiz = ({
  puzName,
  staticPuzDir,
}: {
  puzName: string;
  staticPuzDir: string;
}) => {
  const [isStarted, setIsStarted] = useState(false);
  const [answers, setAnswers] = useState<(number | null)[]>(
    questions.map(() => null)
  );
  const [submitted, setSubmitted] = useState(false);
  const sockClient = useSockClient();
  const submit = async () => {
    setSubmitted(true);
    try {
      void sockClient?.sendDirectBackendReqAsync({
        type: DirectBackendReqType.NORMAL_LOG,
        payload: { answers },
      });
    } catch (e) {
      console.error(e);
    }
  };

  return (
    <div>
      <FourthWall>
        For the optimal solving experience, we recommend going through the quiz
        at least once without using external sources.
      </FourthWall>
      <p>
        Congratulations on completing your final exams! As you know, here at the
        university we have a tradition of making sure our graduates are suited
        to join the American workforce, so we have one final test to make sure
        you're prepared to join adult society. Don't worry; it's all material
        you should know from everyday life.
      </p>
      {!isStarted && <button onClick={() => setIsStarted(true)}>Start!</button>}
      {isStarted && (
        <div>
          <ol className="normal-questions">
            {questions.map((q, index) => (
              <Question
                key={q.name}
                question={q}
                answer={answers[index]}
                setAnswer={(answerIndex: number) =>
                  setAnswers((answers) => {
                    const newAnswers = [...answers];
                    newAnswers[index] = answerIndex;
                    return newAnswers;
                  })
                }
                submitted={submitted}
                staticPuzDir={staticPuzDir}
              />
            ))}
          </ol>
          {!submitted && <button onClick={submit}>Submit</button>}
          {submitted && (
            <>
              <h3>Results</h3>
              <hr />
              <Results
                puzName={puzName}
                answers={answers}
                reset={() => {
                  if (confirm("Clear selected answers and reset the quiz?")) {
                    setAnswers(questions.map(() => null));
                    setSubmitted(false);
                  }
                }}
              />
            </>
          )}
        </div>
      )}
    </div>
  );
};

const Results = ({
  puzName,
  answers,
  reset,
}: {
  puzName: string;
  answers: (number | null)[];
  reset: () => void;
}) => {
  const showWrongest = useIsCheckPuzzleToggleOn(puzName);
  const correctAnswers = answers.filter((answer, index) => {
    return questions[index].correct === answer;
  });
  const wrongestAnswers = answers.filter((answer, index) => {
    return questions[index].wrongest === answer;
  });
  if (wrongestAnswers.length === 15) {
    return "Wow, we've never seen someone with so many misconceptions about the real world. You truly are the ultimate puzzler! Submit OBJECTS to complete the puzzle.";
  }
  if (wrongestAnswers.length > 10) {
    return (
      <span>
        Uh, well, you got a lot of answers wrong... in fact,{" "}
        {wrongestAnswers.length} of your answers are as wrong as they can be!{" "}
        <button onClick={reset}>Please try again...</button>
      </span>
    );
  }
  if (correctAnswers.length === 15) {
    return "You passed with flying colors! Although, hm, looking at your records here, it says you were a puzzling major? This can't be right... Maybe try indexing your answer indices into their corresponding answers and see if that gets you anywhere. (For example, if the correct answer was (d), take the fourth letter of that answer.)";
  }
  return (
    <span>
      You got {correctAnswers.length} out of 15 questions correct.{" "}
      {showWrongest && wrongestAnswers.length > 0 && (
        <>
          {wrongestAnswers.length} of your answers are as wrong as they can
          be.{" "}
        </>
      )}
      <button onClick={reset}>Click to try again!</button>
    </span>
  );
};

