import {
  FloatingFocusManager,
  FloatingOverlay,
  FloatingPortal,
  useDismiss,
  useFloating,
  useInteractions,
  useRole,
} from "@floating-ui/react";
import { HTMLProps, PropsWithChildren, ReactNode, RefObject } from "react";
import "./Modal.css";

interface ModalProps {
  isOpen?: boolean;
  title?: string;
  wrapperClassName?: string;
  footerChildren?: ReactNode;
  // TODO: use onClose in more places
  /** Called on Escape or a click outside the modal. */
  onClose?: () => void;
  /** Element to focus on open; defaults to the first tabbable one. */
  initialFocus?: RefObject<HTMLElement | null>;
  returnFocus?: boolean;
}

function Modal(
  props: PropsWithChildren<ModalProps> & HTMLProps<HTMLDivElement>
) {
  const {
    children,
    footerChildren,
    isOpen = true,
    title,
    className,
    wrapperClassName,
    onClose,
    initialFocus,
    returnFocus,
    ...otherProps
  } = props;

  const { refs, context } = useFloating({
    open: isOpen,
    onOpenChange: (open) => {
      if (!open) onClose?.();
    },
  });

  const dismiss = useDismiss(context, { bubbles: true });
  const role = useRole(context);

  const { getFloatingProps } = useInteractions([dismiss, role]);

  if (!isOpen) return null;

  return (
    // eslint-disable-next-line @eslint-react/purity
    <FloatingPortal root={document.getElementById("game-root")}>
      <FloatingOverlay className={`modal-wrapper ${wrapperClassName ?? ""}`}>
        <FloatingFocusManager
          context={context}
          initialFocus={initialFocus}
          returnFocus={returnFocus}
        >
          <div
            className={`modal ${className}`}
            // eslint-disable-next-line react-hooks/refs
            ref={refs.setFloating}
            {...getFloatingProps(otherProps)}
          >
            {title === undefined ? null : (
              <h3 className="modal-header">{title}</h3>
            )}
            <div className="modal-body">{children}</div>
            {footerChildren === undefined ? null : (
              <div className="modal-footer">{footerChildren}</div>
            )}
          </div>
        </FloatingFocusManager>
      </FloatingOverlay>
    </FloatingPortal>
  );
}

export default Modal;
