import { ReactNode } from "react";
import {
  PuzzleGallery,
  GalleryImageSpec,
} from "components/PuzzleContent/puzzle-components";
import "./FruitForestGallery.css";

type Captions = Record<string, ReactNode>;

const attachCaptions = (
  items: GalleryImageSpec[],
  captions: Captions
): GalleryImageSpec[] =>
  items.map((item) => {
    const id = Object.keys(captions).find((id) =>
      item.images?.includes(`fruit-forest-soln-${id}.png`)
    );
    return id ? { caption: captions[id], ...item } : item;
  });

export function FruitForestGallery({
  staticPuzDir,
  items,
  captions,
  solution,
  authorsNotes,
}: {
  staticPuzDir: string;
  items: GalleryImageSpec[];
  captions: Captions;
  solution: ReactNode;
  authorsNotes: ReactNode;
}) {
  return (
    <div className="fruit-forest-gallery">
      {solution}
      <PuzzleGallery
        // animationHandler={"fade"} // this breaks selection on the legend
        staticPuzDir={staticPuzDir}
        imgProps={{ staticPuzDir, fullHeight: true, decoding: "sync" }}
        items={attachCaptions(items, captions)}
        transitionTime={0}
        useKeyboardArrows
        shouldPreloadImages
      />
      {authorsNotes}
    </div>
  );
}
