/** [text, r, c, color?]. Margins are r or c = -1 or N; side labels are vertical, centered on row r. */
type Label = [string, number, number, string?];
/** [r, c, "r" (vs. cell to the right) | "d" (vs. cell below), symbol]. */
type Relation = [number, number, "r" | "d", string];
type Clue = {
  num?: number;
  text: string;
  /** Regions and dust clouds: the cells of this color in the land. */
  color?: string;
  /** [r, c] also in the region despite their color. */
  extraCells?: [number, number][];
  /** Solution only. */
  answer?: string;
  notes?: string;
};
type ClueSection = { title: string; clues: Clue[] };
type Land = {
  name: string;
  /** The land's own color (RGBCMY for most); the grid tints the land with it. */
  color: string;
  sections: ClueSection[];
};
type Dir = "across" | "down";

type GridAdventureProps = {
  /** Rows of cell text; see `Cell`. */
  cells: string[][];
  /** The sheet's colors, as in `PuzzleGrid` without the margin. Only finds regions. */
  fills: string;
  fillColors: string[];
  bars: string;
  /** Same shape as `fills`; each char indexes `lands`, "." is a block. */
  landMap: string;
  lands: Land[];
  labels: Label[];
  relations: Relation[];
};

/** Sends edits; resolves once the server has applied them (or failed). */
type SendEdits = (edits: GridAdventureCellEdit[]) => Promise<unknown>;

type Solution = {
  /** Each cell's solved text, e.g. "WIL", "A/N" (rot13 across/down), "SE🧭S" (COMPASS across/down); "" for INK squares. */
  cells: string[][];
  /** Black Hole rows, one of RGBCMYW per cell ("." outside the hole). */
  holeColors: string;
};
const HOLE_COLORS: Record<string, string> = {
  R: "#FF0000",
  G: "#00FF00",
  B: "#3366FF",
  C: "#00FFFF",
  M: "#FF00FF",
  Y: "#FFFF00",
  W: "#FFFFFF",
};

const RINGS: Record<string, number> = { "□": 1, "⧈": 2, "▣": 3 };
/**
 * Black Hole marks as paths centered on (0, 0), in cells, read left to right.
 * Paths rather than text so they center exactly: glyphs like ≥ sit off their
 * em box's center, which rotating them for vertical edges makes visible.
 */
const RELATION_PATHS: Record<string, string> = {
  "<": "M.1 -.13L-.1 0L.1 .13",
  ">": "M-.1 -.13L.1 0L-.1 .13",
  "=": "M-.1 -.06H.1M-.1 .06H.1",
  "≠": "M-.1 -.06H.1M-.1 .06H.1M.06 -.13L-.06 .13",
  "≤": "M.1 -.13L-.1 -.035L.1 .06M-.1 .13H.1",
  "≥": "M-.1 -.13L.1 -.035L-.1 .06M-.1 .13H.1",
};
const STEP: Record<Dir, [number, number]> = { across: [0, 1], down: [1, 0] };
const SECTION: Record<Dir, string> = { across: "Across", down: "Down" };

/** A clue's region as a picture of its cells. */
function CageShape(props: { cells: Set<number>; n: number }) {
  const { cells, n } = props;
  const rcs = [...cells].map((i) => [Math.floor(i / n), i % n] as const);
  const r0 = Math.min(...rcs.map(([r]) => r));
  const c0 = Math.min(...rcs.map(([, c]) => c));
  const h = Math.max(...rcs.map(([r]) => r)) - r0 + 1;
  const w = Math.max(...rcs.map(([, c]) => c)) - c0 + 1;
  const unit = Math.min(0.6, 3 / Math.max(w, h));
  return (
    <svg
      className="grid-adventure-cage-shape"
      viewBox={`0 0 ${w} ${h}`}
      style={{ width: `${w * unit}em`, height: `${h * unit}em` }}
    >
      {rcs.map(([r, c]) => (
        <rect
          key={r * n + c}
          x={c - c0 + 0.05}
          y={r - r0 + 0.05}
          width={0.9}
          height={0.9}
        />
      ))}
    </svg>
  );
}

/** Mixes a #rrggbb color with white, keeping `amount` of it. */
const tint = (hex: string, amount = 0.55) =>
  "#" +
  [1, 3, 5]
    .map((i) =>
      Math.round(255 - (255 - parseInt(hex.slice(i, i + 2), 16)) * amount)
        .toString(16)
        .padStart(2, "0")
    )
    .join("");

const graphemes = (text: string) =>
  [...new Intl.Segmenter().segment(text)].length;

const withEmoji = (text: string): ReactNode =>
  /\p{Extended_Pictographic}/u.test(text) ? (
    <Twemoji tag="span">{text}</Twemoji>
  ) : (
    text
  );

/**
 * Cell text as in the author's sheet: optional clue number, "*" for a
 * tombstone around it (with "↓" if it's only for the down entry), then any of □ ⧈ ▣ (extra borders) ◆ \ 🌳. "." is a
 * block. Copies as that same text, less any parts toggled off.
 */
/** How many nested borders cell text has. */
const ringsIn = (text: string) =>
  Math.max(0, ...[...text].map((ch) => RINGS[ch] ?? 0));

function Cell(props: { text: string; numbers: boolean; symbols: boolean }) {
  const { text, numbers, symbols } = props;
  const [, num, tomb, rest] = /^(\d*)(\*?↓?)(.*)$/su.exec(text)!;
  const rings = ringsIn(rest);
  // Copies whichever parts are toggled on.
  const copyText = ((numbers ? num : "") + (symbols ? tomb + rest : "")).trim();
  return (
    <>
      {copyText ? <span className="copy-only">{copyText}</span> : null}
      <span className="no-copy">
        {num ? (
          <span
            className={tomb ? "clue-number grid-adventure-tomb" : "clue-number"}
          >
            {num}
            {tomb.includes("↓") ? (
              <span className="grid-adventure-tomb-dir">↓</span>
            ) : null}
          </span>
        ) : null}
        {rest.includes("🌳") ? (
          <Twemoji tag="span" className="grid-adventure-tree">
            🌳
          </Twemoji>
        ) : null}
        <svg className="grid-adventure-marks" viewBox="0 0 1 1">
          {Array.from({ length: rings }, (_, i) => {
            const d = 0.06 * (i + 1);
            return (
              <rect key={i} x={d} y={d} width={1 - 2 * d} height={1 - 2 * d} />
            );
          })}
          {rest.includes("\\") ? <line x1={0} y1={0} x2={1} y2={1} /> : null}
          {rest.includes("◆") ? (
            <path className="filled" d="M.5 .755L.59 .8525L.5 .95L.41 .8525Z" />
          ) : null}
        </svg>
      </span>
    </>
  );
}

export function GridAdventure(props: GridAdventureProps) {
  const { teamId, send } = usePuzzleTeam();
  if (teamId === null)
    return (
      <GridAdventureBoard
        {...props}
        serverCells={null}
        send={null}
        solution={null}
      />
    );
  return <SyncedGridAdventure {...props} teamId={teamId} canSend={send} />;
}

/** Read-only solved grid; the sidebar and clue list show each clue's answer and notes. */
export function GridAdventureSolution(
  props: GridAdventureProps & {
    solution: string[][];
    holeColors: string;
  }
) {
  const { solution, holeColors, ...rest } = props;
  return (
    <GridAdventureBoard
      {...rest}
      serverCells={null}
      send={null}
      solution={{ cells: solution, holeColors }}
    />
  );
}

/** A blank cell with `cell`'s symbols (as in `cells`), for the solution's prose. */
export function GridAdventureSymbol(props: { cell: string }) {
  return (
    <span className="grid-adventure grid-adventure-symbol">
      <span className="puzzle-grid">
        <Cell text={props.cell} numbers symbols />
      </span>
    </span>
  );
}

/**
 * Black Hole marks on cell (r, c)'s right or bottom edge, from `renderCell`.
 * They live in the cell rather than the overlay, since bars widen their
 * columns and the overlay assumes even ones.
 */
export function GridAdventureRelations(props: {
  relations: Relation[];
  r: number;
  c: number;
}) {
  const { relations, r, c } = props;
  return relations
    .filter(([rr, rc]) => rr === r && rc === c)
    .map(([, , relDir, sym]) => (
      <svg
        key={relDir}
        className={`grid-adventure-relation grid-adventure-relation-${relDir} no-copy`}
        viewBox="-0.5 -0.5 1 1"
      >
        <g transform={relDir === "d" ? "rotate(90)" : undefined}>
          <path className="outline" d={RELATION_PATHS[sym]} />
          <path d={RELATION_PATHS[sym]} />
        </g>
      </svg>
    ));
}

/** A clue's answer and notes, if it has them. */
function ClueAnswer(props: { clue: Clue }) {
  const { answer, notes } = props.clue;
  if (answer === undefined) return null;
  return (
    <div className="grid-adventure-answer">
      <b>{withEmoji(answer)}</b>
      {notes ? <>: {withEmoji(notes)}</> : null}
    </div>
  );
}

function SyncedGridAdventure(
  props: GridAdventureProps & { teamId: string; canSend: boolean }
) {
  const { teamId, canSend } = props;
  const sockClient = useSockClient();
  const identifier = useMemo(() => ({ teamId }), [teamId]);
  const state = useScopeStateResolvable(
    ScopeType.TEAM_GRID_ADVENTURE,
    identifier
  );
  const send = useCallback<SendEdits>(
    (set) =>
      sockClient.sendScopeStepAndWaitAsync(
        { type: ScopeType.TEAM_GRID_ADVENTURE, teamId },
        { set }
      ),
    [sockClient, teamId]
  );
  return (
    <GridAdventureBoard
      {...props}
      serverCells={state?.cells ?? null}
      send={canSend ? send : null}
      solution={null}
    />
  );
}

function GridAdventureBoard(
  props: GridAdventureProps & {
    /** Null when not synced; the grid is then local only. */
    serverCells: string[] | null;
    send: SendEdits | null;
    /** Shows this read-only instead of the team's entries. */
    solution: Solution | null;
  }
) {
  const {
    cells,
    fillColors,
    lands,
    labels,
    relations,
    serverCells,
    send,
    solution,
  } = props;
  const n = cells.length;
  const landRows = props.landMap.split("|");
  const landAt = (r: number, c: number): number | null => {
    const ch = landRows[r]?.[c];
    return ch === undefined || ch === "." ? null : parseInt(ch, 36);
  };
  const isOpen = (r: number, c: number) => landAt(r, c) !== null;
  const barAt = barGrid(props.bars);
  const fillRows = props.fills.split("|");
  const colorAt = (r: number, c: number) =>
    fillColors[parseInt(fillRows[r][c], 36)];
  const numberAt = (r: number, c: number) =>
    parseInt(/^\d+/.exec(cells[r][c])?.[0] ?? "") || null;

  const isHole = (land: number | null) =>
    land !== null && lands[land].color === "#000000";
  /**
   * Whether (r, c) continues into the next cell in `dir` (or the previous, if
   * `back`). Words cross land borders, except into or out of the Black Hole.
   */
  const joined = (r: number, c: number, dir: Dir, back = false) => {
    const [dr, dc] = STEP[dir];
    const [r2, c2] = back ? [r - dr, c - dc] : [r + dr, c + dc];
    const side = { across: back ? LEFT : RIGHT, down: back ? TOP : BOTTOM }[
      dir
    ];
    const [a, b] = [landAt(r, c), landAt(r2, c2)];
    return (
      b !== null &&
      (a === b || !(isHole(a) || isHole(b))) &&
      !(barAt(r, c) & side)
    );
  };
  /** The word through (r, c), walking to blocks, bars, and the Black Hole. */
  const wordAt = (r: number, c: number, dir: Dir): [number, number][] => {
    const [dr, dc] = STEP[dir];
    while (joined(r, c, dir, true)) [r, c] = [r - dr, c - dc];
    const word: [number, number][] = [[r, c]];
    while (joined(r, c, dir)) {
      [r, c] = [r + dr, c + dc];
      word.push([r, c]);
    }
    return word;
  };
  const clueFor = (land: number, num: number | null, dir: Dir) =>
    num === null
      ? undefined
      : lands[land].sections
          .find((s) => s.title === SECTION[dir])
          ?.clues.find((clue) => clue.num === num);

  // Cell values: pending local edits over the server's.
  const [pending, setPending] = useState<Map<number, string>>(() => new Map());
  const valueAt = (r: number, c: number) =>
    solution
      ? solution.cells[r][c]
      : (pending.get(r * n + c) ?? serverCells?.[r * n + c] ?? "");
  const holeColorAt = (r: number, c: number) => {
    const ch = solution?.holeColors.split("|")[r]?.[c];
    return ch === undefined || ch === "." ? undefined : ch;
  };
  const edit = (edits: GridAdventureCellEdit[]) => {
    setPending((prev) => new Map([...prev, ...edits]));
    // local-only grids keep their edits in `pending` forever.
    void send?.(edits).then(() =>
      setPending((prev) => {
        const next = new Map(prev);
        for (const [i, value] of edits)
          if (next.get(i) === value) next.delete(i);
        return next;
      })
    );
  };

  const [cursor, setCursor] = useState<[number, number] | null>(null);
  const [dir, setDir] = useState<Dir>("across");
  const [region, setRegion] = useState<Clue | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [showNames, setShowNames] = useState(true);
  const [showNumbers, setShowNumbers] = useState(true);
  const [showSymbols, setShowSymbols] = useState(true);
  const [showRegions, setShowRegions] = useState(true);
  const [showColors, setShowColors] = useState(true);
  const [helpOpen, setHelpOpen] = useState(false);
  /** The cell a rebus is being typed into, while Shift is held. */
  const rebusRef = useRef<number | null>(null);
  /** The cell last typed into, for characters that continue its last one. */
  const lastTypedRef = useRef<number | null>(null);
  // Close the sidebar on solving, to make way for the solve dialogue.
  const isSolved = useIsPuzzleSolved(GRID_ADVENTURE_CONFIG.puzName);
  const wasSolvedRef = useRef(isSolved);
  useEffect(() => {
    if (isSolved && wasSolvedRef.current === false) setSidebarOpen(false);
    wasSolvedRef.current = isSolved;
  }, [isSolved]);
  const boardRef = useRef<HTMLDivElement>(null);

  const cursorLand = cursor ? landAt(...cursor) : null;
  const words = cursor
    ? { across: wordAt(...cursor, "across"), down: wordAt(...cursor, "down") }
    : null;
  /** A word's clue and land, which is its first cell's. */
  const wordClue = (d: Dir) => {
    if (!words) return {};
    const land = landAt(...words[d][0])!;
    return { land, clue: clueFor(land, numberAt(...words[d][0]), d) };
  };
  const { land: activeLand, clue: activeClue } = wordClue(dir);
  const otherDir: Dir = dir === "across" ? "down" : "across";
  const { clue: crossClue } = wordClue(otherDir);
  const inWord = new Set(words?.[dir].map(([r, c]) => r * n + c));
  // Each region and dust cloud clue's cells: those of its color in its land.
  const cages = new Map<Clue, Set<number>>();
  lands.forEach((land, li) => {
    for (const section of land.sections)
      for (const clue of section.clues) {
        if (clue.color === undefined) continue;
        const cage = new Set<number>();
        for (let r = 0; r < n; r++)
          for (let c = 0; c < n; c++)
            if (landAt(r, c) === li && colorAt(r, c) === clue.color)
              cage.add(r * n + c);
        for (const [r, c] of clue.extraCells ?? []) cage.add(r * n + c);
        cages.set(clue, cage);
      }
  });
  const inCage = (cage: Set<number>, r: number, c: number) =>
    r >= 0 && r < n && c >= 0 && c < n && cage.has(r * n + c);
  const cageShape = (clue: Clue) => (
    <CageShape cells={cages.get(clue)!} n={n} />
  );
  // Region and dust cloud clues whose region the cursor is in.
  const cursorRegions = new Set<Clue>();
  // Other clues for the cursor's cell, with their section titles: those
  // regions, and skyscrapers (numbered clues outside Across and Down) with the
  // cell's number.
  const cursorRelated = new Map<Clue, string>();
  if (cursor && cursorLand !== null)
    for (const section of lands[cursorLand].sections)
      for (const clue of section.clues) {
        if (cages.get(clue)?.has(cursor[0] * n + cursor[1])) {
          cursorRegions.add(clue);
          cursorRelated.set(clue, section.title);
        }
        if (
          clue.num !== undefined &&
          clue.num === numberAt(...cursor) &&
          section.title !== SECTION.across &&
          section.title !== SECTION.down
        )
          cursorRelated.set(clue, section.title);
      }
  // The clicked region, or else the cursor's regions.
  const activeRegions = region ? new Set([region]) : cursorRegions;

  const moveTo = (r: number, c: number) => {
    setCursor([r, c]);
    setRegion(null);
  };
  /** Next open cell from (r, c) in direction (dr, dc), skipping blocks. */
  const nextOpen = (r: number, c: number, dr: number, dc: number) => {
    for (let [r2, c2] = [r + dr, c + dc]; ; [r2, c2] = [r2 + dr, c2 + dc]) {
      if (r2 < 0 || r2 >= n || c2 < 0 || c2 >= n) return null;
      if (isOpen(r2, c2)) return [r2, c2] as const;
    }
  };

  const onKeyDown = (e: KeyboardEvent) => {
    if (!cursor || e.ctrlKey || e.metaKey || e.altKey) return;
    const [r, c] = cursor;
    const [dr, dc] = STEP[dir];
    const arrows: Record<string, [Dir, number]> = {
      ArrowLeft: ["across", -1],
      ArrowRight: ["across", 1],
      ArrowUp: ["down", -1],
      ArrowDown: ["down", 1],
    };
    if (solution && !(e.key in arrows)) return;
    if (e.key in arrows) {
      const [arrowDir, sign] = arrows[e.key];
      if (arrowDir !== dir) setDir(arrowDir);
      else {
        const [adr, adc] = STEP[arrowDir];
        const next = nextOpen(r, c, adr * sign, adc * sign);
        if (next) moveTo(...next);
      }
    } else if (e.key === "Backspace") {
      if (valueAt(r, c) !== "") edit([[r * n + c, ""]]);
      else if (isOpen(r - dr, c - dc)) {
        edit([[(r - dr) * n + c - dc, ""]]);
        moveTo(r - dr, c - dc);
      }
    } else if (e.key === "Delete") {
      edit([[r * n + c, ""]]);
    } else if (e.key === " ") {
      edit([[r * n + c, ""]]);
      if (isOpen(r + dr, c + dc)) moveTo(r + dr, c + dc);
    } else if ([...e.key].length === 1) {
      const key = e.key.toUpperCase();
      // Some emoji input (e.g. on Linux) types one code point at a time. One
      // that joins the last cell's last character, like a ZWJ, a skin tone,
      // or what follows a ZWJ, goes there.
      const last = lastTypedRef.current;
      if (last !== null) {
        const prev = valueAt(Math.floor(last / n), last % n);
        const joined = prev + key;
        if (
          prev &&
          graphemes(joined) === graphemes(prev) &&
          isValidGridAdventureCell(joined)
        ) {
          edit([[last, joined]]);
          e.preventDefault();
          return;
        }
      }
      const i = r * n + c;
      lastTypedRef.current = i;
      // Holding Shift types a rebus; releasing it moves on.
      const value =
        e.shiftKey && rebusRef.current === i ? valueAt(r, c) + key : key;
      if (isValidGridAdventureCell(value)) edit([[i, value]]);
      if (e.shiftKey) rebusRef.current = i;
      else if (isOpen(r + dr, c + dc)) moveTo(r + dr, c + dc);
    } else return;
    if ([...e.key].length !== 1) lastTypedRef.current = null;
    e.preventDefault();
  };

  // Pasting fills the cell, for anything hard to type, like emoji.
  const onPaste = (e: ClipboardEvent) => {
    if (!cursor || solution) return;
    e.preventDefault();
    const value = e.clipboardData.getData("text").trim().toUpperCase();
    if (value && isValidGridAdventureCell(value))
      edit([[cursor[0] * n + cursor[1], value]]);
  };

  const onKeyUp = (e: KeyboardEvent) => {
    const i = rebusRef.current;
    if (e.key !== "Shift" || i === null) return;
    rebusRef.current = null;
    const [r, c] = [Math.floor(i / n), i % n];
    const [dr, dc] = STEP[dir];
    if (cursor?.[0] === r && cursor[1] === c && isOpen(r + dr, c + dc))
      moveTo(r + dr, c + dc);
  };

  const onClick = (e: MouseEvent) => {
    const td = (e.target as Element).closest("td");
    const tr = td?.parentElement;
    if (!td || !tr?.parentElement) return;
    // Skip rows copyjack adds, less the label margin.
    const rows = [...tr.parentElement.children].filter(
      (row) => !row.classList.contains("copy-only")
    );
    const [r, c] = [rows.indexOf(tr) - 1, td.cellIndex - 1];
    if (!isOpen(r, c)) return;
    if (cursor?.[0] === r && cursor[1] === c)
      setDir(dir === "across" ? "down" : "across");
    else moveTo(r, c);
  };

  const onClueClick = (land: number, section: string, clue: Clue) => {
    if (clue.color !== undefined) {
      // Keep the cursor in this land so the region stays highlighted.
      if (cursorLand !== land) {
        const first = landRows.join("|").indexOf(land.toString(36));
        setCursor([Math.floor(first / (n + 1)), first % (n + 1)]);
      }
      setRegion(clue);
      return;
    }
    for (let r = 0; r < n; r++)
      for (let c = 0; c < n; c++)
        if (landAt(r, c) === land && numberAt(r, c) === clue.num) {
          moveTo(r, c);
          if (section === "Across") setDir("across");
          if (section === "Down") setDir("down");
          boardRef.current?.focus({ preventScroll: true });
          return;
        }
  };

  // Keep the active clue in view in the sidebar.
  const panelRef = useRef<HTMLElement>(null);
  useEffect(() => {
    panelRef.current
      ?.querySelector(".grid-adventure-clue-active")
      ?.scrollIntoView({ block: "nearest" });
  }, [activeClue, region, sidebarOpen]);

  // Fills are the lands' colors (or white, with Colors off), which also copy.
  // Black (blocks and the Black Hole) is index 0.
  const landFills = [
    "#000000",
    ...lands.map((land) => (showColors ? tint(land.color) : "white")),
    // The Black Hole's colors, tinted like the lands they come from. They're
    // the solution, so they stay even with Colors off.
    ...Object.values(HOLE_COLORS).map((hex) => tint(hex)),
    "transparent",
  ];
  const fillAt = (r: number, c: number) => {
    const land = landAt(r, c);
    const hole = holeColorAt(r, c);
    if (hole !== undefined)
      return 1 + lands.length + Object.keys(HOLE_COLORS).indexOf(hole);
    return land === null || lands[land].color === "#000000" ? 0 : land + 1;
  };
  // One-cell margin on every side for outer labels.
  const hidden = (landFills.length - 1).toString(36);
  const pad = (rows: string[], ch: string) => [
    ch.repeat(n + 2),
    ...rows.map((row) => ch + row + ch),
    ch.repeat(n + 2),
  ];
  const text = pad(
    cells.map((row) => row.map((t) => (t === "." ? "@" : ".")).join("")),
    "."
  );
  const isSide = (c: number) => c === -1 || c === n;
  // The solution bars off the Black Hole.
  const inHole = (r: number, c: number) => isHole(landAt(r, c));
  const barRows = props.bars.split("|").map((row, r) =>
    solution
      ? [...row]
          .map((ch, c) => {
            let bar = parseInt(ch, 16) || 0;
            if (inHole(r, c))
              for (const [side, dr, dc] of [
                [TOP, -1, 0],
                [RIGHT, 0, 1],
                [BOTTOM, 1, 0],
                [LEFT, 0, -1],
              ])
                if (!inHole(r + dr, c + dc)) bar |= side;
            return bar ? bar.toString(16) : ".";
          })
          .join("")
      : row
  );
  // In the solution, labels inside the grid would cover its letters.
  const shownLabels = solution
    ? labels.filter(([, r, c]) => r < 0 || r >= n || c < 0 || c >= n)
    : labels;

  const grid = (
    <div
      className="grid-adventure"
      ref={boardRef}
      tabIndex={0}
      onKeyDown={onKeyDown}
      onKeyUp={onKeyUp}
      onPaste={onPaste}
      data-hide-labels={showNames ? undefined : ""}
      data-hide-numbers={showNumbers ? undefined : ""}
      data-hide-symbols={showSymbols ? undefined : ""}
      onClick={(e) => {
        onClick(e);
        setSidebarOpen(true);
        boardRef.current?.focus({ preventScroll: true });
      }}
    >
      <PuzzleGrid
        text={text.join("|")}
        fills={pad(
          cells.map((row, r) =>
            row.map((_, c) => fillAt(r, c).toString(36)).join("")
          ),
          hidden
        ).join("|")}
        fillColors={landFills}
        textColors={["white"]}
        bars={pad(barRows, ".").join("|")}
        renderCell={(pr, pc) => {
          const [r, c] = [pr - 1, pc - 1];
          const label = shownLabels.find(
            ([, lr, lc]) => Math.floor(lr) === r && lc === c
          );
          const t = cells[r]?.[c];
          const i = r * n + c;
          const highlight = !isOpen(r, c)
            ? null
            : cursor?.[0] === r && cursor[1] === c
              ? "grid-adventure-cursor"
              : inWord.has(i)
                ? "grid-adventure-word"
                : null;
          const land = isOpen(r, c) ? lands[landAt(r, c)!] : undefined;
          const value = t !== undefined && isOpen(r, c) ? valueAt(r, c) : "";
          return (
            <>
              {/*
               * Killer sudoku style cages: dashed, inset where they end.
               * Highlighted regions' are solid, even with Regions off.
               */}
              {land
                ? [...cages]
                    .filter(
                      ([clue, cage]) =>
                        cage.has(i) && (showRegions || activeRegions.has(clue))
                    )
                    .map(([clue, cage], k) => {
                      const active = activeRegions.has(clue);
                      return (
                        <CageCell
                          key={k}
                          r={r}
                          c={c}
                          inCage={(r2, c2) => inCage(cage, r2, c2)}
                          className={
                            active ? "grid-adventure-cage-active" : undefined
                          }
                          solid={active}
                        />
                      );
                    })
                : null}
              {highlight ? (
                <span
                  className={`grid-adventure-highlight ${highlight}`}
                  data-dark={
                    land?.color === "#000000" && !holeColorAt(r, c)
                      ? ""
                      : undefined
                  }
                />
              ) : null}
              {solution && isOpen(r, c) && value === "" ? (
                <span className="grid-adventure-ink" />
              ) : null}
              {t && t !== "." ? (
                <Cell text={t} numbers={showNumbers} symbols={showSymbols} />
              ) : null}
              {solution && value.includes("🧭") ? (
                <span className="grid-adventure-compass no-copy">
                  {withEmoji("🧭")}
                </span>
              ) : null}
              {solution && /\/|🧭/.test(value) ? (
                // Across in the southwest, down in the northeast, either side
                // of a rot13 square's diagonal; COMPASS squares match.
                value.split(/\/|🧭/).map((part, k) => (
                  <span
                    key={k}
                    className="grid-adventure-value-split no-copy"
                    style={{
                      fontSize: `${0.55 * Math.min(1, 2.4 / graphemes(part))}em`,
                      // Inside any nested borders.
                      [k ? "right" : "left"]: `${6 + 4 * ringsIn(t ?? "")}%`,
                      [k ? "top" : "bottom"]: `${6 + 4 * ringsIn(t ?? "")}%`,
                    }}
                  >
                    {part}
                  </span>
                ))
              ) : value ? (
                <span
                  className="grid-adventure-value no-copy"
                  // Shrink rebuses to fit.
                  style={{
                    fontSize: `${0.9 * Math.min(1, 1.8 / graphemes(value))}em`,
                  }}
                >
                  {withEmoji(value)}
                </span>
              ) : null}
              <GridAdventureRelations relations={relations} r={r} c={c} />
              {label && showNames ? (
                <span className="copy-only">{label[0]}</span>
              ) : null}
            </>
          );
        }}
        overlay={
          <g className="grid-adventure-overlay">
            {shownLabels.map(([label, r, c, color]) =>
              isSide(c) ? (
                <text
                  key={label}
                  className="grid-adventure-label"
                  transform={`translate(${c + 1.5} ${r + 1.5}) rotate(-90)`}
                  textAnchor="middle"
                >
                  {label}
                </text>
              ) : (
                <text
                  key={label}
                  className="grid-adventure-label"
                  x={c + 1.1}
                  y={r + 1.5}
                  fill={color}
                >
                  {label}
                </text>
              )
            )}
          </g>
        }
      />
    </div>
  );

  // The active clue's land, so the sidebar stays put while typing across a border.
  const panelLand = (activeClue && activeLand) ?? cursorLand ?? 0;
  const currentClue = (
    <div className="grid-adventure-clue-bar">
      {activeClue ? (
        <div>
          <b>
            {activeClue.num} {SECTION[dir]}
          </b>{" "}
          {withEmoji(activeClue.text)}
          <ClueAnswer clue={activeClue} />
        </div>
      ) : cursorRelated.size === 0 ? (
        (lands[panelLand]?.name ?? "")
      ) : null}
      {[...cursorRelated].map(([clue, section], i) => (
        <div key={i}>
          {clue.color !== undefined ? (
            cageShape(clue)
          ) : (
            <b>
              {clue.num} {section}
            </b>
          )}{" "}
          {withEmoji(clue.text)}
          <ClueAnswer clue={clue} />
        </div>
      ))}
    </div>
  );
  // Wide screens: a sidebar at the right edge of the screen, portaled out of
  // the page since its ancestors animate.
  const sidebar = createPortal(
    <aside
      className={`grid-adventure-sidebar no-copy ${solution ? "in-solution" : ""}`}
      ref={panelRef}
      data-open={sidebarOpen ? "" : undefined}
      inert={!sidebarOpen}
    >
      <div className="grid-adventure-sidebar-top">
        <div className="grid-adventure-sidebar-head">
          <h3>{lands[panelLand]?.name}</h3>
          <button
            className="grid-adventure-sidebar-close"
            aria-label="Close clues"
            onClick={() => setSidebarOpen(false)}
          >
            ×
          </button>
        </div>
        {currentClue}
      </div>
      {lands[panelLand]?.sections.map((section) => (
        <Fragment key={section.title}>
          <h4>{section.title}</h4>
          <ul>
            {section.clues.map((clue, i) => (
              <li
                key={i}
                className={
                  clue === activeClue || clue === region
                    ? "grid-adventure-clue-active"
                    : clue === crossClue || cursorRelated.has(clue)
                      ? "grid-adventure-clue-cross"
                      : undefined
                }
                onClick={() => onClueClick(panelLand, section.title, clue)}
              >
                {clue.color !== undefined ? cageShape(clue) : <b>{clue.num}</b>}{" "}
                {withEmoji(clue.text)}
                <ClueAnswer clue={clue} />
              </li>
            ))}
          </ul>
        </Fragment>
      ))}
    </aside>,
    document.body
  );

  return (
    <>
      <div
        className="grid-adventure-layout"
        data-sidebar-open={sidebarOpen ? "" : undefined}
      >
        <div className="grid-adventure-toggles no-copy">
          {solution ? null : (
            <button onClick={() => setHelpOpen(true)}>Help</button>
          )}
          Show:
          {(
            [
              ["Names", showNames, setShowNames],
              ["Numbers", showNumbers, setShowNumbers],
              ["Symbols", showSymbols, setShowSymbols],
              ["Regions", showRegions, setShowRegions],
              ["Colors", showColors, setShowColors],
            ] as const
          ).map(([name, checked, setChecked]) => (
            <label key={name}>
              <input
                type="checkbox"
                checked={checked}
                onChange={(e) => setChecked(e.target.checked)}
              />{" "}
              {name}
            </label>
          ))}
        </div>
        <div className="grid-adventure-sticky-clue no-copy">{currentClue}</div>
        {grid}
      </div>
      {sidebar}
      <Modal
        isOpen={helpOpen}
        title="Help"
        footerChildren={
          <button onClick={() => setHelpOpen(false)}>Close</button>
        }
      >
        <p>
          Click a cell and type to fill it. Click it again, or use the arrow
          keys, to switch between across and down. Progress is synced across the
          team.
        </p>
        <p>
          Hold Shift while typing to enter several letters in one cell. You can
          also paste into a cell.
        </p>
        <p>
          The Show switches only affect your view. They also change what gets
          copied to the clipboard.
        </p>
      </Modal>
      {showSymbols ? (
        <p className="copy-only">
          In the grid above, □, ⧈, and ▣ are drawn as two, three, and four
          nested borders; * as a tombstone around the clue number; ◆ as a small
          diamond; and \ as a diagonal line. See original puzzle for details,
          for the symbols in the Black Hole, and for the region shapes.
        </p>
      ) : (
        <p className="copy-only">
          See original puzzle for the symbols in the grid and the region shapes.
        </p>
      )}
      {"\n"}
      <AllClues lands={lands} cageShape={cageShape} />
    </>
  );
}

/**
 * Every land's clues, for reading and copying. The "\n"s are for copyjack's
 * plain text, which only sees literal newlines.
 */
function AllClues(props: {
  lands: Land[];
  cageShape: (clue: Clue) => ReactNode;
}) {
  const { lands, cageShape } = props;
  return lands.map((land) =>
    land.sections.length === 0 ? null : (
      <Fragment key={land.name}>
        <h3>{land.name}</h3>
        {"\n"}
        {land.sections.map((section) => (
          <Fragment key={section.title}>
            <p>
              <b>{section.title}</b>
            </p>
            {"\n"}
            {section.clues.some((clue) => clue.answer !== undefined) ? (
              <table className="grid-adventure-answers">
                <colgroup>
                  <col
                    className={
                      section.clues.some((clue) => clue.color)
                        ? "grid-adventure-answers-region"
                        : "grid-adventure-answers-num"
                    }
                  />
                  <col />
                  <col className="grid-adventure-answers-answer" />
                </colgroup>
                {section.clues.map((clue, i) => (
                  // One tbody per clue, so its notes row stays grouped with it.
                  <tbody key={i}>
                    <tr>
                      <td>
                        {clue.color !== undefined ? (
                          cageShape(clue)
                        ) : (
                          <b>{clue.num}</b>
                        )}
                      </td>
                      <td>{withEmoji(clue.text)}</td>
                      <td className="grid-adventure-answers-answer">
                        {withEmoji(clue.answer ?? "")}
                      </td>
                    </tr>
                    {clue.notes ? (
                      <tr className="grid-adventure-answers-notes">
                        <td />
                        <td colSpan={2}>{withEmoji(clue.notes)}</td>
                      </tr>
                    ) : null}
                  </tbody>
                ))}
              </table>
            ) : section.clues.some((clue) => clue.color !== undefined) ? (
              <table className="grid-adventure-swatches">
                <colgroup>
                  <col className="grid-adventure-answers-region" />
                  <col />
                </colgroup>
                <tbody>
                  {section.clues.map((clue, i) => (
                    <tr key={i}>
                      <td>{cageShape(clue)}</td>
                      <td>{withEmoji(clue.text)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : (
              <p>
                {section.clues.map((clue, i) => (
                  <Fragment key={i}>
                    {i > 0 ? <br /> : null}
                    <b>{clue.num}</b> {withEmoji(clue.text)}
                    {"\n"}
                  </Fragment>
                ))}
              </p>
            )}
            {"\n"}
          </Fragment>
        ))}
      </Fragment>
    )
  );
}
