import { useState } from "react";
import Twemoji from "react-twemoji";
import { ScopeType } from "sockapi/scope-types";
import { SockAPIScopeState } from "sockapi/scope-state";
import { DirectBackendReqType } from "sockapi/direct-backend";

import settings from "settings";
import { useErrataContentForPuzzle } from "stores/ScopeStateStore";
import {
  useSockClient,
  useShouldDisplayAdmin,
} from "stores/ServerInteractionStore";
import { PuzzleLink, Link } from "components/Link";
import { Spinner } from "components/Loading";
import { CafePage } from "pages/WorldBase";
import { LongDate } from "components/dates";
import Tooltip from "components/Tooltip";
import { useUILock } from "client-util/useUILock";
import { toastr } from "Globals";

function ErratumDisplay(props: {
  content: SockAPIScopeState<ScopeType.ERRATUM_CONTENT>;
  page: "updates" | "puzzle";
}) {
  const {
    content: { puzName, updatesText, puzzleText, timestamp },
    page,
  } = props;
  const shouldDisplayAdmin = useShouldDisplayAdmin();
  const [emails, setEmails] = useState<string[] | null>(null);
  const getEmailsLock = useUILock();
  const sockClient = useSockClient();
  const text: string = (() => {
    switch (page) {
      case "updates":
        return updatesText;
      case "puzzle":
        return puzzleText;
    }
  })();
  if (!text) return null;
  return (
    <div className="note-box">
      <div>
        On <LongDate timestamp={timestamp} />,{" "}
        {text.split(/(\$PUZZLE)/g).map((segment, i) =>
          segment === "$PUZZLE" && puzName !== null ? (
            <PuzzleLink key={i} puzName={puzName} />
          ) : (
            // eslint-disable-next-line @eslint-react/dom-no-dangerously-set-innerhtml
            <span key={i} dangerouslySetInnerHTML={{ __html: segment }} />
          )
        )}
      </div>
      {shouldDisplayAdmin && puzName !== null ? (
        <div>
          <button
            onClick={() => {
              getEmailsLock.acquireAndRun(async (getIsCanceled) => {
                try {
                  const emails = (
                    await sockClient.sendDirectBackendReqAsync({
                      type: DirectBackendReqType.GET_ERRATUM_EMAILS,
                      payload: { puzName },
                    })
                  ).payload;
                  if (getIsCanceled()) return;
                  setEmails(emails);
                } catch (err) {
                  console.error(err);
                  toastr.error("Failed to get emails.");
                }
              });
            }}
            disabled={getEmailsLock.isHeld}
          >
            Get emails
          </button>
        </div>
      ) : null}
      {emails !== null ? (
        emails.length === 0 ? (
          <div>None found.</div>
        ) : (
          <textarea>{emails.join(", ")}</textarea>
        )
      ) : null}
    </div>
  );
}

export function ErrataDisplay(props: {
  contents: {
    erratumId: string;
    content: SockAPIScopeState<ScopeType.ERRATUM_CONTENT>;
  }[];
}) {
  const { contents } = props;
  return contents.map(({ erratumId, content }) => (
    <ErratumDisplay key={erratumId} content={content} page="puzzle" />
  ));
}

function ErrataPage() {
  const shouldDisplayAdmin = useShouldDisplayAdmin();
  const contents = useErrataContentForPuzzle(null, true);
  return (
    <CafePage
      heading="Errata & Updates"
      toolbar={
        !settings.isPosthunt && shouldDisplayAdmin ? (
          <div className="button-squish-zone team-name-collectibles">
            <Tooltip text="Add new erratum">
              <Link
                route="admin_subpage"
                params={{ "*": "puzzles/erratum/add" }}
                button
              >
                <Twemoji>➕</Twemoji>
              </Link>
            </Tooltip>
            <Tooltip text="Edit errata">
              <Link
                route="admin_subpage"
                params={{ "*": "puzzles/erratum" }}
                button
              >
                <Twemoji>📜</Twemoji>
              </Link>
            </Tooltip>
          </div>
        ) : null
      }
    >
      {contents === null ? (
        <Spinner inline />
      ) : (
        contents.map(({ erratumId, content }) => (
          <ErratumDisplay key={erratumId} content={content} page="updates" />
        ))
      )}
    </CafePage>
  );
}

export default ErrataPage;
