export function useTimeToNext(now: number | null, counts: number[]) {
  const teamScopeState = useTeamScopeState();
  if (now === null || teamScopeState === null) return null;
  const next = counts
    .flatMap((count, index) =>
      count === 0
        ? []
        : [
            (index + 1) * HINT_CONFIG.timedHintInterval +
              teamScopeState.huntStartTime,
          ]
    )
    .find((time) => time > now);
  if (next === undefined) return null;
  return <LongDate timestamp={next} />;
}

export enum CannedHintDisplayType {
  OPENED = "opened",
  NEXT_TO_OPEN = "next_to_open",
  UNOPENED = "unopened",
  ADMIN_UNOPENED = "admin_unopened",
  ADMIN_LOCKED = "admin_locked",
}

export function CannedHintDisplay(props: {
  puzName: string;
  index: number;
  teamId: string;
  displayType: CannedHintDisplayType;
  spoiler: boolean;
}) {
  const { puzName, index, teamId, displayType, spoiler } = props;
  const isContentAvailable = [
    CannedHintDisplayType.OPENED,
    CannedHintDisplayType.ADMIN_UNOPENED,
    CannedHintDisplayType.ADMIN_LOCKED,
  ].includes(displayType);
  const cannedHintScopeState = useScopeStateResolvable(
    ScopeType.CANNED_HINT,
    isContentAvailable
      ? {
          puzName,
          index,
        }
      : null
  );
  const openCannedHintLock = useUILock();
  const sockClient = useSockClient();

  if (isContentAvailable && cannedHintScopeState === null)
    return <Spinner inline />;

  const icon = ((): ReactNode => {
    switch (displayType) {
      case CannedHintDisplayType.OPENED:
        return <Icon icon={IconType.OPEN_CANNED_HINT} />;
      case CannedHintDisplayType.NEXT_TO_OPEN:
        return <Icon icon={IconType.CANNED_HINT} />;
      case CannedHintDisplayType.UNOPENED:
        return (
          <Icon icon={IconType.CANNED_HINT} className="hints-icon-disabled" />
        );
      case CannedHintDisplayType.ADMIN_UNOPENED:
        return (
          <Tooltip text="Unopened by team">
            <Icon icon={IconType.CANNED_HINT} className="hints-icon-disabled" />
          </Tooltip>
        );
      case CannedHintDisplayType.ADMIN_LOCKED:
        return (
          <Tooltip text="Not yet found by team">
            <Twemoji tag="span">🔒</Twemoji>
          </Tooltip>
        );
    }
  })();
  const isSeenByTeam = [CannedHintDisplayType.OPENED].includes(displayType);

  return (
    <div className="canned-hint">
      <div className="canned-hint-icon">{icon}</div>
      {cannedHintScopeState !== null ? (
        <div
          className={`canned-hint-content ${
            !isSeenByTeam ? "canned-hint-content-unopened" : ""
          }`}
        >
          {spoiler ? (
            <SpoilerText>{cannedHintScopeState.content}</SpoilerText>
          ) : (
            <>{cannedHintScopeState.content}</>
          )}
        </div>
      ) : displayType === CannedHintDisplayType.NEXT_TO_OPEN ? (
        <button
          disabled={openCannedHintLock.isHeld}
          onClick={() => {
            openCannedHintLock.acquireAndRun(async (getIsCanceled) => {
              await sockClient.sendScopeStepAndWaitAsync(
                {
                  type: ScopeType.TEAM_CANNED_HINTS,
                  teamId,
                },
                {
                  openCannedHint: {
                    puzName,
                    index,
                  },
                }
              );
            });
          }}
        >
          Open
        </button>
      ) : null}
    </div>
  );
}

function MarkdownText(props: { text: string }) {
  const { text } = props;
  const [elem, setElem] = useState<MDXContent | null>(null);

  useEffect(() => {
    let isCanceled = false;
    // see usePuzzleContent
    evaluate(text, { ...(runtime as EvaluateOptions), format: "md" })
      .then((module) => {
        if (!isCanceled) setElem(() => module.default);
      })
      .catch((err) => console.error(err));
    return () => {
      isCanceled = true;
    };
  }, [text]);

  if (elem === null) return <Spinner inline />;
  return createElement(elem);
}

function CannedHintsDisplay(props: { puzName: string }) {
  const { puzName } = props;
  const isHuntOver = useIsHuntOver();
  const cannedHints = CANNED_HINTS[puzName] ?? [];

  if (!(isHuntOver ?? false) || cannedHints.length === 0) return null;

  return (
    <>
      <h4>Canned hints</h4>
      {cannedHints.map(({ title, isTitleSpoiler, content }, i) => (
        <details key={i} className="canned-hint-details">
          <summary>
            {isTitleSpoiler ? <span className="spoiler">{title}</span> : title}
          </summary>
          <MarkdownText text={content} />
        </details>
      ))}
    </>
  );
}

function FreeAnswerDisplay(props: { puzData: TeamPuzzleSockAPIScopeState }) {
  const { puzData } = props;
  const { puzName } = puzData;
  const teamId = useTeamId();
  const teamHintsScopeState = useScopeStateResolvable(
    ScopeType.TEAM_HINTS,
    teamId === null ? null : { teamId }
  );
  const numTotalFreeAnswers = useNumTotalTokens(
    teamId,
    TimedTokenType.FREE_ANSWER
  );
  const numUsedFreeAnswers = useNumUsedFreeAnswers(teamId);
  const isSolved = useIsPuzzleSolved(puzName);
  const isHuntOver = useIsHuntOver();
  const now = useServerNow(1000);
  const sockClient = useSockClient();
  const useFreeAnswerLock = useUILock();
  const timeToNext = useTimeToNext(now, HINT_CONFIG.timedFreeAnswerCounts);

  if (
    teamId === null ||
    teamHintsScopeState === null ||
    numTotalFreeAnswers === null ||
    numUsedFreeAnswers === null ||
    isSolved === null ||
    isHuntOver === null ||
    now === null
  )
    return null;

  const numUnusedFreeAnswers = numTotalFreeAnswers - numUsedFreeAnswers;
  const res = checkUseFreeAnswer(
    puzData,
    {
      hasAnswer: puzData.hasAnswer ?? false,
      isHuntClosed: isHuntOver,
      numUnusedFreeAnswers,
      isSolved,
      unlockTime: puzData.unlockTime,
    },
    now
  );
  if (res.type === HelpResultType.INELIGIBLE) return null;

  const freeAnswerEmoji = <Twemoji tag="span">{Emoji.FREE_ANSWER}</Twemoji>;

  if (teamHintsScopeState.freeAnsweredPuzzles[puzName] ?? false)
    return (
      <div className="note-box">
        {freeAnswerEmoji} You used a free answer on this puzzle.
      </div>
    );
  // Don't advertise free answers before the team has any.
  if (isSolved || numTotalFreeAnswers === 0) return null;

  const freeAnswerError = ((): ReactNode | null => {
    switch (res.type) {
      case HelpResultType.HUNT_IS_CLOSED:
        return "Sorry, free answers are closed.";
      case HelpResultType.NO_TOKENS:
        return "You have no free answers available.";
      case HelpResultType.ALREADY_SOLVED:
        return "You've already solved this puzzle.";
      case HelpResultType.TOO_SOON:
        return (
          <>
            You can use a free answer on this puzzle starting{" "}
            <LongDate timestamp={res.availableTime} />.
          </>
        );
      case HelpResultType.SUCCESS:
        return null;
    }
  })();
  const freeAnswerWord =
    numUnusedFreeAnswers === 1 ? "free answer" : "free answers";

  return (
    <>
      <h4>Use a free answer</h4>
      <ul>
        <li>
          You have{" "}
          <b>
            {numUnusedFreeAnswers} {freeAnswerWord}
          </b>{" "}
          {freeAnswerEmoji}. Using one immediately solves this puzzle and shows
          you its answer.
        </li>
        <li>
          You can only use a free answer on a puzzle you’ve had unlocked for{" "}
          <b>
            {HINT_CONFIG.freeAnswerMinUnlockedDuration / 60 / 60 / 1000} hours
          </b>
          .
        </li>
        {timeToNext && (
          <li>Your next free answer will be available on {timeToNext}.</li>
        )}
      </ul>
      {freeAnswerError !== null ? (
        <div className="note-box">{freeAnswerError}</div>
      ) : (
        <div className="hint-controls">
          <button
            disabled={useFreeAnswerLock.isHeld}
            onClick={() => {
              if (
                !confirm(
                  "Use a free answer to solve this puzzle? This can't be undone."
                )
              )
                return;
              useFreeAnswerLock.acquireAndRun(async () => {
                const resp = await sockClient.sendScopeStepAndWaitAsync(
                  { type: ScopeType.TEAM_HINTS, teamId },
                  { puzName, useFreeAnswer: true }
                );
                if (resp !== null && resp.type !== HelpResultType.SUCCESS)
                  toastr.error("Couldn't use a free answer. Please try again.");
              });
            }}
          >
            Use a free answer (&minus;1 {freeAnswerEmoji})
          </button>
        </div>
      )}
    </>
  );
}

function CustomHintsDisplay(props: { puzData: TeamPuzzleSockAPIScopeState }) {
  const { puzData } = props;
  const { puzName } = puzData;
  const [isFollowup, setIsFollowup] = useState(false);
  const followupHintHeaderRef = useRef<HTMLHeadingElement>(null);
  const hintTextAreaRef = useRef<HTMLTextAreaElement>(null);

  const teamId = useTeamId();
  const teamScopeState = useTeamScopeState();
  const teamHintsScopeState = useScopeStateResolvable(
    ScopeType.TEAM_HINTS,
    teamId === null ? null : { teamId }
  );
  /*
  const teamCannedHintsScopeState = useScopeStateResolvable(
    ScopeType.TEAM_CANNED_HINTS,
    teamId === null ? null : { teamId }
  );
  */
  const numTotalHintTokens = useNumTotalTokens(teamId, TimedTokenType.HINT);
  const numUsedHintTokens = useNumUsedHintTokens(teamId);
  const sortedHints = useSortedHintsForTeamPuzzle(teamId, puzName, true);
  const isSolved = useIsPuzzleSolved(puzName);
  const now = useServerNow(1000);
  const sockClient = useSockClient();
  const submitHintLock = useUILock();
  const numUnusedHintTokens =
    numTotalHintTokens === null || numUsedHintTokens === null
      ? null
      : numTotalHintTokens - numUsedHintTokens;
  const openHintPuzName =
    teamHintsScopeState === null
      ? null
      : (Object.keys(teamHintsScopeState.openHints)[0] ?? null);
  const isHintOpenHere = teamHintsScopeState?.openHints[puzName] ?? false;
  const isHuntOver = useIsHuntOver();
  const [reqInputLength, setReqInputLength] = useState(0);
  const timeToNext = useTimeToNext(now, HINT_CONFIG.timedHintCounts);

  const checkSubmit = (isFollowup: boolean) =>
    numUnusedHintTokens === null || isHuntOver === null || now === null
      ? null
      : checkSubmitHint(
          puzData,
          {
            isHuntClosed: isHuntOver,
            numUnusedHintTokens,
            openHintPuzName,
            unlockTime: puzData.unlockTime,
            latestHint: sortedHints?.[0]?.[1],
          },
          isFollowup,
          now
        );
  const canFollowup = checkSubmit(true)?.type === HelpResultType.SUCCESS;

  useEffect(() => {
    if (!canFollowup) setIsFollowup(false);
  }, [canFollowup]);

  if (
    teamId === null ||
    sortedHints === null ||
    teamScopeState === null ||
    teamHintsScopeState === null ||
    //teamCannedHintsScopeState === null ||
    isSolved === null ||
    numUnusedHintTokens === null ||
    isHuntOver === null
  )
    return <Spinner inline />;

  const hintError = ((): ReactNode | null => {
    if (isFollowup) return null;

    const res = checkSubmit(false);
    if (res === null) return null;
    switch (res.type) {
      case HelpResultType.HUNT_IS_CLOSED:
        return "Sorry, hints are closed.";
      case HelpResultType.NO_TOKENS:
        return "You have no hints available!";
      case HelpResultType.OTHER_HINT_OPEN: {
        const { openHintPuzName } = res;
        return (
          <>
            You already have a hint pending on{" "}
            <PuzzleLink puzName={openHintPuzName} subpage="hints" />! You can
            have at most one hint pending at a time.
          </>
        );
      }
      case HelpResultType.TOO_SOON:
        return (
          <>
            You can request a hint on this puzzle starting{" "}
            <LongDate timestamp={res.availableTime} />.
          </>
        );
      case HelpResultType.INELIGIBLE:
      case HelpResultType.CANNOT_FOLLOWUP:
      case HelpResultType.SUCCESS:
        return null;
    }
  })();

  const hintWord = numUnusedHintTokens === 1 ? "hint" : "hints";
  const hintEmoji = <Twemoji tag="span">{Emoji.HINT}</Twemoji>;
  const hintCost = isFollowup ? 0 : 1;
  /*
  const cannedHints = teamCannedHintsScopeState.cannedHints[puzName] ?? {
    numTotal: 0,
    numOpened: 0,
  };
  const numMaxCannedHints = noCannedHints ? 0 : cannedHints.numMax;
  const areAllCannedHintsFound =
    numMaxCannedHints !== undefined &&
    cannedHints.numTotal >= numMaxCannedHints;
  */

  return (
    <>
      <h4>Custom hints</h4>
      <ul>
        <li>
          You have{" "}
          <b>
            {numUnusedHintTokens} {hintWord}
          </b>{" "}
          {hintEmoji} that you may use to ask for help on any puzzle.
        </li>
        <li>
          You may have <b>one hint</b> pending at a time; you must wait until
          that hint is answered to ask another.
        </li>
        <li>
          You can only use a hint on a puzzle you’ve had unlocked for{" "}
          <b>{HINT_CONFIG.hintMinUnlockedDuration / 60 / 60 / 1000} hours</b>.
        </li>
        {timeToNext && (
          <li>Your next hint will be available on {timeToNext}.</li>
        )}
      </ul>
      {isHintOpenHere && !isFollowup ? (
        <div className="note-box">
          You already have a hint pending on this puzzle!
        </div>
      ) : (
        <>
          <h4 ref={followupHintHeaderRef}>
            Request a {isFollowup ? "follow-up hint" : "hint"}
          </h4>
          {/*!areAllCannedHintsFound ? (
        <div className="note-box">
          There are {cannedHints.numTotal > 0 ? "more" : ""}{" "}
          <b>canned hints</b>{" "}
          <Icon icon={IconType.CANNED_HINT} className="hints-icon-disabled" />{" "}
          to be found for this puzzle, but you may still request a custom
          hint. If your hint is answered, you will also receive all{" "}
          {cannedHints.numTotal > 0 ? "remaining" : ""} canned hints for this
          puzzle.
        </div>
      ) : null*/}
          {isFollowup ? (
            <div className="note-box">
              You&rsquo;re asking us for a follow-up to your last hint. You can
              send us additional details on your progress and what kind of nudge
              would be useful for you, and we&rsquo;ll do our best to help.
              <br />
              <Twemoji tag="span">⚠️</Twemoji> <b>Note:</b> You may follow up{" "}
              <b>once</b> for free on each hint you spend. Making another
              request after that will require spending a new hint. (This rule
              has changed from previous years.)
            </div>
          ) : isSolved ? (
            <div className="note-box">
              You&rsquo;ve already solved this puzzle, but you can ask for a
              hint anyway if you&rsquo;d like (for example, if you&rsquo;re not
              sure about a step or you backsolved it). The restrictions above
              still apply.
            </div>
          ) : null}
          <form
            onSubmit={(e: FormEvent<HTMLFormElement>) => {
              e.preventDefault();
              const { hintRequestContent, shouldNotifyEmails } =
                Object.fromEntries(new FormData(e.currentTarget).entries());
              if (
                typeof hintRequestContent !== "string" ||
                !hintRequestContent.trim()
              ) {
                toastr.error("Please fill out the hint request.");
                return;
              }
              submitHintLock.acquireAndRun(async (getIsCanceled) => {
                await sockClient.sendScopeStepAndWaitAsync(
                  {
                    type: ScopeType.TEAM_HINTS,
                    teamId,
                  },
                  {
                    puzName,
                    req: {
                      content: hintRequestContent,
                      isFollowup: isFollowup ? true : undefined,
                      shouldNotifyEmails: shouldNotifyEmails ? true : undefined,
                    },
                  }
                );
              });
            }}
          >
            <label htmlFor="id_hint_question">
              Describe everything you&rsquo;ve tried on this puzzle. We will
              provide a hint to help you move forward. The more detail you
              provide, the less likely it is that we&rsquo;ll tell you something
              you already know. If you&rsquo;re working in a shared spreadsheet,
              it might help us if you linked it.
            </label>
            <textarea
              name="hintRequestContent"
              id="id_hint_question"
              rows={6}
              ref={hintTextAreaRef}
              disabled={submitHintLock.isHeld}
              required
              onChange={() => {
                if (hintTextAreaRef.current === null) return;
                setReqInputLength(hintTextAreaRef.current.value.length);
              }}
            />
            {reqInputLength > HINT_CONFIG.requestMaxLength ? (
              <>
                <div className="note-box">
                  Hint request too long ({reqInputLength} /{" "}
                  {HINT_CONFIG.requestMaxLength} chars). If you have a lot of
                  data to share, please link a spreadsheet or document instead.
                  If necessary, don&rsquo;t forget to set permissions on the
                  document so that anyone with the link can view it.
                </div>
              </>
            ) : null}
            {hintError !== null ? (
              <div className="note-box">{hintError}</div>
            ) : (
              <div className="hint-controls">
                <label className="hint-control">
                  Send an email when the hint is answered?{" "}
                  <input
                    name="shouldNotifyEmails"
                    type="checkbox"
                    disabled={submitHintLock.isHeld}
                    defaultChecked
                  />
                </label>
                <button
                  type="submit"
                  disabled={
                    submitHintLock.isHeld ||
                    reqInputLength > HINT_CONFIG.requestMaxLength
                  }
                >
                  Submit (&minus;{hintCost} {hintEmoji})
                </button>
              </div>
            )}
          </form>
        </>
      )}
      <FreeAnswerDisplay puzData={puzData} />
      {sortedHints.length > 0 ? (
        <>
          <h4>Previously requested hints</h4>
          {!isFollowup && canFollowup ? (
            <div className="hint-control">
              Did our hint not make sense or did we misunderstand your progress?
              <button
                onClick={() => {
                  setIsFollowup(true);
                  hintTextAreaRef.current?.focus();
                  followupHintHeaderRef.current?.scrollIntoView();
                }}
              >
                Request follow-up
              </button>
            </div>
          ) : null}
          {sortedHints.map(([hintId, hint]) => (
            <HintDisplay key={hintId} hintId={hintId} hint={hint} />
          ))}
          <div className="note-box">
            You can see your hints from all puzzles on your{" "}
            <Link {...makeTeamPagePath(teamScopeState.displayName)}>
              team page
            </Link>
            .
          </div>
        </>
      ) : null}
    </>
  );
}

