export function useIsInsightAvailable(
  puzData: TeamPuzzleSockAPIScopeState
): boolean {
  const isHuntOver = useIsHuntOver();
  const now = useServerNow(1000);
  return (
    INSIGHTS[puzData.slug] !== undefined &&
    ((isHuntOver ?? false) ||
      (now !== null &&
        now >= puzData.unlockTime + HINT_CONFIG.hintMinUnlockedDuration))
  );
}

function GainInsight({ puzData }: { puzData: TeamPuzzleSockAPIScopeState }) {
  const isAvailable = useIsInsightAvailable(puzData);
  const insight = INSIGHTS[puzData.slug];
  if (insight === undefined || !isAvailable) return null;

  return (
    <>
      <h4>Gain insight</h4>
      An insight is available for this puzzle. This is a free hint which gives a
      simpler example of a mechanic or aha of the puzzle. You can still ask for
      a custom hint below.
      <details>
        <summary>
          Reveal insight for <PuzzleTitle displayName={puzData.displayName} />
        </summary>
        <div className="gain-insight">
          <div className="gain-example">{insight.example}</div>
          {insight.extract && (
            <div className="gain-extract">→ {insight.extract}</div>
          )}
        </div>
      </details>
    </>
  );
}

function CheckYourWork({ puzData }: { puzData: TeamPuzzleSockAPIScopeState }) {
  const { puzName, slug } = puzData;
  const isHuntOver = useIsHuntOver();
  const isCheckPuzzleOn = useIsCheckPuzzleToggleOn(puzName);
  const updateBrowserWidePersistentState =
    useUpdateBrowserWidePersistentState();
  const checker = CHECKERS[slug];

  if (!(isHuntOver ?? false) || checker === undefined) return null;
  const { Checker, puzzleToggle } = checker;

  return (
    <>
      <h4>Check your work</h4>
      {puzzleToggle !== undefined && (
        <label className="hint-control">
          <input
            type="checkbox"
            checked={isCheckPuzzleOn}
            onChange={(e) =>
              updateBrowserWidePersistentState({
                checkPuzzleToggles: { [puzName]: e.target.checked },
              })
            }
          />
          {puzzleToggle}
        </label>
      )}
      {Checker && <Checker puzName={puzName} />}
    </>
  );
}

function HintsDisplay() {
  const puzData = useOutletContext<TeamPuzzleSockAPIScopeState>();
  const { slug } = puzData;
  const showHints = useShowHints(puzData);
  const setRedirectRoute = useNavStore((state) => state.setRedirectRoute);

  useEffect(() => {
    if (showHints ?? true) return;
    setRedirectRoute(
      slug ? { route: "puzzle", params: { slug } } : { route: "puzzles" }
    );
  }, [showHints, slug, setRedirectRoute]);

  if (!(showHints ?? false)) return <Spinner inline />;

  return (
    <div className="puzzle-page-body hints-page">
      <GainInsight puzData={puzData} />
      <CheckYourWork puzData={puzData} />
      <CannedHintsDisplay puzName={puzData.puzName} />
      <CustomHintsDisplay puzData={puzData} />
    </div>
  );
}

export default HintsDisplay;
