export function FileSubmission(props: {
  isLocked: boolean;
  slot: SubmitImageSlot;
  supportedExtensions: string[];
  maxFileSize: number;
  onSubmitSuccess: () => Promise<void>;
}) {
  const { isLocked, slot, supportedExtensions, maxFileSize, onSubmitSuccess } =
    props;
  const [fileErr, setFileErr] = useState<string | null>(null);
  const sockClient = useSockClient();
  const uploadLock = useUILock();

  return (
    <div className="file-submission">
      <div>
        <input
          type="file"
          accept={supportedExtensions.join(",")}
          disabled={isLocked || uploadLock.isHeld}
          onChange={(e) => {
            if (e.target.files === null) return;
            const [file] = e.target.files;
            if (file === undefined) return;
            const fileName = file.name.toLowerCase();
            if (!supportedExtensions.some((ext) => fileName.endsWith(ext))) {
              setFileErr("File format not supported.");
              return;
            }
            if (file.size > maxFileSize) {
              setFileErr("File is too large.");
              return;
            }
            uploadLock.acquireAndRun(async () => {
              try {
                await sockClient.sendDirectBackendReqAsync(
                  {
                    type: DirectBackendReqType.SUBMIT_IMAGE,
                    payload: { slot },
                  },
                  file,
                  () =>
                    new Promise((resolve, reject) => {
                      const reader = new FileReader();
                      reader.onload = (e) => {
                        const url = e.target?.result;
                        if (typeof url !== "string") {
                          reject(new Error("failed to read file"));
                          return;
                        }
                        resolve(url);
                      };
                      reader.onerror = (e) => {
                        reject(e.target?.error);
                      };
                      reader.readAsDataURL(file);
                    })
                );
                await onSubmitSuccess();
                setFileErr(null);
              } catch (err) {
                setFileErr(
                  "Failed to upload file. Please try again later and contact us if the problem persists."
                );
                console.error(err);
              }
            });
          }}
        />
      </div>
      {uploadLock.isHeld ? (
        <Spinner inline />
      ) : fileErr === null ? null : (
        <div className="file-submission-error">{fileErr}</div>
      )}
    </div>
  );
}

