import {
  CheckerForm,
  CheckerResultList,
  normalizeCheckerInput,
} from "components/PuzzlePage/checkers/AnswerListChecker";

/** Each section's answer, and what it shortens to. */
const SECTIONS = [
  ["FAILURE", "F"],
  ["FOURTH ROOT OF ONE", "I"],
  ["19", "S"],
  ["SYSTEME INTERNATIONAL", "SI"],
  ["ONTARIO", "ON"],
].map(([full, short]) => [normalizeCheckerInput(full), short]);

/**
 * Teams usually knew when a section was right, but often didn't know to
 * shorten it, so a full answer gets a nudge.
 */
function checkSections(text: string) {
  const lines = text
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => normalizeCheckerInput(line) !== "");
  if (lines.length === 0) return null;
  const used = new Set<number>();
  const results = lines.map((line) => {
    const entry = normalizeCheckerInput(line);
    const i = SECTIONS.findIndex(
      ([full, short], i) => !used.has(i) && (entry === full || entry === short)
    );
    if (i === -1) return { status: "wrong" as const, content: line };
    used.add(i);
    const isFull = entry === SECTIONS[i][0];
    return isFull
      ? {
          status: "partial" as const,
          content: <>{line}: almost; abbreviate it.</>,
        }
      : { status: "correct" as const, content: line };
  });
  const numCorrect = results.filter(
    ({ status }) => status === "correct"
  ).length;
  return {
    summary: (
      <>
        <b>
          {numCorrect} of {SECTIONS.length}
        </b>{" "}
        correct.
      </>
    ),
    details: <CheckerResultList results={results} />,
  };
}

/** The card for each Regent region and its star cost; Stardust costs X. */
const REGENT_CARDS = [
  ["Decisions, Decisions", "6"],
  ["The Sealed Throne", "3"],
  ["Crescent Spear", "1"],
  ["Cloak of Stars", "1"],
  ["Constellation", "2"],
  ["Meteor Shower", "2"],
  ["Dying Star", "3"],
  ["Stardust", "2"],
].map(([name, stars]) => ({ name, key: normalizeCheckerInput(name), stars }));

function checkRegent(text: string) {
  const lines = text
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => /[a-z]/i.test(line));
  if (lines.length === 0) return null;
  const used = new Set<number>();
  const results = lines.map((line) => {
    const [, name, stars] = /^(.*?)[\s:,=–-]*(\d+|X)?\s*$/i.exec(line)!;
    const key = normalizeCheckerInput(name);
    const i = REGENT_CARDS.findIndex((card) => card.key === key);
    if (i === -1) {
      return { status: "wrong" as const, content: line };
    }
    if (used.has(i)) {
      return { status: "wrong" as const, content: line };
    }
    used.add(i);
    const card = REGENT_CARDS[i];
    if (stars === undefined) {
      return { status: "partial" as const, content: line };
    }
    if (stars.toUpperCase() === "X" && card.name === "Stardust") {
      return { status: "partial" as const, content: <>{line}: what is X?</> };
    }
    return stars === card.stars
      ? { status: "correct" as const, content: line }
      : {
          status: "wrong" as const,
          content: <>{line}: right card, wrong stars.</>,
        };
  });
  const numRight = results.filter(({ status }) => status === "correct").length;
  return {
    summary: (
      <>
        <b>
          {numRight} of {REGENT_CARDS.length}
        </b>{" "}
        correct.
      </>
    ),
    details: <CheckerResultList results={results} />,
  };
}

export default function InspirationChecker() {
  return (
    <>
      <CheckerForm label="Paste answers, one per line." check={checkSections} />
      <CheckerForm
        label={
          <span className="spoiler">
            Regent: paste card and stars, one per line, like “Card Name 1”.
          </span>
        }
        check={checkRegent}
      />
    </>
  );
}
