import React, { useMemo, useRef, useState, useEffect } from "react";
import { AnimatePresence, motion, useIsPresent } from "framer-motion";
import Twemoji from "react-twemoji";
import { KeyframeData } from "sockapi/scope-specs/keyframe-spec";
import { getIsTeamConditionSatisfied } from "sockapi/scope-specs/team-spec";
import { CUSTOM_TITLE_MAX_LENGTH } from "sockapi/scope-specs/team-titles-spec";
import CUTSCENE_CHARACTERS from "sock-server/puzzles/cutscene-characters";
import { useEvent } from "client-util/useEvent";
import { clsObj } from "client-util/util";
import { useMotion } from "client-util/motion";
import { CharacterIcon } from "components/Icon";
import { CastCue, castWait } from "components/WorldCharacters";
import Modal from "components/Modal";
import Tooltip from "components/Tooltip";
import BgmPlayer from "components/CutsceneUi/BgmPlayer";
import { SFXName, SFXPlayer } from "client-util/useAudioEffect";
import {
  DialogueBox,
  renderDialogueSegments,
} from "components/CutsceneUi/DialogueBox";
import { useTypewriter } from "components/CutsceneUi/useTypewriter";
import { parseDialogue, sliceDialogue } from "components/CutsceneUi/markup";
import { CutscenePlayback } from "components/CutsceneUi/useCutscene";
import { escapeArrows } from "components/PuzzleContent/Arrows";
import { useTeamScopeState, useCustomTitle } from "stores/ScopeStateStore";
import "./CutsceneLayer.css";

function stopClick(evt: React.MouseEvent) {
  evt.preventDefault();
  evt.stopPropagation();
}

function keyframeSpeaker(
  keyframe: KeyframeData
): { characterId: string; name: string; color?: string } | undefined {
  const id = keyframe.speaker;
  if (id === undefined) return undefined;
  const staged = (keyframe.stage ?? []).find((c) => c.characterId === id);
  if (staged !== undefined) return staged;
  const character = CUTSCENE_CHARACTERS[id];
  return character === undefined
    ? undefined
    : { characterId: id, name: character.name, color: character.color };
}

// Wheel events closer together than this are one gesture (one line step).
const WHEEL_GESTURE_GAP_MS = 20;

// Which /static/images/<id>-icon.svg each speaker gets in the log.
const LOG_ICONS = {
  taylor: "taylor",
  camille: "camille",
  lam: "lam",
  dj: "dj",
  dawn: "dj",
  derek: "dj",
};

const CG_INITIAL_PAUSE_MS = 2500;

/**
 * Every line seen, including ones past the current line after a rewind.
 * Clicking one jumps to it.
 */
function CutsceneLog({
  log,
  logPosition,
  goToLogEntry,
  onClose,
}: {
  log: KeyframeData[];
  logPosition: number;
  goToLogEntry: (index: number) => void;
  onClose: () => void;
}) {
  // Focusing the current line also scrolls it into view.
  const currentRef = useRef<HTMLAnchorElement | null>(null);
  return (
    <Modal
      aria-label="Log"
      className="cutscene-log"
      onClose={onClose}
      initialFocus={currentRef}
      returnFocus={false}
      footerChildren={<button onClick={onClose}>Close</button>}
      onKeyDown={(e) => {
        e.stopPropagation();
        if (e.ctrlKey || e.metaKey || e.altKey) return;
        switch (e.key) {
          case "ArrowUp":
            (
              e.currentTarget.querySelector(
                "li:has(+ :focus-within) a"
              ) as HTMLAnchorElement | null
            )?.focus();
            break;
          case "ArrowDown":
            (
              e.currentTarget.querySelector(
                ":focus-within + li a"
              ) as HTMLAnchorElement | null
            )?.focus();
            break;
          case "Tab":
            onClose();
            break;
          default:
            return;
        }
        e.preventDefault();
      }}
    >
      <ol>
        {log.map((keyframe, i) => {
          // A beat has no line to show.
          if (keyframe.dialogue === "") return null;
          const speaker = keyframeSpeaker(keyframe);
          const icon =
            speaker !== undefined
              ? LOG_ICONS[speaker.characterId as keyof typeof LOG_ICONS]
              : undefined;
          return (
            <li
              key={i}
              style={
                speaker?.color !== undefined
                  ? ({
                      "--speaker-color": speaker.color,
                    } as React.CSSProperties)
                  : undefined
              }
            >
              <a
                ref={i === logPosition ? currentRef : undefined}
                aria-current={i === logPosition ? "step" : undefined}
                href="#"
                title="Go to this line"
                onClick={(evt) => {
                  evt.preventDefault();
                  goToLogEntry(i);
                  onClose();
                }}
              >
                {icon !== undefined ? (
                  <CharacterIcon
                    type="icon"
                    characterId={icon}
                    className="cutscene-log-icon"
                  />
                ) : (
                  <span className="cutscene-log-icon" />
                )}
                <span>
                  {speaker !== undefined ? (
                    <span className="cutscene-log-name">{speaker.name}</span>
                  ) : null}
                  <span
                    className={clsObj({
                      "cutscene-log-text": true,
                      "cutscene-log-stage-direction": !!keyframe.stageDirection,
                    })}
                  >
                    {renderDialogueSegments(
                      parseDialogue(keyframe.dialogue).segments
                    )}
                  </span>
                </span>
              </a>
            </li>
          );
        })}
      </ol>
    </Modal>
  );
}

function CutsceneDialogue({
  keyframeId,
  keyframe,
  stepped,
  chooseDialogOption,
  undo,
  redo,
  exit,
  log,
  logPosition,
  goToLogEntry,
  bgm,
  cue,
}: CutscenePlayback & { status: "playing"; cue: CastCue }) {
  // Arrives with the cast, once the layer it replaced has gone.
  const [wait] = useState(() => castWait(cue, "enter"));
  const isPresent = useIsPresent();
  const { fade, surface } = useMotion();
  const { dialogOptions = [null], dialogOptionsReqs } = keyframe;
  const teamScopeState = useTeamScopeState();
  const { segments, schedule } = useMemo(
    () => parseDialogue(keyframe.dialogue),
    [keyframe.dialogue]
  );

  // Only on advancing, not stepping back/forward or through the log. The ref
  // keeps StrictMode's double effect from playing it twice.
  const sfxPlayedForRef = useRef<string | null>(null);
  useEffect(() => {
    if (
      keyframe.sfx === undefined ||
      stepped ||
      sfxPlayedForRef.current === keyframeId
    )
      return;
    sfxPlayedForRef.current = keyframeId;
    SFXPlayer.play(keyframe.sfx as SFXName, { stopOtherSfx: false });
  }, [keyframeId, keyframe.sfx, stepped]);

  const [skipTyping, setSkipTyping] = useState(false);
  const typewriter = useTypewriter(schedule, keyframeId, {
    enabled: !skipTyping,
    initialPause: keyframe.isCg ? CG_INITIAL_PAUSE_MS : 0,
  });
  const step = (move: (() => void) | null) =>
    move &&
    (() => {
      setSkipTyping(true);
      move();
    });
  const prevLine = step(undo);
  const nextLine = step(redo);
  const choose = (index: number) => {
    setSkipTyping(false);
    chooseDialogOption(index);
  };

  const dialogOptionsReqsIsSatisfied =
    dialogOptionsReqs !== undefined && teamScopeState !== null
      ? dialogOptionsReqs.map((req) =>
          getIsTeamConditionSatisfied(req, teamScopeState)
        )
      : undefined;
  const puzData = teamScopeState?.puzzles[keyframe.puzName];
  const canExit = !(
    puzData?.prologue === "taylor" && puzData.solveTime === undefined
  );
  const isBranch = dialogOptions.length > 1;
  const hasLabeledOptions = dialogOptions.some((o) => o !== null);
  const speaker = keyframeSpeaker(keyframe);
  const [isLogOpen, setIsLogOpen] = useState(false);

  const advance = () => {
    if (!typewriter.isDone) {
      typewriter.finish();
      return;
    }
    if (!typewriter.canAdvance) return;
    // Only auto-advance a single, non-branching path.
    if (!isBranch) choose(0);
  };

  const [isSettingCustomTitle, setIsSettingCustomTitle] = useState(false);
  const customTitle = useCustomTitle(keyframe.puzName, () =>
    setIsSettingCustomTitle(false)
  );

  const handleKey = useEvent((e: KeyboardEvent) => {
    if (!isPresent) return;
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    switch (e.key) {
      case "Enter":
      case " ":
        advance();
        break;
      case "ArrowLeft":
        prevLine?.();
        break;
      case "ArrowRight":
        nextLine?.();
        break;
      case "Tab":
        setIsLogOpen(true);
        break;
      case "Escape":
        if (canExit) exit();
        break;
      case "`":
        setIsSettingCustomTitle(true);
        break;
      default:
        return;
    }
    e.preventDefault();
  });
  useEffect(() => {
    document.addEventListener("keydown", handleKey);
    return () => document.removeEventListener("keydown", handleKey);
  }, [handleKey]);

  const lastWheelRef = useRef(0);
  const handleWheel = (e: React.WheelEvent) => {
    const last = lastWheelRef.current;
    lastWheelRef.current = e.timeStamp;
    if (e.timeStamp - last < WHEEL_GESTURE_GAP_MS || e.deltaY === 0) return;
    (e.deltaY < 0 ? prevLine : nextLine)?.();
  };

  return (
    <>
      {bgm === null ? null : (
        <BgmPlayer
          key={bgm}
          name={bgm}
          variant={keyframe.bgm}
          keyframeId={keyframeId}
        />
      )}
      {/* Its parts take their own variants under these labels. */}
      <motion.div
        className="cutscene-layer"
        onClick={advance}
        onWheel={handleWheel}
        initial="enter"
        animate="show"
        exit="leave"
        variants={{ leave: { pointerEvents: "none" } }}
      >
        <motion.div
          className="cutscene-layer-controls"
          variants={fade("small", { after: wait }).variants}
          onClick={stopClick}
          onKeyDown={(e) => e.stopPropagation()}
        >
          {isSettingCustomTitle ? (
            <input
              type="text"
              autoFocus
              maxLength={CUSTOM_TITLE_MAX_LENGTH}
              defaultValue={customTitle.value}
              disabled={customTitle.disableInput}
              onBlur={(e) =>
                customTitle.set(escapeArrows(e.currentTarget.value))
              }
              onKeyDown={(e) => {
                if (e.key === "Enter")
                  customTitle.set(escapeArrows(e.currentTarget.value));
                if (e.key === "Escape") setIsSettingCustomTitle(false);
              }}
            />
          ) : (
            <>
              <h3 className="cafe-heading" title={customTitle.value}>
                {customTitle.value}
              </h3>
              <a
                className="puzzle-rename-button"
                href="#"
                onClick={(evt) => {
                  evt.preventDefault();
                  setIsSettingCustomTitle(true);
                }}
              >
                <Tooltip
                  text="Give this scene a name to help your team keep track of it. (`)"
                  placement="bottom"
                >
                  <Twemoji>✏️</Twemoji>
                </Tooltip>
              </a>
            </>
          )}
          <Tooltip text="Log (Tab)">
            <button onClick={() => setIsLogOpen(true)} aria-label="Log">
              ☰︎
            </button>
          </Tooltip>
          <Tooltip text="Previous line (←, or scroll up)">
            <button
              aria-label="Previous line"
              {...(prevLine === null
                ? { disabled: true }
                : { onClick: prevLine })}
            >
              ⏪︎
            </button>
          </Tooltip>
          <Tooltip text="Next line (→, or scroll down)">
            <button
              aria-label="Next line"
              {...(nextLine === null
                ? { disabled: true }
                : { onClick: nextLine })}
            >
              ⏩︎
            </button>
          </Tooltip>
          {canExit ? (
            <Tooltip text="Exit (Esc)">
              <button onClick={exit} aria-label="Exit">
                ⏹︎
              </button>
            </Tooltip>
          ) : null}
        </motion.div>
        <motion.div
          className="cutscene-layer-bottom"
          variants={surface("medium", { after: wait }).variants}
        >
          {hasLabeledOptions ? (
            <div className="cutscene-layer-options" onClick={stopClick}>
              {dialogOptions.map((dialogOption, index) => {
                const isDisabled = !(
                  dialogOptionsReqsIsSatisfied?.[index] ?? true
                );
                return (
                  <a
                    key={`${keyframeId}_${index}`}
                    href="#"
                    className={clsObj({
                      "keyframe-dialog-option": true,
                      disabled: isDisabled,
                    })}
                    onClick={(evt) => {
                      stopClick(evt);
                      if (isDisabled) return;
                      choose(index);
                    }}
                  >
                    <button>
                      <Twemoji>{dialogOption ?? "..."}</Twemoji>
                    </button>
                  </a>
                );
              })}
            </div>
          ) : null}
          <DialogueBox
            speakerName={speaker?.name}
            speakerColor={speaker?.color}
            stageDirection={keyframe.stageDirection}
            segments={sliceDialogue(segments, typewriter.revealed)}
            showContinue={typewriter.canAdvance && !hasLabeledOptions}
            hidden={typewriter.paused || keyframe.dialogue === ""}
          />
        </motion.div>
      </motion.div>
      {/* Outside the layer: React events bubble out of portals, and a click in
        the log must not advance the dialogue. */}
      {isLogOpen ? (
        <CutsceneLog
          log={log}
          logPosition={logPosition}
          goToLogEntry={(index) => {
            setSkipTyping(true);
            goToLogEntry(index);
          }}
          onClose={() => setIsLogOpen(false)}
        />
      ) : null}
    </>
  );
}

/** Full-screen dialogue UI. The background and cast are world layers. */
export function CutsceneLayer({
  playback,
  cue,
}: {
  playback: CutscenePlayback;
  cue: CastCue;
}) {
  return (
    <AnimatePresence>
      {playback.status !== "playing" ? null : (
        <CutsceneDialogue key="cutscene" {...playback} cue={cue} />
      )}
    </AnimatePresence>
  );
}
