import {
  CheckerForm,
  CheckerResultList,
} from "components/PuzzlePage/checkers/AnswerListChecker";

/** Each clue's phrase. */
const ANSWERS = [
  "LONG-((JUMP-SCARE)-QUOTE)",
  "(LONG-(JUMP-SCARE))-QUOTE",
  "((FRIENDLY-FIRE)-WALL)-UNIT",
  "(BODY-DOUBLE)-(CROSS-SECTION)",
  "((DARK-HORSE)-POWER)-VACUUM",
  "BODY-(DOUBLE-(CROSS-SECTION))",
  "(ANSWER-KEY)-(STONE-AGE)",
  "((LONG-JUMP)-SCARE)-QUOTE",
  "((ANSWER-KEY)-STONE)-AGE",
  "ANSWER-((KEY-STONE)-AGE)",
  "DARK-(HORSE-(POWER-VACUUM))",
  "PINK-(SLIP-(STREAM-LINING))",
  "((PINK-SLIP)-STREAM)-LINING",
  "(PINK-SLIP)-(STREAM-LINING)",
  "DARK-((HORSE-POWER)-VACUUM)",
  "FRIENDLY-(FIRE-(WALL-UNIT))",
  "DRUM-((STICK-FIGURE)-HEAD)",
  "(BLANK-CHECK)-(POINT-GUARD)",
  "BODY-((DOUBLE-CROSS)-SECTION)",
  "(DRUM-STICK)-(FIGURE-HEAD)",
  "PINK-((SLIP-STREAM)-LINING)",
  "DRUM-(STICK-(FIGURE-HEAD))",
  "(FRIENDLY-FIRE)-(WALL-UNIT)",
  "(DARK-HORSE)-(POWER-VACUUM)",
  "((BODY-DOUBLE)-CROSS)-SECTION",
  "((BLANK-CHECK)-POINT)-GUARD",
  "FRIENDLY-((FIRE-WALL)-UNIT)",
  "(LONG-JUMP)-(SCARE-QUOTE)",
  "(BLANK-(CHECK-POINT))-GUARD",
  "((DRUM-STICK)-FIGURE)-HEAD",
  "BLANK-((CHECK-POINT)-GUARD)",
  "(ANSWER-(KEY-STONE))-AGE",
];

/**
 * The words of a phrase, and the word spans [start, end) it groups (none if
 * its parentheses don't balance). Without parentheses, words joined by hyphens
 * group tighter than words separated by spaces, so BLANK-CHECK POINT-GUARD is
 * (BLANK-CHECK)-(POINT-GUARD).
 */
function parse(phrase: string) {
  const words: string[] = [];
  const spans: string[] = [];
  const opens: number[] = [];
  let isBalanced = true;
  if (phrase.includes("(") || phrase.includes(")")) {
    for (const token of phrase.toUpperCase().match(/[A-Z]+|[()]/g) ?? []) {
      if (token === "(") opens.push(words.length);
      else if (token === ")") {
        const start = opens.pop();
        if (start === undefined) isBalanced = false;
        else spans.push(`${start},${words.length}`);
      } else words.push(token);
    }
    if (opens.length > 0) isBalanced = false;
  } else {
    for (const chunk of phrase.toUpperCase().split(/\s+/)) {
      const start = words.length;
      words.push(...(chunk.match(/[A-Z]+/g) ?? []));
      spans.push(`${start},${words.length}`);
    }
  }
  // Groups of a single word or the whole phrase say nothing.
  const grouped = spans.filter((span) => {
    const [start, end] = span.split(",").map(Number);
    return isBalanced && end - start > 1 && end - start < words.length;
  });
  return {
    words,
    spans: grouped,
    hasGrouping: /[-–—()]/.test(phrase),
    isBalanced,
  };
}

/** Indices of the longest run of `indices` (in order) that increases. */
function longestIncreasing(indices: number[]) {
  const best = indices.map(() => 1);
  const prev = indices.map(() => -1);
  indices.forEach((x, i) => {
    for (let j = 0; j < i; j++)
      if (indices[j] < x && best[j] + 1 > best[i]) {
        best[i] = best[j] + 1;
        prev[i] = j;
      }
  });
  const result = new Set<number>();
  let i = best.indexOf(Math.max(0, ...best));
  while (i !== -1) {
    result.add(i);
    i = prev[i];
  }
  return result;
}

const GROUPING_MESSAGES = {
  right: "Groups right.",
  partial: "Groups right so far.",
  wrong: "Groups wrong.",
  missing: "",
  later: "",
  unbalanced: "",
};

/**
 * How a line compares to one clue's phrase: which of its words are right, and
 * whether its grouping is right if it has any. `score` ranks comparisons: 4 per
 * right word, 2 if they're all right, 1 if the grouping isn't wrong.
 */
function checkLine(line: string, answer: string) {
  const expected = parse(answer);
  // A pasted spreadsheet row might have the clue next to the answer.
  const cells = line
    .split("\t")
    .map((text) => ({ text: text.trim(), parsed: parse(text) }));
  const numShared = (words: string[]) =>
    expected.words.filter((word) => words.includes(word)).length;
  const { text, parsed } = cells.reduce((best, cell) =>
    numShared(cell.parsed.words) > numShared(best.parsed.words) ? cell : best
  );
  // Each word's place in the phrase; right words are the longest in-order run.
  const remaining = [...expected.words];
  const places = parsed.words.map((word) => {
    const k = remaining.indexOf(word);
    if (k !== -1) remaining[k] = "";
    return k;
  });
  const inOrder = longestIncreasing(places);
  const isWordRight = places.map((k, i) => k !== -1 && inOrder.has(i));
  const numRight = isWordRight.filter(Boolean).length;
  const allRight =
    numRight === expected.words.length &&
    parsed.words.length === expected.words.length;
  const grouping = !parsed.hasGrouping
    ? null
    : !parsed.isBalanced
      ? "unbalanced"
      : !allRight
        ? "later"
        : parsed.spans.length === 0
          ? "missing"
          : !parsed.spans.every((span) => expected.spans.includes(span))
            ? "wrong"
            : parsed.spans.length < expected.spans.length
              ? "partial"
              : "right";
  const messages = [
    allRight ? null : `${numRight} of ${expected.words.length} words right.`,
    grouping === null ? null : GROUPING_MESSAGES[grouping],
  ].filter((message) => message !== null);
  return {
    text,
    isWordRight,
    status:
      numRight < parsed.words.length || grouping === "wrong"
        ? ("wrong" as const)
        : allRight && (grouping === null || grouping === "right")
          ? ("correct" as const)
          : ("partial" as const),
    message: messages.join(" "),
    score: 4 * numRight + (allRight ? 2 : 0) + (grouping !== "wrong" ? 1 : 0),
  };
}

/** The line with each word marked right or wrong. */
function MarkedPhrase({
  text,
  isWordRight,
}: {
  text: string;
  isWordRight: boolean[];
}) {
  let k = 0;
  return (
    <>
      {(text.match(/[A-Za-z]+|[^A-Za-z]+/g) ?? []).map((token, i) =>
        /[A-Za-z]/.test(token) ? (
          <span
            key={i}
            className={
              (isWordRight[k++] ?? false)
                ? "checker-word-right"
                : "checker-word-wrong"
            }
          >
            {token}
          </span>
        ) : (
          token
        )
      )}
    </>
  );
}

/**
 * Pairs each line with a different clue, best comparisons first. Among equally
 * good pairs, lines with fewer such clues go first, so a line with parentheses
 * isn't crowded out by one without.
 */
function assignClues(lines: string[]) {
  const comparisons = lines.map((line) =>
    ANSWERS.map((answer) => checkLine(line, answer))
  );
  const pairs = comparisons.flatMap((row, i) => {
    const count = (score: number) =>
      row.filter((result) => result.score === score).length;
    return row.map((result, j) => ({
      i,
      j,
      result,
      count: count(result.score),
    }));
  });
  pairs.sort((a, b) => b.result.score - a.result.score || a.count - b.count);
  const lineResults: (ReturnType<typeof checkLine> | null)[] = lines.map(
    () => null
  );
  const isUsed = ANSWERS.map(() => false);
  for (const { i, j, result } of pairs) {
    if (lineResults[i] !== null || isUsed[j]) continue;
    lineResults[i] = result;
    isUsed[j] = true;
  }
  return lineResults.map(
    (result) =>
      result ?? {
        text: "",
        isWordRight: [],
        status: "wrong" as const,
        message: "",
        score: 0,
      }
  );
}

function checkPhrases(text: string) {
  const lines = text
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => /[A-Z]/i.test(line));
  if (lines.length === 0) return null;
  const results = assignClues(lines);
  const numCorrect = results.filter(
    ({ status }) => status === "correct"
  ).length;
  return {
    summary: (
      <>
        <b>
          {numCorrect} of {ANSWERS.length}
        </b>{" "}
        phrases right.
      </>
    ),
    details: (
      <CheckerResultList
        results={results.map(({ text, isWordRight, status, message }, i) => ({
          status,
          content: (
            <>
              {text === "" ? (
                lines[i]
              ) : (
                <MarkedPhrase text={text} isWordRight={isWordRight} />
              )}
              {message === "" ? null : <>: {message}</>}
            </>
          ),
        }))}
      />
    ),
  };
}

export default function MultiHyphenatesChecker() {
  return (
    <CheckerForm
      label={
        <>
          Paste the answers, one per line.{" "}
          <span className="spoiler">You can include punctuation</span>, for
          example, <span className="spoiler">A-((B-C)-D)</span>.
        </>
      }
      check={checkPhrases}
    />
  );
}
