import { useMemo } from "react";
import { DialogueBox } from "components/CutsceneUi/DialogueBox";
import { parseDialogue, sliceDialogue } from "components/CutsceneUi/markup";
import Tooltip from "components/Tooltip";
import { SolveDialoguePlayback } from "components/SolveDialogue/useSolveDialogue";

import "components/CutsceneUi/CutsceneLayer.css";

/**
 * Solve dialogue for screens too narrow for corner bubbles: the page dims, the
 * speakers step to centre stage (WorldCharacters moves them), and the lines
 * play in a cutscene dialogue box.
 */
export function SolveDialogueStage({
  playback,
}: {
  playback: SolveDialoguePlayback;
}) {
  const line =
    playback.status === "playing" && playback.staged
      ? playback.spoken[playback.spoken.length - 1]
      : undefined;
  const segments = useMemo(
    () => (line === undefined ? [] : parseDialogue(line.dialogue).segments),
    [line]
  );
  if (playback.status !== "playing" || line === undefined) return null;

  return (
    <>
      <div className="solve-dialogue-backdrop" />
      <div
        className="cutscene-layer solve-dialogue-stage"
        onClick={playback.advance}
      >
        <div className="cutscene-layer-controls">
          <Tooltip text="Exit">
            <button
              aria-label="Exit"
              onClick={(evt) => {
                evt.stopPropagation();
                playback.exit();
              }}
            >
              ⏹︎
            </button>
          </Tooltip>
        </div>
        <DialogueBox
          speakerName={line.name}
          speakerColor={line.color}
          segments={sliceDialogue(segments, playback.revealed)}
          showContinue={playback.canAdvance}
        />
      </div>
    </>
  );
}
