import { useMemo } from "react";
import Twemoji from "react-twemoji";
import { ScopeType } from "sockapi/scope-types";
import {
  LEADERBOARD_CONFIG,
  TeamSummaryState,
} from "sockapi/scope-specs/team-list-spec";
import {
  StateDownloadResult,
  useGlobalScopeStatePosthuntable,
  useIsHuntOver,
  useTeamScopeState,
} from "stores/ScopeStateStore";
import { useTeamId } from "stores/ServerInteractionStore";
import { Emoji } from "components/Icon";
import { Spinner } from "components/Loading";
import Tooltip from "components/Tooltip";
import { CafePage } from "pages/WorldBase";
import { TeamDisplayNamePreloaded } from "components/TeamDisplayName";
import DownloadFailed from "components/DownloadFailed";

function defaultSortKey(team: TeamSummaryState): number[] {
  const {
    completionTime = Infinity,
    lastSolveTime = Infinity,
    numSolves,
    teamId,
  } = team;
  return [
    completionTime,
    -numSolves,
    lastSolveTime,
    isNaN(+teamId) ? 0 : +teamId,
  ];
}

function bucketingSortKey(team: TeamSummaryState): number[] {
  const { teamId } = team;
  return [isNaN(+teamId) ? 0 : +teamId];
}

const DAY_MS = 24 * 60 * 60 * 1000;

function useSortedTeamsPosthuntable(
  teamToSortKey: (team: TeamSummaryState) => number[],
  includeHidden?: boolean,
  hasPosthunt?: boolean
): StateDownloadResult<TeamSummaryState[]> | null {
  const teamsResult = useGlobalScopeStatePosthuntable(
    ScopeType.TEAM_LIST,
    true,
    { hasPosthunt: hasPosthunt ?? false }
  );

  return useMemo(() => {
    if (teamsResult === null) return null;
    if (!teamsResult.success) return teamsResult;
    const teams = teamsResult.state;
    const sortedTeams = Object.values(teams)
      .filter((team) => {
        if (team.isHidden && !(includeHidden ?? false)) return false;
        return true;
      })
      .sort((a, b) => {
        const aKey = teamToSortKey(a);
        const bKey = teamToSortKey(b);
        for (let i = 0; i < aKey.length; i++) {
          if (aKey[i] !== bKey[i]) return aKey[i] - bKey[i];
        }
        return a.displayName.localeCompare(b.displayName);
      });
    return { success: true, state: sortedTeams };
  }, [teamsResult, includeHidden, teamToSortKey]);
}

export function useSortedTeams(
  includeHidden?: boolean
): TeamSummaryState[] | null {
  const result = useSortedTeamsPosthuntable(
    defaultSortKey,
    includeHidden,
    false
  );
  if (result === null) return null;
  if (!result.success) throw new Error("should not fail if not posthuntable");
  return result.state;
}

type TeamBucket = {
  key: string;
  label: string;
  /** If set, the bucket gets a toolbar button to scroll to it. */
  icon?: string;
  teams: TeamSummaryState[];
};

/**
 * Teams bucket by solve count into at least LEADERBOARD_CONFIG.minBucketSize
 * buckets, without splitting ties.
 */
function bucketTeamsBySnapshotSolves(
  teams: TeamSummaryState[],
  ownTeamId: string | null
): TeamBucket[] {
  const sortedTeams = [...teams].sort(
    (a, b) => b.snapshotNumSolves - a.snapshotNumSolves
  );
  const groups: TeamSummaryState[][] = [];
  let group: TeamSummaryState[] = [];
  sortedTeams.forEach((team, i) => {
    group.push(team);
    const nextTeam = sortedTeams[i + 1] as TeamSummaryState | undefined;
    if (
      group.length >= LEADERBOARD_CONFIG.minBucketSize &&
      nextTeam?.snapshotNumSolves !== team.snapshotNumSolves
    ) {
      groups.push(group);
      group = [];
    }
  });
  // Any leftover group is too small, so fold it into the one above.
  if (group.length > 0) {
    if (groups.length > 0) groups[groups.length - 1].push(...group);
    else groups.push(group);
  }

  return groups.map((groupTeams, i) => {
    const solveNums = groupTeams
      .map((team) => team.snapshotNumSolves)
      .sort((a, b) => a - b);
    const medianSolves = solveNums[Math.floor((solveNums.length - 1) / 2)];
    return {
      key: `bucket-${i}`,
      label: `${medianSolves} ${Emoji.PUZZLE_SOLVED}`,
      teams: groupTeams.sort((a, b) => {
        if (a.teamId === ownTeamId) return -1;
        if (b.teamId === ownTeamId) return 1;
        return (
          bucketingSortKey(a)[0] - bucketingSortKey(b)[0] ||
          a.displayName.localeCompare(b.displayName)
        );
      }),
    };
  });
}

/** Teams bucketed by completion time and then meta solves. */
function bucketTeamsByCompletion(
  teams: TeamSummaryState[],
  huntStartTime: number,
  huntEndTime: number
): TeamBucket[] {
  const buckets: TeamBucket[] = [
    { key: "☕", label: "✈️✈️✈️ ☕ ✈️✈️✈️", icon: "☕", teams: [] },
    { key: "🥐", label: "✈️✈️ 🥐 ✈️✈️", icon: "🥐", teams: [] },
    { key: "🍴", label: "✈️ 🍴 ✈️", icon: "🍴", teams: [] },
    { key: "👤", label: "Teams", icon: "👤", teams: [] },
  ];
  for (const team of teams) {
    if (team.completionTime === undefined) buckets[3].teams.push(team);
    else if (team.completionTime < huntStartTime + DAY_MS * 3)
      buckets[0].teams.push(team);
    else if (team.completionTime < huntEndTime) buckets[1].teams.push(team);
    else buckets[2].teams.push(team);
  }
  return buckets;
}

function TeamListPage() {
  const teamId = useTeamId();
  const teamScopeState = useTeamScopeState();
  const isHuntOver = useIsHuntOver();
  const sortedTeamsResult = useSortedTeamsPosthuntable(
    bucketingSortKey,
    false,
    true
  );

  // When hunt ends, switch to completion-bucketing over snapshot-bucketing.
  const buckets = useMemo(() => {
    if (
      teamScopeState === null ||
      isHuntOver === null ||
      !sortedTeamsResult?.success
    )
      return null;
    return isHuntOver
      ? bucketTeamsByCompletion(
          sortedTeamsResult.state,
          teamScopeState.huntStartTime,
          teamScopeState.huntEndTime
        )
      : bucketTeamsBySnapshotSolves(sortedTeamsResult.state, teamId);
  }, [teamScopeState, isHuntOver, sortedTeamsResult, teamId]);

  if (sortedTeamsResult !== null && !sortedTeamsResult.success)
    return (
      <CafePage heading="Team Scoreboard">
        <DownloadFailed {...sortedTeamsResult} />
      </CafePage>
    );
  if (buckets === null)
    return (
      <CafePage heading="Team Scoreboard">
        <Spinner size={48} />
      </CafePage>
    );

  const toolbar = buckets.flatMap(({ key, label, icon, teams }) =>
    icon === undefined || teams.length === 0 ? (
      []
    ) : (
      <Tooltip
        text={
          <>
            <Twemoji tag="span">{label}</Twemoji> ({teams.length})
          </>
        }
        placement="left"
        key={key}
      >
        <button
          onClick={() => {
            document
              .querySelector(`table[data-bucket="${key}"]`)
              ?.scrollIntoView({
                behavior: "smooth",
              });
          }}
        >
          <Twemoji>{icon}</Twemoji>
        </button>
      </Tooltip>
    )
  );

  return (
    <CafePage
      heading="Team Scoreboard"
      toolbar={
        toolbar.length ? (
          <div className="button-squish-zone">{toolbar}</div>
        ) : null
      }
    >
      {isHuntOver ? (
        <p>
          Teams are grouped by completion time. Within each group, teams are
          sorted by team creation time.
        </p>
      ) : (
        <p>
          Teams are grouped by number of puzzles solved. Each group is labeled
          with the median number of solves. Within each group, teams are sorted
          by team creation time. Groups update every hour.
        </p>
      )}
      {buckets.map(({ key, label, teams }) =>
        teams.length === 0 ? null : (
          <table className="list-table" data-bucket={key} key={key}>
            <tbody>
              <tr>
                <th>
                  <Twemoji tag="span">{label}</Twemoji> ({teams.length})
                </th>
              </tr>
              {teams.map((team) => (
                <tr
                  className={`${
                    teamId !== null && team.teamId === teamId
                      ? "current-team"
                      : ""
                  }`}
                  key={team.teamId}
                >
                  <td>
                    <TeamDisplayNamePreloaded
                      teamData={team}
                      shipStyle="show"
                    />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )
      )}
    </CafePage>
  );
}

export default TeamListPage;
