// Ported from the author's standalone page (app.js). The data is generated
// and checked against the printed sheets upstream; never hand-edit it. The
// traits are positional and unnamed on purpose: naming them is the puzzle.

type Values = (number | number[])[];
type Data = {
  traits: { masks: number[]; values: Values; w?: Record<number, number[]> }[];
  draw: Record<"colour" | "tail" | "teeth" | "eyes" | "antennae", number>;
  eyeSpacing: number;
  eyeOffset: number;
  palette: string[];
  pedigree: {
    vb: number[];
    wires: number[][];
    nodes: { x: number; y: number; r: number; ph: Values }[];
    eggs?: { x: number; y: number; r: number }[];
    eq?: number[];
  };
};
type G = { cx: number; cy: number; r: number; colour: string; tail: number };

const INK = "#111",
  LINE = 2.4,
  RED = "#b3453a";
/* tail tip reaches this many body radii, so the body must stay small enough
   that a tail in any direction still fits the box */
const TAIL_REACH = 2.15,
  BODY_FRAC = 0.21;

/* ---------- genetics ---------- */
const idx = (ch: string) => ch.charCodeAt(0) - 65;
const letter = (i: number) => String.fromCharCode(65 + i);

/* Draws in proportion to how the real process produces each child, not
   uniformly over the legal ones; where a trait's outcome is uniform no
   weight table is shipped. */
function pickChild(D: Data, t: number, a: number, b: number) {
  const mask = D.traits[t].masks[a * 26 + b];
  const opts: number[] = [];
  for (let c = 0; c < 26; c++) if (mask & (1 << c)) opts.push(c);
  if (!opts.length) return null;
  const w = D.traits[t].w?.[a * 26 + b];
  if (!w) return opts[(Math.random() * opts.length) | 0];
  let r = Math.random() * w.reduce((x, y) => x + y, 0);
  for (let i = 0; i < opts.length; i++) {
    r -= w[i];
    if (r < 0) return opts[i];
  }
  return opts[opts.length - 1];
}

/** Each legal child gene for one trait, with the chance pickChild draws it. */
function childOdds(D: Data, t: number, a: number, b: number) {
  const mask = D.traits[t].masks[a * 26 + b];
  const opts: number[] = [];
  for (let c = 0; c < 26; c++) if (mask & (1 << c)) opts.push(c);
  const w = D.traits[t].w?.[a * 26 + b] ?? opts.map(() => 1);
  const total = w.reduce((x, y) => x + y, 0);
  return opts.map((c, i) => ({ gene: letter(c), chance: w[i] / total }));
}

/** Child's phenotype, or null if any trait has no legal child. */
function breed(D: Data, ga: string, gb: string): Values | null {
  const v: Values = [];
  for (let t = 0; t < 5; t++) {
    const c = pickChild(D, t, idx(ga[t]), idx(gb[t]));
    if (c === null) return null;
    v.push(D.traits[t].values[c]);
  }
  return v;
}

/* ---------- drawing (port of alienart.py) ---------- */
const EYE_SPOTS: Record<number, number[][]> = {
  0: [],
  1: [[0, 0]],
  2: [
    [0, -1.15],
    [0, 1.15],
  ],
  3: [
    [0, -1.35],
    [-1.15, 0.85],
    [1.15, 0.85],
  ],
};

function at(g: G, deg: number, dist: number) {
  const a = (deg * Math.PI) / 180;
  return [g.cx + Math.cos(a) * dist, g.cy - Math.sin(a) * dist];
}
function off(pt: number[], deg: number, w: number) {
  const a = ((deg + 90) * Math.PI) / 180;
  return [pt[0] + Math.cos(a) * w, pt[1] - Math.sin(a) * w];
}
const f1 = (n: number) => n.toFixed(1);
const pt = (p: number[]) => `${f1(p[0])} ${f1(p[1])}`;

function drawTail(g: G) {
  if (g.tail === -1) return "";
  const deg = g.tail * 22.5,
    bw = g.r * 0.3;
  const p0 = at(g, deg, g.r * 0.35),
    p1 = at(g, deg + 7, g.r * 1.25),
    p2 = at(g, deg - 2, g.r * 1.75),
    tip = at(g, deg, g.r * TAIL_REACH);
  const a0 = off(p0, deg, bw),
    b0 = off(p0, deg, -bw),
    a1 = off(p1, deg + 7, bw * 0.78),
    b1 = off(p1, deg + 7, -bw * 0.78),
    a2 = off(p2, deg - 2, bw * 0.55),
    b2 = off(p2, deg - 2, -bw * 0.55),
    h1 = off(p2, deg - 2, bw * 1.35),
    h2 = off(p2, deg - 2, -bw * 1.35);
  const d =
    `M ${pt(a0)} Q ${pt(a1)} ${pt(a2)} L ${pt(h1)} L ${pt(tip)} ` +
    `L ${pt(h2)} L ${pt(b2)} Q ${pt(b1)} ${pt(b0)} Z`;
  return (
    `<path d="${d}" fill="${g.colour}" stroke="${INK}" ` +
    `stroke-width="${LINE}" stroke-linejoin="round"/>`
  );
}

/* faint hairline along the exact direction, stopping at the tail's apex;
   the tail's kink makes its silhouette only approximate */
function drawGuide(g: G) {
  if (g.tail === -1) return "";
  const deg = g.tail * 22.5;
  const p0 = at(g, deg, 0),
    p1 = at(g, deg, g.r * TAIL_REACH);
  return (
    `<line x1="${f1(p0[0])}" y1="${f1(p0[1])}" x2="${f1(p1[0])}" ` +
    `y2="${f1(p1[1])}" stroke="${INK}" stroke-opacity="0.42" ` +
    `stroke-width="${(LINE * 0.32).toFixed(2)}"/>`
  );
}

function drawAntennae(g: G, n: number, spread = 150, clear = 34) {
  if (!n) return "";
  let lo = 90 - spread / 2,
    hi = 90 + spread / 2;
  if (g.tail !== -1) {
    const t = g.tail * 22.5;
    if (t > lo - clear && t < hi + clear) {
      if (t <= 90) lo = Math.min(hi - 10, t + clear);
      else hi = Math.max(lo + 10, t - clear);
    }
  }
  let s = "";
  for (let i = 0; i < n; i++) {
    const f = n === 1 ? 0.5 : i / (n - 1),
      deg = lo + (hi - lo) * f;
    const p0 = at(g, deg, g.r * 0.94),
      p1 = at(g, deg, g.r * 1.34);
    s +=
      `<line x1="${f1(p0[0])}" y1="${f1(p0[1])}" x2="${f1(p1[0])}" ` +
      `y2="${f1(p1[1])}" stroke="${INK}" stroke-width="${f1(LINE * 0.8)}" ` +
      `stroke-linecap="round"/>` +
      `<circle cx="${f1(p1[0])}" cy="${f1(p1[1])}" r="${f1(g.r * 0.085)}" ` +
      `fill="${g.colour}" stroke="${INK}" stroke-width="${f1(LINE * 0.7)}"/>`;
  }
  return s;
}

function drawBody(g: G) {
  return (
    `<circle cx="${f1(g.cx)}" cy="${f1(g.cy)}" r="${f1(g.r)}" ` +
    `fill="${g.colour}" stroke="${INK}" stroke-width="${LINE}"/>`
  );
}

function drawEyes(D: Data, g: G, eyes: number[]) {
  const er = g.r * 0.135,
    F = D.eyeSpacing;
  let s = "";
  [
    [eyes[0], -1],
    [eyes[1], 1],
  ].forEach(([n, side]) => {
    const hx = g.cx + side * g.r * D.eyeOffset,
      hy = g.cy - g.r * 0.22;
    (EYE_SPOTS[n] ?? []).forEach(([dx, dy]) => {
      const x = hx + dx * er * F,
        y = hy + dy * er * F;
      s +=
        `<ellipse cx="${f1(x)}" cy="${f1(y)}" rx="${f1(er)}" ` +
        `ry="${f1(er * 1.25)}" fill="#fff" stroke="${INK}" ` +
        `stroke-width="${f1(LINE * 0.7)}"/>` +
        `<ellipse cx="${f1(x)}" cy="${f1(y)}" rx="${f1(er * 0.42)}" ` +
        `ry="${f1(er * 0.8)}" fill="${INK}"/>`;
    });
  });
  return s;
}

function drawMouth(g: G, teeth: number) {
  const w = g.r * 1.05,
    y = g.cy + g.r * 0.3;
  const left = g.cx - w / 2,
    right = g.cx + w / 2,
    depth = g.r * 0.46;
  let s =
    `<path d="M ${f1(left)} ${f1(y)} A ${f1(w / 2)} ${f1(depth)} 0 0 0 ` +
    `${f1(right)} ${f1(y)} Z" fill="#bdbdbd" stroke="${INK}" ` +
    `stroke-width="${LINE}" stroke-linejoin="round"/>`;
  const n = Math.max(0, teeth | 0),
    step = w / (n || 1);
  for (let i = 0; i < n; i++) {
    const x0 = left + i * step,
      t = (i + 0.5) / n;
    const h = depth * 0.62 * (0.45 + 0.55 * Math.sin(Math.PI * t));
    s +=
      `<path d="M ${f1(x0)} ${f1(y)} L ${f1(x0 + step / 2)} ${f1(y + h)} ` +
      `L ${f1(x0 + step)} ${f1(y)} Z" fill="#fff" stroke="${INK}" ` +
      `stroke-width="${f1(LINE * 0.55)}" stroke-linejoin="round"/>`;
  }
  return s;
}

/** The palette colour for three colour bits. */
const colourOf = (D: Data, bits: number[]) =>
  D.palette[(+!!bits[0] << 2) | (+!!bits[1] << 1) | +!!bits[2]];

/* Which genome position drives which feature is D.draw, not a constant. */
function alienBody(D: Data, v: Values, cx: number, cy: number, r: number) {
  const g: G = {
    cx,
    cy,
    r,
    colour: colourOf(D, v[D.draw.colour] as number[]),
    tail: v[D.draw.tail] as number,
  };
  return (
    drawTail(g) +
    drawGuide(g) +
    drawAntennae(g, v[D.draw.antennae] as number) +
    drawBody(g) +
    drawEyes(D, g, v[D.draw.eyes] as number[]) +
    drawMouth(g, v[D.draw.teeth] as number)
  );
}

const alienSVG = (D: Data, v: Values, size: number) =>
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}">` +
  alienBody(D, v, size / 2, size / 2, size * BODY_FRAC) +
  `</svg>`;

/* ---------- pedigree ---------- */
type PedNode = Data["pedigree"]["nodes"][number];
/* An invisible box over an alien and its two label lines, so hovering anywhere
   near it counts. */
const hitbox = (n: PedNode) =>
  `<rect x="${(n.x - n.r * 2.1).toFixed(1)}" y="${(n.y - n.r * 1.5).toFixed(1)}" ` +
  `width="${(n.r * 4.2).toFixed(1)}" height="${(n.r * 4.8).toFixed(1)}" fill="transparent"/>`;

/* A line of label text under node n, `row` lines down, with a halo so tails
   and wires don't cut it. */
function labelSVG(
  n: PedNode,
  row: number,
  body: string,
  colour = INK,
  size = 1
) {
  return (
    `<text x="${n.x}" y="${(n.y + n.r * (1.75 + row)).toFixed(1)}" text-anchor="middle" ` +
    `dominant-baseline="central" font-family="monospace" font-weight="bold" ` +
    `font-size="${(n.r * 0.85 * size).toFixed(1)}" fill="${colour}" stroke="#fff" ` +
    `stroke-width="${(n.r * 0.3).toFixed(1)}" stroke-linejoin="round" ` +
    `paint-order="stroke" letter-spacing="2">${body}</text>`
  );
}

// wires go first, so antennae and tails sit over them
const wiresSVG = (D: Data) =>
  D.pedigree.wires
    .map(
      ([x1, y1, x2, y2]) =>
        `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" ` +
        `stroke="${INK}" stroke-width="2.4"/>`
    )
    .join("");

/* The newborns: no phenotype is shipped for them, so nothing to leak. The '='
   says the two are the same alien. */
function eggsSVG(D: Data) {
  const P = D.pedigree;
  let s = "";
  (P.eggs ?? []).forEach((e) => {
    s +=
      `<circle cx="${e.x}" cy="${e.y}" r="${(e.r * 0.95).toFixed(1)}" ` +
      `fill="#fff" stroke="${INK}" stroke-width="2.2" stroke-dasharray="7 5"/>` +
      `<text x="${e.x}" y="${e.y}" text-anchor="middle" ` +
      `dominant-baseline="central" font-weight="bold" ` +
      `font-size="${(e.r * 1.15).toFixed(1)}" fill="${RED}">?</text>`;
  });
  if (P.eq)
    s +=
      `<text x="${P.eq[0]}" y="${P.eq[1]}" text-anchor="middle" ` +
      `dominant-baseline="central" font-weight="bold" font-size="34" ` +
      `fill="${INK}">=</text>`;
  return s;
}

/* With `labels`, the tree is labelled (the solution's) and static, so the
   nodes aren't buttons. */
function treeSVG(
  D: Data,
  labels?: (string | null)[],
  isStatic = labels !== undefined
) {
  const P = D.pedigree;
  let s =
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${P.vb.join(" ")}" ` +
    `preserveAspectRatio="xMidYMid meet">` +
    wiresSVG(D);
  P.nodes.forEach((n, i) => {
    if (isStatic) {
      s += alienBody(D, n.ph, n.x, n.y, n.r);
      return;
    }
    s +=
      `<g class="genetic-node" data-i="${i}" tabindex="0" role="button" ` +
      `aria-label="Enlarge alien">` +
      `<circle class="genetic-halo" cx="${n.x}" cy="${n.y}" r="${(n.r * 1.28).toFixed(1)}"/>` +
      alienBody(D, n.ph, n.x, n.y, n.r) +
      `<circle class="genetic-hit" cx="${n.x}" cy="${n.y}" r="${n.r.toFixed(1)}"/>` +
      `</g>`;
  });
  // labels after every alien, so none is covered
  if (labels)
    P.nodes.forEach((n, i) => (s += labelSVG(n, 0, labels[i] ?? "?")));
  return s + eggsSVG(D) + "</svg>";
}

export type GeneticData = Data;

export function useGeneticData(src: string) {
  const [data, setData] = useState<Data | null>(null);
  useEffect(() => {
    const ac = new AbortController();
    fetch(src, { signal: ac.signal })
      .then((r) => r.json())
      .then((d: Data) => setData(d))
      .catch((e) => ac.signal.aborted || console.error(e));
    return () => ac.abort();
  }, [src]);
  return data;
}

/* ---------- solution ---------- */
const sameValues = (a: Values, b: Values) =>
  JSON.stringify(a) === JSON.stringify(b);
const express = (D: Data, genome: string): Values =>
  D.traits.map((t, i) => t.values[idx(genome[i])]);
/** Each node's number in `list`, 0 if no genome there matches it. */
const nodeNumbers = (D: Data, list: string[]) =>
  D.pedigree.nodes.map(
    (n) => list.findIndex((g) => sameValues(express(D, g), n.ph)) + 1
  );

/**
 * The puzzle's pedigree with every alien labelled "n GENOME", where n is the
 * genome's position in `genomes` (space-separated, in the solution's numbering).
 * Nodes are matched to genomes by phenotype, since the shipped node order is
 * unrelated to that numbering.
 */
export function GeneticPedigree({
  src,
  genomes,
}: {
  src: string;
  genomes: string;
}) {
  const data = useGeneticData(src);
  if (!data) return <p>Loading…</p>;

  const list = genomes.split(/\s+/).filter(Boolean);
  const labels = nodeNumbers(data, list).map((k) =>
    k ? `${k} ${list[k - 1]}` : null
  );
  return (
    <div
      className="genetic-tree"
      // eslint-disable-next-line @eslint-react/dom-no-dangerously-set-innerhtml -- SVG we generate
      dangerouslySetInnerHTML={{ __html: treeSVG(data, labels) }}
    />
  );
}

/* ---------- posthunt checker ---------- */
/** Pedigree node indices in reading order: by row, then left to right. */
const readingOrder = (D: Data) =>
  D.pedigree.nodes
    .map((n, i) => ({ y: Math.round(n.y), x: n.x, i }))
    .sort((a, b) => a.y - b.y || a.x - b.x)
    .map(({ i }) => i);

/** The genome of each alien in reading order, out of `genomes`. */
export function geneticGenomesInReadingOrder(D: Data, genomes: string[]) {
  return readingOrder(D).map(
    (i) =>
      genomes.find((g) => sameValues(express(D, g), D.pedigree.nodes[i].ph)) ??
      null
  );
}

const cleanEntry = (s: string) =>
  s
    .toUpperCase()
    .replace(/\./g, "?")
    .replace(/[^A-Z?]/g, "")
    .slice(0, 5);

/** The pasted entries, one per box: whole genomes, or single genes. */
const splitPaste = (text: string, gene: number | null) => {
  const tokens = text.split(/\s+/).map(cleanEntry).filter(Boolean);
  return gene !== null && tokens.length === 1 ? [...tokens[0]] : tokens;
};

/**
 * The pedigree with a box under every alien; `values[k]` is the k-th alien in
 * reading order, as five genes with ? for unknowns. With `gene` set, each box
 * is just that gene. Pasting several entries into a box fills it and the boxes
 * after it.
 */
export function GeneticPedigreeInputs({
  data,
  values,
  setValues,
  gene,
}: {
  data: Data;
  values: string[];
  setValues: (values: string[]) => void;
  gene: number | null;
}) {
  const [x0, y0, w, h] = data.pedigree.vb;
  const genomeAt = (k: number) => values[k] ?? "?????";
  const withEntry = (genome: string, entry: string) =>
    gene === null
      ? entry.padEnd(5, "?")
      : genome.slice(0, gene) +
        // A whole pasted genome gives its gene; otherwise the last letter typed.
        ((entry.length === 5 ? entry[gene] : entry.slice(-1)) || "?") +
        genome.slice(gene + 1);
  return (
    <div
      className={`genetic-tree genetic-tree-inputs${gene === null ? "" : " genetic-tree-gene"}`}
    >
      <div
        // eslint-disable-next-line @eslint-react/dom-no-dangerously-set-innerhtml -- SVG we generate
        dangerouslySetInnerHTML={{ __html: treeSVG(data, undefined, true) }}
      />
      {readingOrder(data).map((i, k) => {
        const n = data.pedigree.nodes[i];
        const genome = genomeAt(k);
        const shown =
          gene === null
            ? genome.replace(/\?+$/, "")
            : genome[gene].replace("?", "");
        return (
          <input
            key={i}
            type="text"
            value={shown}
            spellCheck={false}
            autoComplete="off"
            aria-label={`Alien ${k + 1} in reading order`}
            style={{
              left: `${((n.x - x0) / w) * 100}%`,
              top: `${((n.y + n.r * 2 - y0) / h) * 100}%`,
            }}
            onFocus={(e) => e.target.select()}
            onChange={(e) => {
              const entry = cleanEntry(e.target.value);
              const next = [...values];
              next[k] = withEntry(genome, entry);
              setValues(next);
              // One gene per box, so move on as soon as it's typed.
              if (gene !== null && /[A-Z]$/.test(entry)) {
                const inputs =
                  e.target.parentElement!.querySelectorAll("input");
                inputs[k + 1]?.focus();
              }
            }}
            onPaste={(e) => {
              const pasted = splitPaste(e.clipboardData.getData("text"), gene);
              if (pasted.length < 2) return;
              e.preventDefault();
              const next = [...values];
              pasted.forEach((entry, j) => {
                if (k + j < data.pedigree.nodes.length)
                  next[k + j] = withEntry(genomeAt(k + j), entry);
              });
              setValues(next);
            }}
          />
        );
      })}
    </div>
  );
}

/* ---------- solve-path slideshow ---------- */
type Code = "morse" | "nato" | "semaphore" | "braille" | "ternary";

const MORSE =
  ".- -... -.-. -.. . ..-. --. .... .. .--- -.- .-.. -- -. --- .--. --.- .-. ... - ..- ...- .-- -..- -.-- --..".split(
    " "
  );
const NATO =
  "ALFA BRAVO CHARLIE DELTA ECHO FOXTROT GOLF HOTEL INDIA JULIETT KILO LIMA MIKE NOVEMBER OSCAR PAPA QUEBEC ROMEO SIERRA TANGO UNIFORM VICTOR WHISKEY XRAY YANKEE ZULU".split(
    " "
  );
const BRAILLE = "⠁⠃⠉⠙⠑⠋⠛⠓⠊⠚⠅⠇⠍⠝⠕⠏⠟⠗⠎⠞⠥⠧⠺⠭⠽⠵";
// A = 001, …, Z = 222
const ternary = (i: number) => [
  ((i + 1) / 9) | 0,
  (((i + 1) / 3) | 0) % 3,
  (i + 1) % 3,
];

const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

/** How the code writes a letter, as text; null where it's drawn instead. */
function glyphText(code: Code, ch: string) {
  const i = idx(ch);
  switch (code) {
    case "morse":
      return MORSE[i].replace(/\./g, "·").replace(/-/g, "−");
    case "nato":
      return NATO[i];
    case "braille":
      return BRAILLE[i];
    case "ternary":
      return ternary(i).join("");
    case "semaphore":
      return null;
  }
}

/* A solved gene under node n: its letter and how the code writes it. NATO
   words are too wide for the chart, so antennae get the bare letter. */
function geneSVG(n: PedNode, code: Code, ch: string, colour: string) {
  if (code === "nato") return labelSVG(n, 1, ch, colour);
  const text = glyphText(code, ch);
  if (text !== null) return labelSVG(n, 1, `${ch} ${text}`, colour);
  // semaphore: the letter, then its flags
  const fs = n.r * 0.85,
    y = n.y + n.r * 2.75;
  return (
    `<g transform="translate(${(-fs * 0.55).toFixed(1)} 0)">${labelSVG(n, 1, ch, colour)}</g>` +
    `<g transform="translate(${(n.x + fs * 0.6).toFixed(1)} ${y.toFixed(1)}) ` +
    `scale(${(fs / 12).toFixed(2)})" fill="${colour}" stroke="${colour}">` +
    `${semaphoreFlagsSVG(ch)}</g>`
  );
}

type SolveCtx = {
  code: Code;
  data: Data;
  hover: number | null;
  setHover: (n: number | null) => void;
};
const SolveContext = createContext<SolveCtx | null>(null);

type TraitProps = {
  name: string;
  /** 1-based genome position this trait's genes sit at */
  position: string;
  code: Code;
  children: ReactNode;
};
/* What a step deduces is read off its prose: each Cross narrows its aliens
   to what the cross allows, and each Alien with a firm `of` to those letters;
   one letter solves it. */
type StepProps = { children: ReactNode };

/* Data only: GeneticSolvePath reads their props and renders the slides. */
export const GeneticTrait = (_: TraitProps) => null;
export const GeneticStep = (_: StepProps) => null;

const elements = <P,>(children: ReactNode) =>
  // eslint-disable-next-line @eslint-react/no-children-to-array -- MDX hands us the slides as children
  Children.toArray(children).filter(isValidElement<P>);

type Mark = "known" | "new" | "tentative" | "impossible";
type AlienProps = {
  n: string;
  /**
   * Omitted, the alien shows the letters still possible for it. Otherwise
   * the letters it's now known to be; a trailing "?" makes that tentative,
   * inside a supposition.
   */
  of?: string;
  /** show how the code writes each letter, for arguments that read it */
  codes?: boolean;
  /** filled in by GeneticSolvePath: the letters to show, and how */
  shown?: { letters: string; mark?: Mark };
};
/** One alien in a Cross: the letters it could be, and those the cross rules out. */
type Column = { n: number; letters: string; out: string; mark?: Mark };
type CrossProps = {
  /** numbers of the left parent, right parent, and child; `c` may name
     several children, which the parents must make all of */
  a: string;
  b: string;
  c: string;
  /** why, where the cross alone doesn't make it plain */
  children?: ReactNode;
  /** filled in by GeneticSolvePath */
  shown?: Column[];
};

const hoverable = (ctx: SolveCtx, n: number) => ({
  tabIndex: 0,
  onMouseEnter: () => ctx.setHover(n),
  onMouseLeave: () => ctx.setHover(null),
  onFocus: () => ctx.setHover(n),
  onBlur: () => ctx.setHover(null),
});

/**
 * An alien's number in the prose, with the letters it could still be.
 * Hovering it, or the alien in the chart, marks the other.
 */
export function Alien({ n, codes, shown }: AlienProps) {
  const ctx = use(SolveContext);
  if (!ctx || !shown) return n;
  return (
    <span
      className={clsObj({
        "genetic-alien": true,
        [shown.mark ?? ""]: !!shown.mark,
        active: ctx.hover === +n,
      })}
      {...hoverable(ctx, +n)}
    >
      {n}
      {[...shown.letters].map((ch) => (
        <Gene key={ch} of={ch} plain={!codes} />
      ))}
    </span>
  );
}

/**
 * a × b = c, each alien a column of the letters it could be, with those no
 * child of the parents' letters allows struck out. GeneticSolvePath applies
 * what's left.
 */
export function Cross({ children, shown }: CrossProps) {
  const ctx = use(SolveContext);
  if (!ctx || !shown) return null;
  const column = ({ n, letters, out, mark }: Column) => (
    <span
      key={n}
      className={clsObj({
        "genetic-alien genetic-column": true,
        [mark ?? ""]: !!mark,
        active: ctx.hover === n,
      })}
      {...hoverable(ctx, n)}
    >
      {n}
      <span className="genetic-column-genes">
        {[...letters].map((ch) => (
          <Fragment key={ch}>
            <b className={out.includes(ch) ? "genetic-out" : undefined}>{ch}</b>
            <span
              className={clsObj({
                [`genetic-glyph genetic-glyph-${ctx.code}`]: true,
                "genetic-out": out.includes(ch),
              })}
            >
              {glyph(ctx, ch)}
            </span>
          </Fragment>
        ))}
      </span>
    </span>
  );
  // spans throughout, as MDX may set this inside a paragraph
  return (
    <span className="genetic-cross">
      <span className="genetic-cross-sum">
        {column(shown[0])}×{column(shown[1])}={shown.slice(2).map(column)}
      </span>
      {children && <span>{children}</span>}
    </span>
  );
}

const isFirm = (of?: string): of is string => !!of && !of.endsWith("?");

/** How the current trait's code writes a letter. */
function glyph(ctx: SolveCtx, ch: string): ReactNode {
  if (ctx.code === "semaphore") return <Semaphore letter={ch} />;
  if (ctx.code === "braille")
    return <BrailleCell bits={BRAILLE[idx(ch)].charCodeAt(0) - 0x2800} />;
  if (ctx.code === "ternary") {
    const d = ternary(idx(ch));
    return (
      <>
        <span
          className="genetic-swatch"
          style={{ background: colourOf(ctx.data, d) }}
        />
        {d.join("")}
      </>
    );
  }
  return glyphText(ctx.code, ch);
}

/** A Braille cell with its empty dots drawn faint, so a lone dot can be placed. */
function BrailleCell({ bits }: { bits: number }) {
  return (
    <svg
      className="genetic-braille"
      viewBox="0 0 6 10"
      role="img"
      aria-label={String.fromCharCode(0x2800 + bits)}
    >
      {[0, 1, 2, 3, 4, 5].map((i) => {
        const on = (bits >> i) & 1;
        return (
          <circle
            key={i}
            cx={i < 3 ? 1.5 : 4.5}
            cy={1.5 + 3.5 * (i % 3)}
            r={on ? 1.2 : 0.6}
            className={on ? undefined : "off"}
          />
        );
      })}
    </svg>
  );
}

/** The Braille cell with just dots `n` (1–3 down the left, 4–6 the right). */
export const Dots = ({ n }: { n: string }) => (
  <BrailleCell bits={[...n].reduce((bits, d) => bits | (1 << (+d - 1)), 0)} />
);

/** Code written out in the prose, styled as the current trait's glyphs are. */
export function Code({ children }: { children: ReactNode }) {
  const ctx = use(SolveContext);
  return (
    <span className={`genetic-glyph genetic-glyph-${ctx?.code ?? ""}`}>
      {children}
    </span>
  );
}

/**
 * A gene letter, followed by how the current trait's code writes it unless
 * `plain`, for arguments about the letters alone.
 */
export function Gene({ of: ch, plain }: { of: string; plain?: boolean }) {
  const ctx = use(SolveContext);
  return (
    <span className="genetic-gene">
      <b>{ch}</b>
      {ctx && !plain && (
        <span className={`genetic-glyph genetic-glyph-${ctx.code}`}>
          {glyph(ctx, ch)}
        </span>
      )}
    </span>
  );
}

/**
 * The labelled pedigree as a slideshow over one trait at a time. Each
 * GeneticTrait holds GeneticSteps; a step's prose sits under the chart, which
 * labels each alien with its gene once solved, and with the letters still
 * possible until then. Aliens the step doesn't mention are dimmed. Alien
 * numbers are as in `genomes` (space-separated).
 *
 * Within a step, a bare Alien or Cross shows what the prose so far allows,
 * so a supposition's tentative letters carry on, through any Cross they feed,
 * until the next firm `of`, which ends it.
 */
export function GeneticSolvePath({
  src,
  genomes,
  children,
}: {
  src: string;
  genomes: string;
  children: ReactNode;
}) {
  const data = useGeneticData(src);
  const [trait, setTrait] = useState(0);
  const [step, setStep] = useState(0);
  const [hover, setHover] = useState<number | null>(null);

  const traits = elements<TraitProps>(children).map((t) => t.props);
  const steps = [
    { children: <p>All possibilities.</p> },
    ...elements<StepProps>(traits[trait].children).map((s) => s.props),
    { children: <p>Solution.</p> },
  ];
  const go = (d: number) =>
    setStep((k) => Math.max(0, Math.min(steps.length - 1, k + d)));

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.target as Element).closest("input, textarea, select")) return;
      if (e.key === "ArrowLeft") go(-1);
      else if (e.key === "ArrowRight") go(1);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  });

  if (!data) return <p>Loading…</p>;

  const { code } = traits[trait];
  const pos = +traits[trait].position - 1;
  const list = genomes.split(/\s+/).filter(Boolean);
  const gene = (n: number) => list[n - 1][pos];
  const masks = data.traits[pos].masks;
  // each step's firm narrowings, as [alien, letters]; filled in below
  const firm: [number, string][][] = [];
  const solvedBy = (k: number) =>
    new Set(
      firm
        .slice(0, k)
        .flat()
        .flatMap(([n, of]) => (of.length === 1 ? [n] : []))
    );

  // Before step k is done, an unsolved alien can be any letter with its look
  // that's not yet taken, less whatever steps 0..k ruled out (k = -1: none).
  const looks = data.traits[pos].values.map((v) => JSON.stringify(v));
  const optionsAt = (k: number) => {
    const solved = solvedBy(k + 1);
    const taken = new Set([...solved].map(gene));
    const narrowed = new Map<number, string>();
    for (const [n, letters] of firm.slice(0, k + 1).flat()) {
      const prev = narrowed.get(n);
      narrowed.set(
        n,
        prev ? [...prev].filter((c) => letters.includes(c)).join("") : letters
      );
    }
    return (n: number) =>
      solved.has(n)
        ? [gene(n)]
        : [...ALPHABET].filter(
            (c) =>
              looks[idx(c)] === looks[idx(gene(n))] &&
              !taken.has(c) &&
              (narrowed.get(n)?.includes(c) ?? true)
          );
  };

  /* Reads step k's prose in order, filling in what each Alien and Cross
     shows, noting what the step firmly deduces in firm[k] and which aliens
     it mentions. */
  const read = (k: number) => {
    const was = optionsAt(k - 1),
      solvedBefore = solvedBy(k);
    const deduced: [number, string][] = [];
    const mentioned = new Set<number>();
    const said = new Map<number, { letters: string; tentative: boolean }>();
    const current = (n: number) =>
      said.get(n)?.letters ??
      was(n)
        .filter((c) => ![...said].some(([m, s]) => m !== n && s.letters === c))
        .join("");
    const settled = (n: number, letters: string) =>
      letters.length === 1 && (solvedBefore.has(n) || said.has(n));
    const quiet = (n: number, letters: string): Mark | undefined =>
      said.get(n)?.tentative
        ? "tentative"
        : settled(n, letters)
          ? "known"
          : undefined;
    const check = (n: number, prev: string, letters: string, firm: boolean) => {
      if (
        import.meta.env.DEV &&
        ([...letters].some((c) => !prev.includes(c)) ||
          (firm && !letters.includes(gene(n))))
      )
        console.warn(
          `genetic solve path: ${n} [${prev}] can't be [${letters}]`
        );
    };

    const alien = ({ n: num, of }: AlienProps): AlienProps["shown"] => {
      const n = +num;
      mentioned.add(n);
      if (isFirm(of))
        for (const [m, s] of said) if (s.tentative) said.delete(m);
      const prev = current(n);
      if (of === undefined) return { letters: prev, mark: quiet(n, prev) };
      const tentative = !isFirm(of);
      const letters = of.replace("?", "");
      check(n, prev, letters, !tentative);
      const restated =
        letters === prev && (letters.length > 1 || settled(n, letters));
      said.set(n, { letters, tentative });
      if (!tentative) deduced.push([n, letters]);
      return {
        letters,
        mark: tentative ? "tentative" : restated ? "known" : "new",
      };
    };

    const cross = ({ a, b, c }: CrossProps): Column[] => {
      const ns = [+a, +b, ...c.split(/\s+/).map(Number)];
      ns.forEach((n) => mentioned.add(n));
      const before = ns.map(current);
      const tentative = ns.some((n) => said.get(n)?.tentative);
      const ok = ns.map(() => new Set<string>());
      // a pair of parents counts only if it makes some letter of every child
      for (const x of before[0])
        for (const y of before[1]) {
          const mask = masks[idx(x) * 26 + idx(y)];
          const kids = before
            .slice(2)
            .map((cs) => [...cs].filter((z) => (mask >> idx(z)) & 1));
          if (kids.some((k) => !k.length)) continue;
          ok[0].add(x);
          ok[1].add(y);
          kids.forEach((k, i) => k.forEach((z) => ok[i + 2].add(z)));
        }
      return ns.map((n, i) => {
        const left = [...before[i]].filter((ch) => ok[i].has(ch)).join("");
        const out = [...before[i]].filter((ch) => !ok[i].has(ch)).join("");
        if (!ok[0].size)
          return { n, letters: before[i], out, mark: "impossible" };
        if (!out) return { n, letters: before[i], out, mark: quiet(n, left) };
        const t = tentative || !!said.get(n)?.tentative;
        check(n, before[i], left, !t);
        said.set(n, { letters: left, tentative: t });
        if (!t) deduced.push([n, left]);
        return { n, letters: before[i], out, mark: t ? "tentative" : "new" };
      });
    };

    const fill = (node: ReactNode): ReactNode =>
      // eslint-disable-next-line @eslint-react/no-children-map -- rewriting MDX we were handed
      Children.map(node, (el) => {
        if (!isValidElement<{ children?: ReactNode }>(el)) return el;
        /* eslint-disable @eslint-react/no-clone-element -- as above */
        if (el.type === Alien) {
          const a = el as ReactElement<AlienProps>;
          return cloneElement(a, { shown: alien(a.props) });
        }
        if (el.type === Cross) {
          const x = el as ReactElement<CrossProps>;
          return cloneElement(
            x,
            { shown: cross(x.props) },
            fill(x.props.children)
          );
        }
        if (el.props.children === undefined) return el;
        return cloneElement(el, undefined, fill(el.props.children));
        /* eslint-enable @eslint-react/no-clone-element */
      });

    const text = fill(steps[k].children);
    firm[k] = deduced;
    return { text, mentioned };
  };
  let shown = read(0);
  for (let k = 1; k <= step; k++) shown = read(k);

  const known = solvedBy(step + 1);
  const solvedBefore = solvedBy(step);
  const fresh = new Set([...known].filter((n) => !solvedBefore.has(n)));
  const was = optionsAt(step - 1),
    now = optionsAt(step);

  const nums = nodeNumbers(data, list);
  const focus = hover
    ? new Set([hover])
    : new Set([...shown.mentioned, ...fresh]);
  const dimmed = (n: number) => focus.size > 0 && !focus.has(n);

  /* Number, then gene. Letters this step rules out stay one more step, struck
     through, so a solve reads [GM] → M; after that a solved gene shows its
     letter as the code writes it. */
  const label = (node: PedNode, i: number) => {
    const n = nums[i];
    if (!n) return labelSVG(node, 0, "?");
    const before = was(n),
      after = now(n);
    const changed = before.length !== after.length;
    const colour = changed || fresh.has(n) ? RED : INK;
    const head = labelSVG(node, 0, `${n}`, colour);
    if (known.has(n) && !changed)
      return head + geneSVG(node, code, gene(n), colour);
    return (
      head +
      labelSVG(
        node,
        1,
        before.join("") +
          (before.join("") !== after.join("") ? `→${after.join("")}` : ""),
        colour,
        before.length > 4 ? 0.8 : 0.9
      )
    );
  };

  // one <g> per node, labels in a layer above every alien so none is covered
  const layer = (html: (node: PedNode, i: number) => string) =>
    data.pedigree.nodes.map((node, i) => (
      <g
        key={i}
        data-n={nums[i]}
        className={dimmed(nums[i]) ? "genetic-dim" : undefined}
        // eslint-disable-next-line @eslint-react/dom-no-dangerously-set-innerhtml -- SVG we generate
        dangerouslySetInnerHTML={{ __html: html(node, i) }}
      />
    ));

  return (
    <SolveContext value={{ code, data, hover, setHover }}>
      <div className="genetic-solve-path">
        <div className="genetic-traits" role="tablist">
          {traits.map((t, i) => (
            <button
              key={t.name}
              role="tab"
              aria-selected={i === trait}
              onClick={() => {
                setTrait(i);
                setStep(0);
              }}
            >
              {t.name}
            </button>
          ))}
        </div>
        <div
          className="genetic-tree"
          onMouseOver={(e) => {
            const g = (e.target as Element).closest("[data-n]");
            setHover(+(g?.getAttribute("data-n") ?? "") || null);
          }}
          onMouseLeave={() => setHover(null)}
        >
          {/* Each alien and label is its own element, so dimming one is a
              class change that can transition. */}
          <svg
            viewBox={data.pedigree.vb.join(" ")}
            preserveAspectRatio="xMidYMid meet"
          >
            {/* eslint-disable-next-line @eslint-react/dom-no-dangerously-set-innerhtml -- SVG we generate */}
            <g dangerouslySetInnerHTML={{ __html: wiresSVG(data) }} />
            {layer(
              (node) =>
                hitbox(node) + alienBody(data, node.ph, node.x, node.y, node.r)
            )}
            {layer(label)}
            {/* eslint-disable-next-line @eslint-react/dom-no-dangerously-set-innerhtml -- SVG we generate */}
            <g dangerouslySetInnerHTML={{ __html: eggsSVG(data) }} />
          </svg>
        </div>
        <div className="genetic-stepper">
          <button aria-label="Previous step" onClick={() => go(-1)}>
            ←
          </button>
          <span className="genetic-step-count">
            {step + 1} / {steps.length}
          </span>
          <button aria-label="Next step" onClick={() => go(1)}>
            →
          </button>
        </div>
        <div className="genetic-step-text" role="status">
          {shown.text}
        </div>
      </div>
    </SolveContext>
  );
}

/* ---------- ui ---------- */
const clean = (s: string) =>
  s
    .toUpperCase()
    .replace(/[^A-Z]/g, "")
    .slice(0, 5);
const valid = (s: string) => s.length === 5;
const randomParent = () =>
  Array.from({ length: 5 }, () => letter((Math.random() * 26) | 0)).join("");

export function GeneticCode({
  puzName,
  src,
}: {
  puzName: string;
  src: string;
}) {
  const data = useGeneticData(src);
  // seeds must never be the puzzle answer, or the page leaks it
  const [pa, setPa] = useState("ENTER");
  const [pb, setPb] = useState("GENES");
  // bumped by Breed so the same pair can be rerolled
  const [roll, setRoll] = useState(0);
  const [zoomed, setZoomed] = useState<Values | null>(null);
  const showOdds = useIsCheckPuzzleToggleOn(puzName);

  // Random, so computed in an effect rather than during render.
  const [child, setChild] = useState<string | null>(null);
  useEffect(() => {
    if (data && valid(pa) && valid(pb)) {
      const v = breed(data, pa, pb);
      setChild(v && alienSVG(data, v, 240));
    }
  }, [data, pa, pb, roll]);

  if (!data) return <p>Loading…</p>;

  const openNode = (target: EventTarget) => {
    const node = (target as Element).closest<SVGGElement>(".genetic-node");
    if (node) setZoomed(data.pedigree.nodes[+node.dataset.i!].ph);
  };

  // deliberately vague: naming the gene that failed would give away part of
  // the puzzle, so the page only says the pairing is impossible
  const error =
    !valid(pa) || !valid(pb)
      ? "Each parent needs exactly five letters, A to Z."
      : child === null
        ? "These two cannot have a child."
        : null;

  return (
    <div className="genetic-code">
      <div className="genetic-controls">
        {(
          [
            ["Left parent", pa, setPa],
            ["Right parent", pb, setPb],
          ] as const
        ).map(([label, value, set]) => (
          <label key={label} className="genetic-field">
            {label}
            <input
              type="text"
              value={value}
              maxLength={5}
              spellCheck={false}
              autoComplete="off"
              aria-invalid={!valid(value)}
              onChange={(e) => set(clean(e.target.value))}
            />
          </label>
        ))}
        <Tooltip text="Breed">
          <button aria-label="Breed" onClick={() => setRoll((r) => r + 1)}>
            <Twemoji>🧬</Twemoji>
          </button>
        </Tooltip>
        <Tooltip text="Random parents">
          <button
            aria-label="Random parents"
            onClick={() => {
              setPa(randomParent());
              setPb(randomParent());
            }}
          >
            <Twemoji>🔀</Twemoji>
          </button>
        </Tooltip>
      </div>

      <div className="genetic-child">
        {error ? (
          <p className="genetic-error" role="status">
            {error}
          </p>
        ) : (
          // eslint-disable-next-line @eslint-react/dom-no-dangerously-set-innerhtml -- SVG we generate
          child && <div dangerouslySetInnerHTML={{ __html: child }} />
        )}
      </div>

      {showOdds && valid(pa) && valid(pb) && (
        <table className="genetic-odds">
          <tbody>
            {[0, 1, 2, 3, 4].map((t) => {
              const odds = childOdds(data, t, idx(pa[t]), idx(pb[t]));
              return (
                <tr key={t}>
                  <th>
                    {pa[t]}×{pb[t]}
                  </th>
                  <td>
                    {odds.length === 0
                      ? "none"
                      : odds
                          .map(
                            ({ gene, chance }) =>
                              `${gene} ${+(chance * 100).toFixed(1)}%`
                          )
                          .join(", ")}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}

      <div
        className="genetic-tree"
        onClick={(e) => openNode(e.target)}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            openNode(e.target);
          }
        }}
        // eslint-disable-next-line @eslint-react/dom-no-dangerously-set-innerhtml -- SVG we generate
        dangerouslySetInnerHTML={{ __html: treeSVG(data) }}
      />

      <Modal
        isOpen={zoomed !== null}
        onClose={() => setZoomed(null)}
        className="genetic-zoom"
        aria-label="Alien"
      >
        <button
          className="genetic-zoom-close"
          aria-label="Close"
          onClick={() => setZoomed(null)}
        >
          ×
        </button>
        {zoomed && (
          <div
            // eslint-disable-next-line @eslint-react/dom-no-dangerously-set-innerhtml -- SVG we generate
            dangerouslySetInnerHTML={{ __html: alienSVG(data, zoomed, 320) }}
          />
        )}
      </Modal>
    </div>
  );
}
