import { useMemo, useState } from "react";
import Twemoji from "react-twemoji";

import { ScopeType } from "sockapi/scope-types";
import { SockAPIScopeState } from "sockapi/scope-state";
import { AdminQueueTaskType } from "sockapi/scope-specs/admin-queue-task-spec";
import {
  useGlobalScopeState,
  useScopeStateArrayResolvable,
} from "stores/ScopeStateStore";
import { Spinner } from "components/Loading";
import { LongDate } from "components/dates";
import Tooltip from "components/Tooltip";
import TeamDisplayName from "components/TeamDisplayName";
import { useHintAdminQueueTaskContext } from "components/AdminQueue/admin-queue-hint";

import "./PastHintResponses.css";

type Hint = SockAPIScopeState<ScopeType.HINT>;

type ResponseGroup = {
  response: string;
  hints: Hint[];
  latestRespondTime: number;
};

const NUM_GROUPS_SHOWN = 5;

const normalize = (s: string) => s.trim().replace(/\s+/g, " ").toLowerCase();

function PastHintRequests(props: { hints: Hint[] }) {
  const { hints } = props;
  const [isOpen, setIsOpen] = useState(false);
  return (
    <details onToggle={(e) => setIsOpen(e.currentTarget.open)}>
      <summary>
        {hints.length === 1 ? "1 request" : `${hints.length} requests`}
      </summary>
      {isOpen
        ? hints.map((hint) => (
            <div
              key={hint.request.timestamp + hint.teamId}
              className="past-hint-request"
            >
              <pre className="hint-text">{hint.request.content}</pre>
              <div className="hint-metadata">
                <TeamDisplayName teamId={hint.teamId} />,{" "}
                <LongDate timestamp={hint.request.timestamp} />
                {(hint.request.isFollowup ?? false) ? " (follow-up)" : ""}
              </div>
            </div>
          ))
        : null}
    </details>
  );
}

/** Subscribes to every hint scope for the puzzle, so mount lazily. */
function PastHintResponses(props: { puzName: string }) {
  const { puzName } = props;
  const hintCtx = useHintAdminQueueTaskContext();
  const [query, setQuery] = useState("");
  const [showAll, setShowAll] = useState(false);
  const adminQueueScopeState = useGlobalScopeState(ScopeType.ADMIN_QUEUE);

  // TODO: in the future, we should get the hint ID from the queue summary? or
  // just make some scope that doesn't require doing sending a bunch of requests
  const taskIdentifiers = useMemo(
    () =>
      adminQueueScopeState === null
        ? null
        : Object.entries(adminQueueScopeState.tasks)
            .filter(
              ([, task]) =>
                task.type === AdminQueueTaskType.HINT &&
                task.puzName === puzName &&
                task.respondTime !== undefined
            )
            .map(([taskId]) => ({ taskId })),
    [adminQueueScopeState, puzName]
  );
  const taskScopeStates = useScopeStateArrayResolvable(
    ScopeType.ADMIN_QUEUE_TASK,
    taskIdentifiers
  );
  const hintIdentifiers = useMemo(
    () =>
      taskScopeStates?.flatMap(({ task }) =>
        task.type === AdminQueueTaskType.HINT ? [{ hintId: task.hintId }] : []
      ) ?? null,
    [taskScopeStates]
  );
  const hints = useScopeStateArrayResolvable(ScopeType.HINT, hintIdentifiers);

  const groups = useMemo(() => {
    if (hints === null) return null;
    const byResponse = new Map<string, ResponseGroup>();
    for (const hint of hints) {
      const { response } = hint;
      if (!response?.content) continue;
      const key = normalize(response.content);
      const group = byResponse.get(key) ?? {
        response: response.content,
        hints: [],
        latestRespondTime: 0,
      };
      group.hints.push(hint);
      if (response.timestamp > group.latestRespondTime) {
        group.response = response.content;
        group.latestRespondTime = response.timestamp;
      }
      byResponse.set(key, group);
    }
    const result = [...byResponse.values()];
    for (const group of result)
      group.hints.sort((h1, h2) => h2.request.timestamp - h1.request.timestamp);
    return result.sort(
      (g1, g2) =>
        g2.hints.length - g1.hints.length ||
        g2.latestRespondTime - g1.latestRespondTime
    );
  }, [hints]);

  if (groups === null) return <Spinner inline />;
  if (groups.length === 0) return <div>No hints yet.</div>;

  const queryWords = normalize(query).split(" ").filter(Boolean);
  const filteredGroups = groups.filter((group) => {
    const haystack = normalize(
      [group.response, ...group.hints.map((hint) => hint.request.content)].join(
        " "
      )
    );
    return queryWords.every((term) => haystack.includes(term));
  });
  const shownGroups = showAll
    ? filteredGroups
    : filteredGroups.slice(0, NUM_GROUPS_SHOWN);

  return (
    <div className="past-hint-responses">
      <input
        type="text"
        placeholder="Filter requests and responses"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />
      <div className="past-hint-responses-list">
        {shownGroups.length === 0 && (
          <div className="past-hint-response">No results.</div>
        )}
        {shownGroups.map((group) => (
          <div key={normalize(group.response)} className="past-hint-response">
            <div className="hint-content-row">
              <div className="past-hint-response-count">
                ×{group.hints.length}
              </div>
              <pre className="hint-text">{group.response}</pre>
              {hintCtx && (
                <Tooltip
                  text={
                    <>
                      Copy this response to your hint response input.{" "}
                      <b>This will wipe your existing response.</b>
                    </>
                  }
                  className="hint-text-button"
                >
                  <button
                    onClick={() => hintCtx.setAnswerResponse(group.response)}
                  >
                    <Twemoji>📋</Twemoji>
                  </button>
                </Tooltip>
              )}
            </div>
            <PastHintRequests hints={group.hints} />
          </div>
        ))}
      </div>
      {filteredGroups.length > NUM_GROUPS_SHOWN ? (
        <button onClick={() => setShowAll(!showAll)}>
          {showAll
            ? `Show top ${NUM_GROUPS_SHOWN}`
            : `Show all ${filteredGroups.length}`}
        </button>
      ) : null}
    </div>
  );
}

export default PastHintResponses;
