import { SVGProps, PropsWithChildren } from "react";
import Tooltip from "components/Tooltip";

export function Alternates(
  props: PropsWithChildren<{
    wiki?: string;
    scry?: string;
    scries?: string[];
  }> &
    (
      | { shape: "none"; text: string }
      | ({ shape: "rect" } & SVGProps<SVGRectElement>)
      | ({ shape: "circle" } & SVGProps<SVGCircleElement>)
    )
) {
  const { wiki, scry, scries, children, shape } = props;
  const url = wiki
    ? `https://mtg.wiki/page/${wiki.replace(/ /g, "_").replace(/'/g, "%27")}`
    : scry
      ? `https://scryfall.com/search?q=${encodeURIComponent(scry)}`
      : null;
  const embed = (
    <Tooltip
      text={
        <>
          {wiki && (
            <div style={{ textAlign: "center" }}>
              {wiki}{" "}
              <img src="https://mtg.wiki/favicon.ico" className="emoji" />
            </div>
          )}
          {scry && (
            <img
              src={`https://api.scryfall.com/cards/named?fuzzy=${encodeURIComponent(scry)}&format=image&version=border_crop`}
              style={{ width: "15em" }}
              alt={scry}
            />
          )}
          {scries && (
            <div style={{ width: "15em", display: "flex", flexWrap: "wrap" }}>
              {scries.map((scry) => (
                <img
                  key={scry}
                  src={`https://api.scryfall.com/cards/named?fuzzy=${encodeURIComponent(scry)}&format=image&version=border_crop`}
                  style={{ width: "50%" }}
                  alt={scry}
                />
              ))}
            </div>
          )}
        </>
      }
      style={shape === "none" ? { display: "inline" } : { height: "100%" }}
    >
      {url && (
        <a
          href={url}
          target="_blank"
          rel="noreferrer"
          style={shape === "none" ? {} : { display: "block", height: "100%" }}
        >
          {shape === "none" ? props.text : null}
        </a>
      )}
    </Tooltip>
  );

  switch (shape) {
    case "none":
      return embed;
    case "rect": {
      const { x, y, width, height } = props;
      return (
        <>
          <rect {...props} />
          {children}
          <foreignObject
            x={x}
            y={y}
            width={width}
            height={height}
            style={{ zIndex: 1 }}
          >
            {embed}
          </foreignObject>
        </>
      );
    }
    case "circle": {
      const { cx = 0, cy = 0, r = 0 } = props;
      return (
        <>
          <circle {...props} />
          {children}
          <foreignObject
            x={+cx - +r}
            y={+cy - +r}
            width={2 * +r}
            height={2 * +r}
            style={{ zIndex: 1 }}
          >
            {embed}
          </foreignObject>
        </>
      );
    }
  }
}
