import { ScopeType } from "sockapi/scope-types";
import { SubmitImageSlot } from "sockapi/direct-backend";
import {
  VOWELS_CONFIG,
  VowelsStatus,
  VowelsStatusType,
  isTeamVowelsEditable,
} from "sockapi/scope-specs/team-vowels-spec";
import { useSockClient } from "stores/ServerInteractionStore";
import { useScopeStateResolvable } from "stores/ScopeStateStore";
import { useUILock } from "client-util/useUILock";
import { Spinner } from "components/Loading";
import {
  FileSubmission,
  FancyBox,
} from "components/PuzzleContent/puzzle-components";
import settings from "settings";

export const makeSubmittedFileUrl = (url: string): string =>
  url.startsWith("/") ? `${settings.djangoBaseUrl}${url.slice(1)}` : url;

export function VowelsStatusDisplay(props: { status?: VowelsStatus }) {
  const { status } = props;
  if (status === undefined) return null;
  switch (status.type) {
    case VowelsStatusType.PENDING:
      return <p>Thank you for your submission. We will review it shortly.</p>;
    case VowelsStatusType.ACCEPTED:
      return (
        <>
          <p>
            <b>Your submission was accepted!</b>
          </p>
          {status.comment === undefined ? null : <p>{status.comment}</p>}
        </>
      );
    case VowelsStatusType.REJECTED:
      return (
        <div className="note-box">
          <p>
            <b>Your submission was rejected with the following response:</b>
          </p>
          <p>{status.reason}</p>
          <p>
            <b>Please make the necessary corrections and try again.</b>
          </p>
        </div>
      );
  }
}

export function VowelsSubmission(props: { teamId: string }) {
  const { teamId } = props;
  const sockClient = useSockClient();
  const vowelsState = useScopeStateResolvable(ScopeType.TEAM_VOWELS, {
    teamId,
  });
  const submitLock = useUILock();

  if (vowelsState === null) return <Spinner inline />;
  const { audioUrl, status } = vowelsState;
  const isLocked = !isTeamVowelsEditable(vowelsState);
  const scope = { type: ScopeType.TEAM_VOWELS, teamId } as const;

  return (
    <FancyBox>
      <h4 style={{ marginTop: 0 }}>
        Upload a recording (MP3, WAV, M4A, or OGG; max 10MB)
      </h4>
      <FileSubmission
        isLocked={isLocked}
        slot={SubmitImageSlot.VOWELS}
        supportedExtensions={VOWELS_CONFIG.supportedExtensions}
        maxFileSize={VOWELS_CONFIG.maxFileSize}
        onSubmitSuccess={async () => {
          await sockClient.sendScopeStepAndWaitAsync(scope, {
            downloadAudioUrl: true,
          });
        }}
      />
      {audioUrl === undefined ? null : (
        <audio controls src={makeSubmittedFileUrl(audioUrl)} />
      )}
      {isLocked ? null : (
        <div>
          <button
            disabled={submitLock.isHeld || audioUrl === undefined}
            onClick={() => {
              submitLock.acquireAndRun(async () => {
                await sockClient.sendScopeStepAndWaitAsync(scope, {
                  submit: true,
                });
              });
            }}
          >
            Submit
          </button>
        </div>
      )}
      <VowelsStatusDisplay status={status} />
    </FancyBox>
  );
}
