import twemoji from "@twemoji/api";
import { DialogueTag, matchDialogueTag } from "util/dialogue-tags";

// Parses dialogue (**bold**, *italic* or _italic_, emoji, and the pacing tags
// in util/dialogue-tags) into segments and the schedule the typewriter reveals
// them on. A segment is either a run of same-styled text or a
// single emoji, and maps 1:1 to a rendered node (see DialogueBox).
//
// Emoji become Twemoji <img> segments we emit as normal React elements — NOT via
// react-twemoji, which mutates the DOM after render. Against the typewriter's
// per-frame rewrites that makes React reconcile nodes it no longer owns and
// crash; owning the nodes ourselves also keeps revealed emoji flicker-free.

export type DialogueSegment =
  | {
      kind: "text";
      bold: boolean;
      italic: boolean;
      text: string;
    }
  | { kind: "emoji"; emoji: string; src: string };

export type ParsedDialogue = {
  segments: DialogueSegment[];
  /** When each revealable character appears, in ms from the start, ascending. */
  schedule: number[];
};

type MarkupRun = {
  kind: "run";
  text: string;
  bold: boolean;
  italic: boolean;
};

/** Split dialogue into styled text runs (bold/italic) and pacing tags. */
function parseInlineMarkup(input: string): (MarkupRun | DialogueTag)[] {
  const runs: (MarkupRun | DialogueTag)[] = [];
  let bold = false;
  let italic = false;
  let buffer = "";

  const flush = () => {
    if (buffer.length > 0) {
      runs.push({ kind: "run", text: buffer, bold, italic });
      buffer = "";
    }
  };

  for (let i = 0; i < input.length; i++) {
    const tag = matchDialogueTag(input, i);
    if (tag !== null) {
      flush();
      runs.push(tag.tag);
      i += tag.length - 1;
      continue;
    }
    if (input[i] === "$" && input[i + 1] === "$") {
      buffer += getWordle();
      i++;
      continue;
    }
    if (input[i] === "*" && input[i + 1] === "*") {
      flush();
      bold = !bold;
      i++; // consume the second '*'
      continue;
    }
    if (input[i] === "*" || input[i] === "_") {
      flush();
      italic = !italic;
      continue;
    }
    buffer += input[i];
  }
  flush();
  return runs;
}

const ZWJ = "\u200d";
const VARIATION_SELECTOR = /\ufe0f/g;

// Mirror @twemoji/api's default asset URL (jsDelivr, 72x72 png) and its
// icon-id derivation, so these images match every other emoji on the site.
function emojiSrc(emoji: string): string {
  const iconId = twemoji.convert.toCodePoint(
    emoji.includes(ZWJ) ? emoji : emoji.replace(VARIATION_SELECTOR, "")
  );
  return `${twemoji.base}${twemoji.size}/${iconId}${twemoji.ext}`;
}

/** How long an ordinary character takes to type. */
const BEAT_MS = 1000 / 45;

/** Extra beats the typewriter waits after revealing these characters. */
const PAUSE_BEATS_AFTER: { [char: string]: number } = {
  "…": 10,
  "—": 6,
  ".": 3,
  "!": 3,
  "?": 3,
};

type Pace = { from: number; to: number; length: number };

/** Split dialogue into text-run + emoji segments (each renders as one node). */
export function parseDialogue(text: string): ParsedDialogue {
  const segments: DialogueSegment[] = [];
  // Every revealable character, with the pacing in effect when it appears.
  const chars: { char: string; pace: Pace | null; pauseMs: number }[] = [];
  let pace: Pace | null = null;
  let pauseMs = 0;
  const pushSegment = (seg: DialogueSegment) => {
    segments.push(seg);
    for (const char of seg.kind === "emoji" ? [seg.emoji] : [...seg.text]) {
      chars.push({ char, pace, pauseMs });
      pauseMs = 0;
      if (pace !== null) pace.length++;
    }
  };

  for (const token of parseInlineMarkup(text)) {
    if (token.kind === "pace") {
      pace = { from: token.from, to: token.to, length: 0 };
      continue;
    }
    if (token.kind === "endPace") {
      pace = null;
      continue;
    }
    if (token.kind === "pause") {
      pauseMs += token.ms;
      continue;
    }
    const { text: runText, bold, italic } = token;
    let lastIndex = 0;
    const pushText = (chunk: string) => {
      if (chunk.length > 0)
        pushSegment({ kind: "text", bold, italic, text: chunk });
    };
    // twemoji.replace walks the run with Twemoji's emoji regex; we use it purely
    // to locate emoji (returning the match unchanged).
    twemoji.replace(runText, (match: string, ...args: unknown[]): string => {
      const offset = args[args.length - 2] as number;
      pushText(runText.slice(lastIndex, offset));
      pushSegment({ kind: "emoji", emoji: match, src: emojiSrc(match) });
      lastIndex = offset + match.length;
      return match;
    });
    pushText(runText.slice(lastIndex));
  }

  // Each character takes one beat (divided by its pace, a speed), plus
  // PAUSE_BEATS_AFTER (also paced) once it's out; {pause} holds come before
  // the character.
  const schedule: number[] = [];
  const paceIndex = new Map<Pace, number>();
  let ms = 0;
  for (const { char, pace, pauseMs } of chars) {
    let multiplier = 1;
    if (pace !== null) {
      const i = paceIndex.get(pace) ?? 0;
      paceIndex.set(pace, i + 1);
      const t = pace.length > 1 ? i / (pace.length - 1) : 0;
      multiplier = 1 / (pace.from + (pace.to - pace.from) * t);
    }
    ms += pauseMs + BEAT_MS * multiplier;
    schedule.push(ms);
    ms += BEAT_MS * multiplier * (PAUSE_BEATS_AFTER[char] ?? 0);
  }
  return { segments, schedule };
}

// Length in revealable characters. Slicing is code-point-aware so a truncated
// text run never splits a surrogate pair; emoji count as one and are atomic.
const segmentLength = (seg: DialogueSegment): number =>
  seg.kind === "emoji" ? 1 : [...seg.text].length;

/** The first `count` characters as segments, with the last text run truncated. */
export function sliceDialogue(
  segments: DialogueSegment[],
  count: number
): DialogueSegment[] {
  const out: DialogueSegment[] = [];
  let remaining = count;
  for (const seg of segments) {
    if (remaining <= 0) break;
    const len = segmentLength(seg);
    if (len <= remaining) {
      out.push(seg);
      remaining -= len;
    } else {
      // Only a text run can be partially revealed (emoji are atomic and len 1).
      if (seg.kind === "text")
        out.push({ ...seg, text: [...seg.text].slice(0, remaining).join("") });
      remaining = 0;
    }
  }
  return out;
}

