import { PropsWithChildren } from "react";
import Tooltip from "components/Tooltip";

const VERSION = "v0.111.0";

/** Slay the Spire II card (or relic) name with a hover render from Spire Codex. */
export function SpireCard(
  props: PropsWithChildren<{
    name: string;
    /** Override the slug derived from `name`, e.g. "strike_ironclad". */
    id?: string;
    relic?: boolean;
  }>
) {
  const { name, relic = false, children } = props;
  const id =
    props.id ??
    name
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "_")
      .replace(/^_|_$/g, "");
  const kind = relic ? "relics" : "cards";
  return (
    <Tooltip
      text={
        <img
          src={`https://cdn.spire-codex.com/game/${VERSION}/${kind}/${id}.webp`}
          style={{ width: relic ? "5em" : "12em", display: "block" }}
          alt={name}
        />
      }
      directRef={(refProps) => (
        <a
          {...refProps}
          href={`https://spire-codex.com/${kind}/${id}`}
          target="_blank"
          rel="noreferrer"
        >
          {children ?? name}
        </a>
      )}
    />
  );
}
