import { PropsWithChildren, useEffect } from "react";
import Twemoji from "react-twemoji";
import { PuzzleType, RoundData } from "sockapi/puzzle-data";
import { TeamPuzzleSockAPIScopeState } from "sockapi/scope-specs/team-spec";
import { Emoji, PuzzleIcon, CharacterIcon } from "components/Icon";
import { PuzzleLink } from "components/Link";
import { LargeSpinner } from "components/Loading";
import Tooltip from "components/Tooltip";
import { useRouteMatch } from "components/urls";
import { CafePage, CharacterButton } from "pages/WorldBase";
import {
  useCompletedStoryBeats,
  useViewTimes,
} from "stores/BrowserWidePersistentState";
import { useSlug, useNavStore } from "stores/NavStore";
import {
  isPuzzleSolved,
  roundMatchesSlug,
  roundUrlSlug,
  useTeamScopeState,
  useAccessibleRounds,
} from "stores/ScopeStateStore";
import { useSockClient } from "stores/ServerInteractionStore";
import { addFlushSockAPIMessagesEffect, clsObj } from "client-util/util";
import { toastr } from "Globals";
import "./RoundPage.css";

export function RoundPuzzles({
  puzzles,
  children,
}: PropsWithChildren<{ puzzles: TeamPuzzleSockAPIScopeState[] }>) {
  const rounds = useAccessibleRounds();
  const completedStoryBeats = useCompletedStoryBeats();
  const viewTimes = useViewTimes();

  if (rounds === null) return <LargeSpinner inline />;

  const getIcon = (puzData: TeamPuzzleSockAPIScopeState) => {
    const puzRounds = [...(puzData.roundIds ?? [])]
      .sort()
      .flatMap((roundId) => rounds[roundId] ?? []);
    if (puzData.answer)
      return <div className="solved-title-answer">{puzData.answer}</div>;
    if (puzData.type === PuzzleType.PUZZLE && puzRounds.length > 1)
      return (
        <div className="round-friends">
          {puzRounds.map((round) => (
            <Tooltip key={round.roundId} text={round.displayName}>
              <CharacterIcon type="icon" characterId={round.roundId} />
            </Tooltip>
          ))}
        </div>
      );
    if (isPuzzleSolved(puzData, completedStoryBeats))
      return <Twemoji>{Emoji.PUZZLE_SOLVED}</Twemoji>;
    if (!viewTimes[puzData.puzName])
      return <Twemoji>{Emoji.PUZZLE_UNSEEN}</Twemoji>;
    return null;
  };

  return (
    <div className="round-puzzles">
      {puzzles.map((puzData) => (
        <div
          key={puzData.puzName}
          className={clsObj({
            "round-puzzle": true,
            "has-answer": !!puzData.answer,
          })}
        >
          <PuzzleIcon puzData={puzData} />
          <div className="round-puzzle-body">
            <PuzzleLink puzName={puzData.puzName} />
            {getIcon(puzData)}
          </div>
        </div>
      ))}
      {children}
    </div>
  );
}

const ROUND_ORDERS = {
  0: [1, 2, 3],
  1: [0, 3, 2],
  2: [3, 0, 1],
  3: [2, 1, 0],
} as Record<number, number[]>;

function RoundContent({ roundId }: { roundId: string }) {
  const rounds = useAccessibleRounds();
  const teamScopeState = useTeamScopeState();

  if (rounds === null || teamScopeState === null)
    return <LargeSpinner inline />;

  const puzzles: TeamPuzzleSockAPIScopeState[] = [];
  const soloScenes: TeamPuzzleSockAPIScopeState[] = [];
  const shared: Record<string, TeamPuzzleSockAPIScopeState[]> = {};
  Object.values(teamScopeState.puzzles)
    .sort((puzData1, puzData2) => puzData2.unlockTime - puzData1.unlockTime)
    .forEach((puzData) => {
      const { roundIds = [] } = puzData;
      if (!roundIds.includes(roundId)) return;
      const others = roundIds.filter((otherId) => otherId !== roundId);
      if (others.length === 0) {
        return puzData.type === PuzzleType.PUZZLE
          ? puzzles.push(puzData)
          : soloScenes.push(puzData);
      }
      for (const otherId of others) (shared[otherId] ??= []).push(puzData);
    });

  const isMeta = (puzData: TeamPuzzleSockAPIScopeState) =>
    puzData.type === PuzzleType.PUZZLE ? 0 : 1;
  const column = (otherId: string) =>
    [...(shared[otherId] ?? [])].sort(
      (puzData1, puzData2) => isMeta(puzData1) - isMeta(puzData2)
    );

  const otherRounds = ROUND_ORDERS[rounds[roundId].order]
    .map((order) =>
      Object.values(rounds).find((round) => round.order === order)
    )
    .filter((round): round is RoundData => !!round);

  return (
    <>
      <div className="round-story">
        {otherRounds.map((round) => (
          <div key={round.roundId}>
            <div className="round-heading">
              <CharacterButton
                round={round}
                label={`Go to ${round.displayName}`}
              >
                {round.displayName}
              </CharacterButton>
            </div>
            <RoundPuzzles puzzles={column(round.roundId)} />
          </div>
        ))}
      </div>
      <hr />
      {soloScenes.length > 0 && (
        <div className="round-solo-scenes">
          <RoundPuzzles puzzles={soloScenes} />
        </div>
      )}
      <div className="round-puzzle-list">
        <RoundPuzzles puzzles={puzzles} />
      </div>
    </>
  );
}

function RoundPage() {
  const rounds = useAccessibleRounds();
  const slug = useSlug();
  const inRound = useRouteMatch("round") !== null;
  const sockClient = useSockClient();
  const setRedirectRoute = useNavStore((state) => state.setRedirectRoute);
  const round =
    rounds === null || slug === null
      ? null
      : (Object.values(rounds).find((round) => roundMatchesSlug(round, slug)) ??
        null);

  const needRedirectForInvalidRound = (() => {
    // Handle effects going out of sync with React Router.
    if (!inRound) return null;
    if (rounds === null) return null;
    return round === null;
  })();
  useEffect(() => {
    if (!(needRedirectForInvalidRound ?? false)) return;
    return addFlushSockAPIMessagesEffect(sockClient, () => {
      toastr.error("Invalid round name.");
      setRedirectRoute({ route: "puzzles", replace: true });
    });
  }, [needRedirectForInvalidRound, setRedirectRoute, sockClient]);

  const completedStoryBeats = useCompletedStoryBeats();
  const canonicalSlug =
    inRound && round !== null ? roundUrlSlug(round, completedStoryBeats) : null;
  useEffect(() => {
    if (canonicalSlug === null || canonicalSlug === slug) return;
    setRedirectRoute({
      route: "round",
      params: { slug: canonicalSlug },
      replace: true,
    });
  }, [canonicalSlug, slug, setRedirectRoute]);

  if (needRedirectForInvalidRound === null || round === null)
    return <LargeSpinner inline />;

  return (
    <CafePage className="round-page" heading={round.displayName}>
      <title>{round.displayName}</title>
      <RoundContent roundId={round.roundId} />
    </CafePage>
  );
}

export default RoundPage;
