export default function WorldSearch(
  props: PropsWithChildren<{
    points: [keyof typeof MARKERS, number, number][];
    lines: [number, number, number, number][];
    strips: [string, string, number, number, number, number][];
    staticPuzDir: string;
  }>
) {
  const [index, setIndex] = useState<number>(-1);
  const [image, setImage] = useState<string | undefined>(undefined);
  const [camera, setCamera] = useState<Partial<MapCameraProps>>({ zoom: 2 });

  const { points, lines, strips, staticPuzDir, children } = props;
  const current = strips[index];
  useEffect(() => {
    if (!current) return;
    const [id, style, zoom, lat, lng, heading] = current;
    setImage(`${staticPuzDir}/default/${id}.png`);
    setCamera({ center: { lat, lng }, zoom, heading });
  }, [staticPuzDir, current]);

  return (
    <APIProvider apiKey="AIzaSyDW-EmcC_dFhGYK7xJSQxnzHl3JIAS6hoM">
      <Map
        renderingType="VECTOR"
        style={{ width: "100%", aspectRatio: "2 / 1" }}
        {...camera}
        onCameraChanged={(evt) => setCamera(evt.detail)}
        headingInteractionEnabled
        streetViewControl={false}
        reuseMaps
      >
        {points.flatMap(([icon, lat, lng], i) => [
          <Marker
            key={`bg${i}`}
            position={{ lat, lng }}
            icon={{
              path: MARKERS[icon],
              anchor: { x: 8, y: 8 },
              strokeColor: "white",
              strokeWeight: 4,
            }}
          />,
          <Marker
            key={`fg${i}`}
            position={{ lat, lng }}
            icon={{
              path: MARKERS[icon],
              anchor: { x: 8, y: 8 },
              fillColor: "red",
              fillOpacity: 1,
              strokeOpacity: 0,
            }}
          />,
        ])}
        {lines.map(([lat1, lng1, lat2, lng2], i) => (
          <Polyline
            key={i}
            path={[
              { lat: lat1, lng: lng1 },
              { lat: lat2, lng: lng2 },
            ]}
            strokeWeight={2}
          />
        ))}
      </Map>
      <div
        style={{
          display: "flex",
          gap: "0.5em",
          height: "8em",
          alignItems: "center",
        }}
      >
        <button disabled={index <= 0} onClick={() => setIndex(index - 1)}>
          <Twemoji>⬆️</Twemoji>
        </button>
        <button
          disabled={index >= strips.length - 1}
          onClick={() => setIndex(index + 1)}
        >
          <Twemoji>⬇️</Twemoji>
        </button>
        <img src={image} style={{ width: 0, flexGrow: 1 }} />
      </div>
      <p
        onClick={(evt) => {
          const question = (evt.target as HTMLElement).dataset.question;
          if (!question) return;
          evt.preventDefault();
          const [lat, lng, zoom] = JSON.parse(question);
          setCamera({ center: { lat, lng }, zoom, heading: 0 });
        }}
      >
        {children}
      </p>
    </APIProvider>
  );
}
