import { useRef, useEffect } from "react";
import { BGM_VARIANTS } from "sockapi/scope-specs/keyframe-spec";
import { useSeparatelyPersistedState } from "stores/UserPreferencesStore";

type PlayerState = {
  ctx: AudioContext;
  tick: number;
  volume: number;
  tracks: {
    variant: (typeof BGM_VARIANTS)[number];
    source: AudioBufferSourceNode;
    gain: GainNode;
    currentVolume: number;
    desiredVolume: number;
  }[];
};

function crossFade(
  state: PlayerState,
  desiredVariant: null | (typeof BGM_VARIANTS)[number]
) {
  // hmm... I was going to sync timestamps here just to make sure we're always
  // fading to the same spot in the other track, but it looks like these nodes
  // are designed not to be seeked (sought?). I guess we can just hope that the
  // tracks are close enough in length to not desync after a reasonable number
  // of loops... and it's not a disaster if they do anyway (cope?)
  for (const track of state.tracks)
    track.desiredVolume = track.variant === desiredVariant ? 100 : 0;
  cancelAnimationFrame(state.tick);
  const volumeTick = () => {
    let changed = false;
    for (const track of state.tracks) {
      if (track.currentVolume !== track.desiredVolume) {
        changed = true;
        track.currentVolume +=
          track.currentVolume > track.desiredVolume ? -1 : 1;
      }
      track.gain.gain.value =
        (track.currentVolume / 100) * (state.volume / 100);
    }
    if (changed) state.tick = requestAnimationFrame(volumeTick);
  };
  volumeTick();
}

// name is expected not to change over the lifetime of the player.
// CutsceneLayer sets key=name to ensure this.
// there's also a bug where when going back/forward sometimes the scene starts
// at like half volume. it's not clear why this is happening.
export default function BgmPlayer({
  name,
  variant,
  keyframeId,
}: {
  name: string;
  variant: null | (typeof BGM_VARIANTS)[number];
  keyframeId: string;
}) {
  const stateRef = useRef<PlayerState | null>(null);

  useEffect(() => {
    if (stateRef.current === null) {
      const ctx = new AudioContext();
      const tracks = BGM_VARIANTS.map((variant) => {
        const source = new AudioBufferSourceNode(ctx, { loop: true });
        const gain = new GainNode(ctx, { gain: 0 });
        source.connect(gain);
        gain.connect(ctx.destination);
        const track = {
          variant,
          source,
          gain,
          currentVolume: 0,
          desiredVolume: 0,
        };
        const promise = (async () => {
          const url = `/static/bgm/${name}-${variant}.ogg`;
          const data = await (await fetch(url)).arrayBuffer();
          return ctx.decodeAudioData(data);
        })();
        return { track, promise };
      });
      Promise.all(
        tracks.map(async ({ track, promise }) => ({
          track,
          buffer: await promise,
        }))
      ).then(
        (tracks) => {
          for (const { track, buffer } of tracks) {
            track.source.buffer = buffer;
            track.source.start();
          }
        },
        (err) => console.error(err)
      );
      stateRef.current = {
        ctx,
        tick: 0,
        volume: 0,
        tracks: tracks.map(({ track }) => track),
      };
    }
    return () => {
      const state = stateRef.current;
      if (state === null) return;
      // fade out when unmounted, but kill in 3s at the latest no matter what
      crossFade(state, null);
      /* eslint-disable @eslint-react/web-api-no-leaked-timeout */
      setTimeout(() => state.ctx.close(), 3000);
      stateRef.current = null;
    };
  }, [name]);

  const volume = useSeparatelyPersistedState((state) => state.bgmVolume);
  const isMuted = useSeparatelyPersistedState((state) => state.bgmIsMuted);

  useEffect(() => {
    const state = stateRef.current;
    if (state === null) return;
    state.volume = isMuted ? 0 : volume;
    crossFade(state, variant);
  }, [volume, isMuted, variant]);

  useEffect(() => {
    const state = stateRef.current;
    if (state === null) return;
    // the audio may have been prevented from starting until the user
    // interacted with the page. try again when we advance keyframes.
    if (state.ctx.state === "suspended") void state.ctx.resume();
  }, [keyframeId]);

  return null;
}
