function StateUploader() {
  const sockClient = useSockClient();
  const [stateToUpload, setStateToUpload] =
    useState<SavedHuntBackendState | null>(null);

  if (!settings.localMode)
    return (
      <div className="note-box">
        State loader is only supported in local mode.
      </div>
    );

  return (
    <>
      <button
        onClick={() => {
          if (stateToUpload === null) return;
          sockClient.resetServer(stateToUpload);
          setStateToUpload(null);
        }}
        disabled={stateToUpload === null}
      >
        Load progress
      </button>{" "}
      <input
        type="file"
        onChange={(e) => {
          if (e.target.files === null) return;
          const [file] = e.target.files;
          if (file === undefined) return;
          if (file.type !== "application/json") {
            toastr.error(
              "Saved state should be a JSON file.",
              "Unable to load state"
            );
            return;
          }

          const reader = new FileReader();
          reader.onload = (e) => {
            const jsonData = e.target?.result;
            if (typeof jsonData !== "string")
              throw new Error("expect file data to be a string");
            try {
              setStateToUpload(JSON.parse(jsonData));
            } catch (err) {
              console.error(err);
              toastr.error("Failed to parse file.");
            }
          };
          reader.onerror = (err) => {
            console.error(err);
            toastr.error("Failed to read file.");
          };
          reader.readAsText(file);
        }}
      />
    </>
  );
}

function StateDownloader() {
  const sockClient = useSockClient();
  const teamId = useTeamId();
  const downloadLock = useUILock();

  if (teamId === null) return <Spinner inline />;

  return (
    <button
      onClick={() => {
        downloadLock.acquireAndRun(async (getIsCanceled) => {
          await downloadTeamStateAsync(sockClient, teamId, getIsCanceled);
        });
      }}
      disabled={downloadLock.isHeld}
    >
      Save progress
    </button>
  );
}

function UnlockPuzzles({ filter }: { filter: PuzzleFilter }) {
  const sockClient = useSockClient();
  const teamScopeState = useTeamScopeState();
  const huntAdminScopeState = useGlobalScopeState(ScopeType.HUNT_ADMIN);
  const puzzleDisplayNames = usePuzzleDisplayNames();
  const teamId = useTeamId();

  if (
    teamScopeState === null ||
    huntAdminScopeState === null ||
    puzzleDisplayNames === null ||
    teamId === null
  )
    return <LargeSpinner />;

  const { puzzles } = teamScopeState;
  const { puzzles: allPuzzles } = huntAdminScopeState;
  const filteredPuzzles = Object.values(allPuzzles)
    .sort((a, b) => a.order - b.order)
    .filter((puzData) =>
      checkPuzzleFilter(
        filter,
        puzData,
        puzzleDisplayNames[puzData.puzName] ?? ""
      )
    );
  const solvablePuzzles = filteredPuzzles;

  const resetAll = () => {
    sockClient.resetServer();
    updateBrowserWidePersistentStateNonReactive({ resetProgress: true });
  };

  const makePuzConstValDict = (list: PuzzleData[], val: boolean) =>
    Object.fromEntries(list.map(({ puzName }) => [puzName, val]));

  const sendModifyTeamUpdate = (upd: AdminModifyTeamParams) =>
    sockClient.sendAdminScopeStep({
      teams: {
        [teamId]: upd,
      },
    });

  const unlockAllPuzzles = () =>
    sendModifyTeamUpdate({
      overrideUnlocked: makePuzConstValDict(filteredPuzzles, true),
    });

  const lockAllPuzzles = () =>
    sendModifyTeamUpdate({
      overrideUnlocked: makePuzConstValDict(filteredPuzzles, false),
    });

  const solveAllPuzzles = () =>
    sendModifyTeamUpdate({
      overrideSolved: makePuzConstValDict(solvablePuzzles, true),
    });

  const unsolveAllPuzzles = () =>
    sendModifyTeamUpdate({
      overrideSolved: makePuzConstValDict(solvablePuzzles, false),
    });

  /*
  const getAllCannedHints = () =>
    sendModifyTeamUpdate({
      overridePuzzleNumTotalCannedHints: puzzleNumTotalCannedHints,
    });
  */

  const unlockCount = Object.values(filteredPuzzles).filter(
    ({ puzName }) => puzzles[puzName]?.unlockTime
  ).length;
  const solveCount = Object.values(filteredPuzzles).filter(
    ({ puzName }) => puzzles[puzName]?.solveTime
  ).length;

  return (
    <>
      <div className="unlock-toolbar">
        <div className="button-squish-zone">
          <div>
            <button onClick={resetAll}>
              <Twemoji tag="span">🔄️ Reset all progress</Twemoji>
            </button>
          </div>
          <Tooltip text="Lock all">
            <button onClick={lockAllPuzzles}>
              <Twemoji tag="span">🔒</Twemoji>
            </button>
          </Tooltip>
          <Tooltip text="Unlock all">
            <button onClick={unlockAllPuzzles}>
              <Twemoji tag="span">🔑</Twemoji>
            </button>
          </Tooltip>
          <Tooltip text="Unsolve all">
            <button onClick={unsolveAllPuzzles}>
              <Twemoji tag="span">🔲️</Twemoji>
            </button>
          </Tooltip>
          <Tooltip text="Solve all">
            <button onClick={solveAllPuzzles}>
              <Twemoji tag="span">✅️</Twemoji>
            </button>
          </Tooltip>
          {/*
          <Tooltip text="Get all canned hints">
            <button onClick={getAllCannedHints}>
              <Twemoji tag="span">🥫️</Twemoji>
            </button>
          </Tooltip>
          */}
        </div>
        <Twemoji tag="span">
          {unlockCount} / {filteredPuzzles.length} 🔑
        </Twemoji>
        <Twemoji tag="span">
          {solveCount} / {solvablePuzzles.length} ✅️
        </Twemoji>
      </div>
      <div className="unlock-puzzles">
        {filteredPuzzles.map((puzData) => (
          <AdminPuzzleControl
            key={puzData.puzName}
            teamId={teamId}
            puzName={puzData.puzName}
          />
        ))}
      </div>
    </>
  );
}

export function NewHuntRedirect() {
  const navigate = useNavigate();
  const { search } = useLocation();

  useEffect(() => {
    void navigate(
      { pathname: resolveRoute({ route: "unlock" }), search },
      { replace: true, state: { openNewHunt: true } }
    );
  }, [navigate, search]);

  return null;
}

export default function UnlockPage() {
  const teamId = useTeamId();
  const shouldDisplayAdmin = useShouldDisplayAdmin();
  const [filter, setFilter] = useState(emptyPuzzleFilter);
  const location = useLocation();
  const openNewHunt =
    (location.state as { openNewHunt?: boolean } | null)?.openNewHunt === true;
  const sockClient = useSockClient();
  const setRedirectRoute = useNavStore((state) => state.setRedirectRoute);
  const hasControls = shouldDisplayAdmin || settings.isPosthunt;

  useEffect(() => {
    if (shouldDisplayAdmin) return;
    if (settings.isPosthunt) return;
    setRedirectRoute({ route: "puzzles", replace: true });
  }, [shouldDisplayAdmin, setRedirectRoute]);

  if (teamId === null) return <LargeSpinner />;

  return (
    <BoringPage heading="Posthunt Unlocking" className="unlock-page">
      <div>
        <p>
          <b>Galactic Puzzle Hunt 2026</b> has ended. The site is now archived,
          which means all puzzles are unlocked by default. This unlocking page,
          which you can always access from the sidebar, allows you to:
        </p>
      </div>
      <details
        className="unlock-section"
        name="unlock-section"
        open={openNewHunt}
      >
        <summary>Start a new hunt</summary>
        <div className="unlock-section-body">
          <p>
            You can <b>start the puzzlehunt from the beginning</b> and progress
            through the hunt as if it was live. Not all puzzles will be unlocked
            from the start – unlock new puzzles by solving puzzles and watching
            cutscenes!
          </p>
          <p>
            If you try to access a puzzle that you don’t have unlocked (from a
            direct link), you’ll be asked if you want to unlock it ahead of
            time. You can always revisit this page from the sidebar to unlock
            all puzzles, or skip a particular puzzle. Click the button below to
            clear any existing progress and start the hunt from the beginning.
          </p>
          <div className="unlock-buttons">
            <button
              onClick={() => {
                sockClient.resetServer();
                updateBrowserWidePersistentStateNonReactive({
                  resetProgress: true,
                });
                setRedirectRoute({ route: "countdown" });
              }}
            >
              Start GPH 2026 from the beginning
            </button>
          </div>
        </div>
      </details>

      {hasControls ? (
        <details className="unlock-section" name="unlock-section">
          <summary>Unlock all puzzles</summary>
          <div className="unlock-section-body">
            <p>
              The default posthunt state has <b>all puzzles unlocked</b> to
              support solving individual puzzles independently. To reset all
              local progress and restore this state, click the button below.
            </p>
            <div className="unlock-buttons">
              <button
                onClick={() => {
                  sockClient.resetServer(undefined, true);
                  updateBrowserWidePersistentStateNonReactive({
                    resetProgress: true,
                  });
                  setRedirectRoute({ route: "puzzles" });
                }}
              >
                Reset progress and unlock all puzzles
              </button>
            </div>
          </div>
        </details>
      ) : null}
      <details className="unlock-section" name="unlock-section">
        <summary>Save/restore existing team progress</summary>
        <div className="unlock-section-body">
          <p>
            You may <b>save or load your team&rsquo;s progress</b> using the
            buttons below. This lets you make backups of your progress or
            transfer your progress between browsers. You may also use this to
            transfer your team&rsquo;s progress from the live hunt website
            before the hunt closes.
          </p>
          {hasControls ? (
            <div className="hunt-state-control">
              <StateDownloader />
              <StateUploader />
            </div>
          ) : (
            <>
              <div>
                <StateDownloader />
              </div>
              <div>
                <p>
                  You are still logged in. You will lose access to your
                  team&rsquo;s progress after the hunt closes. To continue
                  progressing through the hunt locally:
                </p>
                <ol>
                  <li>
                    Download your team&rsquo;s progress with the button above.
                  </li>
                  <li>Log out.</li>
                  <li>
                    Navigate back to this page and upload the file containing
                    your team&rsquo;s progress.
                  </li>
                </ol>
              </div>
            </>
          )}
        </div>
      </details>
      {hasControls ? (
        <details className="unlock-section" name="unlock-section">
          <summary>Access full unlock controls</summary>
          <div className="unlock-section-body">
            <div>
              <p>
                Additional details about the postsolving experience and the
                unlock controls:
              </p>
              <ul>
                <li>
                  All hunt features are simulated, including interactions with
                  hunt staff and other teams. You will not need to manually set
                  puzzles solved or unlocked to fully progress through the hunt.
                </li>
                <li>
                  Progress is saved locally in your browser. On most desktop
                  browsers, your progress will be synced across all your browser
                  tabs.
                </li>
                <li>
                  There is no support for interaction between multiple solvers.
                </li>
                <li>The leaderboard is frozen.</li>
                <li>Spoilers for puzzle titles below!</li>
                <li>
                  <b>Note:</b> Setting a puzzle to locked may appear to fail
                  silently if your existing solves would cause the puzzle to be
                  immediately unlocked.
                </li>
                <li>
                  <Twemoji tag="span">⚠️</Twemoji> <b>Be careful!</b> There are
                  no confirmations for anything you click below.
                </li>
              </ul>
            </div>
            <div className="full-unlock-controls">
              <AdminTopControl
                teamId={teamId}
                filter={filter}
                setFilter={setFilter}
              />
              <UnlockPuzzles filter={filter} />
            </div>
          </div>
        </details>
      ) : null}
    </BoringPage>
  );
}
