import Tooltip from "components/Tooltip";
import { SolveDialogueContext } from "components/SolveDialogue/useSolveDialogue";

export function useShowSolution(
  puzData: TeamPuzzleSockAPIScopeState
): boolean | null {
  const { puzName } = puzData;
  const isHuntOver = useIsHuntOver();
  const isSolved = useIsPuzzleSolved(puzName);
  const shouldDisplayAdmin = useShouldDisplayAdmin();
  const teamScopeState = useTeamScopeState();
  if (isHuntOver === null || isSolved === null || teamScopeState === null)
    return null;
  const isFinished = teamScopeState.finishedData !== undefined;
  return (
    doesSolutionExist(puzData) &&
    (isHuntOver ||
      isSolutionPageAvailable(puzName, isSolved, isFinished) ||
      shouldDisplayAdmin)
  );
}

export function useShowHints(
  puzData: TeamPuzzleSockAPIScopeState
): boolean | null {
  const { puzName, slug } = puzData;
  const teamId = useTeamId();
  const teamCannedHintsScopeState = useScopeStateResolvable(
    ScopeType.TEAM_CANNED_HINTS,
    teamId === null ? null : { teamId }
  );
  const teamHintsScopeState = useScopeStateResolvable(
    ScopeType.TEAM_HINTS,
    teamId === null ? null : { teamId }
  );
  const numTotalHintTokens = useNumTotalTokens(teamId, TimedTokenType.HINT);
  const numTotalFreeAnswers = useNumTotalTokens(
    teamId,
    TimedTokenType.FREE_ANSWER
  );
  const isHuntOver = useIsHuntOver();
  const isInsightAvailable = useIsInsightAvailable(puzData);
  if (
    isHuntOver === null ||
    teamCannedHintsScopeState === null ||
    teamHintsScopeState === null ||
    numTotalHintTokens === null ||
    numTotalFreeAnswers === null
  )
    return null;
  const numTotalCannedHints =
    teamCannedHintsScopeState.cannedHints[puzName]?.numTotal ?? 0;
  const numUsedHints = Object.keys(
    teamHintsScopeState.hints[puzName] ?? {}
  ).length;
  return (
    isInsightAvailable ||
    (isHuntOver && CHECKERS[slug] !== undefined) ||
    (puzzleHasHints(puzData) &&
      ((isHuntOver && (CANNED_HINTS[puzName]?.length ?? 0) > 0) ||
        numTotalCannedHints > 0 ||
        numTotalHintTokens > 0 ||
        numUsedHints > 0 ||
        numTotalFreeAnswers > 0 ||
        (teamHintsScopeState.freeAnsweredPuzzles[puzName] ?? false)))
  );
}

export function useShowStats(
  puzData: TeamPuzzleSockAPIScopeState
): boolean | null {
  const isHuntOver = useIsHuntOver();
  const shouldDisplayAdmin = useShouldDisplayAdmin();
  if (isHuntOver === null) return null;
  return (
    puzData.type === PuzzleType.PUZZLE && (isHuntOver || shouldDisplayAdmin)
  );
}

export function useShowHuntStats(): boolean | null {
  const isHuntOver = useIsHuntOver();
  const shouldDisplayAdmin = useShouldDisplayAdmin();
  if (isHuntOver === null) return null;
  return isHuntOver || shouldDisplayAdmin;
}

export default function PuzzlePageToolbar(props: {
  puzData: TeamPuzzleSockAPIScopeState;
}) {
  const { puzData } = props;
  const { puzName } = puzData;
  //const deps = usePuzzleBodyDependencies(puzData);
  //const updateBrowserWidePersistentState =
  //  useUpdateBrowserWidePersistentState();
  const showSolution = useShowSolution(puzData) ?? false;
  const showHints = useShowHints(puzData) ?? false;
  const showStats = useShowStats(puzData) ?? false;
  const { inPuzzle, inSolution, inHints, inStats } = useInPuzzlePage();
  const isSolved = useIsPuzzleSolved(puzName);
  const solveDialogue = use(SolveDialogueContext);
  const now = useServerNow(1000);
  const timeToHints = useTimeToNext(now, HINT_CONFIG.timedHintCounts);

  //const { cutsceneState, isPuzzleSolved } = deps ?? {};
  const hintEligible = puzzleHasHints(puzData);

  return (
    <div className="button-squish-zone">
      {showSolution || showHints || hintEligible || showStats ? (
        <Tooltip text="Puzzle" placement="left">
          <PuzzleLink
            className={inPuzzle ? "active" : ""}
            aria-label="Puzzle"
            puzName={puzName}
            disabled={inPuzzle}
            button
          >
            <Twemoji>{isSolved ? Emoji.PUZZLE_SOLVED : Emoji.PUZZLE}</Twemoji>
          </PuzzleLink>
        </Tooltip>
      ) : null}
      {showSolution ? (
        <Tooltip text="Solution" placement="left">
          <PuzzleLink
            className={inSolution ? "active" : ""}
            aria-label="Solution"
            puzName={puzName}
            subpage="solution"
            disabled={inSolution}
            button
          >
            <Twemoji>{Emoji.SOLUTION}</Twemoji>
          </PuzzleLink>
        </Tooltip>
      ) : null}
      {showHints ? (
        <Tooltip text="Hints" placement="left">
          <PuzzleLink
            className={inHints ? "active" : ""}
            aria-label="Hints"
            puzName={puzName}
            subpage="hints"
            disabled={inHints}
            button
          >
            <Twemoji>{Emoji.HINT}</Twemoji>
          </PuzzleLink>
        </Tooltip>
      ) : hintEligible ? (
        <Tooltip
          text={
            timeToHints === null ? (
              "Hints are not currently available."
            ) : (
              <>Hints will become available on {timeToHints}.</>
            )
          }
          placement="left"
          into={timeToHints !== null}
        >
          <button disabled>
            <Twemoji>{Emoji.HINT}</Twemoji>
          </button>
        </Tooltip>
      ) : null}
      {showStats ? (
        <Tooltip text="Stats" placement="left">
          <PuzzleLink
            className={inStats ? "active" : ""}
            aria-label="Stats"
            puzName={puzName}
            subpage="stats"
            disabled={inStats}
            button
          >
            <Twemoji>{Emoji.STATS}</Twemoji>
          </PuzzleLink>
        </Tooltip>
      ) : null}
      {solveDialogue.status === "idle" ? (
        <Tooltip
          text={`${solveDialogue.unseen ? "Play" : "Replay"} ${solveDialogue.cutscene ? "scene" : "solve dialogue"}`}
          placement="left"
        >
          <button
            className={solveDialogue.unseen ? "solve-dialogue-unseen-tool" : ""}
            aria-label={`${solveDialogue.unseen ? "Play" : "Replay"} ${solveDialogue.cutscene ? "scene" : "solve dialogue"}`}
            onClick={solveDialogue.replay}
          >
            <Twemoji>{solveDialogue.cutscene ? "🎬" : "💬"}</Twemoji>
          </button>
        </Tooltip>
      ) : solveDialogue.status === "playing" ? (
        <Tooltip text="Next line" placement="left">
          <button
            className="active"
            aria-label="Next line"
            onClick={solveDialogue.advance}
          >
            ⏩︎
          </button>
        </Tooltip>
      ) : null}
      {/*
      TODO(sniper): more cutscene controls...
      {(cutsceneState?.historyPosition ?? null) != null ? (
        isPuzzleTeamSolved(puzData) ? (
          // If the puzzle has been solved by the team but not
          // locally, give the user the option to skip it.
          <a
            href="#"
            onClick={(evt) => {
              evt.preventDefault();
              updateBrowserWidePersistentState({
                completedStoryBeats: { [puzName]: true },
                cutscenesState: {
                  [puzName]: makeDefaultCutsceneState(),
                },
              });
            }}
          >
            <button>{isPuzzleSolved ? "Exit" : "Skip"}</button>
          </a>
        ) : (
          <a
            href="#"
            onClick={(evt) => {
              evt.preventDefault();
              updateBrowserWidePersistentState({
                cutscenesState: {
                  [puzName]: makeDefaultCutsceneState(),
                },
              });
            }}
          >
            <button>Reset</button>
          </a>
        )
      ) : null}
      */}
    </div>
  );
}
