import {
  CheckerForm,
  CheckerGrid,
} from "components/PuzzlePage/checkers/AnswerListChecker";

// Each classroom's seats by row, front row first, left to right.
const CLASSROOMS = [
  "HIAGKJFML",
  "EHMDJOCBA",
  "BJHCLGDEF",
  "OGFHDEMIJ",
  "MOBLHDKJI",
  "ALCEMHJNO",
  "JKLIBMHON",
  "CDEBOFAHG",
  "LBJFEIOGH",
];

/** Seat permutations for the eight rotations and reflections. */
const SYMMETRIES = (() => {
  const rotate = (p: number[]) =>
    p.map((_, i) => p[3 * (i % 3) + (2 - Math.floor(i / 3))]);
  const reflect = (p: number[]) =>
    p.map((_, i) => p[3 * Math.floor(i / 3) + (2 - (i % 3))]);
  const result = [[...Array(9).keys()]];
  for (let i = 0; i < 3; i++) result.push(rotate(result[i]));
  return [...result, ...result.map(reflect)];
})();

const known = (seats: string) => [...seats].filter((ch) => ch !== "?");
const isValid = (seats: string) =>
  /^[A-O?]{9}$/.test(seats) &&
  known(seats).length > 0 &&
  new Set(known(seats)).size === known(seats).length;

/** Known seats that agree with `classroom` seen through symmetry `p`. */
const score = (seats: string, classroom: string, p: number[]) =>
  [...seats].filter((ch, i) => ch === classroom[p[i]]).length;

/**
 * The classroom (and symmetry) agreeing with the most known seats; ties go to
 * the unflipped arrangement, then to the earlier classroom.
 */
function bestMatch(seats: string, symmetries: number[][]) {
  let best = { classroom: 0, symmetry: 0, score: -1 };
  symmetries.forEach((p, symmetry) =>
    CLASSROOMS.forEach((classroom, i) => {
      const s = score(seats, classroom, p);
      if (s > best.score) best = { classroom: i, symmetry, score: s };
    })
  );
  return best;
}

/** Reads `rows` as classrooms side by side, three rows at a time. */
function sideBySide(rows: string[]): string[] | null {
  if (rows.length % 3 !== 0) return null;
  const classrooms: string[] = [];
  for (let i = 0; i < rows.length; i += 3) {
    const [a, b, c] = rows.slice(i, i + 3);
    if (a.length % 3 !== 0 || b.length !== a.length || c.length !== a.length)
      return null;
    for (let j = 0; j < a.length; j += 3)
      classrooms.push([a, b, c].map((row) => row.slice(j, j + 3)).join(""));
  }
  return classrooms;
}

/** Reads `rows` as one stream of seats, nine to a classroom. */
const inSequence = (rows: string[]) => rows.join("").match(/.{1,9}/g) ?? [];

/** How plausible a reading is: valid classrooms, then seats that agree. */
const plausibility = (classrooms: string[]) => {
  const valid = classrooms.filter(isValid);
  return (
    100 * valid.length +
    valid.reduce((sum, seats) => sum + bestMatch(seats, SYMMETRIES).score, 0)
  );
};

/**
 * Splits the text into classrooms, however it's laid out: a classroom per
 * line, a row per line, or (as from a spreadsheet) several classrooms side by
 * side, with blank lines between blocks. Each block is read whichever way
 * makes the most sense.
 */
function parseClassrooms(text: string): string[] {
  const blocks = text
    .toUpperCase()
    .split(/\n\s*\n/)
    .map((block) =>
      block
        .split("\n")
        .map((line) => line.replace(/[^A-Z?]/g, ""))
        .filter((row) => row !== "")
    )
    .filter((rows) => rows.length > 0);
  return blocks.flatMap((rows) => {
    const readings = [inSequence(rows), sideBySide(rows)].filter(
      (reading) => reading !== null
    );
    return readings.reduce((best, reading) =>
      plausibility(reading) > plausibility(best) ? reading : best
    );
  });
}

/**
 * Each seat against the classroom (unflipped) that agrees with it most, plus a
 * note if something's off with the classroom as a whole.
 */
function describe(seats: string, duplicateOf: number | undefined) {
  if (!isValid(seats)) {
    return {
      cells: null,
      note: "Should be nine different initials from A to O, or ?.",
    };
  }
  const { classroom } = bestMatch(seats, [SYMMETRIES[0]]);
  const solution = CLASSROOMS[classroom];
  const cells = [0, 3, 6].map((i) =>
    [...seats.slice(i, i + 3)].map((text, j) => ({
      text,
      status:
        text === "?"
          ? ("unknown" as const)
          : text === solution[i + j]
            ? ("right" as const)
            : ("wrong" as const),
    }))
  );
  const numKnown = known(seats).length;
  const note =
    duplicateOf !== undefined
      ? `Duplicate of ${duplicateOf}?`
      : score(seats, solution, SYMMETRIES[0]) < numKnown &&
          bestMatch(seats, SYMMETRIES).score === numKnown
        ? "Wrong rotation."
        : null;
  return { cells, note };
}

function checkClassrooms(text: string) {
  const classrooms = parseClassrooms(text);
  if (classrooms.length === 0) return null;
  const firstWithMatch = new Map<number, number>();
  const duplicateOf = classrooms.map((seats, i) => {
    if (!isValid(seats)) return undefined;
    const { classroom } = bestMatch(seats, SYMMETRIES);
    const first = firstWithMatch.get(classroom);
    if (first === undefined) firstWithMatch.set(classroom, i + 1);
    return first;
  });
  const results = classrooms.map((seats, i) => describe(seats, duplicateOf[i]));
  const numCorrect = results.filter(
    ({ cells }, i) =>
      duplicateOf[i] === undefined &&
      cells?.every((row) => row.every(({ status }) => status === "right"))
  ).length;
  return {
    summary: (
      <>
        <b>
          {numCorrect} of {CLASSROOMS.length}
        </b>{" "}
        classrooms correct.
      </>
    ),
    details: (
      <div className="checker-grids">
        {results.map(({ cells, note }, i) => (
          <CheckerGrid
            key={i}
            cells={
              cells ??
              (classrooms[i].match(/.{1,3}/g) ?? []).map((row) =>
                [...row].map((text) => ({ text, status: "unknown" as const }))
              )
            }
            title={i + 1}
            note={note}
          />
        ))}
      </div>
    ),
  };
}

export default function FuzzyLogicChecker() {
  return (
    <CheckerForm
      label={
        <span className="spoiler">
          Paste each classroom as the initials of its nine students. Use ? for
          unknown seats.
        </span>
      }
      check={checkClassrooms}
    />
  );
}
