import { PropsWithChildren } from "react";
import Tooltip from "components/Tooltip";
import { Cryptic } from "components/PuzzleContent/puzzle-components";

/**
 * OverPower card name linking to its image on overpower.ca, with a hover render.
 * With `tip`, also styled as cryptic wordplay, with `tip` captioning the image.
 */
export function OverPowerCard(
  props: PropsWithChildren<{
    /** Card number in overpower.ca's specials, e.g. 1385 for Bear Hug. */
    id: number;
    name: string;
    tip?: string;
  }>
) {
  const { id, name, tip, children } = props;
  const src = `https://overpower.ca/cards/specials/${id}.png`;
  const image = (
    <img src={src} style={{ width: "12em", display: "block" }} alt={name} />
  );
  if (tip !== undefined) {
    return (
      <Cryptic
        tip={
          <>
            {image}
            <div style={{ textAlign: "center" }}>{tip}</div>
          </>
        }
      >
        <a href={src} target="_blank" rel="noreferrer">
          {children ?? name}
        </a>
      </Cryptic>
    );
  }
  return (
    <Tooltip
      text={image}
      directRef={(refProps) => (
        <a {...refProps} href={src} target="_blank" rel="noreferrer">
          {children ?? name}
        </a>
      )}
    />
  );
}
