import { Transition, useReducedMotion, Variants } from "framer-motion";

import settings from "settings";

/**
 * Motion tokens. Durations grow with how much of the screen changes; easings
 * are picked by role, not per site:
 * - standard: stays on screen and changes (heights, scroll, colour)
 * - enter: arriving, so it decelerates into place
 * - exit: leaving, so it accelerates away, one size shorter than entering
 */
export type MotionSize = "feedback" | "small" | "medium" | "large";

const DURATION: Record<MotionSize, number> = {
  feedback: 0.15,
  small: 0.2,
  medium: 0.35,
  large: 0.5,
};

const SMALLER: Record<MotionSize, MotionSize> = {
  feedback: "feedback",
  small: "feedback",
  medium: "small",
  large: "medium",
};

export const EASE = {
  standard: [0.2, 0, 0, 1],
  enter: [0.05, 0.7, 0.1, 1],
  exit: [0.3, 0, 0.8, 0.15],
} as const;

/** How far a surface rises in from and sinks back to. */
const SURFACE_DISTANCE = "5em";
/** How far new content rises when fading through. */
const FADE_THROUGH_RISE = "1.5em";
/** Fraction of a fade-through spent fading out the old content. */
const FADE_THROUGH_OUT = 0.3;

/**
 * Variants are labelled enter/show/leave, with transitions inside them, so
 * children that only declare matching variants follow the same timing.
 */
export interface MotionPreset {
  variants: Variants;
  initial: "enter";
  animate: "show";
  exit: "leave";
}

export interface EnterOptions {
  /** Seconds to wait before entering: the leave of whatever this replaces. */
  after?: number;
}

function preset(variants: Variants): MotionPreset {
  return { variants, initial: "enter", animate: "show", exit: "leave" };
}

/** `offset` with every number zeroed, units kept, so motion can tween to it. */
const zeroed = (offset: string) => offset.replace(/-?[\d.]+/g, "0");

// CSS durations (static/base.css) scale by --slowmo too.
if (settings.slowMotion !== 1)
  document.documentElement.style.setProperty(
    "--slowmo",
    String(settings.slowMotion)
  );

export function useMotion() {
  const scale = useReducedMotion() ? 0 : settings.slowMotion;
  const scaled = (seconds: number) => seconds * scale;
  const duration = (size: MotionSize) => scaled(DURATION[size]);
  /** Arriving: decelerates into place. */
  const enter = (size: MotionSize, after = 0): Transition => ({
    duration: duration(size),
    delay: after,
    ease: EASE.enter,
  });
  /** Leaving: accelerates away, one size shorter than arriving. */
  const exit = (size: MotionSize): Transition => ({
    duration: duration(SMALLER[size]),
    ease: EASE.exit,
  });
  /** Comes in from `offset` and goes back out to it, fading too if `fade`. */
  const slide = (
    size: MotionSize,
    offset: string,
    { after = 0, fade = true }: EnterOptions & { fade?: boolean } = {}
  ): MotionPreset => {
    const away = { translate: offset, ...(fade ? { opacity: 0 } : {}) };
    return preset({
      enter: away,
      show: {
        translate: zeroed(offset),
        ...(fade ? { opacity: 1 } : {}),
        transition: enter(size, after),
      },
      leave: { ...away, transition: exit(size) },
    });
  };

  return {
    duration,
    /**
     * A duration that isn't a token, such as one by distance, scaled the same
     * way: by ?slowmo, and to nothing under reduced motion.
     */
    scaled,
    /**
     * How long each kind of departure takes, for whatever replaces it to
     * wait out: a fade or slide (surfaces included), or a fade-through.
     */
    leaveDuration: (size: MotionSize, kind: "exit" | "fadeThrough") =>
      kind === "exit"
        ? duration(SMALLER[size])
        : duration(size) * FADE_THROUGH_OUT,
    enter,
    exit,
    /** Something that stays on screen and changes. */
    tween: (size: MotionSize): Transition => ({
      duration: duration(size),
      ease: EASE.standard,
    }),
    /**
     * Something moving or resizing on screen, settling with a little bounce.
     * Never for opacity or colour.
     */
    spring: (size: MotionSize): Transition =>
      scale === 0
        ? { duration: 0 }
        : { type: "spring", visualDuration: duration(size), bounce: 0.15 },
    /** Something appearing or disappearing on its own, in place. */
    fade: (size: MotionSize, { after = 0 }: EnterOptions = {}): MotionPreset =>
      preset({
        enter: { opacity: 0 },
        show: { opacity: 1, transition: enter(size, after) },
        leave: { opacity: 0, transition: exit(size) },
      }),
    slide,
    /**
     * A large surface over the world: rises in, sinks out. Every surface uses
     * the same distance, so they all read as one layer.
     */
    surface: (size: MotionSize, options: EnterOptions = {}): MotionPreset =>
      slide(size, `0em ${SURFACE_DISTANCE}`, options),
    /**
     * Content replacing content: the old fades out quickly in place, then the
     * new fades in, rising by `rise`. The two are never both visible. By
     * default the new waits out an old that also fades through.
     */
    fadeThrough: (
      size: MotionSize,
      { rise = FADE_THROUGH_RISE, after }: EnterOptions & { rise?: string } = {}
    ): MotionPreset => {
      const total = duration(size);
      const out = total * FADE_THROUGH_OUT;
      return preset({
        enter: { opacity: 0, translate: `0em ${rise}` },
        show: {
          opacity: 1,
          translate: "0em 0em",
          transition: {
            duration: total - out,
            delay: after ?? out,
            ease: EASE.enter,
          },
        },
        leave: {
          opacity: 0,
          transition: { duration: out, ease: EASE.exit },
        },
      });
    },
  };
}
