import { useState, useEffect, useRef, useCallback } from "react";
import { ScopeType } from "sockapi/scope-types";
import { KeyframeData, KeyframesById } from "sockapi/scope-specs/keyframe-spec";
import { PuzzleType } from "sockapi/puzzle-data";
import { PuzzleContentType } from "sockapi/scope-specs/puzzle-content-spec";
import { SolveDialogueLine } from "sockapi/scope-specs/solve-dialogue-spec";
import { useUILock } from "client-util/useUILock";
import { resolveRoute, useRouteMatch } from "components/urls";
import { useNavStore, useParsedSlug } from "stores/NavStore";
import {
  useCutsceneState,
  useUpdateBrowserWidePersistentState,
  makeDefaultCutsceneState,
} from "stores/BrowserWidePersistentState";
import {
  useIsPuzzleSolved,
  useScopeStateResolvable,
} from "stores/ScopeStateStore";
import {
  useTeamId,
  useSockClient,
  useShouldDisplayAdmin,
} from "stores/ServerInteractionStore";

/**
 * The keyframe ids from `firstKeyframeId` to the end, following single
 * `nextId`s. Stops at the first branch, since there's no one path past it.
 */
function linearKeyframeIds(
  keyframes: KeyframesById,
  firstKeyframeId: string
): string[] {
  const ids: string[] = [];
  let id: string | undefined = firstKeyframeId;
  while (id !== undefined && !ids.includes(id)) {
    const keyframe: KeyframeData | undefined = keyframes[id];
    if (keyframe === undefined) break;
    ids.push(id);
    if (keyframe.endCutscene ?? false) break;
    id = keyframe.nextId.length === 1 ? keyframe.nextId[0] : undefined;
  }
  return ids;
}

/**
 * A linear cutscene as solve-dialogue lines, so it can play in speech
 * bubbles instead of full screen.
 */
export function keyframesToDialogueLines(
  keyframes: KeyframesById,
  firstKeyframeId: string
): SolveDialogueLine[] {
  return linearKeyframeIds(keyframes, firstKeyframeId).flatMap((id) => {
    const {
      speaker,
      stage = [],
      dialogue,
      dialogOptions = [],
      stageDirection,
    } = keyframes[id];
    // Bubbles have nowhere to put narration, and nothing to say for a beat.
    if (stageDirection || dialogue === "") return [];
    if (dialogOptions.length > 1)
      throw new Error(`keyframe ${id} has dialogue options`);
    const character = stage.find(({ characterId }) => characterId === speaker);
    if (character === undefined)
      throw new Error(`keyframe ${id} has no speaker on stage`);
    const { characterId, name, color, imageName, flip } = character;
    return [{ characterId, name, color, imageName, flip, dialogue }];
  });
}

export const cutsceneImageNameToUrl = (imageName: string): string | null =>
  imageName === "blank" ? null : `/static/images/${imageName}`;

export type CutscenePlayback =
  | { status: "none" }
  | { status: "loading" }
  | {
      status: "playing";
      keyframeId: string;
      keyframe: KeyframeData;
      /** Reached by stepping (back, forward, or through the log), not advancing. */
      stepped: boolean;
      chooseDialogOption: (index: number) => void;
      undo: (() => void) | null;
      redo: (() => void) | null;
      exit: () => void;
      log: KeyframeData[];
      logPosition: number;
      goToLogEntry: (index: number) => void;
      bgm: string | null;
    };

/**
 * The cutscene the current route is showing, or null.
 */
export function useCutscenePuzName(): string | null {
  const inPuzzleRoute = useRouteMatch("scene") !== null;
  const { puzName, puzData } = useParsedSlug();
  if (!inPuzzleRoute) return null;
  if (puzData?.type !== PuzzleType.STORY) return null;
  return puzName;
}

/**
 * Whether `puzName` has a cutscene to play, or null while that is still
 * unknown. Lets a page hold off on drawing chrome the cutscene would replace.
 */
export function useHasCutscene(puzName: string | null): boolean | null {
  const content = useScopeStateResolvable(
    ScopeType.PUZZLE_CONTENT,
    puzName === null ? null : { puzName }
  );
  if (puzName === null) return false;
  if (content === null) return null;
  return content.type === PuzzleContentType.STORY;
}

/**
 * Drives cutscene playback for `puzName` (pass null when not on a cutscene).
 */
export function useCutscene(puzName: string | null): CutscenePlayback {
  const content = useScopeStateResolvable(
    ScopeType.PUZZLE_CONTENT,
    puzName === null ? null : { puzName }
  );

  const teamId = useTeamId();
  const sockClient = useSockClient();
  const isPuzzleSolved = useIsPuzzleSolved(puzName);
  const shouldDisplayAdmin = useShouldDisplayAdmin();
  const cutsceneState = useCutsceneState(puzName) ?? makeDefaultCutsceneState();
  const updateBrowserWidePersistentState =
    useUpdateBrowserWidePersistentState();
  const previousPathname = useNavStore((state) => state.previousPathname);
  const setRedirectCommand = useNavStore((state) => state.setRedirectCommand);
  const advanceLock = useUILock();

  // Buffer the current keyframe so nav transitions don't flash a spinner.
  const [state, setState] = useState<{
    puzName: string;
    firstKeyframeId: string;
    bgm: string | null;
    keyframes: KeyframesById;
    keyframeId: string;
    keyframe: KeyframeData;
    history: string[];
    historyPosition: number;
  } | null>(null);
  const [stepped, setStepped] = useState(false);

  const resolveHistory = useCallback(
    (
      {
        firstKeyframeId,
        keyframes,
      }: { firstKeyframeId: string; keyframes: KeyframesById },
      history: string[],
      historyPosition: number | null
    ): {
      keyframeId: string;
      keyframe: KeyframeData;
      history: string[];
      historyPosition: number;
    } => {
      history =
        history[0] === firstKeyframeId ? [...history] : [firstKeyframeId];
      const badIndex = history.findIndex(
        (keyframeId) => !keyframes[keyframeId]
      );
      if (badIndex === 0) throw new Error("cutscene has invalid first frame");
      if (badIndex > 0) history = history.slice(0, badIndex);
      historyPosition = Math.min(history.length - 1, historyPosition ?? 0);
      const keyframeId = history[historyPosition];
      const keyframe = keyframes[keyframeId];
      if (isPuzzleSolved || shouldDisplayAdmin)
        history.push(...linearKeyframeIds(keyframes, history.pop()!));
      return { keyframeId, keyframe, history, historyPosition };
    },
    [isPuzzleSolved, shouldDisplayAdmin]
  );

  useEffect(() => {
    if (puzName === state?.puzName) return;
    if (puzName === null || content?.type !== PuzzleContentType.STORY) {
      if (state !== null) setState(null);
      return;
    }
    const { history, historyPosition } = cutsceneState;
    const resolved = resolveHistory(content, history, historyPosition);
    setState({ puzName, ...content, ...resolved });
  }, [puzName, content, cutsceneState, state, resolveHistory]);

  // When leavingCutscene is set, wait for the cutscene to be marked solved from
  // the server before processing end cutscene nav actions.
  const [leavingCutscene, setLeavingCutscene] = useState(false);
  // Where the cutscene returns to, on finishing or on backing out
  const returnPath = previousPathname ?? resolveRoute({ route: "puzzles" });

  useEffect(() => {
    if (!leavingCutscene) return;
    if (puzName !== state?.puzName) {
      setLeavingCutscene(false);
      return;
    }

    const { endCutscene = false, redirectPath } = state.keyframe;
    const victoryPath = resolveRoute({ route: "victory" });
    const finishingCutscene = endCutscene && redirectPath !== victoryPath;

    // It takes a bit of time for the solve to register with the server the
    // first time the cutscene is finished. Wait for the solve before performing
    // the end cutscene actions.
    if (finishingCutscene && !(isPuzzleSolved ?? false)) return;

    setLeavingCutscene(false);

    // from metameta, always return to metameta. else, use redirect path.
    // else, use return path.
    const fromGoodbye =
      returnPath ===
      resolveRoute({ route: "puzzle", params: { slug: "goodbye" } });
    setRedirectCommand({
      path: fromGoodbye ? returnPath : (redirectPath ?? returnPath),
    });
    updateBrowserWidePersistentState({
      cutscenesState: {
        [state.puzName]: { history: state.history, historyPosition: null },
      },
    });
  }, [
    puzName,
    leavingCutscene,
    state,
    cutsceneState,
    returnPath,
    updateBrowserWidePersistentState,
    setRedirectCommand,
    isPuzzleSolved,
  ]);

  const cutsceneImagesPreloadRef = useRef<HTMLImageElement[]>([]);
  const keyframes = state?.keyframes ?? null;

  // Preload and decode every sprite and background up front, so each
  // character's first appearance doesn't wait on the network
  useEffect(() => {
    if (keyframes === null) return;
    const imageNames = new Set(
      Object.values(keyframes).flatMap((keyframe) => [
        ...(keyframe.background !== undefined ? [keyframe.background] : []),
        ...(keyframe.stage ?? []).map((character) => character.imageName),
      ])
    );
    cutsceneImagesPreloadRef.current = Array.from(imageNames).flatMap(
      (imageName) => {
        const imgUrl = cutsceneImageNameToUrl(imageName);
        if (imgUrl === null) return [];
        const img = new Image();
        img.src = imgUrl;
        img.decode().catch(() => {});
        return [img];
      }
    );
  }, [keyframes]);

  if (puzName === null) return { status: "none" };
  if (teamId === null || isPuzzleSolved === null || state === null)
    return { status: "loading" };

  const goToHistoryPosition = (historyPosition: number, history?: string[]) => {
    const resolved = resolveHistory(
      state,
      history ?? state.history,
      historyPosition
    );
    setState({ ...state, ...resolved });
    updateBrowserWidePersistentState({
      cutscenesState: {
        [state.puzName]: {
          history: resolved.history,
          historyPosition: resolved.historyPosition,
        },
      },
    });
  };

  return {
    status: "playing",
    keyframeId: state.keyframeId,
    keyframe: state.keyframe,
    stepped,
    exit: () => {
      setRedirectCommand({ path: returnPath });
      updateBrowserWidePersistentState({
        cutscenesState: {
          [state.puzName]: { history: state.history, historyPosition: null },
        },
      });
    },
    undo:
      state.historyPosition > 0
        ? () => {
            setStepped(true);
            goToHistoryPosition(state.historyPosition - 1);
          }
        : null,
    redo:
      state.historyPosition < state.history.length - 1
        ? () => {
            setStepped(true);
            goToHistoryPosition(state.historyPosition + 1);
          }
        : null,
    log: state.history.flatMap((id) => state.keyframes[id] ?? []),
    logPosition: state.historyPosition,
    goToLogEntry: (index: number) => {
      setStepped(true);
      goToHistoryPosition(index);
    },
    bgm: state.bgm,
    chooseDialogOption: (index: number) => {
      advanceLock.acquireAndRun(async (getIsCanceled) => {
        const { keyframeId, keyframe, history, historyPosition } = state;
        const {
          endCutscene = false,
          redirectPath,
          dialogOptions = [],
          nextId,
        } = keyframe;
        // VictoryPage handles these itself after the navigation.
        const victoryPath = resolveRoute({ route: "victory" });
        const finishingCutscene = endCutscene && redirectPath !== victoryPath;
        const needChooseDialogOption = dialogOptions.length > 1;
        const needSetCutsceneComplete = finishingCutscene && !isPuzzleSolved;
        // Send a step if needed.
        if (needSetCutsceneComplete || needChooseDialogOption) {
          const resp = await sockClient.sendScopeStepAndWaitAsync(
            { type: ScopeType.TEAM_CUTSCENES, teamId },
            {
              setCutsceneComplete: needSetCutsceneComplete
                ? puzName
                : undefined,
              chooseDialogOption: needChooseDialogOption
                ? { keyframeId, index }
                : undefined,
            }
          );
          if (getIsCanceled() || resp === null || (resp.isDisallowed ?? false))
            return;
        }
        if (finishingCutscene)
          updateBrowserWidePersistentState({
            completedStoryBeats: { [puzName]: true },
          });
        if (endCutscene || redirectPath) {
          setLeavingCutscene(true);
          return;
        }
        // If there is only one nextId, then all dialog options should default
        // to that nextId.
        const nextKeyframeId = nextId.length === 1 ? nextId[0] : nextId[index];
        if (nextKeyframeId === undefined)
          throw new Error(
            `no next keyframe id for option ${index} in ${keyframeId}`
          );
        // Only drop the lines ahead if this goes somewhere else.
        const newHistory =
          history[historyPosition + 1] === nextKeyframeId
            ? history
            : [...history.slice(0, historyPosition + 1), nextKeyframeId];
        setStepped(false);
        goToHistoryPosition(historyPosition + 1, newHistory);
      });
    },
  };
}
