import { useState } from "react";

import { ScopeType } from "sockapi/scope-types";
import {
  PuzzleContentType,
  getPuzzleContentStaticDir,
} from "sockapi/scope-specs/puzzle-content-spec";
import { useScopeStateResolvable } from "stores/ScopeStateStore";
import {
  GeneticData,
  GeneticPedigreeInputs,
  geneticGenomesInReadingOrder,
  useGeneticData,
} from "components/PuzzleContent/GeneticCode";
import { Spinner } from "components/Loading";
import type { CheckerProps } from "components/PuzzlePage/checkers";
import { CheckerResultList } from "components/PuzzlePage/checkers/AnswerListChecker";

const GENOMES =
  "KNMNG FGXVN SJRTC LXGBM XFLXD YVFQY CONRH EZYYZ VRSFP DQJUU HTBII BWKZB UYZSF PCWMO QIAPL OKUWE ISIOQ TPQDK MBPKV JLCGS ZUVCX RHHAA WDEJJ AEOEW NMDLR GATHT".split(
    " "
  );

/**
 * Solvers work out one gene position across every alien at a time, so the
 * check is per position rather than per alien.
 */
function GeneResults({
  data,
  checked,
}: {
  data: GeneticData;
  checked: string[];
}) {
  const solution = geneticGenomesInReadingOrder(data, GENOMES);
  return (
    <CheckerResultList
      results={[0, 1, 2, 3, 4].map((t) => {
        const filled = solution.flatMap((genome, k) => {
          const gene = checked[k]?.[t] ?? "?";
          return gene === "?" ? [] : [gene === genome?.[t]];
        });
        const numCorrect = filled.filter(Boolean).length;
        return {
          status:
            numCorrect < filled.length
              ? "wrong"
              : numCorrect === solution.length
                ? "correct"
                : "partial",
          content: (
            <>
              Gene {t + 1}:{" "}
              {filled.length === 0 ? (
                <>empty</>
              ) : numCorrect === solution.length ? (
                <b>all correct!</b>
              ) : (
                <>
                  {numCorrect} of {filled.length} correct
                </>
              )}
            </>
          ),
        };
      })}
    />
  );
}

function GeneticCodeEntry({ src }: { src: string }) {
  const data = useGeneticData(src);
  const [values, setValues] = useState<string[]>([]);
  const [gene, setGene] = useState<number | null>(0);
  const [checked, setChecked] = useState<string[] | null>(null);
  if (data === null) return <Spinner inline />;
  return (
    <>
      <h4>
        <label>
          Check{" "}
          <select
            value={gene ?? "all"}
            onChange={(e) =>
              setGene(e.target.value === "all" ? null : +e.target.value)
            }
          >
            {[0, 1, 2, 3, 4].map((t) => (
              <option key={t} value={t}>
                letter {t + 1}
              </option>
            ))}
            <option value="all">all letters</option>
          </select>
        </label>
      </h4>
      <p>
        Paste each alien's letter
        {gene === null ? "s. Use ? for unknowns." : "."}
      </p>
      <GeneticPedigreeInputs
        data={data}
        values={values}
        setValues={setValues}
        gene={gene}
      />
      <p>
        <button onClick={() => setChecked(values)}>Check</button>
      </p>
      {checked && <GeneResults data={data} checked={checked} />}
    </>
  );
}

export default function GeneticCodeChecker({ puzName }: CheckerProps) {
  const content = useScopeStateResolvable(ScopeType.PUZZLE_CONTENT, {
    puzName,
  });
  if (content === null || content.type === PuzzleContentType.STORY)
    return <Spinner inline />;
  return (
    <GeneticCodeEntry
      src={`${getPuzzleContentStaticDir(content)}/default.json`}
    />
  );
}
