import { SVGProps } from "react";
import Tooltip from "components/Tooltip";
import Star4 from "images/icons/star-4.svg?react";
import Star5 from "images/icons/star-5.svg?react";
import Star6 from "images/icons/star-6.svg?react";
import Star7 from "images/icons/star-7.svg?react";
import Star8 from "images/icons/star-8.svg?react";
import "./StarIcon.css";

const STAR_ICON = {
  "4": Star4,
  "5": Star5,
  "6": Star6,
  "7": Star7,
  "8": Star8,
};

const STAR_HUE = {
  "4": 0,
  "5": 20,
  "6": 120,
  "7": 200,
  "8": -40,
};

export function StarIcon({
  rarity,
  className = "",
  style = {},
  ...otherProps
}: { rarity: keyof typeof STAR_ICON } & SVGProps<SVGSVGElement>) {
  return (
    <>
      <span className="copy-only">[a star with {rarity} points]</span>
      {STAR_ICON[rarity]({
        className: `emoji no-copy star-icon ${className}`,
        style: { filter: `hue-rotate(${STAR_HUE[rarity]}deg)`, ...style },
        ...otherProps,
      })}
    </>
  );
}

export function StarSequence({
  sequence,
}: {
  sequence: [keyof typeof STAR_ICON, string, string][];
}) {
  return sequence.map(([rarity, slug, name]) => (
    <Tooltip text={name || "Unnamed Star"} key={slug}>
      <a
        {...(slug === "find_the_answer_v"
          ? {
              style: { cursor: "not-allowed" },
            }
          : {
              href: `https://2024.galacticpuzzlehunt.com/puzzle/${slug}`,
              target: "_blank",
            })}
      >
        <StarIcon rarity={rarity} />
      </a>
    </Tooltip>
  ));
}
