import { ReactNode } from "react";

import { ScopeType } from "sockapi/scope-types";
import { AdminQueueTaskSummary } from "sockapi/scope-specs/admin-queue-spec";
import {
  PuzzleSubmissionType,
  AdminQueueTaskType,
} from "sockapi/scope-specs/admin-queue-task-spec";
import { useScopeStateResolvable } from "stores/ScopeStateStore";
import { useAdminPreferencesStore } from "stores/UserPreferencesStore";
import { Spinner } from "components/Loading";
import { Link } from "components/Link";

import ClaimedBy from "components/AdminQueue/ClaimedBy";
import { HintAdminQueueTaskSummaryDisplay } from "components/AdminQueue/admin-queue-hint";
import { VowelsAdminQueueTaskSummaryDisplay } from "components/AdminQueue/admin-queue-vowels";
import { AdminQueueFilterPref } from "pages/AdminQueuePage";
import { useReactiveTimeout } from "client-util/useReactiveTimeout";

export const CLAIM_FILTERS = {
  MINE: true,
  OTHERS: true,
  UNCLAIMED: true,
  SNOOZED: true,
} as const;

export function AdminQueueTaskSummaryDisplay(props: {
  taskId: string;
  taskSummary: AdminQueueTaskSummary;
  filter: AdminQueueFilterPref;
}) {
  const { taskId, taskSummary, filter } = props;
  const adminQueueTaskScopeState = useScopeStateResolvable(
    ScopeType.ADMIN_QUEUE_TASK,
    {
      taskId,
    }
  );
  const staffId = useAdminPreferencesStore((state) => state.staffId);
  const hasUnsnoozed = useReactiveTimeout(
    adminQueueTaskScopeState?.snooze?.snoozeUntil ?? null
  );

  if (adminQueueTaskScopeState === null) return <Spinner inline />;
  const { task, claim, snooze } = adminQueueTaskScopeState;
  const isClaimedBySelf = claim?.staffId === staffId;
  const isSnoozed = snooze !== undefined && !hasUnsnoozed;
  // This is a "fake" filter: it runs after pagination, because it uses data
  // that's only available when reading each task's individual scope.
  const claimFilters = Object.entries({
    MINE: claim !== undefined && isClaimedBySelf,
    OTHERS: claim !== undefined && !isClaimedBySelf,
    UNCLAIMED: claim === undefined,
    SNOOZED: isSnoozed,
  } as { [name in keyof typeof CLAIM_FILTERS]: boolean });
  if (!claimFilters.some(([name, ok]) => (filter[name] ?? true) && ok))
    return null;

  const taskContent = ((): NonNullable<ReactNode> => {
    switch (task.type) {
      case AdminQueueTaskType.HINT:
        return <HintAdminQueueTaskSummaryDisplay hintId={task.hintId} />;
      case AdminQueueTaskType.PUZZLE_SUBMISSION:
        switch (task.submissionType) {
          case PuzzleSubmissionType.VOWELS:
            return <VowelsAdminQueueTaskSummaryDisplay teamId={task.teamId} />;
        }
    }
  })();

  return (
    <div
      className={`admin-queue-task-summary ${
        taskSummary.respondTime === undefined
          ? isSnoozed
            ? "admin-queue-task-summary-snoozed"
            : claim !== undefined && !isClaimedBySelf
              ? "admin-queue-task-summary-claimed"
              : "admin-queue-task-summary-open"
          : "admin-queue-task-summary-closed"
      }`}
    >
      <div className="admin-queue-task-claim-control">
        <ClaimedBy taskId={taskId} taskSummary={taskSummary} useClaimLink />
        <div>
          <Link route="admin_queue_task" params={{ taskId }}>
            {isClaimedBySelf ? "View" : "View without claiming"}
          </Link>
        </div>
      </div>
      <div className="admin-queue-task-summary-content">{taskContent}</div>
    </div>
  );
}
