// all fields optional: facing defaults to "right", x/y default to 0
// x/y are offsets in cqw (percent of the certificate width); +x = right, +y = down
type PoseConfig = { facingLeft?: boolean; x?: number; y?: number };
type Pose = { name: string; facingLeft: boolean; x: number; y: number };

// default left-to-right order
const CHARACTER_ORDER = ["dj", "lam", "taylor", "camille"] as const;

// the direction each slot should face
const SLOT_FACES_LEFT = [false, false, true, true];

// added to every pose of that character (same sign convention as x/y in PoseConfig)
const CHARACTER_OFFSET: Record<string, { x?: number; y?: number }> = {
  dj: { x: -8 },
  lam: { x: 3 },
  taylor: {},
  camille: { x: -5 },
};

const shuffle = <T,>(arr: readonly T[]): T[] => {
  const out = [...arr];
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
};

const pickOrder = (shipArray: string[]): string[] => {
  const pinned = [...new Set(shipArray)].slice(0, 2);
  const rest = shuffle(CHARACTER_ORDER.filter((c) => !pinned.includes(c)));
  // slots 1 and 2 are the centre two
  const centreSlots = shuffle([1, 2]).slice(0, pinned.length);
  const order: string[] = [];
  pinned.forEach((c, i) => {
    order[centreSlots[i]] = c;
  });
  return Array.from({ length: CHARACTER_ORDER.length }, (_, i) => {
    return order[i] ?? rest.pop()!;
  });
};

const pickPose = (character: string, avoidName?: string): Pose => {
  const offset = CHARACTER_OFFSET[character];
  const all: Pose[] = Object.entries(validCharacterImages[character]).map(
    ([name, { facingLeft = false, x = 0, y = 0 }]) => ({
      name,
      facingLeft,
      x: x - (offset.x ?? 0),
      y: y - (offset.y ?? 0),
    })
  );
  const candidates = all.filter((pose) => pose.name !== avoidName);
  const pool = candidates.length > 0 ? candidates : all;
  return pool[Math.floor(Math.random() * pool.length)];
};

// if `previous` is given, every character gets a different pose than before
const pickPoses = (previous?: Record<string, Pose>) =>
  Object.fromEntries(
    CHARACTER_ORDER.map((c) => [c, pickPose(c, previous?.[c].name)])
  ) as Record<string, Pose>;

const genHash = (s: string, len: number): string => {
  const hexChars = "0123456789abcdef";
  let hashValue = "";
  let seed = 5381;
  for (let i = 0; i < s.length; i++) seed = (seed * 33) ^ s.charCodeAt(i);
  for (let i = 0; i < len; i++) {
    seed = (seed * 33 + i) % 0xffffffff;
    const randomHex = hexChars[(seed >> (i % 16)) & 0xf];
    hashValue += randomHex;
  }
  return hashValue;
};

// generate a number in [0, 1) based on s
const genHashNumber = (s: string): number => {
  return parseInt(genHash(s, 4), 16) / Math.pow(16, 4);
};

// generate a number in [min, max) based on poses
const genRandRangeFromPoses = (
  poses: Record<string, Pose>,
  min: number,
  max: number
): number => {
  const n = genHashNumber(
    Object.values(poses)
      .map((p: Pose) => p.name)
      .join("")
  );
  return n * (max - min) + min;
};

function CertificatePage() {
  const isAllowed = useRedirectIfNonAdmin();

  const teams = useGlobalScopeState(ScopeType.TEAM_LIST) ?? {};
  const { teamId } = useParams();
  if (teamId === undefined) throw new Error("expect teamId to be defined");
  const team = teams[teamId] ?? null;

  const teamScopeState = useTeamScopeState(isAllowed ? teamId : null);
  const teamMembersScopeState = useTeamMembersScopeState(
    isAllowed ? teamId : null
  );
  const areTeamsLoaded = Object.keys(teams).length > 0;
  const setRedirectRoute = useNavStore((state) => state.setRedirectRoute);
  const sockClient = useSockClient();

  const [emails, setEmails] = useState<string[] | null>(null);
  const getEmailsLock = useUILock();
  const shipState = useScopeStateResolvable(
    ScopeType.TEAM_SHIP,
    teamId !== null ? { teamId } : null
  );
  // chosen ship chars are always in the center
  // eslint-disable-next-line @eslint-react/exhaustive-deps,react-hooks/exhaustive-deps
  const shipArray = shipState?.ship ?? [];

  // eslint-disable-next-line @eslint-react/use-state
  const [order, setOrder] = useState<string[]>([...pickOrder(shipArray)]);
  const [poses, setPoses] = useState<Record<string, Pose>>(() => pickPoses());

  const stampAngle = genRandRangeFromPoses(poses, -5, 5);

  useEffect(() => {
    if (!areTeamsLoaded) return;
    if (team !== null) return;
    if (!isAllowed) return;

    return addFlushSockAPIMessagesEffect(sockClient, () => {
      toastr.error(`Team “${teamId}” not found.`);
      setRedirectRoute({ route: "teams" });
    });
  }, [isAllowed, areTeamsLoaded, team, teamId, setRedirectRoute, sockClient]);

  useEffect(() => {
    setOrder(pickOrder(shipArray));
  }, [shipArray]);

  if (
    !areTeamsLoaded ||
    teamId === null ||
    teamMembersScopeState === null ||
    teamScopeState === null
  )
    return <LargeSpinner />;

  return (
    <div className="certificate-page">
      <title>{`Cert: ${teamScopeState.displayName}`}</title>
      <div className="certificate-toolbar">
        <button onClick={() => setOrder(pickOrder(shipArray))}>
          {/* ship isn't set on first load */}
          Shuffle order
        </button>
        <button onClick={() => setPoses((prev) => pickPoses(prev))}>
          Randomize poses
        </button>
        <button onClick={print}>Print (use CHROMIUM or else)</button>
        <button
          onClick={() => {
            getEmailsLock.acquireAndRun(async (getIsCanceled) => {
              try {
                const emails = (
                  await sockClient.sendDirectBackendReqAsync({
                    type: DirectBackendReqType.GET_TEAM_EMAILS,
                    payload: { teamId },
                  })
                ).payload;
                if (getIsCanceled()) return;
                setEmails(emails);
              } catch (err) {
                console.error(err);
                toastr.error("Failed to get emails.");
              }
            });
          }}
        >
          Get emails
        </button>
      </div>
      {emails !== null ? (
        emails.length === 0 ? (
          <div>None found.</div>
        ) : (
          <textarea>{emails.join(", ")}</textarea>
        )
      ) : null}
      <div className="debug">Team's ship: {shipArray}</div>

      <div className="certificate-ciphertext">
        <div className="certificate-front">
          <img className="header-img" src="/static/images/cert/header.png" />
          {order.map((character, i) => {
            const pose = poses[character];
            return (
              <img
                key={character}
                className={`cert-char-${i + 1}`}
                src={imageUrl(pose.name)}
                style={{
                  transform:
                    pose.facingLeft !== SLOT_FACES_LEFT[i]
                      ? `scaleX(-1) translate(${-pose.x}cqw, ${-pose.y}cqw)`
                      : `translate(${-pose.x}cqw, ${-pose.y}cqw)`,
                }}
              />
            );
          })}
        </div>
        <div className="certificate-back">
          <div className="inside"></div>
          <img
            className="taylors-drawing"
            src="/static/images/cert/taylors-drawing.png"
          />
          <img
            className="stamp"
            src="/static/images/cert/stamp.png"
            style={{ transform: `rotate(${stampAngle}deg)` }}
          />
          <div className="return-address">
            <span className="cafe-heading">
              <h1>{order.map((n) => NAMES[n]).join(", ")}</h1>
            </span>
            <h2>The Little Riddle</h2>
            <h3>Riddleton OH&nbsp;&nbsp;42026</h3>
          </div>
          <div className="to-address">
            <div className="cert-h1-wrapper cafe-heading">
              <Twemoji tag="h1">{teamScopeState.displayName}</Twemoji>
            </div>
            <div className="cert-h2-wrapper">
              <Twemoji tag="h2">
                {teamMembersScopeState.members.join(", ")}
              </Twemoji>
            </div>
            <div className="cert-h3-wrapper">
              <h3>Galactic Puzzle Hunt 2026</h3>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

